1	// Cyrus R3 gameplay designers: the DESIGN IR. A typed Custom Item Designer spec (ItemDesign) with an ability/event
2	// graph (AbilityGraph = trigger -> conditions -> actions, with branches) that the compiler (./compile.ts) turns into
3	// straight Java calling the verified component library (./components). Nothing here is free-form code: every node is a
4	// fixed kind, every number has a hard min/max (CAPS below; the JSON Schema carries them too), every activation has a
5	// static worst-case resource budget that must fit BUDGET, loops are bounded (query_* `max`, delayed `delayTicks` and
6	// nesting depth) and there is no way to run a command or arbitrary code. Numbers, texts and sound keys become config.yml
7	// parameters (editable without regenerating the mod, see ./params.ts); structure (kinds, effects, particles, targets)
8	// is code.
9	//
10	// Files: the build model writes one ItemDesign per file at assets/designs/<id>.json; a mod has at most
11	// DESIGN_LIMITS.maxItems of them. Identifiers live in the project's reserved namespace (engine-core identifiers):
12	// an item's full id is `nx_<8>:<id>`. Validation never throws: { ok, design | errors, warnings, checks, budgets }.
13	// The JSON Schema (designer.v1.schema.json) is generated from these Zod types (scripts/cyrus/build-designer-artifacts.ts;
14	// a test fails while it is stale).
15	import { z } from "zod";
16	import { NAMESPACE_RE, buildIdentifier } from "../engine-core/identifiers";
17	import { IngredientSchema, TEXT_COLORS, canonicalJson } from "../datapack/spec";
18	import { compareMc, isVanilla, missingIdReason, vanillaIds } from "../datapack/versions";
19	import { getVersion } from "../versions/registry";
20	
21	export const DESIGN_SPEC_VERSION = 1;
22	export { canonicalJson };
23	
24	/** Per-mod limits. */
25	export const DESIGN_LIMITS = { maxItems: 6, maxSpecBytes: 64 * 1024, maxAbilities: 6, maxNodes: 48, maxDepth: 3, maxConditions: 8, maxActions: 16, maxMarks: 4, maxPassives: 4, maxLore: 6, maxPermissions: 8 } as const;
26	
27	/**
28	 * Hard caps on every number (inclusive). The config loader clamps to the SAME caps at runtime, so a hand-edited
29	 * config.yml can never exceed them. Ticks: 20 = 1 second.
30	 */
31	export const CAPS = {
32	  cooldownTicks: [0, 72000], // up to 1 hour
33	  chargesMax: [1, 20],
34	  chargeRegenTicks: [20, 72000],
35	  targetRange: [1, 32], // blocks the click triggers look for a target / point
36	  periodTicks: [10, 1200], // held_interval: never faster than twice a second
37	  minChargeTicks: [5, 200],
38	  maxChargeTicks: [10, 400],
39	  damage: [0, 40], // health points (2 = one heart)
40	  heal: [0, 20],
41	  potionTicks: [1, 1200], // up to 60 s
42	  amplifier: [0, 4], // level I..V
43	  strength: [0, 3], // knockback / pull / push horizontal velocity (blocks per tick)
44	  vertical: [0, 1.5],
45	  teleportRange: [1, 16],
46	  projectileSpeed: [0.2, 3],
47	  projectileLifetime: [20, 200],
48	  particleCount: [1, 64],
49	  particleSpread: [0, 4],
50	  particleSpeed: [0, 1],
51	  volume: [0, 2],
52	  pitch: [0.5, 2],
53	  giveCount: [1, 64],
54	  chargeCost: [1, 5],
55	  markTicks: [20, 1200],
56	  marksPerOwner: [1, 32],
57	  queryMarkedRadius: [1, 32],
58	  queryNearbyRadius: [1, 12],
59	  queryMax: [1, 16],
60	  delayTicks: [1, 100],
61	  chance: [0, 1],
62	  healthFraction: [0, 1],
63	  timeOfDay: [0, 23999],
64	  titleFadeTicks: [0, 40],
65	  titleStayTicks: [10, 200],
66	  passiveAmplifier: [0, 2],
67	  lootChance: [0, 1],
68	  statDamage: [1, 40], // shown attack damage (player base 1 + modifier)
69	  statAttackSpeed: [0.25, 4], // attacks per second
70	  durability: [1, 10000],
71	} as const satisfies Record<string, readonly [number, number]>;
72	export type CapName = keyof typeof CAPS;
73	
74	/** Per-activation budget (static worst case must fit; the runtime Budget component enforces the same numbers). */
75	export const BUDGET = { actions: 64, entities: 32, tasks: 8, particles: 512, projectiles: 3 } as const;
76	/** Plugin-wide runtime caps (component constants). */
77	export const RUNTIME_CAPS = { liveTasks: 128, marksTotal: 2048, textChars: 120, titleChars: 40, subtitleChars: 60 } as const;
78	
79	const capNum = (c: CapName) => z.number().min(CAPS[c][0]).max(CAPS[c][1]);
80	const capInt = (c: CapName) => z.number().int().min(CAPS[c][0]).max(CAPS[c][1]);
81	
82	const KEY = /^[a-z][a-z0-9_]{1,31}$/;
83	const Key = z.string().regex(KEY, "2-32 chars: lowercase letters, digits, _; starts with a letter");
84	const VanillaRef = z.string().max(80).regex(/^minecraft:[a-z0-9_./]+$/, "a vanilla id like minecraft:diamond");
85	const NsRef = z.string().max(100).regex(/^[a-z0-9_.-]+:[a-z0-9_./-]+$/, "a namespaced id like nx_abcd1234:void_reaper");
86	const SoundKey = z.string().max(100).regex(/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/, "a namespaced sound key like nx_abcd1234:void_reaper.pull or minecraft:entity.enderman.teleport");
87	export const COLORS = TEXT_COLORS;
88	const Color = z.union([z.enum(TEXT_COLORS), z.string().regex(/^#[0-9a-fA-F]{6}$/)]);
89	const Text = (max: number) => z.string().min(1).max(max).regex(/^[^\u0000-\u001f§]*$/, "plain text (no control characters or § codes)");
90	const StyledText = z.strictObject({ text: Text(60), color: Color.optional() });
91	
92	// ------------------------------------------------------------------------------------------------ catalogs (curated)
93	/** Data-free particles that exist with the same Bukkit name on every registry version (catalog-compiled on 1.21.11 + 26.2). */
94	export const PARTICLES = ["flame", "soul_fire_flame", "portal", "reverse_portal", "end_rod", "crit", "enchanted_hit", "witch", "smoke", "large_smoke", "cloud", "heart", "happy_villager", "angry_villager", "enchant", "firework", "totem_of_undying", "sweep_attack", "electric_spark", "glow", "snowflake", "soul", "poof", "note", "damage_indicator", "squid_ink", "explosion", "sonic_boom"] as const;
95	/** Potion effects (vanilla ids; Java constant = UPPER_SNAKE, the post-1.20.5 names). */
96	export const EFFECTS = ["speed", "slowness", "haste", "mining_fatigue", "strength", "instant_health", "instant_damage", "jump_boost", "nausea", "regeneration", "resistance", "fire_resistance", "water_breathing", "invisibility", "blindness", "night_vision", "hunger", "weakness", "poison", "wither", "health_boost", "absorption", "saturation", "glowing", "levitation", "luck", "unluck", "slow_falling", "conduit_power", "dolphins_grace", "darkness"] as const;
97	/** Harmful effects: a passive may not grant them to the holder. */
98	export const HARMFUL_EFFECTS = ["slowness", "mining_fatigue", "instant_damage", "nausea", "blindness", "hunger", "weakness", "poison", "wither", "levitation", "unluck", "darkness"] as const;
99	export const PROJECTILES = ["snowball", "arrow", "small_fireball", "wind_charge"] as const;
100	export const TARGET_KINDS = ["player", "hostile", "animal", "living"] as const;
101	/** Base items that may carry item_consume (eaten/drunk normally; chorus fruit and milk excluded: they teleport / clear effects). */
102	export const CONSUMABLE_BASES = ["apple", "golden_apple", "bread", "carrot", "golden_carrot", "baked_potato", "cookie", "melon_slice", "sweet_berries", "glow_berries", "honey_bottle", "potion", "dried_kelp", "pumpkin_pie", "cooked_beef", "cooked_chicken", "cooked_porkchop", "cooked_mutton", "cooked_cod", "cooked_salmon", "beetroot", "mushroom_stew", "rabbit_stew", "beetroot_soup", "suspicious_stew"] as const;
103	/** Base items never allowed (operator/creative items, items whose own right-click does something drastic). */
104	export const BANNED_BASES = /^(air|command_block.*|chain_command_block|repeating_command_block|structure_block|structure_void|jigsaw|barrier|light|debug_stick|knowledge_book|.*_spawn_egg|ender_pearl|ender_eye|chorus_fruit|milk_bucket|written_book|bundle|.*_bundle|test_block|test_instance_block)$/;
105	
106	// ---------------------------------------------------------------------------------------------------------- triggers
107	export const TRIGGER_TYPES = ["right_click", "left_click_hit_entity", "sneak_right_click", "kill_entity", "projectile_hit", "held_interval", "join", "death", "item_consume", "charge_release"] as const;
108	export type TriggerType = (typeof TRIGGER_TYPES)[number];
109	const Range = { targetRange: capNum("targetRange").optional() };
110	export const TriggerSchema = z.discriminatedUnion("type", [
111	  /** Right-click with the item in the main hand (not sneaking, unless the item has no sneak right-click ability). targetRange: look for a target entity / point. */
112	  z.strictObject({ type: z.literal("right_click"), ...Range }),
113	  z.strictObject({ type: z.literal("left_click_hit_entity") }),
114	  z.strictObject({ type: z.literal("sneak_right_click"), ...Range }),
115	  z.strictObject({ type: z.literal("kill_entity") }),
116	  /** A projectile launched by this item's launch_projectile with the same tag hits something. */
117	  z.strictObject({ type: z.literal("projectile_hit"), tag: Key }),
118	  /** Every periodTicks while the item is held (main hand) or carried (inventory). */
119	  z.strictObject({ type: z.literal("held_interval"), periodTicks: capInt("periodTicks"), slot: z.enum(["main_hand", "inventory"]).optional() }),
120	  /** On join / on death while the item is in the inventory. */
121	  z.strictObject({ type: z.literal("join") }),
122	  z.strictObject({ type: z.literal("death") }),
123	  z.strictObject({ type: z.literal("item_consume") }),
124	  /** Hold sneak (with the item in the main hand) to charge, then release: right-click while still sneaking, or stop sneaking. */
125	  z.strictObject({ type: z.literal("charge_release"), minChargeTicks: capInt("minChargeTicks"), maxChargeTicks: capInt("maxChargeTicks"), release: z.enum(["right_click", "unsneak"]), ...Range }),
126	]);
127	export type Trigger = z.infer<typeof TriggerSchema>;
128	
129	// -------------------------------------------------------------------------------------------------------- conditions
130	const Neg = { negate: z.boolean().optional() };
131	const ConditionSchema = z.discriminatedUnion("type", [
132	  /** Another ability's cooldown (own ability: automatic when cooldownTicks is set). */
133	  z.strictObject({ type: z.literal("cooldown_ready"), ability: Key.optional(), ...Neg }),
134	  /** Permission `<namespace>.<node>`, declared in the item's permissions. */
135	  z.strictObject({ type: z.literal("has_permission"), node: z.string().regex(/^[a-z0-9_]+(\.[a-z0-9_]+){0,3}$/), ...Neg }),
136	  z.strictObject({ type: z.literal("target_is"), kinds: z.array(z.enum(TARGET_KINDS)).max(4).optional(), types: z.array(VanillaRef).min(1).max(16).optional(), ...Neg }),
137	  z.strictObject({ type: z.literal("world_in"), worlds: z.array(z.string().regex(/^[A-Za-z0-9_./-]{1,64}$/)).min(1).max(8), ...Neg }),
138	  z.strictObject({ type: z.literal("health_below"), subject: z.enum(["self", "target"]), fraction: capNum("healthFraction"), ...Neg }),
139	  z.strictObject({ type: z.literal("health_above"), subject: z.enum(["self", "target"]), fraction: capNum("healthFraction"), ...Neg }),
140	  /** The given design item (this mod) is in that slot. */
141	  z.strictObject({ type: z.literal("item_identity"), slot: z.enum(["main_hand", "off_hand"]), item: Key, ...Neg }),
142	  z.strictObject({ type: z.literal("sneaking"), ...Neg }),
143	  z.strictObject({ type: z.literal("charges_available"), ability: Key.optional(), amount: capInt("chargeCost"), ...Neg }),
144	  /** Seeded random (java.util.Random with general.random_seed): the TS simulator draws the same sequence. */
145	  z.strictObject({ type: z.literal("random_chance"), chance: capNum("chance"), ...Neg }),
146	  /** World time in ticks (0 = sunrise, 6000 noon, 13000 night, 18000 midnight); from > to wraps over midnight. */
147	  z.strictObject({ type: z.literal("time_of_day"), from: capInt("timeOfDay"), to: capInt("timeOfDay"), ...Neg }),
148	]);
149	export type Condition = z.infer<typeof ConditionSchema>;
150	export type ConditionType = Condition["type"];
151	export const CONDITION_TYPES = ConditionSchema.options.map((o) => o.shape.type.value) as ConditionType[];
152	
153	// ----------------------------------------------------------------------------------------------------------- actions
154	const Who = z.enum(["self", "target"]);
155	const At = z.enum(["self", "target", "point"]);
156	const Charge = { scaleWithCharge: z.boolean().optional() };
157	export type Action =
158	  | { type: "damage"; amount: number; target?: "self" | "target"; scaleWithCharge?: boolean }
159	  | { type: "heal"; amount: number; target?: "self" | "target"; scaleWithCharge?: boolean }
160	  | { type: "potion_effect"; effect: (typeof EFFECTS)[number]; durationTicks: number; amplifier?: number; target?: "self" | "target" }
161	  | { type: "knockback"; strength: number; vertical?: number; target?: "self" | "target"; scaleWithCharge?: boolean }
162	  | { type: "pull_to"; to: "self" | "point"; strength: number; vertical?: number; target?: "self" | "target"; scaleWithCharge?: boolean }
163	  | { type: "push_from"; from: "self" | "point"; strength: number; vertical?: number; target?: "self" | "target"; scaleWithCharge?: boolean }
164	  | { type: "teleport_short"; range: number }
165	  | { type: "launch_projectile"; kind: (typeof PROJECTILES)[number]; speed: number; tag?: string; lifetimeTicks?: number }
166	  | { type: "spawn_particles"; particle: (typeof PARTICLES)[number]; count: number; spread?: number; speed?: number; at?: "self" | "target" | "point" }
167	  | { type: "play_sound"; sound: string; volume?: number; pitch?: number; at?: "self" | "target" | "point" }
168	  | { type: "send_message"; text: string; color?: string; to?: "self" | "target" }
169	  | { type: "title"; title: string; subtitle?: string; color?: string; fadeInTicks?: number; stayTicks?: number; fadeOutTicks?: number; to?: "self" | "target" }
170	  | { type: "actionbar"; text: string; color?: string; to?: "self" | "target" }
171	  | { type: "give_item"; item: string; count?: number }
172	  | { type: "set_cooldown"; ability?: string; ticks?: number }
173	  | { type: "consume_charge"; ability?: string; amount?: number }
174	  | { type: "apply_mark"; mark: string; target?: "target" }
175	  | { type: "query_marked"; mark: string; radius: number; max: number; around?: "self" | "point"; actions: Action[] }
176	  | { type: "query_nearby"; radius: number; max: number; around?: "self" | "point"; kinds?: (typeof TARGET_KINDS)[number][]; types?: string[]; includePlayers?: boolean; actions: Action[] }
177	  | { type: "delayed"; delayTicks: number; actions: Action[] }
178	  | { type: "branch"; if: Condition[]; then: Action[]; else?: Action[] };
179	export type ActionType = Action["type"];
180	
181	const Actions: z.ZodType<Action[]> = z.lazy(() => z.array(ActionSchema).min(1).max(DESIGN_LIMITS.maxActions));
182	export const ActionSchema: z.ZodType<Action> = z.lazy(() => z.discriminatedUnion("type", [
183	  z.strictObject({ type: z.literal("damage"), amount: capNum("damage"), target: Who.optional(), ...Charge }),
184	  z.strictObject({ type: z.literal("heal"), amount: capNum("heal"), target: Who.optional(), ...Charge }),
185	  z.strictObject({ type: z.literal("potion_effect"), effect: z.enum(EFFECTS), durationTicks: capInt("potionTicks"), amplifier: capInt("amplifier").optional(), target: Who.optional() }),
186	  z.strictObject({ type: z.literal("knockback"), strength: capNum("strength"), vertical: capNum("vertical").optional(), target: Who.optional(), ...Charge }),
187	  z.strictObject({ type: z.literal("pull_to"), to: z.enum(["self", "point"]), strength: capNum("strength"), vertical: capNum("vertical").optional(), target: Who.optional(), ...Charge }),
188	  z.strictObject({ type: z.literal("push_from"), from: z.enum(["self", "point"]), strength: capNum("strength"), vertical: capNum("vertical").optional(), target: Who.optional(), ...Charge }),
189	  /** Self only, along the look direction, to the farthest SAFE spot within range (feet + head free, solid ground, loaded chunk). */
190	  z.strictObject({ type: z.literal("teleport_short"), range: capNum("teleportRange") }),
191	  z.strictObject({ type: z.literal("launch_projectile"), kind: z.enum(PROJECTILES), speed: capNum("projectileSpeed"), tag: Key.optional(), lifetimeTicks: capInt("projectileLifetime").optional() }),
192	  z.strictObject({ type: z.literal("spawn_particles"), particle: z.enum(PARTICLES), count: capInt("particleCount"), spread: capNum("particleSpread").optional(), speed: capNum("particleSpeed").optional(), at: At.optional() }),
193	  z.strictObject({ type: z.literal("play_sound"), sound: SoundKey, volume: capNum("volume").optional(), pitch: capNum("pitch").optional(), at: At.optional() }),
194	  z.strictObject({ type: z.literal("send_message"), text: Text(RUNTIME_CAPS.textChars), color: Color.optional(), to: Who.optional() }),
195	  z.strictObject({ type: z.literal("title"), title: Text(RUNTIME_CAPS.titleChars), subtitle: Text(RUNTIME_CAPS.subtitleChars).optional(), color: Color.optional(), fadeInTicks: capInt("titleFadeTicks").optional(), stayTicks: capInt("titleStayTicks").optional(), fadeOutTicks: capInt("titleFadeTicks").optional(), to: Who.optional() }),
196	  z.strictObject({ type: z.literal("actionbar"), text: Text(RUNTIME_CAPS.textChars), color: Color.optional(), to: Who.optional() }),
197	  /** A vanilla item (minecraft:...) or one of this mod's design items (its key). */
198	  z.strictObject({ type: z.literal("give_item"), item: z.union([VanillaRef, Key]), count: capInt("giveCount").optional() }),
199	  z.strictObject({ type: z.literal("set_cooldown"), ability: Key.optional(), ticks: capInt("cooldownTicks").optional() }),
200	  z.strictObject({ type: z.literal("consume_charge"), ability: Key.optional(), amount: capInt("chargeCost").optional() }),
201	  z.strictObject({ type: z.literal("apply_mark"), mark: Key, target: z.literal("target").optional() }),
202	  /** For each living entity that carries this player's mark within radius (nearest first, at most max): `target` = that entity. */
203	  z.strictObject({ type: z.literal("query_marked"), mark: Key, radius: capNum("queryMarkedRadius"), max: capInt("queryMax"), around: z.enum(["self", "point"]).optional(), actions: Actions }),
204	  /** For each living entity within radius matching kinds/types (never the player; other players only with includePlayers; nearest first, at most max). */
205	  z.strictObject({ type: z.literal("query_nearby"), radius: capNum("queryNearbyRadius"), max: capInt("queryMax"), around: z.enum(["self", "point"]).optional(), kinds: z.array(z.enum(TARGET_KINDS)).max(4).optional(), types: z.array(VanillaRef).min(1).max(16).optional(), includePlayers: z.boolean().optional(), actions: Actions }),
206	  /** Run later (one scheduled task; re-checks that the player is still online). */
207	  z.strictObject({ type: z.literal("delayed"), delayTicks: capInt("delayTicks"), actions: Actions }),
208	  z.strictObject({ type: z.literal("branch"), if: z.array(ConditionSchema).min(1).max(DESIGN_LIMITS.maxConditions), then: Actions, else: Actions.optional() }),
209	]));
210	
211	// ---------------------------------------------------------------------------------------------------------- abilities
212	export const AbilitySchema = z.strictObject({
213	  id: Key,
214	  name: Text(40),
215	  trigger: TriggerSchema,
216	  conditions: z.array(ConditionSchema).max(DESIGN_LIMITS.maxConditions).optional(),
217	  actions: z.array(ActionSchema).min(1).max(DESIGN_LIMITS.maxActions),
218	  /** Own cooldown: checked before the conditions and started when the ability fires (unless manualCooldown). */
219	  cooldownTicks: capInt("cooldownTicks").optional(),
220	  manualCooldown: z.boolean().optional(),
221	  /** Own charges: one is needed and spent per activation (unless manualCharges); they come back one per regenTicks. */
222	  charges: z.strictObject({ max: capInt("chargesMax"), regenTicks: capInt("chargeRegenTicks") }).optional(),
223	  manualCharges: z.boolean().optional(),
224	  /** Shown on the actionbar when the ability is blocked by its cooldown / missing charges. */
225	  feedback: z.boolean().optional(),
226	});
227	export type Ability = z.infer<typeof AbilitySchema>;
228	
229	export const MarkSchema = z.strictObject({ name: Key, durationTicks: capInt("markTicks"), maxPerOwner: capInt("marksPerOwner"), glow: z.boolean().optional() });
230	export const PassiveSchema = z.strictObject({ effect: z.enum(EFFECTS), amplifier: capInt("passiveAmplifier").optional(), slot: z.enum(["main_hand", "off_hand", "either"]) });
231	export const PermissionSchema = z.strictObject({ node: z.string().regex(/^[a-z0-9_]+(\.[a-z0-9_]+){0,3}$/), description: Text(80), default: z.enum(["true", "op", "false"]) });
232	
233	/** The datapack recipe spec's shaped/shapeless shapes, with the design item as the result (plugin-registered: the result carries the PDC identity). */
234	const CraftCategory = z.enum(["building", "redstone", "equipment", "misc"]);
235	export const DesignRecipeSchema = z.discriminatedUnion("kind", [
236	  z.strictObject({ kind: z.literal("shaped"), pattern: z.array(z.string().min(1).max(3)).min(1).max(3), key: z.record(z.string().regex(/^[^ ]$/, "one character (not space)"), z.union([IngredientSchema, Key])), count: capInt("giveCount").optional(), category: CraftCategory.optional() }),
237	  z.strictObject({ kind: z.literal("shapeless"), ingredients: z.array(z.union([IngredientSchema, Key])).min(1).max(9), count: capInt("giveCount").optional(), category: CraftCategory.optional() }),
238	]);
239	export type DesignRecipe = z.infer<typeof DesignRecipeSchema>;
240	
241	export const ItemDesignSchema = z.strictObject({
242	  schemaVersion: z.literal(DESIGN_SPEC_VERSION),
243	  /** Item key: file name (assets/designs/<id>.json) and the id in the project namespace (`nx_<8>:<id>`). */
244	  id: Key,
245	  base: VanillaRef,
246	  name: StyledText,
247	  lore: z.array(StyledText).max(DESIGN_LIMITS.maxLore).optional(),
248	  rarity: z.enum(["common", "uncommon", "rare", "epic"]).optional(),
249	  glint: z.boolean().optional(),
250	  /** Asset references by key (the texture / sound / model slices make them; the asset gates apply there). */
251	  assets: z.strictObject({ model: NsRef.optional(), sounds: z.array(SoundKey).max(16).optional() }).optional(),
252	  stats: z.strictObject({ damage: capNum("statDamage").optional(), attackSpeed: capNum("statAttackSpeed").optional(), durability: capInt("durability").optional(), unbreakable: z.boolean().optional() }).optional(),
253	  passives: z.array(PassiveSchema).max(DESIGN_LIMITS.maxPassives).optional(),
254	  marks: z.array(MarkSchema).max(DESIGN_LIMITS.maxMarks).optional(),
255	  abilities: z.array(AbilitySchema).max(DESIGN_LIMITS.maxAbilities),
256	  permissions: z.array(PermissionSchema).max(DESIGN_LIMITS.maxPermissions).optional(),
257	  recipe: DesignRecipeSchema.optional(),
258	  acquisition: z.strictObject({
259	    /** Extra loot in these loot tables (vanilla or this mod's data pack), chance per generated chest/drop. */
260	    loot: z.array(z.strictObject({ table: NsRef, chance: capNum("lootChance") })).max(8).optional(),
261	    /** Dropped by these mobs when a player kills them. */
262	    drops: z.array(z.strictObject({ entity: VanillaRef, chance: capNum("lootChance") })).max(8).optional(),
263	  }).optional(),
264	});
265	export type ItemDesign = z.infer<typeof ItemDesignSchema>;
266	
267	export function designJsonSchema(): Record<string, unknown> {
268	  return z.toJSONSchema(ItemDesignSchema, { io: "input", reused: "ref" }) as Record<string, unknown>;
269	}
270	
271	// ---------------------------------------------------------------------------------------------- version features
272	export type DesignFeatures = {
273	  version: string;
274	  /** item_model component (ItemMeta#setItemModel) exists: 1.21.4+ in the registry (capability itemModelDefinitions). */
275	  itemModel: boolean;
276	  /** Attribute constants: GENERIC_* (1.21.1, enum) vs unprefixed (1.21.3+, registry interface). */
277	  attributeNames: "generic-prefix" | "plain";
278	  javaRelease: 21 | 25;
279	  /** Scheduling lane: always the Paper/Bukkit main-thread scheduler (no Folia regions; plugin.yml has no folia-supported). */
280	  scheduling: "paper";
281	};
282	export type FeaturesResult = { ok: true; features: DesignFeatures } | { ok: false; error: string };
283	
284	/** Fails closed: unknown version, blocked version, or no generated vanilla ids for it (ids are needed to check the design). */
285	export function designFeatures(version: string): FeaturesResult {
286	  const row = getVersion(version);
287	  if (!row) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
288	  if (row.status === "blocked") return { ok: false, error: `Minecraft ${version} is blocked in the version registry` };
289	  if (!vanillaIds("item", version).size) return { ok: false, error: `Cyrus has no vanilla id list for Minecraft ${version} yet (needs a pinned server jar on the build host)` };
290	  return { ok: true, features: { version, itemModel: row.capabilities.includes("itemModelDefinitions"), attributeNames: compareMc(version, "1.21.3") >= 0 ? "plain" : "generic-prefix", javaRelease: row.javaRelease, scheduling: "paper" } };
291	}
