294	export type DzIssue = { path: string; code: string; message: string };
295	export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
296	export type DzCheck = { id: string; status: CheckStatus; items: string[] };
297	export type AbilityBudget = { ability: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number };
298	export type DesignValidation =
299	  | { ok: true; design: ItemDesign; errors: []; warnings: DzIssue[]; checks: DzCheck[]; budgets: AbilityBudget[]; features: DesignFeatures }
300	  | { ok: false; errors: DzIssue[]; warnings: DzIssue[]; checks: DzCheck[]; budgets: AbilityBudget[] };
