302	export type DesignContext = {
303	  version: string;
304	  namespace: string;
305	  /** Keys of the other design items of the same mod (give_item / item_identity / recipe ingredients may use them). */
306	  items?: string[];
307	  /** Asset keys the mod has: item model keys (`nx_x:name`) and sound keys (`nx_x:set.event`). Undefined = not checked. */
308	  assets?: { models?: string[]; sounds?: string[] };
309	};
