311	export const DESIGN_CHECKS = ["schema", "namespace", "vanilla_ids", "references", "context", "budget", "version_features", "limits"] as const;
312	const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");
313	
314	/** Which triggers give the activation a target entity (possibly absent at runtime) / a point other than the player. */
315	export const TRIGGER_HAS_TARGET: Record<TriggerType, "always" | "maybe" | "never"> = {
316	  right_click: "maybe", sneak_right_click: "maybe", charge_release: "maybe", left_click_hit_entity: "always", kill_entity: "always", projectile_hit: "maybe",
317	  held_interval: "never", join: "never", death: "never", item_consume: "never",
318	};
319	const isBlockItem = (id: string, v: string) => vanillaIds("block", v).has(id);
320	
321	/** Static worst case of one action list (multiplicity = how many times the list runs per activation). */
322	export function budgetOf(list: Action[], mult = 1, depth = 1): { actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number } {
323	  const t = { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, nodes: 0, depth };
324	  for (const a of list) {
325	    t.actions += mult; t.nodes += 1;
326	    const add = (b: ReturnType<typeof budgetOf>) => { t.actions += b.actions; t.entities += b.entities; t.tasks += b.tasks; t.particles += b.particles; t.projectiles += b.projectiles; t.nodes += b.nodes; t.depth = Math.max(t.depth, b.depth); };
327	    switch (a.type) {
328	      case "damage": case "heal": case "potion_effect": case "knockback": case "pull_to": case "push_from": case "apply_mark": t.entities += mult; break;
329	      case "spawn_particles": t.particles += a.count * mult; break;
330	      case "launch_projectile": t.projectiles += mult; t.tasks += mult; break; // the lifetime task
331	      case "query_marked": case "query_nearby": add(budgetOf(a.actions, mult * a.max, depth + 1)); break;
332	      case "delayed": t.tasks += mult; add(budgetOf(a.actions, mult, depth + 1)); break;
333	      case "branch": { const th = budgetOf(a.then, mult, depth + 1), el = a.else ? budgetOf(a.else, mult, depth + 1) : null; t.nodes += th.nodes + (el?.nodes ?? 0) + a.if.length;
334	        // worst case = the heavier branch for each counter
335	        for (const k of ["actions", "entities", "tasks", "particles", "projectiles"] as const) t[k] += Math.max(th[k], el?.[k] ?? 0);
336	        t.depth = Math.max(t.depth, th.depth, el?.depth ?? 0); break; }
337	      default: break;
338	    }
339	  }
340	  return t;
341	}
