343	/** Walk every action (pre-order) with its path ("a0", "a1.n0", "a2.then0", "a2.else1"). */
344	export function walkActions(list: Action[], fn: (a: Action, path: string, inLoop: boolean) => void, prefix = "", inLoop = false): void {
345	  list.forEach((a, i) => {
346	    const here = prefix ? `${prefix}${i}` : `a${i}`;
347	    fn(a, here, inLoop);
348	    if (a.type === "query_marked" || a.type === "query_nearby") walkActions(a.actions, fn, `${here}.n`, true);
349	    else if (a.type === "delayed") walkActions(a.actions, fn, `${here}.n`, inLoop);
350	    else if (a.type === "branch") { walkActions(a.then, fn, `${here}.then`, inLoop); if (a.else) walkActions(a.else, fn, `${here}.else`, inLoop); }
351	  });
352	}
353	/** Every condition of an ability with its path ("c0", "a2.if0"). */
354	export function walkConditions(ab: Ability, fn: (c: Condition, path: string, inLoop: boolean) => void): void {
355	  (ab.conditions ?? []).forEach((c, i) => fn(c, `c${i}`, false));
356	  walkActions(ab.actions, (a, p, inLoop) => { if (a.type === "branch") a.if.forEach((c, i) => fn(c, `${p}.if${i}`, inLoop)); });
357	}
