359	export function validateDesign(input: unknown, ctx: DesignContext): DesignValidation {
360	  const errors: DzIssue[] = [];
361	  const warnings: DzIssue[] = [];
362	  const bucket = new Map<string, string[]>(DESIGN_CHECKS.map((c) => [c, []]));
363	  const failed = new Set<string>();
364	  const ran = new Set<string>(["schema"]);
365	  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); failed.add(check); bucket.get(check)!.push(`${path}: ${message}`); };
366	  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
367	  const budgets: AbilityBudget[] = [];
368	  const checksOf = (): DzCheck[] => DESIGN_CHECKS.map((id) => {
369	    const items = bucket.get(id)!;
370	    return { id, status: !ran.has(id) ? "not_run" : failed.has(id) ? "fail" : items.length ? "warn" : "pass", items: items.slice(0, 20) };
371	  });
372	  const bad = (): DesignValidation => ({ ok: false, errors, warnings, checks: checksOf(), budgets });
373	
374	  ran.add("namespace");
375	  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return bad(); }
376	  ran.add("version_features");
377	  const fe = designFeatures(ctx.version);
378	  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return bad(); }
379	  const v = ctx.version;
380	  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DESIGN_SPEC_VERSION) {
381	    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DESIGN_SPEC_VERSION}`); return bad();
382	  }
383	  const bytes = (() => { try { return new TextEncoder().encode(JSON.stringify(input)).length; } catch { return Infinity; } })();
384	  ran.add("limits");
385	  if (bytes > DESIGN_LIMITS.maxSpecBytes) { fail("limits", "(root)", "spec_size", `the design is ${bytes} bytes; the limit is ${DESIGN_LIMITS.maxSpecBytes}`); return bad(); }
386	  const parsed = ItemDesignSchema.safeParse(input);
387	  if (!parsed.success) {
388	    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
389	    return bad();
390	  }
391	  const d = parsed.data;
392	  for (const c of ["vanilla_ids", "references", "context", "budget"]) ran.add(c);
393	  const ns = ctx.namespace;
394	  const id = buildIdentifier(ns, "item", d.id);
395	  if (!id.ok) fail("namespace", "id", "bad_id", id.error);
396	
397	  // base item
398	  const base = d.base.slice("minecraft:".length);
399	  if (!isVanilla("item", d.base, v)) fail("vanilla_ids", "base", "unknown_vanilla_id", missingIdReason("item", d.base, v));
400	  if (BANNED_BASES.test(base)) fail("context", "base", "banned_base", `${d.base} cannot be a design item's base (operator item, or its own right-click teleports/places/spawns)`);
401	  const clicks = d.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type));
402	  if (clicks && isBlockItem(base, v)) fail("context", "base", "block_base", `${d.base} is a block: right-clicking would place it. Pick a non-block base item for click abilities`);
403	  const consume = d.abilities.some((a) => a.trigger.type === "item_consume");
404	  if (consume && !(CONSUMABLE_BASES as readonly string[]).includes(base)) fail("context", "base", "not_consumable", `item_consume needs an edible/drinkable base item (${CONSUMABLE_BASES.slice(0, 8).join(", ")}, ...); ${d.base} is not one`);
