522	  // recipe (the datapack recipe shapes; ingredients are vanilla items, #tags or this mod's design items)
523	  if (d.recipe) {
524	    const r = d.recipe;
525	    const ing = (at: string, x: unknown) => {
526	      const list = Array.isArray(x) ? x as string[] : [x as string];
