67	const COLOR_NAMES: Record<string, string> = { black: "BLACK", dark_blue: "DARK_BLUE", dark_green: "DARK_GREEN", dark_aqua: "DARK_AQUA", dark_red: "DARK_RED", dark_purple: "DARK_PURPLE", gold: "GOLD", gray: "GRAY", dark_gray: "DARK_GRAY", blue: "BLUE", green: "GREEN", aqua: "AQUA", red: "RED", light_purple: "LIGHT_PURPLE", yellow: "YELLOW", white: "WHITE" };
68	const colorExpr = (c?: string) => (!c ? "null" : c.startsWith("#") ? `TextColor.color(0x${c.slice(1).toUpperCase()})` : `NamedTextColor.${COLOR_NAMES[c]}`);
69	const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
70	const maskOf = (k?: string[]) => (k ?? []).reduce((m, x) => m | (KIND_BITS[x] ?? 0), 0);
71	const bare = (id: string) => id.replace(/^minecraft:/, "");
72	const MATERIAL = (id: string) => `Material.${bare(id).toUpperCase()}`;
