74	/** Optional-field defaults (documented in docs "Cyrus gameplay designers (R3)"). */
75	export const DEFAULTS = {
76	  knockbackVertical: 0.35, pullVertical: 0.25, pushVertical: 0.35, amplifier: 0, lifetimeTicks: 100, spread: 0.3, particleSpeed: 0.02,
77	  volume: 1, pitch: 1, fadeInTicks: 10, stayTicks: 40, fadeOutTicks: 10, giveCount: 1, chargeCost: 1, passiveAmplifier: 0,
78	} as const;
