81	type ParamSink = { params: Param[]; base: string; item: string; ability?: string; abilityName?: string };
82	function addParam(s: ParamSink, rel: string, kind: ParamKind, cap: CapName | [number, number], value: number | string, label: string, role: string): Param {
83	  const [min, max] = Array.isArray(cap) ? cap : CAPS[cap as CapName];
84	  const p: Param = { path: s.base + rel, field: fieldOf(rel), kind, min, max, value, label: s.abilityName ? `${s.abilityName}: ${label}` : label, item: s.item, ...(s.ability ? { ability: s.ability } : {}), role };
85	  s.params.push(p);
86	  return p;
87	}
