89	/** The parameters of one ability, in config order (also the Java field order). */
90	export function abilityParams(item: ItemDesign, ab: Ability): Param[] {
91	  const s: ParamSink = { params: [], base: `items.${item.id}.abilities.${ab.id}.`, item: item.id, ability: ab.id, abilityName: ab.name };
92	  if (ab.cooldownTicks !== undefined) addParam(s, "cooldown_ticks", "ticks", "cooldownTicks", ab.cooldownTicks, "cooldown (ticks, 20 = 1 s)", "cooldown");
93	  if (ab.charges) { addParam(s, "charges.max", "int", "chargesMax", ab.charges.max, "charges", "charges"); addParam(s, "charges.regen_ticks", "ticks", "chargeRegenTicks", ab.charges.regenTicks, "ticks per charge regained", "cooldown"); }
94	  const t = ab.trigger;
95	  if ("targetRange" in t && t.targetRange !== undefined) addParam(s, "trigger.target_range", "num", "targetRange", t.targetRange, "target range (blocks)", "range");
96	  if (t.type === "held_interval") addParam(s, "trigger.period_ticks", "ticks", "periodTicks", t.periodTicks, "interval (ticks)", "cooldown");
97	  if (t.type === "charge_release") { addParam(s, "trigger.min_charge_ticks", "ticks", "minChargeTicks", t.minChargeTicks, "minimum charge (ticks)", "duration"); addParam(s, "trigger.max_charge_ticks", "ticks", "maxChargeTicks", t.maxChargeTicks, "full charge (ticks)", "duration"); }
98	  const cond = (c: Condition, rel: string) => {
99	    switch (c.type) {
100	      case "health_below": case "health_above": addParam(s, `${rel}.fraction`, "num", "healthFraction", c.fraction, `${c.type.replace("_", " ")} (fraction of max health)`, "other"); break;
101	      case "random_chance": addParam(s, `${rel}.chance`, "num", "chance", c.chance, "chance (0-1)", "chance"); break;
102	      case "time_of_day": addParam(s, `${rel}.from`, "int", "timeOfDay", c.from, "time window start (ticks)", "other"); addParam(s, `${rel}.to`, "int", "timeOfDay", c.to, "time window end (ticks)", "other"); break;
103	      case "charges_available": addParam(s, `${rel}.amount`, "int", "chargeCost", c.amount, "charges needed", "count"); break;
104	      default: break;
105	    }
106	  };
107	  (ab.conditions ?? []).forEach((c, i) => cond(c, `c${i}`));
108	  walkActions(ab.actions, (a, p) => {
109	    switch (a.type) {
110	      case "damage": addParam(s, `${p}.amount`, "num", "damage", a.amount, "damage (health points)", "damage"); break;
111	      case "heal": addParam(s, `${p}.amount`, "num", "heal", a.amount, "heal (health points)", "heal"); break;
112	      case "potion_effect": addParam(s, `${p}.duration_ticks`, "ticks", "potionTicks", a.durationTicks, `${a.effect} duration (ticks)`, "duration"); addParam(s, `${p}.amplifier`, "int", "amplifier", a.amplifier ?? DEFAULTS.amplifier, `${a.effect} level - 1`, "level"); break;
113	      case "knockback": case "pull_to": case "push_from": {
114	        const dv = a.type === "knockback" ? DEFAULTS.knockbackVertical : a.type === "pull_to" ? DEFAULTS.pullVertical : DEFAULTS.pushVertical;
115	        addParam(s, `${p}.strength`, "num", "strength", a.strength, `${a.type.replace("_", " ")} strength`, "strength"); addParam(s, `${p}.vertical`, "num", "vertical", a.vertical ?? dv, `${a.type.replace("_", " ")} lift`, "lift"); break;
116	      }
117	      case "teleport_short": addParam(s, `${p}.range`, "num", "teleportRange", a.range, "teleport range (blocks)", "range"); break;
118	      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "speed"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;
119	      case "spawn_particles": addParam(s, `${p}.count`, "int", "particleCount", a.count, `${a.particle} particles`, "count"); addParam(s, `${p}.spread`, "num", "particleSpread", a.spread ?? DEFAULTS.spread, `${a.particle} spread`, "other"); addParam(s, `${p}.speed`, "num", "particleSpeed", a.speed ?? DEFAULTS.particleSpeed, `${a.particle} speed`, "other"); break;
120	      case "play_sound": addParam(s, `${p}.sound`, "sound", [0, 100], a.sound, "sound key", "sound"); addParam(s, `${p}.volume`, "num", "volume", a.volume ?? DEFAULTS.volume, "sound volume", "other"); addParam(s, `${p}.pitch`, "num", "pitch", a.pitch ?? DEFAULTS.pitch, "sound pitch", "other"); break;
121	      case "send_message": case "actionbar": addParam(s, `${p}.text`, "text", [0, RUNTIME_CAPS.textChars], a.text, a.type === "actionbar" ? "actionbar text" : "message text", "text"); break;
122	      case "title":
123	        addParam(s, `${p}.title`, "text", [0, RUNTIME_CAPS.titleChars], a.title, "title text", "text");
124	        if (a.subtitle !== undefined) addParam(s, `${p}.subtitle`, "text", [0, RUNTIME_CAPS.subtitleChars], a.subtitle, "subtitle text", "text");
125	        addParam(s, `${p}.fade_in_ticks`, "ticks", "titleFadeTicks", a.fadeInTicks ?? DEFAULTS.fadeInTicks, "title fade in", "duration");
126	        addParam(s, `${p}.stay_ticks`, "ticks", "titleStayTicks", a.stayTicks ?? DEFAULTS.stayTicks, "title stay", "duration");
127	        addParam(s, `${p}.fade_out_ticks`, "ticks", "titleFadeTicks", a.fadeOutTicks ?? DEFAULTS.fadeOutTicks, "title fade out", "duration");
128	        break;
129	      case "give_item": addParam(s, `${p}.count`, "int", "giveCount", a.count ?? DEFAULTS.giveCount, `${a.item} count`, "count"); break;
130	      case "set_cooldown": {
131	        const ref = item.abilities.find((x) => x.id === (a.ability ?? ab.id));
132	        addParam(s, `${p}.ticks`, "ticks", "cooldownTicks", a.ticks ?? ref?.cooldownTicks ?? 0, `cooldown set on ${a.ability ?? ab.id} (ticks)`, "cooldown"); break;
133	      }
134	      case "consume_charge": addParam(s, `${p}.amount`, "int", "chargeCost", a.amount ?? DEFAULTS.chargeCost, "charges spent", "count"); break;
135	      case "query_marked": addParam(s, `${p}.radius`, "num", "queryMarkedRadius", a.radius, `marked "${a.mark}" search radius`, "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
136	      case "query_nearby": addParam(s, `${p}.radius`, "num", "queryNearbyRadius", a.radius, "nearby search radius", "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
137	      case "delayed": addParam(s, `${p}.delay_ticks`, "ticks", "delayTicks", a.delayTicks, "delay (ticks)", "duration"); break;
138	      case "branch": a.if.forEach((c, i) => cond(c, `${p}.if${i}`)); break;
139	      default: break;
140	    }
141	  });
142	  return s.params;
143	}
