154	export function designParams(designs: ItemDesign[]): Param[] {
155	  return [...designs].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)).flatMap((d) => [...itemParams(d), ...d.abilities.flatMap((ab) => abilityParams(d, ab))]);
156	}
