158	// ---------------------------------------------------------------------------------------------------- Java codegen
159	class Out {
160	  lines: string[] = [];
161	  push(ind: number, s: string) { this.lines.push("    ".repeat(ind) + s); }
162	}
163	const JTYPE: Record<ParamKind, string> = { num: "double", ticks: "long", int: "int", text: "String", sound: "String" };
164	function loadLine(p: Param, rel: string): string {
165	  switch (p.kind) {
166	    case "num": return `${p.field} = c.num(B + ${jstr(rel)}, ${jnum(p.min)}, ${jnum(p.max)});`;
167	    case "ticks": return `${p.field} = c.ticks(B + ${jstr(rel)}, ${p.min}L, ${p.max}L);`;
168	    case "int": return `${p.field} = c.integer(B + ${jstr(rel)}, ${p.min}, ${p.max});`;
169	    case "text": return `${p.field} = c.text(B + ${jstr(rel)}, ${p.max});`;
170	    case "sound": return `${p.field} = c.soundKey(B + ${jstr(rel)});`;
171	  }
172	}
