174	type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number };
175	const P = (g: AbGen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
176	
177	function condExpr(g: AbGen, c: Condition, rel: string, A: string): string {
178	  const neg = (e: string) => (c.negate ? `!(${e})` : e);
179	  const own = (ref?: string) => !ref || ref === g.ab.id;
180	  const other = (ref: string) => `d.ability(${jstr(g.item.id)}, ${jstr(ref)})`;
181	  switch (c.type) {
182	    case "cooldown_ready": return neg(own(c.ability) ? `cooldownReady(${A}.player())` : `(${other(c.ability!)} == null || ${other(c.ability!)}.cooldownReady(${A}.player()))`);
183	    case "has_permission": return neg(`${A}.player().hasPermission(${jstr(`${g.ns}.${c.node}`)})`);
184	    case "target_is": {
185	      const set = c.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
186	      if (c.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${c.types.map((t) => jstr(bare(t))).join(", ")});`);
187	      const e = `Checks.targetIs(${A}.target(), ${maskOf(c.kinds)}, ${set})`;
188	      return c.negate ? `(${A}.target() != null && ${A}.target().isValid() && !${e})` : e;
189	    }
190	    case "world_in": {
191	      const set = `W_${rel.replace(/\./g, "_")}`;
192	      g.statics.push(`private static final Set<String> ${set} = Set.of(${c.worlds.map(jstr).join(", ")});`);
193	      return neg(`${set}.contains(${A}.player().getWorld().getName())`);
194	    }
195	    case "health_below": case "health_above":
196	      return `Checks.health(${c.subject === "self" ? `${A}.player()` : `${A}.livingTarget()`}, ${P(g, `${rel}.fraction`)}, ${c.type === "health_below"}, ${!!c.negate})`;
197	    case "item_identity": return neg(`d.identity().is(${A}.player().getInventory().${c.slot === "main_hand" ? "getItemInMainHand" : "getItemInOffHand"}(), ${jstr(c.item)})`);
198	    case "sneaking": return neg(`${A}.player().isSneaking()`);
199	    case "charges_available": return neg(own(c.ability) ? `chargesLeft(${A}.player()) >= ${P(g, `${rel}.amount`)}` : `(${other(c.ability!)} != null && ${other(c.ability!)}.chargesLeft(${A}.player()) >= ${P(g, `${rel}.amount`)})`);
200	    case "random_chance": return neg(`d.random().nextDouble() < ${P(g, `${rel}.chance`)}`);
201	    case "time_of_day": return neg(`Checks.timeIn(${A}.player().getWorld(), ${P(g, `${rel}.from`)}, ${P(g, `${rel}.to`)})`);
202	  }
203	}
204	
205	function actions(g: AbGen, o: Out, list: Action[], prefix: string, A: string, ind: number): void {
206	  list.forEach((a, i) => {
207	    const rel = prefix ? `${prefix}${i}` : `a${i}`;
208	    o.push(ind, `// ${rel}: ${a.type}`);
209	    o.push(ind, `if (!${A}.budget().action()) return;`);
210	    const subj = (t: string | undefined, dflt: "self" | "target") => ((t ?? dflt) === "self" ? `${A}.player()` : `${A}.livingTarget()`);
211	    const ent = (t: string | undefined) => ((t ?? "self") === "self" ? `${A}.player()` : `${A}.target()`);
212	    const at = (w: string | undefined) => (w === "target" ? `d.effects().target(${A})` : w === "point" ? `d.effects().point(${A})` : `d.effects().self(${A})`);
213	    const scale = (b?: boolean) => (b ? ` * ${A}.charge()` : "");
214	    switch (a.type) {
215	      case "damage": o.push(ind, `d.effects().damage(${A}, ${subj(a.target, "target")}, ${P(g, `${rel}.amount`)}${scale(a.scaleWithCharge)});`); break;
216	      case "heal": o.push(ind, `d.effects().heal(${A}, ${subj(a.target, "self")}, ${P(g, `${rel}.amount`)}${scale(a.scaleWithCharge)});`); break;
217	      case "potion_effect": o.push(ind, `d.effects().potion(${A}, ${subj(a.target, "self")}, PotionEffectType.${a.effect.toUpperCase()}, (int) ${P(g, `${rel}.duration_ticks`)}, ${P(g, `${rel}.amplifier`)});`); break;
218	      case "knockback": o.push(ind, `d.effects().knockback(${A}, ${subj(a.target, "target")}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
219	      case "pull_to": o.push(ind, `d.effects().pullTo(${A}, ${subj(a.target, "target")}, ${a.to === "self" ? `${A}.player().getLocation()` : `${A}.point()`}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
220	      case "push_from": o.push(ind, `d.effects().pushFrom(${A}, ${subj(a.target, "target")}, ${a.from === "self" ? `${A}.player().getLocation()` : `${A}.point()`}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
221	      case "teleport_short": o.push(ind, `d.effects().teleportShort(${A}, ${P(g, `${rel}.range`)});`); break;
222	      case "launch_projectile": o.push(ind, `d.effects().launch(${A}, ${jstr(a.kind)}, ${P(g, `${rel}.speed`)}, ${a.tag ? jstr(a.tag) : "null"}, ${P(g, `${rel}.lifetime_ticks`)});`); break;
223	      case "spawn_particles": o.push(ind, `d.effects().particles(${A}, ${at(a.at)}, Particle.${a.particle.toUpperCase()}, ${P(g, `${rel}.count`)}, ${P(g, `${rel}.spread`)}, ${P(g, `${rel}.speed`)});`); break;
224	      case "play_sound": o.push(ind, `d.effects().sound(${A}, ${at(a.at)}, ${P(g, `${rel}.sound`)}, (float) ${P(g, `${rel}.volume`)}, (float) ${P(g, `${rel}.pitch`)});`); break;
225	      case "send_message": o.push(ind, `d.effects().message(${A}, ${ent(a.to)}, ${P(g, `${rel}.text`)}, ${colorExpr(a.color)});`); break;
226	      case "actionbar": o.push(ind, `d.effects().actionbar(${A}, ${ent(a.to)}, ${P(g, `${rel}.text`)}, ${colorExpr(a.color)});`); break;
227	      case "title": o.push(ind, `d.effects().title(${A}, ${ent(a.to)}, ${P(g, `${rel}.title`)}, ${a.subtitle !== undefined ? P(g, `${rel}.subtitle`) : "null"}, ${colorExpr(a.color)}, ${P(g, `${rel}.fade_in_ticks`)}, ${P(g, `${rel}.stay_ticks`)}, ${P(g, `${rel}.fade_out_ticks`)});`); break;
228	      case "give_item":
229	        if (a.item.startsWith("minecraft:")) o.push(ind, `d.effects().give(${A}, new ItemStack(${MATERIAL(a.item)}), ${P(g, `${rel}.count`)});`);
230	        else { o.push(ind, `{`); o.push(ind + 1, `DesignItem gi = d.item(${jstr(a.item)});`); o.push(ind + 1, `d.effects().give(${A}, gi == null ? null : gi.create(), ${P(g, `${rel}.count`)});`); o.push(ind, `}`); }
231	        break;
232	      case "set_cooldown":
233	        if (!a.ability || a.ability === g.ab.id) o.push(ind, `startCooldown(${A}.player(), ${P(g, `${rel}.ticks`)});`);
234	        else { o.push(ind, `{`); o.push(ind + 1, `Ability o = d.ability(${jstr(g.item.id)}, ${jstr(a.ability)});`); o.push(ind + 1, `if (o != null) o.startCooldown(${A}.player(), ${P(g, `${rel}.ticks`)});`); o.push(ind, `}`); }
235	        break;
236	      case "consume_charge":
237	        if (!a.ability || a.ability === g.ab.id) o.push(ind, `spendCharges(${A}.player(), ${P(g, `${rel}.amount`)});`);
238	        else { o.push(ind, `{`); o.push(ind + 1, `Ability o = d.ability(${jstr(g.item.id)}, ${jstr(a.ability)});`); o.push(ind + 1, `if (o != null) o.spendCharges(${A}.player(), ${P(g, `${rel}.amount`)});`); o.push(ind, `}`); }
239	        break;
240	      case "apply_mark":
241	        o.push(ind, `{`);
242	        o.push(ind + 1, `LivingEntity mt = ${A}.livingTarget();`);
243	        o.push(ind + 1, `DesignItem.Mark m = d.item(${jstr(g.item.id)}).mark(${jstr(a.mark)});`);
244	        o.push(ind + 1, `if (mt != null && mt != ${A}.player() && ${A}.budget().entity() && d.marks().apply(${A}.player().getUniqueId(), mt.getUniqueId(), ${jstr(`${g.item.id}.${a.mark}`)}, d.now(), m.ticks(), m.max()) && m.glow()) mt.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING, (int) m.ticks(), 0, false, false));`);
245	        o.push(ind, `}`);
246	        break;
247	      case "query_marked": case "query_nearby": {
248	        const n = ++g.loopN;
249	        const around = a.around === "point" ? `${A}.point()` : `${A}.player().getLocation()`;
250	        if (a.type === "query_marked") o.push(ind, `for (LivingEntity t${n} : d.marks().marked(${A}.player().getUniqueId(), ${jstr(`${g.item.id}.${a.mark}`)}, ${around}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.max`)}, d.now())) {`);
251	        else {
252	          const set = a.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
253	          if (a.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${a.types.map((t) => jstr(bare(t))).join(", ")});`);
254	          o.push(ind, `for (LivingEntity t${n} : Targets.nearby(${A}.player(), ${around}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.max`)}, ${maskOf(a.kinds)}, ${set}, ${!!a.includePlayers})) {`);
255	        }
256	        o.push(ind + 1, `Activation a${n} = ${A}.withTarget(t${n});`);
257	        actions(g, o, a.actions, `${rel}.n`, `a${n}`, ind + 1);
258	        o.push(ind, `}`);
259	        break;
260	      }
261	      case "delayed":
262	        o.push(ind, `d.later(${A}, ${P(g, `${rel}.delay_ticks`)}, () -> {`);
263	        actions(g, o, a.actions, `${rel}.n`, A, ind + 1);
264	        o.push(ind, `});`);
265	        break;
266	      case "branch":
267	        o.push(ind, `if (${a.if.map((c, j) => condExpr(g, c, `${rel}.if${j}`, A)).join(" && ")}) {`);
268	        actions(g, o, a.then, `${rel}.then`, A, ind + 1);
269	        if (a.else) { o.push(ind, `} else {`); actions(g, o, a.else, `${rel}.else`, A, ind + 1); }
270	        o.push(ind, `}`);
271	        break;
272	    }
273	  });
274	}
