535	function yamlTree(params: Param[]): string[] {
536	  type Node = { children: Map<string, Node>; param?: Param };
537	  const root: Node = { children: new Map() };
538	  for (const p of params) {
539	    let n = root;
540	    for (const seg of p.path.split(".")) { if (!n.children.has(seg)) n.children.set(seg, { children: new Map() }); n = n.children.get(seg)!; }
541	    n.param = p;
542	  }
543	  const out: string[] = [];
544	  const walk = (n: Node, ind: number) => {
545	    for (const [k, c] of n.children) {
546	      const pad = "  ".repeat(ind);
547	      if (c.param) {
548	        const p = c.param;
549	        const range = p.kind === "text" ? `text, max ${p.max} characters` : p.kind === "sound" ? "namespaced sound key" : `${fmtNum(p.min, p.kind)} to ${fmtNum(p.max, p.kind)}`;
550	        out.push(`${pad}# ${p.label} (${range})`);
551	        out.push(`${pad}${k}: ${p.kind === "text" || p.kind === "sound" ? ystr(String(p.value)) : fmtNum(Number(p.value), p.kind)}`);
552	      } else { out.push(`${pad}${k}:`); walk(c, ind + 1); }
553	    }
554	  };
555	  walk(root, 0);
556	  return out;
557	}
