562	export function nextConfigVersion(previous: string | undefined, valuesHash: string): number {
563	  if (!previous) return 1;
564	  const v = /^config_version:\s*(\d+)\s*$/m.exec(previous);
565	  const h = /^# designer-values: ([0-9a-f]{16})\s*$/m.exec(previous);
566	  const prev = v ? Math.max(1, Math.min(1_000_000, Number(v[1]))) : 1;
567	  return h && h[1] === valuesHash ? prev : prev + 1;
568	}
