644	      lines.push(``, r.kind === "shaped" ? `Recipe (crafting table): ${r.pattern.map((row) => `\`${row.replace(/ /g, "·")}\``).join(" / ")} with ${Object.keys(r.key).sort().map((k) => `${k} = ${show(r.key[k])}`).join(", ")}.` : `Recipe (shapeless): ${r.ingredients.map(show).join(" + ")}.`);
645	    }
646	    for (const l of d.acquisition?.loot ?? []) lines.push(`Found in ${l.table} loot (${Math.round(l.chance * 1000) / 10}% per roll).`);
647	    for (const l of d.acquisition?.drops ?? []) lines.push(`Dropped by ${bare(l.entity)} (${Math.round(l.chance * 1000) / 10}%).`);
648	    lines.push(``);
649	  }
650	  lines.push(`## Settings (config.yml)`, ``, `Change any of these in plugins/${name}/config.yml and run \`/${command} reload\` (values are clamped to the range shown):`, ``);
651	  for (const p of params) lines.push(`- \`${p.path}\` = ${p.kind === "text" || p.kind === "sound" ? `"${p.value}"` : fmtNum(Number(p.value), p.kind)}: ${p.label}${p.kind === "text" || p.kind === "sound" ? "" : ` (${fmtNum(p.min, p.kind)}-${fmtNum(p.max, p.kind)})`}`);
652	  lines.push(``, `## Commands and permissions`, ``, `- \`/${command} give <item> [player] [count]\` (${ns}.give, operators)`, `- \`/${command} list\`, \`/${command} params [item]\` (${ns}.command, operators)`, `- \`/${command} reload\` (${ns}.reload, operators)`);
653	  for (const d of designs) for (const p of d.permissions ?? []) lines.push(`- ${ns}.${p.node}: ${p.description} (default ${p.default})`);
654	  if (notes.length) lines.push(``, `## Good to know`, ``, ...notes.map((n) => `- ${n}`));
655	  lines.push(``);
656	  return lines.join("\n");
