660	export function compileDesigns(inputs: unknown[], ctx: CompileContext): CompileResult {
661	  const warnings: DzIssue[] = [];
662	  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
663	  if (!inputs.length) return { ok: false, errors: [{ path: "(mod)", code: "no_designs", message: "no design items" }], warnings };
664	  const v = validateDesigns(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
665	  const errors: DzIssue[] = [...v.errors];
666	  v.results.forEach((r, i) => {
667	    const id = (inputs[i] as { id?: string })?.id ?? `#${i}`;
668	    for (const e of r.errors) errors.push({ ...e, path: `${id}: ${e.path}` });
669	    for (const w of r.warnings) warnings.push({ ...w, path: `${id}: ${w.path}` });
670	  });
671	  if (!v.ok || errors.length) return { ok: false, errors, warnings };
672	  const designs = v.results.map((r) => (r as Extract<typeof r, { ok: true }>).design).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
673	  const fe = (v.results[0] as Extract<(typeof v.results)[number], { ok: true }>).features;
674	  const lower = ctx.pluginName.toLowerCase().replace(/_/g, "");
675	  const pkg = `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
676	  const main = camel(ctx.pluginName.replace(/^[a-z]/, (c) => c.toUpperCase())) || "DesignerMod";
677	  const mainCls = /^[A-Z]/.test(main) ? main : `M${main}`;
678	  const command = ctx.pluginName.toLowerCase().slice(0, 32);
679	  // a vanilla command root would be shadowed (or shadow vanilla): refuse (the exact version's command tree)
680	  if (vanillaIds("command", ctx.version).has(command)) return { ok: false, errors: [{ path: "pluginName", code: "command_clash", message: `/${command} is a vanilla command in Minecraft ${ctx.version}; pick another plugin name` }], warnings };
681	  const classes = new Map<string, string>();
682	  const claim = (cls: string, what: string): string | null => { if (classes.has(cls)) return classes.get(cls)!; classes.set(cls, what); return null; };
683	  const files: CompiledFile[] = [];
684	  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
685	  const add = (path: string, content: string, role: CompiledFile["role"]) => files.push({ path, content, sha256: sha256(content), role });
686	  for (const c of COMPONENTS) add(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
687	  add(`${dir}/${COMPAT_META.file}`, renderComponent(compatSource(fe), pkg), "compat");
688	  const itemClasses: string[] = [];
689	  const params: Param[] = [];
690	  const modelsApplied: string[] = [];
691	  for (const d of designs) {
692	    const icls = `${camel(d.id)}Item`;
693	    const clash = claim(icls, d.id);
694	    if (clash) return { ok: false, errors: [{ path: d.id, code: "class_clash", message: `items ${clash} and ${d.id} map to the same Java class ${icls}; rename one` }], warnings };
695	    const abCls: string[] = [];
696	    for (const ab of d.abilities) {
697	      const acls = `${camel(d.id)}${camel(ab.id)}`;
698	      const c2 = claim(acls, `${d.id}.${ab.id}`);
699	      if (c2) return { ok: false, errors: [{ path: `${d.id}.${ab.id}`, code: "class_clash", message: `${c2} and ${d.id}.${ab.id} map to the same Java class ${acls}; rename one` }], warnings };
700	      const g = abilityClass(pkg, d, ab, acls, ctx.namespace);
701	      add(`${dir}/abilities/${acls}.java`, g.source, "generated");
702	      abCls.push(acls);
703	      params.push(...g.params);
704	    }
705	    const modelOk = !!d.assets?.model && (!ctx.assets?.models || ctx.assets.models.includes(d.assets.model));
706	    if (modelOk) modelsApplied.push(d.assets!.model!);
707	    const it = itemClass(pkg, d, icls, abCls, ctx.namespace, fe, modelOk);
708	    add(`${dir}/items/${icls}.java`, it.source, "generated");
709	    itemClasses.push(icls);
710	    params.push(...it.params);
711	  }
712	  // config order = designParams order (item params first, then abilities), independent of the class emission order
713	  const ordered = designParams(designs);
714	  add(`${dir}/${mainCls}.java`, mainClass(pkg, mainCls, ctx.namespace, command, itemClasses, designs.map((d) => d.id), !!ctx.customHooks), "generated");
715	  const notes: string[] = [];
716	  for (const d of designs) if (d.assets?.model && fe.itemModel && !modelsApplied.includes(d.assets.model)) notes.push(`${d.name.text} keeps the ${bare(d.base).replace(/_/g, " ")} look: this mod has no custom model "${d.assets.model}".`);
717	  if (!fe.itemModel && designs.some((d) => d.assets?.model)) notes.push(`Custom item models need Minecraft 1.21.4 or newer: on ${fe.version} the items keep their base look.`);
718	  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "charge_release")) notes.push(`${d.name.text}: charge by holding sneak with it in your main hand, then ${d.abilities.find((a) => a.trigger.type === "charge_release" && a.trigger.release === "unsneak") ? "let go of sneak" : "right-click while still sneaking"}.`);
719	  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "item_consume") && !(CONSUMABLE_BASES as readonly string[]).includes(bare(d.base))) notes.push(`${d.name.text} must be eaten to work.`);
720	  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
721	  const valuesHash = designerValuesHash(ordered);
722	  const configVersion = ctx.configVersion !== undefined ? Math.max(1, Math.min(1_000_000, Math.round(ctx.configVersion))) : nextConfigVersion(ctx.previousConfig, valuesHash);
723	  const seed = randomSeedFor(ctx.namespace);
724	  add(`src/main/resources/config.yml`, configYml(ctx.pluginName, command, ordered, configVersion, valuesHash, seed), "resource");
725	  add(`src/main/resources/plugin.yml`, pluginYml(ctx.pluginName, `${pkg}.${mainCls}`, ctx.pluginVersion ?? "1.0.0", ctx.version, (ctx.description ?? `Custom items: ${designs.map((d) => d.name.text).join(", ")}`).slice(0, 200), command, ctx.namespace, designs), "resource");
726	  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
727	  const rd = readme(ctx.pluginName, command, ctx.namespace, designs, ordered, fe, notes);
728	  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(rd)}`);
729	  return {
730	    ok: true, files, readme: rd, readmeSha256: sha256(rd), hash, params: ordered, warnings, notes, pkg, modelsApplied, mainClass: `${pkg}.${mainCls}`, command, configVersion, designerValuesHash: valuesHash,
731	    features: fe, javacVerified: (JAVAC_VERIFIED_VERSIONS as readonly string[]).includes(ctx.version), compiler: COMPILER_VERSION, library: COMPONENT_LIBRARY_VERSION, libraryHash: libraryHash(), designs,
732	  };
733	}
