735	export const DESIGN_VERSION = DESIGN_SPEC_VERSION;
736	/** config.yml general.random_seed default: derived from the namespace (deterministic; the simulator uses the same). */
737	export const randomSeedFor = (namespace: string) => Number(BigInt.asUintN(31, BigInt("0x" + sha256(namespace).slice(0, 12))));
