13	/**
14	 * Component designer-config v1: config.yml with defaults from the jar, validation and CLAMPING to the design caps (a
15	 * hand-edited value can never exceed what the validator allows), and a migration hook: when the jar's config_version is
16	 * newer than the server's file (the design's parameters were edited in Cyrus), every value under "items" is reset to the
17	 * jar's new default (Cyrus is the source of truth for designer values), the old file is kept as config.yml.bak-v<N>,
18	 * other sections are kept. A missing or non-numeric value falls back to the jar default.
19	 */
20	public final class DesignConfig {
21	    private final JavaPlugin plugin;
22	    private FileConfiguration cfg;
23	    private Configuration defaults;
24	    private final List<String> notes = new ArrayList<>();
25	    private String migrated;
26	
27	    public DesignConfig(JavaPlugin plugin) { this.plugin = plugin; }
28	
29	    public void load() {
30	        plugin.saveDefaultConfig();
31	        plugin.reloadConfig();
32	        cfg = plugin.getConfig();
33	        defaults = cfg.getDefaults();
34	        notes.clear();
35	        migrated = null;
36	        if (defaults == null) return;
37	        int jarVersion = defaults.getInt("config_version", 1);
38	        Object raw = cfg.get("config_version", null);
39	        int fileVersion = raw instanceof Number n ? n.intValue() : 0;
40	        if (fileVersion < jarVersion) migrate(fileVersion, jarVersion);
41	    }
42	
43	    private void migrate(int from, int to) {
44	        File folder = plugin.getDataFolder();
45	        File file = new File(folder, "config.yml");
46	        try {
47	            if (file.isFile()) Files.copy(file.toPath(), new File(folder, "config.yml.bak-v" + from).toPath(), StandardCopyOption.REPLACE_EXISTING);
48	        } catch (IOException e) {
49	            plugin.getLogger().warning("could not back up config.yml before the update: " + e.getMessage());
50	        }
51	        int n = 0;
52	        for (String key : defaults.getKeys(true)) {
53	            if (!key.startsWith("items.") || defaults.isConfigurationSection(key)) continue;
54	            cfg.set(key, defaults.get(key));
55	            n++;
56	        }
57	        cfg.set("config_version", to);
58	        plugin.saveConfig();
59	        migrated = "config.yml migrated from version " + from + " to " + to + " (" + n + " designer values updated, backup config.yml.bak-v" + from + ")";
60	        plugin.getLogger().info(migrated);
61	    }
62	
63	    private double fallback(String path, double min) { return defaults == null ? min : defaults.getDouble(path, min); }
64	
65	    /** A number clamped to [min, max]; out-of-range values are clamped and noted. */
66	    public double num(String path, double min, double max) {
67	        double v;
68	        if (cfg.isDouble(path) || cfg.isInt(path) || cfg.isLong(path)) v = cfg.getDouble(path);
69	        else { v = fallback(path, min); if (cfg.contains(path, true)) notes.add(path + " is not a number, using " + v); }
70	        if (Double.isNaN(v) || Double.isInfinite(v)) v = fallback(path, min);
71	        if (v < min || v > max) {
72	            double c = Math.max(min, Math.min(max, v));
73	            notes.add("clamped " + path + " " + v + " -> " + c);
74	            return c;
75	        }
76	        return v;
77	    }
78	
79	    public long ticks(String path, long min, long max) { return Math.round(num(path, min, max)); }
80	
81	    public int integer(String path, int min, int max) { return (int) Math.round(num(path, min, max)); }
82	
83	    /** Plain text: control characters and section signs removed, cut to maxLen. */
84	    public String text(String path, int maxLen) {
85	        String s = cfg.getString(path);
86	        if (s == null) s = defaults == null ? "" : defaults.getString(path, "");
87	        StringBuilder b = new StringBuilder();
88	        for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (c >= ' ' && c != '§') b.append(c); }
89	        String t = b.toString();
90	        if (t.length() > maxLen) { notes.add("shortened " + path + " to " + maxLen + " characters"); t = t.substring(0, maxLen); }
91	        return t;
92	    }
