98	        String d = defaults == null ? "minecraft:ui.button.click" : defaults.getString(path, "minecraft:ui.button.click");
99	        notes.add(path + " is not a sound key, using " + d);
100	        return d;
101	    }
102	
103	    public long seed() { return cfg.getLong("general.random_seed", 0L); }
104	    public List<String> notes() { return notes; }
105	    public String migrated() { return migrated; }
106	}
