211	    private final Map<UUID, Long> lastClick = new HashMap<>();
212	    private Random random = new Random(0L);
213	
214	    public Designer(JavaPlugin plugin, String namespace) {
215	        this.plugin = plugin;
216	        this.namespace = namespace;
217	        this.identity = new ItemIdentity(namespace);
218	        this.projectileKey = new NamespacedKey(namespace, "projectile");
219	        this.tasks = new Tasks(plugin);
220	        this.config = new DesignConfig(plugin);
221	        this.effects = new Effects(this);
222	    }
223	
224	    public void enable(PluginCommand command, List<DesignItem> list) {
225	        for (DesignItem i : list) items.put(i.id(), i);
226	        reload();
227	        plugin.getServer().getPluginManager().registerEvents(new DesignListener(this), plugin);
228	        if (command != null) {
229	            DesignCommand c = new DesignCommand(this, command.getName());
230	            command.setExecutor(c);
231	            command.setTabCompleter(c);
232	        }
233	        for (DesignItem i : items.values()) {
234	            for (Recipe r : i.recipes()) {
235	                if (!(r instanceof Keyed k)) continue;
236	                if (Bukkit.addRecipe(r)) recipeKeys.add(k.getKey());
237	                else plugin.getLogger().warning("recipe " + k.getKey() + " was not added (a recipe with that key exists)");
238	            }
239	        }
240	    }
241	
242	    /** Reload config.yml (with migration + clamping) into every ability; restarts the interval timers. Returns notes. */
243	    public List<String> reload() {
244	        config.load();
245	        random = new Random(config.seed());
246	        for (DesignItem i : items.values()) i.load(config);
247	        tasks.cancelTimers();
248	        boolean passives = false;
249	        for (DesignItem i : items.values()) {
250	            for (Ability a : i.abilities(Trigger.HELD_INTERVAL)) tasks.timer(a.periodTicks(), () -> heldTick(i, a));
251	            passives |= i.hasPassives();
252	        }
253	        if (passives) tasks.timer(40L, this::passiveTick);
254	        List<String> notes = new ArrayList<>();
255	        if (config.migrated() != null) notes.add(config.migrated());
256	        for (String n : config.notes()) { notes.add(n); plugin.getLogger().warning("config: " + n); }
257	        return notes;
258	    }
259	
260	    private void heldTick(DesignItem item, Ability a) {
261	        for (Player p : Bukkit.getOnlinePlayers()) {
262	            if (p.isDead()) continue;
263	            boolean has = a.inventorySlot() ? identity.carries(p, item.id()) : identity.is(p.getInventory().getItemInMainHand(), item.id());
264	            if (has) a.fire(Activation.of(a, p, null, null, 0));
265	        }
266	    }
267	
268	    private void passiveTick() {
269	        for (Player p : Bukkit.getOnlinePlayers()) {
270	            if (p.isDead()) continue;
271	            String main = identity.idOf(p.getInventory().getItemInMainHand());
272	            String off = identity.idOf(p.getInventory().getItemInOffHand());
273	            for (DesignItem i : items.values()) if (i.hasPassives()) i.passives(p, i.id().equals(main), i.id().equals(off));
274	        }
275	    }
276	
277	    public void disable() {
278	        tasks.close();
279	        for (NamespacedKey k : recipeKeys) Bukkit.removeRecipe(k);
280	        recipeKeys.clear();
281	        cooldowns.clearAll();
282	        charges.clearAll();
283	        marks.clear();
284	        active.clear();
285	        chargeStart.clear();
286	        lastClick.clear();
287	    }
288	
289	    /** Drop everything a player had (quit, death). */
290	    public void forget(UUID id) {
291	        cooldowns.clear(id);
292	        charges.clear(id);
293	        marks.removeOwner(id);
294	        chargeStart.remove(id);
295	        lastClick.remove(id);
296	        active.remove(id);
297	    }
298	
299	    /** Server tick (Paper Bukkit.getCurrentTick): cooldowns, charges, marks and charge timers count ticks. */
300	    public long now() { return Bukkit.getCurrentTick(); }
301	
302	    /** Re-entry guard: while a player's activation runs, events it causes do not trigger abilities. */
303	    boolean enter(Player p) { return active.add(p.getUniqueId()); }
304	    void exit(Player p) { active.remove(p.getUniqueId()); }
305	    public boolean busy(Player p) { return active.contains(p.getUniqueId()); }
306	
307	    /** At most one click activation per player per tick (the client can send two interact packets for one click). */
308	    boolean firstClickThisTick(Player p) { long t = now(); Long last = lastClick.put(p.getUniqueId(), t); return last == null || last != t; }
309	
310	    void startCharge(UUID id) { chargeStart.put(id, now()); }
311	    Long chargeStart(UUID id) { return chargeStart.get(id); }
312	    void clearCharge(UUID id) { chargeStart.remove(id); }
313	
314	    /** Run a step later for this activation (counts against its task budget; skipped if the player left). */
315	    public boolean later(Activation a, long delay, Runnable step) {
316	        if (!a.budget().task()) return false;
317	        return tasks.later(delay, () -> {
318	            if (!a.valid() || !enter(a.player())) return;
319	            try { step.run(); } finally { exit(a.player()); }
320	        });
321	    }
322	
323	    public DesignItem held(Player p) { String id = identity.idOf(p.getInventory().getItemInMainHand()); return id == null ? null : items.get(id); }
324	    public DesignItem item(String id) { return items.get(id); }
325	    public Ability ability(String itemId, String abilityId) { DesignItem i = items.get(itemId); return i == null ? null : i.ability(abilityId); }
326	    public Collection<DesignItem> items() { return items.values(); }
327	    public List<NamespacedKey> recipeKeys() { return recipeKeys; }
328	    public JavaPlugin plugin() { return plugin; }
329	    public String namespace() { return namespace; }
330	    public ItemIdentity identity() { return identity; }
331	    public NamespacedKey projectileKey() { return projectileKey; }
332	    public Cooldowns cooldowns() { return cooldowns; }
333	    public Charges charges() { return charges; }
334	    public Marks marks() { return marks; }
335	    public Tasks tasks() { return tasks; }
336	    public Effects effects() { return effects; }
337	    public Random random() { return random; }
338	}
