371	/**
372	 * Component designer-listener v1 (the safe listener base): every trigger in one place. Observation handlers run at
373	 * MONITOR and never change or cancel the event; they skip events another plugin cancelled (ignoreCancelled), except
374	 * PlayerInteractEvent, which Bukkit delivers already "cancelled" for right-clicks in the air: there the item-use
375	 * result is checked instead (DENY = another plugin blocked it). The two handlers that ADD items (loot, mob drops) run at
376	 * NORMAL. Nothing here cancels another plugin's event.
377	 */
378	public final class DesignListener implements Listener {
379	    private final Designer d;
380	
381	    DesignListener(Designer d) { this.d = d; }
382	
383	    @EventHandler(priority = EventPriority.MONITOR)
384	    public void onInteract(PlayerInteractEvent e) {
385	        if (e.getHand() != EquipmentSlot.HAND) return;
386	        if (e.getAction() != Action.RIGHT_CLICK_AIR && e.getAction() != Action.RIGHT_CLICK_BLOCK) return;
387	        if (e.useItemInHand() == Event.Result.DENY) return;
388	        click(e.getPlayer(), null);
389	    }
390	
391	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
392	    public void onInteractEntity(PlayerInteractEntityEvent e) {
393	        if (e.getHand() != EquipmentSlot.HAND) return;
394	        click(e.getPlayer(), e.getRightClicked());
395	    }
396	
397	    private void click(Player p, Entity clicked) {
398	        if (d.busy(p)) return;
399	        DesignItem item = d.held(p);
400	        if (item == null || !d.firstClickThisTick(p)) return;
401	        if (p.isSneaking()) {
402	            boolean sneakAbility = false;
403	            Long start = d.chargeStart(p.getUniqueId());
404	            for (Ability a : item.abilities(Trigger.CHARGE_RELEASE)) {
405	                if (!a.releaseOnRightClick()) continue;
406	                sneakAbility = true;
407	                if (start == null) continue;
408	                long held = d.now() - start;
409	                if (held < a.minChargeTicks()) continue;
410	                d.clearCharge(p.getUniqueId());
411	                aim(a, p, clicked, a.chargeFraction(held));
412	            }
413	            List<Ability> sneak = item.abilities(Trigger.SNEAK_RIGHT_CLICK);
414	            for (Ability a : sneak) aim(a, p, clicked, 0);
415	            if (sneakAbility || !sneak.isEmpty()) return;
416	        }
417	        for (Ability a : item.abilities(Trigger.RIGHT_CLICK)) aim(a, p, clicked, 0);
