420	    /** Target + point for click triggers: the right-clicked entity, else a ray trace within the ability's targetRange. */
421	    private void aim(Ability a, Player p, Entity clicked, double charge) {
422	        Entity target = null;
423	        Location point = null;
424	        if (a.targetRange() > 0) {
425	            if (clicked instanceof LivingEntity && clicked.getLocation().distance(p.getLocation()) <= a.targetRange() + 1) { target = clicked; point = clicked.getLocation(); }
426	            else { RayTraceResult r = Targets.look(p, a.targetRange()); target = Targets.lookEntity(r); point = Targets.lookPoint(p, r, a.targetRange()); }
