429	    }
430	
431	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
432	    public void onHit(EntityDamageByEntityEvent e) {
433	        if (!(e.getDamager() instanceof Player p) || !(e.getEntity() instanceof LivingEntity t)) return;
434	        if (e.getCause() != EntityDamageEvent.DamageCause.ENTITY_ATTACK || d.busy(p)) return;
435	        DesignItem item = d.held(p);
436	        if (item == null) return;
437	        for (Ability a : item.abilities(Trigger.LEFT_CLICK_HIT_ENTITY)) a.fire(Activation.of(a, p, t, t.getLocation(), 0));
438	    }
439	
440	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
441	    public void onDeath(EntityDeathEvent e) {
442	        LivingEntity dead = e.getEntity();
443	        Player killer = dead.getKiller();
444	        if (killer != null && killer != dead && !d.busy(killer)) {
445	            DesignItem item = d.held(killer);
446	            if (item != null) for (Ability a : item.abilities(Trigger.KILL_ENTITY)) a.fire(Activation.of(a, killer, dead, dead.getLocation(), 0));
447	        }
448	        d.marks().removeTarget(dead.getUniqueId());
449	        if (dead instanceof Player p) {
450	            for (DesignItem i : d.items()) {
451	                List<Ability> list = i.abilities(Trigger.DEATH);
452	                if (!list.isEmpty() && d.identity().carries(p, i.id())) for (Ability a : list) a.fire(Activation.of(a, p, null, null, 0));
453	            }
454	            d.forget(p.getUniqueId());
455	        }
456	    }
457	
458	    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
459	    public void onDrops(EntityDeathEvent e) {
460	        if (e.getEntity() instanceof Player || e.getEntity().getKiller() == null) return;
461	        String type = e.getEntity().getType().getKey().getKey();
462	        for (DesignItem i : d.items()) i.drops(type, e.getDrops(), d.random());
463	    }
464	
465	    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
466	    public void onLoot(LootGenerateEvent e) {
467	        String table = e.getLootTable().getKey().toString();
468	        for (DesignItem i : d.items()) i.loot(table, e.getLoot(), d.random());
469	    }
470	
471	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
472	    public void onProjectile(ProjectileHitEvent e) {
473	        Projectile pr = e.getEntity();
474	        String tagged = pr.getPersistentDataContainer().get(d.projectileKey(), PersistentDataType.STRING);
475	        if (tagged == null) return;
476	        int bar = tagged.indexOf('|');
477	        if (bar > 0 && pr.getShooter() instanceof Player p && p.isOnline() && !d.busy(p)) {
478	            DesignItem item = d.item(tagged.substring(0, bar));
479	            String tag = tagged.substring(bar + 1);
480	            if (item != null) {
481	                Entity hit = e.getHitEntity();
482	                Location point = hit != null ? hit.getLocation() : e.getHitBlock() != null ? e.getHitBlock().getLocation().add(0.5, 1.0, 0.5) : pr.getLocation();
483	                LivingEntity t = hit instanceof LivingEntity le && hit != p ? le : null;
484	                for (Ability a : item.abilities(Trigger.PROJECTILE_HIT)) if (tag.equals(a.projectileTag())) a.fire(Activation.of(a, p, t, point, 0));
485	            }
486	        }
487	        if (pr instanceof AbstractArrow) pr.remove();
488	    }
489	
490	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
491	    public void onSneak(PlayerToggleSneakEvent e) {
492	        Player p = e.getPlayer();
493	        DesignItem item = d.held(p);
494	        if (e.isSneaking()) {
495	            if (item != null && !item.abilities(Trigger.CHARGE_RELEASE).isEmpty()) d.startCharge(p.getUniqueId());
496	            else d.clearCharge(p.getUniqueId());
497	            return;
498	        }
499	        Long start = d.chargeStart(p.getUniqueId());
500	        d.clearCharge(p.getUniqueId());
501	        if (item == null || start == null || d.busy(p)) return;
502	        long held = d.now() - start;
503	        for (Ability a : item.abilities(Trigger.CHARGE_RELEASE)) if (!a.releaseOnRightClick() && held >= a.minChargeTicks()) aim(a, p, null, a.chargeFraction(held));
504	    }
505	
506	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
507	    public void onHeld(PlayerItemHeldEvent e) { d.clearCharge(e.getPlayer().getUniqueId()); }
508	
509	    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
510	    public void onConsume(PlayerItemConsumeEvent e) {
511	        Player p = e.getPlayer();
512	        if (d.busy(p)) return;
513	        String id = d.identity().idOf(e.getItem());
514	        DesignItem item = id == null ? null : d.item(id);
515	        if (item == null) return;
516	        for (Ability a : item.abilities(Trigger.ITEM_CONSUME)) a.fire(Activation.of(a, p, null, null, 0));
517	    }
518	
519	    @EventHandler(priority = EventPriority.MONITOR)
520	    public void onJoin(PlayerJoinEvent e) {
521	        Player p = e.getPlayer();
522	        if (!d.recipeKeys().isEmpty()) p.discoverRecipes(d.recipeKeys());
