525	            if (!list.isEmpty() && d.identity().carries(p, i.id())) for (Ability a : list) a.fire(Activation.of(a, p, null, null, 0));
526	        }
527	    }
528	
529	    @EventHandler(priority = EventPriority.MONITOR)
530	    public void onQuit(PlayerQuitEvent e) { d.forget(e.getPlayer().getUniqueId()); }
531	}
