555	 * Console can use every subcommand (give needs a player name there).
556	 */
557	public final class DesignCommand implements CommandExecutor, TabCompleter {
558	    private static final List<String> SUBS = List.of("give", "list", "params", "reload");
559	    private final Designer d;
560	    private final String label;
561	
562	    DesignCommand(Designer d, String label) { this.d = d; this.label = label; }
563	
564	    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }
565	
566	    private boolean allowed(CommandSender s, String node) {
567	        if (s.hasPermission(d.namespace() + "." + node)) return true;
568	        say(s, "You don't have permission for that.", NamedTextColor.RED);
569	        return false;
570	    }
571	
572	    @Override
573	    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
574	        if (args.length == 0) {
575	            List<String> ids = new ArrayList<>();
576	            for (DesignItem i : d.items()) ids.add(i.id());
577	            say(sender, d.plugin().getName() + " items: " + String.join(", ", ids) + ". Use /" + label + " give <item> [player] [count], /" + label + " list, /" + label + " params, /" + label + " reload", NamedTextColor.GOLD);
578	            return true;
579	        }
580	        switch (args[0].toLowerCase(Locale.ROOT)) {
581	            case "give" -> give(sender, args);
582	            case "list" -> list(sender);
583	            case "params" -> params(sender, args);
584	            case "reload" -> {
585	                if (!allowed(sender, "reload")) return true;
586	                List<String> notes = d.reload();
587	                say(sender, d.plugin().getName() + " config reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
588	                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
589	            }
590	            default -> say(sender, "Unknown subcommand. Use /" + label + " give, list, params or reload.", NamedTextColor.RED);
591	        }
592	        return true;
593	    }
594	
595	    private void give(CommandSender sender, String[] args) {
596	        if (!allowed(sender, "give")) return;
597	        if (args.length < 2) { say(sender, "Usage: /" + label + " give <item> [player] [count]", NamedTextColor.RED); return; }
598	        DesignItem item = d.item(args[1].toLowerCase(Locale.ROOT));
599	        if (item == null) { say(sender, "Unknown item " + args[1] + ".", NamedTextColor.RED); return; }
600	        Player target;
601	        if (args.length >= 3) {
602	            target = Bukkit.getPlayerExact(args[2]);
603	            if (target == null) { say(sender, "Player " + args[2] + " is not online.", NamedTextColor.RED); return; }
604	        } else if (sender instanceof Player p) target = p;
605	        else { say(sender, "Usage from the console: /" + label + " give <item> <player> [count]", NamedTextColor.RED); return; }
606	        int count = 1;
607	        if (args.length >= 4) {
608	            try { count = Math.max(1, Math.min(64, Integer.parseInt(args[3]))); }
609	            catch (NumberFormatException e) { say(sender, "Count must be a number from 1 to 64.", NamedTextColor.RED); return; }
610	        }
611	        for (int i = 0; i < count; i++) for (ItemStack left : target.getInventory().addItem(item.create()).values()) target.getWorld().dropItemNaturally(target.getLocation(), left);
612	        say(sender, "Gave " + count + " x " + item.id() + " to " + target.getName() + ".", NamedTextColor.GREEN);
