    private static boolean alive(LivingEntity t) { return t != null && t.isValid() && !t.isDead(); }

    public Location self(Activation a) { return a.player().getLocation().add(0, 1.0, 0); }
    public Location target(Activation a) { Entity t = a.target(); return t == null || !t.isValid() ? null : t.getLocation().add(0, t.getHeight() / 2.0, 0); }
