            if (!manualCharges && maxCharges > 0 && chargesLeft(p) < 1) {
                if (feedback) p.sendActionBar(Component.text(name + ": no charges", NamedTextColor.GRAY));
                return false;
            }
            if (!check(a)) return false;
            if (!manualCooldown && cooldownTicks > 0) startCooldown(p, cooldownTicks);
            if (!manualCharges && maxCharges > 0) spendCharges(p, 1);
            run(a);
            return true;
        } finally {
            d.exit(p);
        }
    }
}
