  const tex = `${n} custom texture${n === 1 ? "" : "s"}`;
  if (n && a.status === "ready") lines.push(`Includes ${tex}; players accept a resource pack on join.`);
  else if (n && a.status === "unhosted") lines.push(`Includes ${tex} in a resource pack; delivery to servers is not switched on yet, so players don't see them yet.`);
  else if (n && a.status === "failed") lines.push(`Has ${tex}, but its resource pack could not be built for this version, so players see vanilla looks.`);
  // Sound slice: only events that are really in the pack count; designed-but-unrendered sounds are said plainly.
