  if (m && a.status === "ready") lines.push(`Includes ${sw}; players accept a resource pack on join.`);
  else if (m && a.status === "unhosted") lines.push(`Includes ${sw} in a resource pack; delivery to servers is not switched on yet, so players don't hear them yet.`);
  else if (m && a.status === "failed") lines.push(`Has ${sw}, but its resource pack could not be built for this version, so players hear vanilla sounds.`);
  if (!m && (a.soundRender === "off" || a.soundRender === "failed")) lines.push("Custom sounds are designed for this mod but not rendered yet, so players hear vanilla sounds for now.");
