  const cre = a.creatures ?? [];
  const k = cre.length;
  if (k) {
    lines.push(`Includes ${k} animated custom creature${k === 1 ? "" : "s"} (${cre.map((c) => c.name.replace(/_/g, " ")).slice(0, 4).join(", ")}); requires the Nxeon-managed BetterModel plugin on the server (Minecraft 26.x), and players accept a resource pack on join.`);
    lines.push("Bedrock players (Geyser/Floodgate) see the plain base mob: animated creatures are a Java Edition feature.");
  }
  const isSound = (d: { kind?: string }) => d.kind === "sound";
  const isCreature = (d: { kind?: string }) => d.kind === "creature";
  const droppedSounds = a.dropped.filter(isSound);
  const droppedCreatures = a.dropped.filter(isCreature);
  const droppedTex = a.dropped.filter((d) => !isSound(d) && !isCreature(d));
  if (droppedCreatures.length) lines.push(`${droppedCreatures.length} requested creature${droppedCreatures.length === 1 ? " was" : "s were"} left out after failing Nxeon's creature checks.`);
  if (droppedTex.length) lines.push(`${droppedTex.length} requested texture${droppedTex.length === 1 ? " was" : "s were"} left out after failing Nxeon's texture checks.`);
  if (droppedSounds.length) lines.push(`${droppedSounds.length} requested sound${droppedSounds.length === 1 ? " was" : "s were"} left out after failing Nxeon's sound checks.`);
  if (n) lines.push("Bedrock players (Geyser/Floodgate) see vanilla looks: the custom textures are a Java Edition resource pack.");
  if (m) lines.push("Bedrock players (Geyser/Floodgate) hear vanilla sounds: the custom sounds are a Java Edition resource pack.");
  return lines;
}

