// Cyrus R3 gameplay designers, part 2: the MENU and QUEST design IR. Same philosophy as the item designer (../spec.ts):
// typed data, every number capped (GAMEPLAY_CAPS; the JSON Schema carries them, the runtime config loader clamps to the
// same numbers), bounded structure (GAMEPLAY_LIMITS), a closed set of actions / objectives / rewards and no way to express
// code or commands. A mod's design files stay `assets/designs/<id>.json` (the existing `design` asset kind); the top-level
// `kind` discriminator says what a file is: absent or "item" = ItemDesign (unchanged, byte for byte), "menu" = MenuDesign,
// "quest" = QuestDesign. Identifiers share one id space per mod (the file name is the id).
//
// Validation never throws. `validateGameplay` validates a whole mod (items + menus + quests) with the cross-file checks:
// references, prerequisite cycles, reachability (every menu can be opened, every quest can be started), dupe/arbitrage
// loops across the shop graph, reward farms, and the worst-case size of a player's stored progress.
import { z } from "zod";
import { NAMESPACE_RE } from "../../engine-core/identifiers";
import { isVanilla, missingIdReason } from "../../datapack/versions";
import {
  BANNED_BASES, CAPS, Color, DESIGN_LIMITS, EFFECTS, KEY, Key, NsRef, PermissionSchema, SoundKey, StyledText, TARGET_KINDS, Text, VanillaRef,
  TRIGGER_HAS_TARGET, designFeatures, validateDesigns, type DesignFeatures, type DesignValidation, type DzIssue, type ItemDesign,
} from "../spec";

export const GAMEPLAY_SPEC_VERSION = 1;
export type DesignKind = "item" | "menu" | "quest";

/** Per-mod structure limits (inclusive). */
export const GAMEPLAY_LIMITS = {
  maxMenus: 8, maxQuests: 16, maxButtons: 54, maxListSlots: 45, maxFixedEntries: 54, maxConfigDefaults: 54, maxConfigEntries: 270,
  maxPages: 10, maxClickActions: 8, maxChoices: 5, maxDialogueLines: 6, maxLore: 6, maxPermissions: 8,
  maxSteps: 8, maxObjectives: 3, maxBranches: 3, maxBranchSteps: 4, maxRewards: 8, maxRequires: 4, maxBack: 8,
  /** Active quests per player: config general.max_active_quests is clamped to this range. */
  activeQuests: [1, 5] as const,
  /** Characters of one player's stored progress for one mod (PersistentDataContainer string). */
  maxProgressChars: 2048,
  /** All design files of one mod (items + menus + quests). */
  maxDesignFiles: DESIGN_LIMITS.maxItems + 8 + 16,
  maxSpecBytes: 64 * 1024,
} as const;

/** Hard caps on every gameplay number (inclusive). */
export const GAMEPLAY_CAPS = {
  rows: [1, 6],
  slot: [0, 53],
  iconAmount: [1, 64],
  itemCost: [1, 2304], // 36 stacks
  xpLevelCost: [1, 1000],
  economyCost: [0.01, 1000000],
  giveCount: [1, 64],
  heal: [0, 20],
  potionTicks: [1, 1200],
  amplifier: [0, 4],
  volume: [0, 2],
  pitch: [0.5, 2],
  killCount: [1, 1000],
  collectCount: [1, 2304],
  craftCount: [1, 1000],
  breakCount: [1, 10000],
  surviveSeconds: [10, 7200],
  visitRadius: [1, 64],
  coord: [-30000000, 30000000],
  coordY: [-2048, 2048],
  repeatCooldownSeconds: [0, 2592000], // 30 days
  timeLimitSeconds: [60, 604800],
  xpPoints: [1, 100000],
  xpLevels: [1, 100],
  configAmount: [1, 64],
  clickCooldownTicks: [2, 40],
} as const satisfies Record<string, readonly [number, number]>;
export type GpCapName = keyof typeof GAMEPLAY_CAPS;
/** Below this repeat cooldown a quest that can be completed instantly (talk / visit only) must not give items or XP. */
export const FARM_COOLDOWN_SECONDS = 60;
export const REPEAT_DEFAULTS = { once: 0, repeatable: 0, daily: 86400, weekly: 604800 } as const;

const capNum = (c: GpCapName) => z.number().min(GAMEPLAY_CAPS[c][0]).max(GAMEPLAY_CAPS[c][1]);
const capInt = (c: GpCapName) => z.number().int().min(GAMEPLAY_CAPS[c][0]).max(GAMEPLAY_CAPS[c][1]);
const Node = z.string().regex(/^[a-z0-9_]+(\.[a-z0-9_]+){0,3}$/, "a permission node like vip or shop.vip");
const ItemRef = z.union([VanillaRef, Key]);

// ------------------------------------------------------------------------------------------------------------- icons
export const IconSchema = z.strictObject({
  /** A vanilla item to show, OR `item`: one of this mod's design items (shown as a display copy without its identity). */
  material: VanillaRef.optional(),
  item: Key.optional(),
  /** An item model of this mod (`<ns>:<texture name>`, 1.21.4+). */
  model: NsRef.optional(),
  name: StyledText.optional(),
  lore: z.array(StyledText).max(GAMEPLAY_LIMITS.maxLore).optional(),
  amount: capInt("iconAmount").optional(),
  glint: z.boolean().optional(),
});
export type Icon = z.infer<typeof IconSchema>;

// ------------------------------------------------------------------------------------------------------------- costs
export const CostSchema = z.discriminatedUnion("type", [
  /** Items taken from the player's inventory: a vanilla item without a design identity, or one of this mod's design items. */
  z.strictObject({ type: z.literal("item"), item: ItemRef, count: capInt("itemCost") }),
  z.strictObject({ type: z.literal("xp_levels"), levels: capInt("xpLevelCost") }),
  /** Money through the Vault API (only when Vault + an economy plugin are on the server; otherwise the click is refused with a message). */
  z.strictObject({ type: z.literal("economy"), amount: capNum("economyCost") }),
]);
export type Cost = z.infer<typeof CostSchema>;

// ------------------------------------------------------------------------------------------------------ menu actions
/** A SUBSET of the ability graph actions (messages, sound, give, potion, heal on the clicking player) + menu/quest actions. */
export const MenuActionSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("open_menu"), menu: Key }),
  z.strictObject({ type: z.literal("close") }),
  z.strictObject({ type: z.literal("back") }),
  z.strictObject({ type: z.literal("next_page") }),
  z.strictObject({ type: z.literal("prev_page") }),
  z.strictObject({ type: z.literal("give_item"), item: ItemRef, count: capInt("giveCount").optional() }),
  z.strictObject({ type: z.literal("send_message"), text: Text(120), color: Color.optional() }),
  z.strictObject({ type: z.literal("actionbar"), text: Text(120), color: Color.optional() }),
  z.strictObject({ type: z.literal("play_sound"), sound: SoundKey, volume: capNum("volume").optional(), pitch: capNum("pitch").optional() }),
  z.strictObject({ type: z.literal("potion_effect"), effect: z.enum(EFFECTS), durationTicks: capInt("potionTicks"), amplifier: capInt("amplifier").optional() }),
  z.strictObject({ type: z.literal("heal"), amount: capNum("heal") }),
  /** Fire one ability of one of this mod's design items for the clicking player (its own cooldown/charges/conditions apply). */
  z.strictObject({ type: z.literal("run_ability"), item: Key, ability: Key }),
  z.strictObject({ type: z.literal("start_quest"), quest: Key }),
  z.strictObject({ type: z.literal("abandon_quest"), quest: Key }),
  z.strictObject({ type: z.literal("choose_branch"), quest: Key, branch: Key }),
  z.strictObject({ type: z.literal("open_quest_log") }),
]);
export type MenuAction = z.infer<typeof MenuActionSchema>;
export const MENU_ACTION_TYPES = MenuActionSchema.options.map((o) => o.shape.type.value);

const Clickable = {
  icon: IconSchema,
  actions: z.array(MenuActionSchema).max(GAMEPLAY_LIMITS.maxClickActions).optional(),
  cost: CostSchema.optional(),
  /** `<ns>.<permission>` needed to use it (declare it in permissions). */
  permission: Node.optional(),
  /** Without the permission: hide it (true) or show it locked (default). */
  hideWithoutPermission: z.boolean().optional(),
};
export const ButtonSchema = z.strictObject({ slot: capInt("slot"), ...Clickable });
export const EntrySchema = z.strictObject(Clickable);
export type Button = z.infer<typeof ButtonSchema>;
export type Entry = z.infer<typeof EntrySchema>;

/** A config-list entry: owner-editable shop line (lists.<menu id> in config.yml): buy `amount` x `material` for `price` of the list's currency. */
export const ConfigEntrySchema = z.strictObject({ material: VanillaRef, amount: capInt("configAmount"), price: z.number().min(0).max(1000000), name: Text(40).optional() });
export type ConfigEntry = z.infer<typeof ConfigEntrySchema>;
export const CurrencySchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("item"), item: ItemRef }),
  z.strictObject({ type: z.literal("xp_levels") }),
  z.strictObject({ type: z.literal("economy") }),
  z.strictObject({ type: z.literal("free") }),
]);
export const ListSchema = z.strictObject({
  /** Slots of one page (page size = slots.length). */
  slots: z.array(capInt("slot")).min(1).max(GAMEPLAY_LIMITS.maxListSlots),
  prev: z.strictObject({ slot: capInt("slot"), icon: IconSchema }),
  next: z.strictObject({ slot: capInt("slot"), icon: IconSchema }),
  /** A typed source: a fixed list of entries (each a full clickable), or a config list the server owner edits. Never code. */
  source: z.discriminatedUnion("type", [
    z.strictObject({ type: z.literal("fixed"), entries: z.array(EntrySchema).min(1).max(GAMEPLAY_LIMITS.maxFixedEntries) }),
    z.strictObject({ type: z.literal("config"), currency: CurrencySchema, entries: z.array(ConfigEntrySchema).max(GAMEPLAY_LIMITS.maxConfigDefaults) }),
  ]),
});
export type MenuList = z.infer<typeof ListSchema>;

const OpenWith = z.strictObject({
  /** `/<mod> menu <id>` (default true). */
  command: z.boolean().optional(),
  /** Right-click with this design item (of this mod) opens the menu. */
  item: Key.optional(),
  /** Right-clicking an entity tagged `<ns>.npc.<menu id>` (vanilla /tag) opens it: a quest NPC. */
  npc: z.boolean().optional(),
});
const MenuCommon = {
  schemaVersion: z.literal(GAMEPLAY_SPEC_VERSION),
  kind: z.literal("menu"),
  id: Key,
  title: Text(32),
  permission: Node.optional(),
  permissions: z.array(PermissionSchema).max(GAMEPLAY_LIMITS.maxPermissions).optional(),
  openWith: OpenWith.optional(),
};
export const ChestMenuSchema = z.strictObject({
  ...MenuCommon,
  style: z.literal("chest"),
  rows: capInt("rows"),
  filler: VanillaRef.optional(),
  buttons: z.array(ButtonSchema).max(GAMEPLAY_LIMITS.maxButtons).optional(),
  list: ListSchema.optional(),
});
export const ChoiceSchema = z.strictObject({ ...Clickable, icon: IconSchema });
export const DialogueMenuSchema = z.strictObject({
  ...MenuCommon,
  /** A dialogue: speaker + lines + up to 5 choices, laid out by the DialogueMenu component (3 rows). */
  style: z.literal("dialogue"),
  speaker: StyledText,
  speakerIcon: IconSchema.optional(),
  lines: z.array(Text(80)).min(1).max(GAMEPLAY_LIMITS.maxDialogueLines),
  choices: z.array(ChoiceSchema).min(1).max(GAMEPLAY_LIMITS.maxChoices),
});
export const MenuDesignSchema = z.discriminatedUnion("style", [ChestMenuSchema, DialogueMenuSchema]);
export type MenuDesign = z.infer<typeof MenuDesignSchema>;
export type ChestMenu = z.infer<typeof ChestMenuSchema>;
export type DialogueMenu = z.infer<typeof DialogueMenuSchema>;

// --------------------------------------------------------------------------------------------------------- quests
export const ObjectiveSchema = z.discriminatedUnion("type", [
  /** Kill mobs/players: an exact vanilla entity type and/or kinds (player/hostile/animal/living). */
  z.strictObject({ type: z.literal("kill_entity"), entity: VanillaRef.optional(), kinds: z.array(z.enum(TARGET_KINDS)).max(4).optional(), count: capInt("killCount") }),
  /** Have `count` in the inventory (checked on pickup, inventory close, the 2-second timer) or pick up `count`; take: removed when the step completes. */
  z.strictObject({ type: z.literal("collect_item"), item: ItemRef, count: capInt("collectCount"), mode: z.enum(["inventory", "pickup"]), take: z.boolean().optional() }),
  z.strictObject({ type: z.literal("craft_item"), item: ItemRef, count: capInt("craftCount") }),
  z.strictObject({ type: z.literal("visit_location"), world: z.string().regex(/^[A-Za-z0-9_./-]{1,64}$/), x: capNum("coord"), y: capNum("coordY"), z: capNum("coord"), radius: capNum("visitRadius") }),
  /** Break blocks (blocks a player placed since the server started are not counted, up to 4096 remembered). */
  z.strictObject({ type: z.literal("break_block"), block: VanillaRef, count: capInt("breakCount") }),
  /** Open a dialogue menu of this mod (by command, NPC, item or another menu). */
  z.strictObject({ type: z.literal("talk"), menu: Key }),
  /** Stay online and alive for `seconds` while the step is active (death restarts the count). */
  z.strictObject({ type: z.literal("survive"), seconds: capInt("surviveSeconds") }),
]);
export type Objective = z.infer<typeof ObjectiveSchema>;
export const OBJECTIVE_TYPES = ObjectiveSchema.options.map((o) => o.shape.type.value);

export const RewardSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("give_item"), item: ItemRef, count: capInt("giveCount").optional() }),
  z.strictObject({ type: z.literal("xp"), points: capInt("xpPoints").optional(), levels: capInt("xpLevels").optional() }),
  z.strictObject({ type: z.literal("potion_effect"), effect: z.enum(EFFECTS), durationTicks: capInt("potionTicks"), amplifier: capInt("amplifier").optional() }),
  /** An advancement of THIS project's data pack (`<ns>:<path>`; the data pack route must already have it). */
  z.strictObject({ type: z.literal("advancement"), advancement: NsRef }),
  z.strictObject({ type: z.literal("run_ability"), item: Key, ability: Key }),
  z.strictObject({ type: z.literal("send_message"), text: Text(120), color: Color.optional() }),
]);
export type Reward = z.infer<typeof RewardSchema>;

export const StepSchema = z.strictObject({ id: Key, text: Text(80), objectives: z.array(ObjectiveSchema).min(1).max(GAMEPLAY_LIMITS.maxObjectives) });
export type Step = z.infer<typeof StepSchema>;
export const BranchSchema = z.strictObject({ id: Key, label: StyledText, icon: IconSchema.optional(), steps: z.array(StepSchema).min(1).max(GAMEPLAY_LIMITS.maxBranchSteps), rewards: z.array(RewardSchema).max(GAMEPLAY_LIMITS.maxRewards).optional() });
export type Branch = z.infer<typeof BranchSchema>;

export const QuestDesignSchema = z.strictObject({
  schemaVersion: z.literal(GAMEPLAY_SPEC_VERSION),
  kind: z.literal("quest"),
  id: Key,
  title: Text(40),
  description: Text(120).optional(),
  icon: IconSchema.optional(),
  /** Quests that must have been completed first (a chain). */
  requires: z.array(Key).max(GAMEPLAY_LIMITS.maxRequires).optional(),
  /** "command" (default): /<mod> quests start <id>, the quest log or a menu; "menu": only a menu/dialogue start_quest action. */
  start: z.enum(["command", "menu"]).optional(),
  repeat: z.strictObject({ mode: z.enum(["once", "repeatable", "daily", "weekly"]), cooldownSeconds: capInt("repeatCooldownSeconds").optional() }).optional(),
  steps: z.array(StepSchema).min(1).max(GAMEPLAY_LIMITS.maxSteps),
  /** After the main steps the player picks one branch in a choice menu (or a dialogue choose_branch action). */
  branches: z.strictObject({ prompt: Text(60).optional(), options: z.array(BranchSchema).min(2).max(GAMEPLAY_LIMITS.maxBranches) }).optional(),
  rewards: z.array(RewardSchema).max(GAMEPLAY_LIMITS.maxRewards).optional(),
  failure: z.strictObject({ onDeath: z.enum(["keep", "reset_step", "fail"]).optional(), timeLimitSeconds: capInt("timeLimitSeconds").optional(), abandon: z.boolean().optional() }).optional(),
  /** Progress on the actionbar when it changes (default true). */
  progressBar: z.boolean().optional(),
  permission: Node.optional(),
  permissions: z.array(PermissionSchema).max(GAMEPLAY_LIMITS.maxPermissions).optional(),
});
export type QuestDesign = z.infer<typeof QuestDesignSchema>;
export type GameplayDesign = ItemDesign | MenuDesign | QuestDesign;

export function gameplayJsonSchema(): Record<string, unknown> {
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    title: "Cyrus gameplay designs v1 (menus and quests); item designs: designer.v1.schema.json",
    oneOf: [z.toJSONSchema(MenuDesignSchema, { io: "input", reused: "ref" }), z.toJSONSchema(QuestDesignSchema, { io: "input", reused: "ref" })],
  };
}

/** The kind of a design file (absent kind = item). null = not an object or an unknown kind. */
export function designKind(input: unknown): DesignKind | null {
  if (!input || typeof input !== "object" || Array.isArray(input)) return null;
  const k = (input as { kind?: unknown }).kind;
  if (k === undefined || k === "item") return "item";
  return k === "menu" || k === "quest" ? k : null;
}

// --------------------------------------------------------------------------------------------------------- helpers
export type GpContext = {
  version: string;
  namespace: string;
  /** Asset keys of the mod. models / sounds as for items; advancements: `<ns>:<path>` of the project's data pack (undefined = not checked). */
  assets?: { models?: string[]; sounds?: string[]; advancements?: string[] };
};
export type GpIssue = DzIssue & { file?: string };
export type GpValidation<T> =
  | { ok: true; design: T; errors: []; warnings: GpIssue[] }
  | { ok: false; errors: GpIssue[]; warnings: GpIssue[] };

const RESERVED_NODES = /^(give|reload|command|list|params|menu|quests|npc)(\.|$)/;
const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");
const sizeOf = (x: unknown) => { try { return new TextEncoder().encode(JSON.stringify(x)).length; } catch { return Infinity; } };

/** Every clickable of a menu with its path (buttons, list entries, choices, nav arrows excluded). */
export function menuClickables(m: MenuDesign): { path: string; c: { icon: Icon; actions?: MenuAction[]; cost?: Cost; permission?: string; hideWithoutPermission?: boolean }; slot?: number }[] {
  if (m.style === "dialogue") return m.choices.map((c, i) => ({ path: `choices[${i}]`, c }));
  const out: { path: string; c: Entry; slot?: number }[] = (m.buttons ?? []).map((b, i) => ({ path: `buttons[${i}]`, c: b, slot: b.slot }));
  if (m.list?.source.type === "fixed") m.list.source.entries.forEach((e, i) => out.push({ path: `list.source.entries[${i}]`, c: e }));
  return out;
}
export const questSteps = (q: QuestDesign): { step: Step; branch?: string; path: string }[] => [
  ...q.steps.map((s, i) => ({ step: s, path: `steps[${i}]` })),
  ...(q.branches?.options ?? []).flatMap((b, j) => b.steps.map((s, i) => ({ step: s, branch: b.id, path: `branches.options[${j}].steps[${i}]` }))),
];

/** Worst-case characters of one quest's progress entry (QuestStore v1 encoding: id,S,step,branch,c.c.c,started,completions,last). */
export function progressEntryChars(q: QuestDesign): number {
  const steps = questSteps(q);
  const stepLen = Math.max(...steps.map((s) => s.step.id.length));
  const branchLen = Math.max(0, ...(q.branches?.options ?? []).map((b) => b.id.length));
  const counts = Math.max(...steps.map((s) => s.step.objectives.map((o) => String(objectiveTarget(o)).length).reduce((a, b) => a + b + 1, -1)));
  return q.id.length + 1 + 1 + 1 + stepLen + 1 + branchLen + 1 + counts + 1 + 10 + 1 + 7 + 1 + 10;
}
/** The target count of an objective (visit/talk: 1; survive: seconds). */
export function objectiveTarget(o: Objective): number {
  switch (o.type) { case "visit_location": case "talk": return 1; case "survive": return o.seconds; default: return o.count; }
}
export const repeatCooldown = (q: QuestDesign): number => q.repeat?.cooldownSeconds ?? REPEAT_DEFAULTS[q.repeat?.mode ?? "once"];

// --------------------------------------------------------------------------------------------------- validation
type Index = { items: Map<string, ItemDesign>; menus: Map<string, MenuDesign>; quests: Map<string, QuestDesign> };
type Sink = { errors: GpIssue[]; warnings: GpIssue[]; file: string };
const failF = (s: Sink, path: string, code: string, message: string) => s.errors.push({ path, code, message, file: s.file });
const warnF = (s: Sink, path: string, code: string, message: string) => s.warnings.push({ path, code, message, file: s.file });

function checkItemRef(s: Sink, at: string, ref: string, ctx: GpContext, idx: Index, what: string) {
  if (ref.startsWith("minecraft:")) {
    if (!isVanilla("item", ref, ctx.version)) failF(s, at, "unknown_vanilla_id", missingIdReason("item", ref, ctx.version));
    else if (BANNED_BASES.test(ref.slice(10)) || ref === "minecraft:air") failF(s, at, "banned_item", `${ref} cannot be ${what} (operator item, spawn egg or a drastic right-click)`);
  } else if (!idx.items.has(ref)) failF(s, at, "unresolved_ref", `no design item "${ref}" in this mod`);
}
function checkIcon(s: Sink, at: string, ic: Icon, ctx: GpContext, idx: Index, fe: DesignFeatures) {
  if ((ic.material === undefined) === (ic.item === undefined)) { failF(s, at, "icon_source", "an icon needs exactly one of material (a vanilla item) or item (a design item of this mod)"); return; }
  if (ic.material) checkItemRef(s, `${at}.material`, ic.material, ctx, idx, "an icon");
  if (ic.item && !idx.items.has(ic.item)) failF(s, `${at}.item`, "unresolved_ref", `no design item "${ic.item}" in this mod`);
  if (ic.model) {
    if (!ic.model.startsWith(`${ctx.namespace}:`)) failF(s, `${at}.model`, "foreign_namespace", `the item model must be in this mod's namespace ${ctx.namespace}`);
    else if (ctx.assets?.models && !ctx.assets.models.includes(ic.model)) warnF(s, `${at}.model`, "asset_unresolved", `${ic.model}: this mod has no such item model, so the icon keeps its base look`);
    if (!fe.itemModel) warnF(s, `${at}.model`, "item_model_unsupported", `custom item models need Minecraft 1.21.4 or newer; on ${ctx.version} the icon keeps its base look`);
  }
}
function checkSound(s: Sink, at: string, key: string, ctx: GpContext) {
  const kns = key.split(":")[0];
  if (kns === "minecraft") warnF(s, at, "vanilla_sound_unchecked", `${key}: vanilla sound keys are not checked against the game (a wrong key plays nothing)`);
  else if (kns !== ctx.namespace) failF(s, at, "foreign_namespace", `${key} uses the namespace ${kns}; sounds must be minecraft: or this mod's ${ctx.namespace}`);
  else if (ctx.assets?.sounds && !ctx.assets.sounds.includes(key)) warnF(s, at, "asset_unresolved", `${key}: this mod has no such custom sound, so it plays nothing`);
}
function checkCost(s: Sink, at: string, c: Cost | undefined, ctx: GpContext, idx: Index) {
  if (!c) return;
  if (c.type === "item") checkItemRef(s, `${at}.item`, c.item, ctx, idx, "a cost");
  if (c.type === "economy") warnF(s, at, "economy_needs_vault", "money costs work only when the server runs Vault and an economy plugin; without them this is refused with a message");
}
function checkAbilityRef(s: Sink, at: string, item: string, ability: string, idx: Index) {
  const it = idx.items.get(item);
  if (!it) { failF(s, at, "unresolved_ref", `no design item "${item}" in this mod`); return; }
  const ab = it.abilities.find((a) => a.id === ability);
  if (!ab) { failF(s, at, "unresolved_ref", `item ${item} has no ability "${ability}"`); return; }
  if (TRIGGER_HAS_TARGET[ab.trigger.type] === "always") warnF(s, at, "run_ability_no_target", `${item}.${ability} normally has a target (${ab.trigger.type}); run from a menu or reward it has none, so target effects are skipped`);
}
function permsOf(s: Sink, perms: { node: string }[] | undefined): Set<string> {
  const out = new Set<string>();
  (perms ?? []).forEach((p, i) => {
    if (out.has(p.node)) failF(s, `permissions[${i}].node`, "duplicate_id", `permission ${p.node} is declared twice`);
    if (RESERVED_NODES.test(p.node)) failF(s, `permissions[${i}].node`, "reserved_node", `${p.node} is reserved for the mod's own command`);
    out.add(p.node);
  });
  return out;
}

function checkActions(s: Sink, at: string, list: MenuAction[] | undefined, ctx: GpContext, idx: Index, here: MenuDesign | null) {
  (list ?? []).forEach((a, i) => {
    const ap = `${at}.actions[${i}]`;
    switch (a.type) {
      case "open_menu": if (!idx.menus.has(a.menu)) failF(s, `${ap}.menu`, "unresolved_ref", `no menu "${a.menu}" in this mod`); else if (here && a.menu === here.id) warnF(s, ap, "reopen_self", "opening the same menu only refreshes it"); break;
      case "next_page": case "prev_page": if (!here || here.style !== "chest" || !here.list) failF(s, ap, "no_list", `${a.type} needs a menu with a paginated list`); break;
      case "back": break;
      case "give_item": checkItemRef(s, `${ap}.item`, a.item, ctx, idx, "given by a menu"); break;
      case "play_sound": checkSound(s, `${ap}.sound`, a.sound, ctx); break;
      case "run_ability": checkAbilityRef(s, ap, a.item, a.ability, idx); break;
      case "start_quest": case "abandon_quest": if (!idx.quests.has(a.quest)) failF(s, `${ap}.quest`, "unresolved_ref", `no quest "${a.quest}" in this mod`); break;
      case "choose_branch": {
        const q = idx.quests.get(a.quest);
        if (!q) failF(s, `${ap}.quest`, "unresolved_ref", `no quest "${a.quest}" in this mod`);
        else if (!q.branches?.options.some((b) => b.id === a.branch)) failF(s, `${ap}.branch`, "unresolved_ref", `quest ${a.quest} has no branch "${a.branch}"`);
        break;
      }
      case "open_quest_log": if (!idx.quests.size) failF(s, ap, "no_quests", "open_quest_log needs at least one quest in this mod"); break;
      default: break;
    }
  });
  const gives = (list ?? []).filter((a) => a.type === "give_item").length;
  if (gives > 4) failF(s, `${at}.actions`, "too_many_gives", `${gives} give_item actions in one click; the limit is 4`);
}

/** Validate one menu (references resolved against the mod index). */
export function validateMenu(input: unknown, ctx: GpContext, idx: Index, fe: DesignFeatures): GpValidation<MenuDesign> {
  const id = (input as { id?: string })?.id ?? "?";
  const s: Sink = { errors: [], warnings: [], file: id };
  if (sizeOf(input) > GAMEPLAY_LIMITS.maxSpecBytes) { failF(s, "(root)", "spec_size", `the menu is larger than ${GAMEPLAY_LIMITS.maxSpecBytes} bytes`); return { ok: false, ...s }; }
  const p = MenuDesignSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) failF(s, issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors: s.errors, warnings: s.warnings }; }
  const m = p.data;
  const perms = permsOf(s, m.permissions);
  const needPerm = (at: string, node?: string) => { if (node && !perms.has(node)) failF(s, at, "undeclared_permission", `permission ${ctx.namespace}.${node} is not declared in "permissions"`); };
  needPerm("permission", m.permission);
  if (m.openWith?.item) {
    const it = idx.items.get(m.openWith.item);
    if (!it) failF(s, "openWith.item", "unresolved_ref", `no design item "${m.openWith.item}" in this mod`);
    else if (it.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type))) failF(s, "openWith.item", "opener_conflict", `${m.openWith.item} has right-click abilities; a menu opener item must not (both would fire on one click)`);
  }
  const clicks = menuClickables(m);
  for (const { path, c } of clicks) {
    checkIcon(s, `${path}.icon`, c.icon, ctx, idx, fe);
    checkCost(s, `${path}.cost`, c.cost, ctx, idx);
    needPerm(`${path}.permission`, c.permission);
    checkActions(s, path, c.actions, ctx, idx, m);
    // dupe at the IR level: a click that gives more of its own cost item than it takes is an infinite source
    if (c.cost?.type === "item") {
      const give = (c.actions ?? []).filter((a) => a.type === "give_item" && a.item === (c.cost as { item: string }).item).reduce((n, a) => n + ((a as { count?: number }).count ?? 1), 0);
      if (give > c.cost.count) failF(s, path, "cost_loop", `gives ${give} x ${c.cost.item} for ${c.cost.count} x ${c.cost.item}: an endless source of that item`);
      else if (give && give === c.cost.count) warnF(s, path, "cost_noop", "gives back exactly what it costs");
    }
    if (c.hideWithoutPermission && !c.permission) warnF(s, path, "hide_without_permission", "hideWithoutPermission does nothing without a permission");
    if (!c.actions?.length && c.cost) failF(s, path, "cost_without_action", "a cost with no actions takes the player's items for nothing");
  }
  if (m.style === "chest") {
    const size = m.rows * 9;
    const used = new Map<number, string>();
    const claim = (slot: number, at: string) => {
      if (slot >= size) { failF(s, at, "slot_outside", `slot ${slot} is outside a ${m.rows}-row menu (0-${size - 1})`); return; }
      if (used.has(slot)) failF(s, at, "slot_overlap", `slot ${slot} is also used by ${used.get(slot)}`);
      else used.set(slot, at);
    };
    (m.buttons ?? []).forEach((b, i) => claim(b.slot, `buttons[${i}].slot`));
    if (m.filler) checkItemRef(s, "filler", m.filler, ctx, idx, "a filler");
    if (m.list) {
      const L = m.list;
      L.slots.forEach((x, i) => claim(x, `list.slots[${i}]`));
      claim(L.prev.slot, "list.prev.slot"); claim(L.next.slot, "list.next.slot");
      checkIcon(s, "list.prev.icon", L.prev.icon, ctx, idx, fe); checkIcon(s, "list.next.icon", L.next.icon, ctx, idx, fe);
      if (L.source.type === "fixed") {
        const pages = Math.ceil(L.source.entries.length / L.slots.length);
        if (pages > GAMEPLAY_LIMITS.maxPages) failF(s, "list.source.entries", "too_many_pages", `${L.source.entries.length} entries in ${L.slots.length} slots is ${pages} pages; the limit is ${GAMEPLAY_LIMITS.maxPages}`);
      } else {
        const cur = L.source.currency;
        if (cur.type === "item") checkItemRef(s, "list.source.currency.item", cur.item, ctx, idx, "a currency");
        if (cur.type === "economy") warnF(s, "list.source.currency", "economy_needs_vault", "money prices work only when the server runs Vault and an economy plugin; without them purchases are refused with a message");
        const [lo, hi] = cur.type === "item" ? GAMEPLAY_CAPS.itemCost : cur.type === "xp_levels" ? GAMEPLAY_CAPS.xpLevelCost : cur.type === "economy" ? GAMEPLAY_CAPS.economyCost : [0, 0];
        L.source.entries.forEach((e, i) => {
          const at = `list.source.entries[${i}]`;
          checkItemRef(s, `${at}.material`, e.material, ctx, idx, "sold");
          if (cur.type === "item" && e.material === cur.item) failF(s, `${at}.material`, "cost_loop", "a config list cannot sell its own currency");
          if (cur.type !== "free" && (e.price < lo || e.price > hi)) failF(s, `${at}.price`, "price_range", `price ${e.price} is outside ${lo}-${hi} for a ${cur.type} currency`);
          if (cur.type !== "economy" && !Number.isInteger(e.price)) failF(s, `${at}.price`, "price_integer", "item and XP prices are whole numbers");
        });
        const cap = Math.min(GAMEPLAY_LIMITS.maxConfigEntries, L.slots.length * GAMEPLAY_LIMITS.maxPages);
        if (L.source.entries.length > cap) failF(s, "list.source.entries", "too_many_pages", `more than ${cap} entries do not fit ${GAMEPLAY_LIMITS.maxPages} pages`);
        if (cur.type === "free") warnF(s, "list.source.currency", "free_list", "every entry of this list is free");
      }
      if (L.prev.slot === L.next.slot) failF(s, "list.next.slot", "slot_overlap", "prev and next use the same slot");
    } else if (!(m.buttons ?? []).length) failF(s, "buttons", "empty_menu", "a chest menu needs buttons or a list");
  }
  if (m.style === "dialogue" && m.speakerIcon) checkIcon(s, "speakerIcon", m.speakerIcon, ctx, idx, fe);
  if (m.openWith?.npc && m.style !== "dialogue") warnF(s, "openWith.npc", "npc_chest", "NPC menus are usually dialogues; this opens a chest menu from an NPC");
  return s.errors.length ? { ok: false, errors: s.errors, warnings: s.warnings } : { ok: true, design: m, errors: [], warnings: s.warnings };
}

/** Validate one quest (references resolved against the mod index). */
export function validateQuest(input: unknown, ctx: GpContext, idx: Index): GpValidation<QuestDesign> {
  const id = (input as { id?: string })?.id ?? "?";
  const s: Sink = { errors: [], warnings: [], file: id };
  if (sizeOf(input) > GAMEPLAY_LIMITS.maxSpecBytes) { failF(s, "(root)", "spec_size", `the quest is larger than ${GAMEPLAY_LIMITS.maxSpecBytes} bytes`); return { ok: false, ...s }; }
  const p = QuestDesignSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) failF(s, issuePath(i.path) || "(root)", "schema", i.message); return { ok: false, errors: s.errors, warnings: s.warnings }; }
  const q = p.data;
  const v = ctx.version;
  const perms = permsOf(s, q.permissions);
  if (q.permission && !perms.has(q.permission)) failF(s, "permission", "undeclared_permission", `permission ${ctx.namespace}.${q.permission} is not declared in "permissions"`);
  (q.requires ?? []).forEach((r, i) => {
    if (r === q.id) failF(s, `requires[${i}]`, "circular_prerequisites", "a quest cannot require itself");
    else if (!idx.quests.has(r)) failF(s, `requires[${i}]`, "unresolved_ref", `no quest "${r}" in this mod`);
  });
  if (new Set(q.requires ?? []).size !== (q.requires ?? []).length) failF(s, "requires", "duplicate_id", "a prerequisite is listed twice");
  const stepIds = new Set<string>();
  for (const { step, path } of questSteps(q)) {
    if (stepIds.has(step.id)) failF(s, `${path}.id`, "duplicate_id", `step ${step.id} is defined twice in this quest (main and branch steps share one id space)`);
    stepIds.add(step.id);
    step.objectives.forEach((o, j) => {
      const at = `${path}.objectives[${j}]`;
      switch (o.type) {
        case "kill_entity":
          if (!o.entity && !o.kinds?.length) failF(s, at, "empty_filter", "kill_entity needs an entity or kinds");
          if (o.entity && !isVanilla("entity_type", o.entity, v)) failF(s, `${at}.entity`, "unknown_vanilla_id", missingIdReason("entity_type", o.entity, v));
          break;
        case "collect_item": case "craft_item":
          checkItemRef(s, `${at}.item`, o.item, ctx, idx, o.type === "collect_item" ? "collected" : "crafted");
          if (o.type === "craft_item" && !o.item.startsWith("minecraft:") && idx.items.get(o.item) && !idx.items.get(o.item)!.recipe) failF(s, `${at}.item`, "not_craftable", `design item ${o.item} has no recipe, so it can never be crafted`);
          if (o.type === "collect_item" && o.take && o.mode === "pickup") warnF(s, at, "take_pickup", "take with pickup mode removes the items only if the player still has them when the step completes");
          break;
        case "break_block": if (!isVanilla("block", o.block, v)) failF(s, `${at}.block`, "unknown_vanilla_id", missingIdReason("block", o.block, v)); break;
        case "talk": {
          const m = idx.menus.get(o.menu);
          if (!m) failF(s, `${at}.menu`, "unresolved_ref", `no menu "${o.menu}" in this mod`);
          else if (m.style !== "dialogue") failF(s, `${at}.menu`, "not_dialogue", `talk needs a dialogue menu; ${o.menu} is a chest menu`);
          break;
        }
        default: break;
      }
    });
    const kinds = step.objectives.map((o) => o.type === "talk" ? `talk:${o.menu}` : o.type === "visit_location" ? `visit:${o.world}:${o.x}:${o.y}:${o.z}` : "");
    if (kinds.some((k, i) => k && kinds.indexOf(k) !== i)) warnF(s, `${path}.objectives`, "duplicate_objective", "two identical objectives in one step complete together");
  }
  if (q.branches) {
    const ids = new Set<string>();
    q.branches.options.forEach((b, i) => { if (ids.has(b.id)) failF(s, `branches.options[${i}].id`, "duplicate_id", `branch ${b.id} is defined twice`); ids.add(b.id); if (b.icon) checkIcon(s, `branches.options[${i}].icon`, b.icon, ctx, idx, designFeatures(v).ok ? (designFeatures(v) as { features: DesignFeatures }).features : ({ itemModel: true } as DesignFeatures)); });
  }
  const rewardCheck = (list: Reward[] | undefined, at: string) => (list ?? []).forEach((r, i) => {
    const rp = `${at}[${i}]`;
    switch (r.type) {
      case "give_item": checkItemRef(s, `${rp}.item`, r.item, ctx, idx, "a reward"); break;
      case "xp": if ((r.points === undefined) === (r.levels === undefined)) failF(s, rp, "xp_amount", "xp needs exactly one of points or levels"); break;
      case "advancement": {
        const ns = r.advancement.split(":")[0];
        if (ns !== ctx.namespace) failF(s, `${rp}.advancement`, "foreign_namespace", `${r.advancement}: only this project's own data pack advancements (${ctx.namespace}:...) can be granted`);
        else if (ctx.assets?.advancements === undefined) warnF(s, `${rp}.advancement`, "advancement_unchecked", `${r.advancement} is not checked against the project's data pack here; if it is missing the reward logs a note and grants nothing`);
        else if (!ctx.assets.advancements.includes(r.advancement)) failF(s, `${rp}.advancement`, "advancement_not_in_project", `${r.advancement} is not an advancement of this project's data pack (make it with the data pack studio first)`);
        break;
      }
      case "run_ability": checkAbilityRef(s, rp, r.item, r.ability, idx); break;
      default: break;
    }
  });
  rewardCheck(q.rewards, "rewards");
  q.branches?.options.forEach((b, i) => rewardCheck(b.rewards, `branches.options[${i}].rewards`));
  if (q.icon) { const fe = designFeatures(v); if (fe.ok) checkIcon(s, "icon", q.icon, ctx, idx, fe.features); }
  const mode = q.repeat?.mode ?? "once";
  if (mode === "once" && q.repeat?.cooldownSeconds !== undefined) warnF(s, "repeat.cooldownSeconds", "no_repeat", "a once-only quest has no cooldown");
  const surviveTotal = (steps: Step[]) => steps.reduce((n, st) => n + Math.max(0, ...st.objectives.map((o) => (o.type === "survive" ? o.seconds : 0))), 0);
  const limit = q.failure?.timeLimitSeconds;
  if (limit !== undefined) {
    const worst = surviveTotal(q.steps) + Math.max(0, ...(q.branches?.options ?? []).map((b) => surviveTotal(b.steps)));
    if (worst > limit) failF(s, "failure.timeLimitSeconds", "time_limit_too_short", `the survive objectives need ${worst} s but the time limit is ${limit} s: the quest can never be completed`);
  }
  // reward farm: a repeatable quest that completes instantly (only talk / visit) with a short cooldown must not give items or XP
  const instant = questSteps(q).every(({ step }) => step.objectives.every((o) => o.type === "talk" || o.type === "visit_location"));
  const valuable = [...(q.rewards ?? []), ...(q.branches?.options ?? []).flatMap((b) => b.rewards ?? [])].some((r) => r.type === "give_item" || r.type === "xp");
  if (mode !== "once" && repeatCooldown(q) < FARM_COOLDOWN_SECONDS && instant && valuable) failF(s, "repeat", "reward_farm", `this quest completes instantly (talk/visit only) and repeats after ${repeatCooldown(q)} s: its item/XP rewards could be farmed. Use a cooldown of at least ${FARM_COOLDOWN_SECONDS} s or a real objective`);
  if (mode !== "once" && repeatCooldown(q) < FARM_COOLDOWN_SECONDS) {
    // collecting X (kept) and getting X back as a reward is an endless source
    const kept = new Set(questSteps(q).flatMap(({ step }) => step.objectives.filter((o) => o.type === "collect_item" && !o.take).map((o) => (o as { item: string }).item)));
    const back = [...(q.rewards ?? []), ...(q.branches?.options ?? []).flatMap((b) => b.rewards ?? [])].filter((r) => r.type === "give_item" && kept.has(r.item));
    if (back.length) failF(s, "rewards", "reward_farm", `the reward gives ${(back[0] as { item: string }).item}, which the quest only asks the player to have (not take), and it repeats quickly: an endless source`);
  }
  if (q.failure?.abandon === false && mode === "once" && !limit) warnF(s, "failure.abandon", "no_abandon", "players can never drop this quest");
  return s.errors.length ? { ok: false, errors: s.errors, warnings: s.warnings } : { ok: true, design: q, errors: [], warnings: s.warnings };
}

export type GameplayValidation = {
  ok: boolean;
  /** Per file, in input order. */
  files: { id: string; kind: DesignKind | null; ok: boolean; errors: GpIssue[]; warnings: GpIssue[] }[];
  items: ItemDesign[]; menus: MenuDesign[]; quests: QuestDesign[];
  /** Mod-level errors (also listed in each affected file's errors when one is affected). */
  errors: GpIssue[];
  itemResults: DesignValidation[];
  features?: DesignFeatures;
  /** Worst-case progress characters per player (QuestStore v1). */
  progressChars: number;
};

/** Exchange graph of every priced click (cost item -> given item): a cycle that multiplies the start amount is an arbitrage dupe. */
export function arbitrageLoops(menus: MenuDesign[], quests: QuestDesign[] = []): { cycle: string[]; gain: number; where: string }[] {
  type Edge = { from: string; to: string; rate: number; where: string };
  const edges: Edge[] = [];
  for (const m of menus) {
    for (const { path, c } of menuClickables(m)) {
      if (c.cost?.type !== "item") continue;
      for (const a of c.actions ?? []) if (a.type === "give_item") edges.push({ from: c.cost.item, to: a.item, rate: (a.count ?? 1) / c.cost.count, where: `${m.id}: ${path}` });
    }
    if (m.style === "chest" && m.list?.source.type === "config" && m.list.source.currency.type === "item") {
      const cur = m.list.source.currency.item;
      m.list.source.entries.forEach((e, i) => { if (e.price > 0) edges.push({ from: cur, to: e.material, rate: e.amount / e.price, where: `${m.id}: list.source.entries[${i}]` }); });
    }
  }
  for (const q of quests) {
    if ((q.repeat?.mode ?? "once") === "once" || repeatCooldown(q) >= FARM_COOLDOWN_SECONDS) continue;
    for (const { step, path } of questSteps(q)) for (const o of step.objectives) if (o.type === "collect_item" && o.take)
      for (const r of q.rewards ?? []) if (r.type === "give_item") edges.push({ from: o.item, to: r.item, rate: (r.count ?? 1) / o.count, where: `${q.id}: ${path}` });
  }
  // Bellman-Ford on -log(rate) from every node; bounded: at most ~600 edges
  const nodes = [...new Set(edges.flatMap((e) => [e.from, e.to]))];
  const out: { cycle: string[]; gain: number; where: string }[] = [];
  const seen = new Set<string>();
  for (const start of nodes) {
    const dist = new Map<string, number>(nodes.map((n) => [n, Infinity]));
    const pred = new Map<string, Edge>();
    dist.set(start, 0);
    for (let i = 0; i < nodes.length; i++) for (const e of edges) { const w = -Math.log(e.rate); if (dist.get(e.from)! + w < dist.get(e.to)! - 1e-12) { dist.set(e.to, dist.get(e.from)! + w); pred.set(e.to, e); } }
    for (const e of edges) {
      if (dist.get(e.from)! - Math.log(e.rate) < dist.get(e.to)! - 1e-12) {
        // walk back to find the cycle
        let x = e.to;
        for (let i = 0; i < nodes.length; i++) x = pred.get(x)?.from ?? x;
        const cyc: string[] = []; let y = x; let gain = 1; let where = "";
        for (let i = 0; i <= nodes.length; i++) { const pe = pred.get(y); if (!pe) break; cyc.unshift(y); gain *= pe.rate; where = pe.where; y = pe.from; if (y === x) break; }
        const key = [...cyc].sort().join(">");
        if (cyc.length && !seen.has(key)) { seen.add(key); out.push({ cycle: [...cyc, cyc[0]], gain: +gain.toFixed(4), where }); }
      }
    }
  }
  return out;
}

/** Validate a whole mod: every design file (any kind) + the cross-file checks. */
export function validateGameplay(inputs: unknown[], ctx: GpContext): GameplayValidation {
  const errors: GpIssue[] = [];
  const res: GameplayValidation = { ok: false, files: [], items: [], menus: [], quests: [], errors, itemResults: [], progressChars: 0 };
  const fail = (file: string | undefined, path: string, code: string, message: string) => { const e = { path, code, message, ...(file ? { file } : {}) }; errors.push(e); const f = res.files.find((x) => x.id === file); if (f) { f.errors.push(e); f.ok = false; } };
  if (!NAMESPACE_RE.test(ctx.namespace)) { fail(undefined, "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return res; }
  const fe = designFeatures(ctx.version);
  if (!fe.ok) { fail(undefined, "version", "unsupported_version", fe.error); return res; }
  res.features = fe.features;
  const kinds = inputs.map(designKind);
  const ids = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : ""));
  inputs.forEach((_, i) => res.files.push({ id: ids[i] || `#${i}`, kind: kinds[i], ok: true, errors: [], warnings: [] }));
  if (inputs.length > GAMEPLAY_LIMITS.maxDesignFiles) fail(undefined, "(mod)", "too_many_files", `${inputs.length} design files; the limit is ${GAMEPLAY_LIMITS.maxDesignFiles}`);
  kinds.forEach((k, i) => { if (!k) fail(res.files[i].id, "kind", "unknown_kind", `"kind" must be absent/"item", "menu" or "quest"`); });
  const dup = ids.find((k, i) => k && ids.indexOf(k) !== i);
  if (dup) fail(dup, "(mod)", "duplicate_item", `design ${dup} is defined twice (items, menus and quests share one id space)`);
  const count = (k: DesignKind) => kinds.filter((x) => x === k).length;
  if (count("menu") > GAMEPLAY_LIMITS.maxMenus) fail(undefined, "(mod)", "too_many_menus", `${count("menu")} menus; the limit is ${GAMEPLAY_LIMITS.maxMenus}`);
  if (count("quest") > GAMEPLAY_LIMITS.maxQuests) fail(undefined, "(mod)", "too_many_quests", `${count("quest")} quests; the limit is ${GAMEPLAY_LIMITS.maxQuests}`);
  // items first (the item validator, unchanged)
  const itemIdx = inputs.map((x, i) => (kinds[i] === "item" ? i : -1)).filter((i) => i >= 0);
  const iv = validateDesigns(itemIdx.map((i) => inputs[i]), { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
  res.itemResults = iv.results;
  for (const e of iv.errors) fail(undefined, e.path, e.code, e.message);
  iv.results.forEach((r, j) => {
    const f = res.files[itemIdx[j]];
    for (const w of r.warnings) f.warnings.push({ ...w, file: f.id });
    if (!r.ok) { for (const e of r.errors) { const x = { ...e, file: f.id }; f.errors.push(x); errors.push(x); } f.ok = false; } else res.items.push(r.design);
  });
  // the index: every parseable menu/quest (so references between them resolve even when another check fails)
  const idx: Index = { items: new Map(res.items.map((d) => [d.id, d])), menus: new Map(), quests: new Map() };
  inputs.forEach((x, i) => {
    if (kinds[i] === "menu") { const p = MenuDesignSchema.safeParse(x); if (p.success) idx.menus.set(p.data.id, p.data); }
    if (kinds[i] === "quest") { const p = QuestDesignSchema.safeParse(x); if (p.success) idx.quests.set(p.data.id, p.data); }
  });
  inputs.forEach((x, i) => {
    const k = kinds[i];
    if (k !== "menu" && k !== "quest") return;
    const r = k === "menu" ? validateMenu(x, ctx, idx, fe.features) : validateQuest(x, ctx, idx);
    const f = res.files[i];
    f.warnings.push(...r.warnings);
    if (!r.ok) { for (const e of r.errors) { const y = { ...e, file: f.id }; f.errors.push(y); errors.push(y); } f.ok = false; }
    else if (k === "menu") res.menus.push(r.design as MenuDesign); else res.quests.push(r.design as QuestDesign);
  });
  // ---- cross-file: prerequisite cycles
  const qmap = new Map(res.quests.map((q) => [q.id, q]));
  const state = new Map<string, number>();
  const stack: string[] = [];
  const inCycle = new Set<string>();
  const dfs = (id: string) => {
    state.set(id, 1); stack.push(id);
    for (const r of qmap.get(id)?.requires ?? []) {
      if (!qmap.has(r)) continue;
      if (state.get(r) === 1) stack.slice(stack.indexOf(r)).forEach((x) => inCycle.add(x));
      else if (!state.get(r)) dfs(r);
    }
    stack.pop(); state.set(id, 2);
  };
  for (const q of res.quests) if (!state.get(q.id)) dfs(q.id);
  for (const id of [...inCycle].sort()) fail(id, "requires", "circular_prerequisites", `quest ${id} is part of a prerequisite cycle (${[...inCycle].sort().join(" -> ")}), so it can never start`);
  // ---- reachability: menus that can be opened, quests that can be started
  const openable = new Set<string>();
  for (const m of res.menus) if (m.openWith?.command !== false || m.openWith?.item || m.openWith?.npc) openable.add(m.id);
  const mmap = new Map(res.menus.map((m) => [m.id, m]));
  const queue = [...openable];
  while (queue.length) {
    const m = mmap.get(queue.shift()!);
    if (!m) continue;
    for (const { c } of menuClickables(m)) for (const a of c.actions ?? []) if (a.type === "open_menu" && mmap.has(a.menu) && !openable.has(a.menu)) { openable.add(a.menu); queue.push(a.menu); }
  }
  for (const m of res.menus) if (!openable.has(m.id)) fail(m.id, "openWith", "unreachable_menu", `menu ${m.id} can never be opened (no command, item, NPC or open_menu from an openable menu)`);
  const startedFromMenu = new Set<string>();
  for (const m of res.menus) if (openable.has(m.id)) for (const { c } of menuClickables(m)) for (const a of c.actions ?? []) if (a.type === "start_quest") startedFromMenu.add(a.quest);
  const startable = new Map<string, boolean>();
  const canStart = (id: string, seen = new Set<string>()): boolean => {
    if (startable.has(id)) return startable.get(id)!;
    const q = qmap.get(id);
    if (!q || seen.has(id) || inCycle.has(id)) return false;
    seen.add(id);
    const ok = ((q.start ?? "command") === "command" || startedFromMenu.has(id)) && (q.requires ?? []).every((r) => canStart(r, seen));
    startable.set(id, ok);
    return ok;
  };
  for (const q of res.quests) {
    if (inCycle.has(q.id)) continue;
    if (!canStart(q.id)) fail(q.id, q.start === "menu" && !startedFromMenu.has(q.id) ? "start" : "requires", "unreachable_quest", q.start === "menu" && !startedFromMenu.has(q.id) ? `quest ${q.id} starts only from a menu, but no openable menu has a start_quest for it` : `quest ${q.id} needs a quest that can never be started`);
    for (const { step, path } of questSteps(q)) step.objectives.forEach((o, j) => { if (o.type === "talk" && mmap.has(o.menu) && !openable.has(o.menu)) fail(q.id, `${path}.objectives[${j}]`, "unreachable_dialogue", `dialogue ${o.menu} can never be opened, so this objective can never be met`); });
  }
  // ---- arbitrage (dupe) loops across every shop and fast-repeat quest
  for (const loop of arbitrageLoops(res.menus, res.quests)) fail(loop.where.split(":")[0], loop.where.split(": ")[1] ?? "(mod)", "arbitrage_loop", `trading ${loop.cycle.join(" -> ")} multiplies the items by ${loop.gain}: an endless source (lower the given counts or raise the costs)`);
  // ---- stored progress worst case (bounded PDC string per player)
  res.progressChars = 3 + res.quests.reduce((n, q) => n + progressEntryChars(q) + 1, 0);
  if (res.progressChars > GAMEPLAY_LIMITS.maxProgressChars) fail(res.quests.at(-1)?.id, "(mod)", "progress_oversize", `a player's stored quest progress could reach ${res.progressChars} characters; the limit is ${GAMEPLAY_LIMITS.maxProgressChars} (use shorter quest/step ids or fewer quests)`);
  // drop invalid designs from the lists (a cross-file failure makes that file invalid)
  const bad = new Set(res.files.filter((f) => !f.ok).map((f) => f.id));
  res.menus = res.menus.filter((m) => !bad.has(m.id)).sort((a, b) => (a.id < b.id ? -1 : 1));
  res.quests = res.quests.filter((q) => !bad.has(q.id)).sort((a, b) => (a.id < b.id ? -1 : 1));
  res.items = res.items.filter((d) => !bad.has(d.id));
  res.ok = !errors.length && res.files.every((f) => f.ok);
  return res;
}

export const GAMEPLAY_CHECK_CODES = [
  "schema", "unknown_kind", "duplicate_item", "too_many_menus", "too_many_quests", "too_many_files", "slot_outside", "slot_overlap", "too_many_pages", "cost_loop", "arbitrage_loop",
  "reward_farm", "circular_prerequisites", "unreachable_quest", "unreachable_menu", "unreachable_dialogue", "progress_oversize", "opener_conflict", "not_dialogue", "no_list",
  "undeclared_permission", "reserved_node", "advancement_not_in_project", "foreign_namespace", "unresolved_ref", "time_limit_too_short", "cost_without_action", "icon_source", "banned_item",
] as const;
export { KEY };

