export const PAGINATION_JAVA = String.raw`package __PKG__.designer;

/** Component gameplay-pagination v1: page math of paginated menu lists (pure). Pages are 0-based, always clamped, at most MAX_PAGES. */
public final class Pagination {
    public static final int MAX_PAGES = 10;

    private Pagination() {}

    public static int pages(int entries, int pageSize) {
        if (pageSize <= 0) return 1;
        int p = (Math.max(0, entries) + pageSize - 1) / pageSize;
        return Math.max(1, Math.min(MAX_PAGES, p));
    }

    public static int clamp(int page, int entries, int pageSize) { return Math.max(0, Math.min(pages(entries, pageSize) - 1, page)); }

    public static int first(int page, int pageSize) { return Math.max(0, page) * Math.max(0, pageSize); }

    /** Entries shown on this (clamped) page; entries past MAX_PAGES are never shown. */
    public static int count(int page, int entries, int pageSize) {
        if (pageSize <= 0) return 0;
        int f = first(clamp(page, entries, pageSize), pageSize);
        int shown = Math.min(Math.max(0, entries), pages(entries, pageSize) * pageSize);
        return Math.max(0, Math.min(pageSize, shown - f));
    }

    public static boolean hasNext(int page, int entries, int pageSize) { return clamp(page, entries, pageSize) < pages(entries, pageSize) - 1; }

    public static boolean hasPrev(int page, int entries, int pageSize) { return clamp(page, entries, pageSize) > 0; }
}
