        Holder(String menu, UUID viewer, int page) { this.menu = menu; this.viewer = viewer; this.page = page; }

        @Override
        public Inventory getInventory() { return inv; }

        public String menu() { return menu; }
        public int page() { return page; }
        void page(int p) { page = p; }
        public UUID viewer() { return viewer; }
    }

    private static final class Session {
        final ArrayDeque<String> back = new ArrayDeque<>();
        String current;
        long lastClick = -1000L;
        long lastOpen = -1000L;
        int opening;
    }

    private final Gameplay g;
    private final Map<String, MenuDef> menus = new LinkedHashMap<>();
    private final Map<UUID, Session> sessions = new HashMap<>();
    private final NamespacedKey iconKey;
    private long clickCooldown = 4L;

    MenuManager(Gameplay g) {
        this.g = g;
        this.iconKey = new NamespacedKey(g.designer().namespace(), "menu_icon");
    }

    void register(List<MenuDef> list) { for (MenuDef m : list) menus.put(m.id(), m); }

