        for (MenuDef m : menus.values()) m.load(c);
    }

    public MenuDef menu(String id) { return menus.get(id); }
    public Map<String, MenuDef> menus() { return menus; }
    public int sessions() { return sessions.size(); }
    NamespacedKey iconKey() { return iconKey; }

    public boolean isIcon(ItemStack s) {
        if (s == null || s.getType().isAir() || !s.hasItemMeta()) return false;
        ItemMeta m = s.getItemMeta();
        return m != null && m.getPersistentDataContainer().has(iconKey, PersistentDataType.BYTE);
    }

    void later(Player p, Runnable r) { g.designer().tasks().later(1L, () -> { if (p.isOnline()) r.run(); }); }

    private static Holder holder(Inventory inv) { return inv != null && inv.getHolder() instanceof Holder h ? h : null; }

    private static void say(Player p, String text, NamedTextColor color) { p.sendMessage(Component.text(text, color)); }

    // ------------------------------------------------------------------------------------------------ opening
    public void open(Player p, String id, int page, boolean push) {
        if (!p.isOnline() || p.isDead()) return;
        MenuDef m = null;
        String title;
        int size;
        if (LOG.equals(id)) { title = "Quests"; size = DialogueMenu.logSize(g.quests().defs().size()); }
        else if (id.startsWith(BRANCH)) {
            QuestDef q = g.quests().def(id.substring(BRANCH.length()));
            if (q == null) return;
            title = q.title().length() > 32 ? q.title().substring(0, 32) : q.title();
            size = DialogueMenu.SIZE;
        } else {
            m = menus.get(id);
            if (m == null) { say(p, "There is no menu " + id + ".", NamedTextColor.RED); return; }
            if (m.permission() != null && !p.hasPermission(g.designer().namespace() + "." + m.permission())) { say(p, "You don't have permission to open that.", NamedTextColor.RED); return; }
            title = m.title();
            size = m.rows() * 9;
        }
        Session s = sessions.computeIfAbsent(p.getUniqueId(), k -> new Session());
        Holder h = new Holder(id, p.getUniqueId(), page);
        h.inv = Bukkit.createInventory(h, size, Component.text(title));
        render(p, h, m);
        if (push && s.current != null && !s.current.equals(id)) { s.back.push(s.current); while (s.back.size() > MAX_BACK) s.back.removeLast(); }
        s.current = id;
        s.opening++;
        try { p.openInventory(h.inv); } finally { s.opening--; }
        if (m != null && m.style() == MenuDef.Style.DIALOGUE) g.quests().talked(p, id);
    }

    void back(Player p) {
        Session s = sessions.get(p.getUniqueId());
        String prev = s == null ? null : s.back.poll();
        if (prev == null) { p.closeInventory(); return; }
        open(p, prev, 0, false);
    }

    /** Re-render the menu a player has open (after a purchase changed what they can afford). */
    void refresh(Player p) {
        Holder h = holder(p.getOpenInventory().getTopInventory());
        if (h == null || !h.viewer().equals(p.getUniqueId())) return;
        render(p, h, menus.get(h.menu()));
    }

    private void render(Player p, Holder h, MenuDef m) {
        h.inv.clear();
        h.slots.clear();
        if (LOG.equals(h.menu())) { DialogueMenu.renderLog(g, p, h); return; }
        if (h.menu().startsWith(BRANCH)) { DialogueMenu.renderBranches(g, p, h, g.quests().def(h.menu().substring(BRANCH.length()))); return; }
        if (m == null) return;
        if (m.style() == MenuDef.Style.DIALOGUE) { DialogueMenu.renderDialogue(g, m, p, h); return; }
        if (m.filler != null) { ItemStack f = g.icon(m.filler, " ", null, List.of(), 1, false, null, null); for (int i = 0; i < h.inv.getSize(); i++) h.inv.setItem(i, f); }
        for (MenuDef.Button b : m.buttons) place(p, h, b, b.slot);
        if (m.listSlots.length > 0) {
            List<MenuDef.Button> visible = new ArrayList<>();
            for (MenuDef.Button b : m.entries) if (!b.hide || allowed(p, b)) visible.add(b);
            int size = m.listSlots.length;
            int page = Pagination.clamp(h.page(), visible.size(), size);
            h.page(page);
            int first = Pagination.first(page, size);
            int n = Pagination.count(page, visible.size(), size);
            for (int i = 0; i < size; i++) {
                if (i < n) place(p, h, visible.get(first + i), m.listSlots[i]);
                else if (m.listSlots[i] < h.inv.getSize()) { h.inv.setItem(m.listSlots[i], null); h.slots.remove(m.listSlots[i]); }
            }
            if (m.prev != null && Pagination.hasPrev(page, visible.size(), size)) place(p, h, m.prev, m.prev.slot);
            if (m.next != null && Pagination.hasNext(page, visible.size(), size)) place(p, h, m.next, m.next.slot);
        }
    }

    private boolean allowed(Player p, MenuDef.Button b) { return b.permission == null || p.hasPermission(g.designer().namespace() + "." + b.permission); }

    /** Put one clickable into a slot, with its cost and lock lines (a hidden locked button leaves the slot as it is). */
    void place(Player p, Holder h, MenuDef.Button b, int slot) {
        if (b == null || b.icon == null || slot < 0 || slot >= h.inv.getSize()) return;
        boolean ok = allowed(p, b);
        if (!ok && b.hide) return;
        ItemStack icon = b.icon.clone();
        List<Component> extra = new ArrayList<>();
        if (!b.cost.free()) extra.add(Component.text("Cost: " + g.costs().describe(b.cost), NamedTextColor.YELLOW).decoration(TextDecoration.ITALIC, false));
        if (!ok) extra.add(Component.text("Locked", NamedTextColor.RED).decoration(TextDecoration.ITALIC, false));
        if (!extra.isEmpty()) {
            ItemMeta meta = icon.getItemMeta();
            if (meta != null) {
                List<Component> lore = meta.lore() == null ? new ArrayList<>() : new ArrayList<>(meta.lore());
                lore.addAll(extra);
                meta.lore(lore);
                icon.setItemMeta(meta);
            }
        }
        h.inv.setItem(slot, icon);
        h.slots.put(slot, b);
    }

    // --------------------------------------------------------------------------------------- click hardening
    @EventHandler(priority = EventPriority.LOWEST)
    public void onClickEarly(InventoryClickEvent e) {
        if (holder(e.getView().getTopInventory()) != null) { e.setCancelled(true); e.setResult(Event.Result.DENY); }
    }

    @EventHandler(priority = EventPriority.HIGHEST)
    public void onClick(InventoryClickEvent e) {
        Holder h = holder(e.getView().getTopInventory());
        if (h == null) return;
        e.setCancelled(true);
        e.setResult(Event.Result.DENY);
        if (!(e.getWhoClicked() instanceof Player p) || !p.getUniqueId().equals(h.viewer())) return;
        if (e.getClick() != ClickType.LEFT && e.getClick() != ClickType.RIGHT) return;
        int raw = e.getRawSlot();
        if (raw < 0 || raw >= h.inv.getSize()) return;
        MenuDef.Button b = h.slots.get(raw);
        Session s = sessions.get(p.getUniqueId());
        if (b == null || s == null) return;
        long now = g.designer().now();
        if (now - s.lastClick < clickCooldown) return;
        s.lastClick = now;
        press(p, h, b);
    }

    /** The fixed, dupe-proof click protocol (the TS simulator implements exactly this order). */
    private void press(Player p, Holder h, MenuDef.Button b) {
        if (!allowed(p, b)) { say(p, "You don't have permission for that.", NamedTextColor.RED); return; }
        if (!CostCharger.fits(p, b.gives)) { say(p, "Your inventory is full.", NamedTextColor.RED); return; }
        String why = g.costs().refusal(p, b.cost);
        if (why != null) { say(p, why, NamedTextColor.RED); return; }
        if (!g.costs().take(p, b.cost)) { say(p, "You can't pay for that right now.", NamedTextColor.RED); return; }
        if (b.click != null) b.click.run(new MenuContext(g, p, h));
        if (!b.cost.free()) later(p, () -> refresh(p));
    }

    @EventHandler(priority = EventPriority.LOWEST)
    public void onDragEarly(InventoryDragEvent e) {
        if (holder(e.getView().getTopInventory()) != null) { e.setCancelled(true); e.setResult(Event.Result.DENY); }
    }

    @EventHandler(priority = EventPriority.HIGHEST)
    public void onDrag(InventoryDragEvent e) {
        if (holder(e.getView().getTopInventory()) != null) { e.setCancelled(true); e.setResult(Event.Result.DENY); }
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onClose(InventoryCloseEvent e) {
        Holder h = holder(e.getInventory());
        if (h == null || !(e.getPlayer() instanceof Player p)) return;
        Session s = sessions.get(p.getUniqueId());
        if (s != null && s.opening == 0) sessions.remove(p.getUniqueId());
        sweep(p);
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onQuit(PlayerQuitEvent e) { sessions.remove(e.getPlayer().getUniqueId()); sweep(e.getPlayer()); }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onDeath(PlayerDeathEvent e) {
        Player p = e.getEntity();
        if (holder(p.getOpenInventory().getTopInventory()) != null) p.closeInventory();
        sessions.remove(p.getUniqueId());
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onDrop(PlayerDropItemEvent e) { if (isIcon(e.getItemDrop().getItemStack())) e.getItemDrop().remove(); }

    /** Defence in depth: no menu icon survives outside a menu. */
    private void sweep(Player p) {
        if (isIcon(p.getItemOnCursor())) p.setItemOnCursor(null);
        ItemStack[] st = p.getInventory().getContents();
        boolean changed = false;
        for (int i = 0; i < st.length; i++) if (isIcon(st[i])) { st[i] = null; changed = true; }
        if (changed) p.getInventory().setContents(st);
    }

    // ---------------------------------------------------------------------------------- openers: item, NPC
    @EventHandler(priority = EventPriority.MONITOR)
    public void onUse(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        if (e.getAction() != Action.RIGHT_CLICK_AIR && e.getAction() != Action.RIGHT_CLICK_BLOCK) return;
        if (e.useItemInHand() == Event.Result.DENY) return;
        String id = g.designer().identity().idOf(e.getPlayer().getInventory().getItemInMainHand());
        if (id == null) return;
        for (MenuDef m : menus.values()) if (id.equals(m.opener())) { openSoon(e.getPlayer(), m.id()); return; }
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onNpc(PlayerInteractEntityEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        Entity t = e.getRightClicked();
        String prefix = g.designer().namespace() + ".npc.";
        for (String tag : t.getScoreboardTags()) {
            if (!tag.startsWith(prefix)) continue;
            MenuDef m = menus.get(tag.substring(prefix.length()));
            if (m == null || !m.npc()) continue;
            e.setCancelled(true);
            openSoon(e.getPlayer(), m.id());
            return;
        }
    }

    private void openSoon(Player p, String id) {
        Session s = sessions.computeIfAbsent(p.getUniqueId(), k -> new Session());
        long now = g.designer().now();
        if (now - s.lastOpen < 2L) return;
        s.lastOpen = now;
        later(p, () -> open(p, id, 0, false));
    }

    public void closeAll() {
        for (UUID id : new ArrayList<>(sessions.keySet())) {
            Player p = Bukkit.getPlayer(id);
            if (p != null && holder(p.getOpenInventory().getTopInventory()) != null) p.closeInventory();
            if (p != null) sweep(p);
        }
        sessions.clear();
    }

    // ------------------------------------------------------------------------------------- config lists
    /** lists.<menu>: [{material, amount, price, name?}] read, checked and clamped; bad lines are skipped with a note. */
    void loadConfigList(MenuDef m, String path, CostCharger.Kind currency, Material currencyMaterial, String currencyItem) {
        List<Map<?, ?>> raw = g.designer().plugin().getConfig().getMapList(path);
        int i = -1;
        for (Map<?, ?> row : raw) {
            i++;
            if (m.entries.size() >= MAX_CONFIG_ENTRIES || m.entries.size() >= m.pageSize() * Pagination.MAX_PAGES) { g.note(path + ": more than " + m.entries.size() + " entries do not fit " + Pagination.MAX_PAGES + " pages; the rest is ignored"); break; }
            Object mat = row.get("material");
            Material type = mat instanceof String ms ? Material.matchMaterial(ms) : null;
            String key = type == null ? "" : type.getKey().getKey();
            if (type == null || !type.isItem() || BANNED.matcher(key).matches()) { g.note(path + "[" + i + "]: " + mat + " cannot be sold, skipped"); continue; }
            if (currency == CostCharger.Kind.ITEM && currencyMaterial == type && currencyItem == null) { g.note(path + "[" + i + "]: a list cannot sell its own currency, skipped"); continue; }
            int amount = clampInt(row.get("amount"), 1, 64, 1, path + "[" + i + "].amount");
            double price = row.get("price") instanceof Number n ? n.doubleValue() : -1;
            CostCharger.Cost cost;
            switch (currency) {
                case ITEM: { int c = (int) Math.round(clampD(price, 1, 2304, path + "[" + i + "].price")); cost = currencyItem != null ? CostCharger.Cost.design(currencyItem, c) : CostCharger.Cost.items(currencyMaterial, c); break; }
                case XP_LEVELS: cost = CostCharger.Cost.levels((int) Math.round(clampD(price, 1, 1000, path + "[" + i + "].price"))); break;
                case ECONOMY: cost = CostCharger.Cost.money(clampD(price, 0.01, 1000000, path + "[" + i + "].price")); break;
                default: cost = CostCharger.Cost.NONE;
            }
            String name = row.get("name") instanceof String s ? clean(s, 40) : "";
            if (name.isEmpty()) name = pretty(key);
            final ItemStack give = new ItemStack(type);
            final int count = amount;
            final String label = name;
            ItemStack icon = g.icon(type, name, NamedTextColor.WHITE, List.of("x" + amount), Math.min(amount, type.getMaxStackSize()), false, null, null);
            m.entry(icon, cost, null, false, MenuDef.gives(stack(type, amount)), ctx -> { ctx.give(give, count); ctx.message("Bought " + count + " x " + label + ".", NamedTextColor.GREEN); });
        }
    }

    private static ItemStack stack(Material m, int n) { ItemStack s = new ItemStack(m); s.setAmount(Math.max(1, n)); return s; }

    private int clampInt(Object v, int min, int max, int dflt, String at) {
        if (!(v instanceof Number n)) { g.note(at + " is not a number, using " + dflt); return dflt; }
        int x = (int) Math.round(n.doubleValue());
        if (x < min || x > max) { int c = Math.max(min, Math.min(max, x)); g.note("clamped " + at + " " + x + " -> " + c); return c; }
        return x;
    }

    private double clampD(double v, double min, double max, String at) {
        if (Double.isNaN(v) || v < min || v > max) { double c = Double.isNaN(v) ? min : Math.max(min, Math.min(max, v)); g.note("clamped " + at + " " + v + " -> " + c); return c; }
        return v;
    }

    static String clean(String s, int max) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < s.length() && b.length() < max; i++) { char c = s.charAt(i); if (c >= ' ' && c != '§') b.append(c); }
        return b.toString();
    }

    static String pretty(String key) {
        String[] parts = key.split("_");
        StringBuilder b = new StringBuilder();
        for (String w : parts) { if (w.isEmpty()) continue; if (b.length() > 0) b.append(' '); b.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1).toLowerCase(Locale.ROOT)); }
        return b.toString();
    }
}
`;

export const DIALOGUE_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

/**
 * Component gameplay-dialogue v1 (DialogueMenu): the 3-row dialogue layout (speaker in slot 4, the lines on a book in
 * slot 13, up to five choices centred in the bottom row), used by dialogue menus and by the branch choice of a quest;
 * plus the quest log. Uses inventory menus on every version (Paper's Dialog API, 1.21.7+ and experimental, is not used).
 */
public final class DialogueMenu {
    public static final int SIZE = 27;
    private static final int[][] CHOICES = { {}, {22}, {20, 24}, {20, 22, 24}, {19, 21, 23, 25}, {18, 20, 22, 24, 26} };

    private DialogueMenu() {}

    public static int[] choiceSlots(int n) { return CHOICES[Math.max(0, Math.min(5, n))].clone(); }

    public static int logSize(int quests) { return Math.max(9, Math.min(54, ((quests + 8) / 9) * 9)); }

    static void renderDialogue(Gameplay g, MenuDef m, Player p, MenuManager.Holder h) {
        ItemStack head = m.speakerIcon != null ? m.speakerIcon : g.icon(Material.PLAYER_HEAD, m.speaker, m.speakerColor, List.of(), 1, false, null, null);
        h.inv.setItem(4, head);
        List<String> rest = m.lines.size() > 1 ? m.lines.subList(1, m.lines.size()) : List.of();
        h.inv.setItem(13, g.icon(Material.BOOK, m.lines.isEmpty() ? "..." : m.lines.get(0), NamedTextColor.WHITE, rest, 1, false, null, null));
        List<MenuDef.Button> visible = new ArrayList<>();
        for (MenuDef.Button b : m.entries) if (!b.hide || b.permission == null || p.hasPermission(g.designer().namespace() + "." + b.permission)) visible.add(b);
        int[] slots = choiceSlots(Math.min(5, visible.size()));
        for (int i = 0; i < slots.length; i++) g.menus().place(p, h, visible.get(i), slots[i]);
    }

    static void renderBranches(Gameplay g, Player p, MenuManager.Holder h, QuestDef q) {
        if (q == null) return;
        h.inv.setItem(4, q.icon());
        h.inv.setItem(13, g.icon(Material.BOOK, q.prompt(), NamedTextColor.WHITE, List.of("Pick one path to continue " + q.title() + "."), 1, false, null, null));
        int[] slots = choiceSlots(Math.min(5, q.branches().size()));
        for (int i = 0; i < slots.length; i++) {
            final QuestDef.Branch b = q.branches().get(i);
            final String quest = q.id();
            g.menus().place(p, h, new MenuDef.Button(-1, b.icon(), CostCharger.Cost.NONE, null, false, List.of(), ctx -> ctx.chooseBranch(quest, b.id())), slots[i]);
        }
    }

    static void renderLog(Gameplay g, Player p, MenuManager.Holder h) {
        int i = 0;
        for (QuestDef q : g.quests().defs().values()) {
            if (i >= h.inv.getSize()) break;
            final String id = q.id();
            ItemStack icon = q.icon().clone();
            List<String> lore = new ArrayList<>();
            lore.add(g.quests().state(p, q));
            if (!q.description().isEmpty()) lore.add(q.description());
            ItemStack shown = g.icon(icon.getType(), q.title(), NamedTextColor.GOLD, lore, 1, false, null, null);
            g.menus().place(p, h, new MenuDef.Button(-1, shown, CostCharger.Cost.NONE, null, false, List.of(), ctx -> {
                if (g.quests().startRefusal(ctx.player(), g.quests().def(id), true) == null) ctx.startQuest(id);
                else g.quests().info(ctx.player(), id);
            }), i++);
        }
    }
}
`;

export const QUESTDEF_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.kyori.adventure.text.format.TextColor;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

/**
 * Component gameplay-quest-def v1: the base of every generated quest. A generated quest declares its steps (each with
 * 1-3 objectives of the closed set), its branches and its rewards in load() / rewards() from config.yml parameters.
 * Main steps and branch steps share one id space; progress is stored by step id (see QuestStore).
 */
public abstract class QuestDef {
    public enum Start { COMMAND, MENU }
    public enum Repeat { ONCE, REPEATABLE, DAILY, WEEKLY }
    public enum OnDeath { KEEP, RESET_STEP, FAIL }
    public enum Kind { KILL, COLLECT, CRAFT, VISIT, BREAK, TALK, SURVIVE }

    /** One objective; count is the target (visit / talk: 1, survive: seconds). */
    public record Objective(Kind kind, Material material, String design, Set<String> entities, int kinds, int count, String world, double x, double y, double z, double radius, boolean pickup, boolean take, String menu) {
        public static Objective kill(Set<String> types, int kinds, int count) { return new Objective(Kind.KILL, null, null, types == null ? Set.of() : types, kinds, Math.max(1, count), null, 0, 0, 0, 0, false, false, null); }
        public static Objective collect(Material m, String design, int count, boolean pickup, boolean take) { return new Objective(Kind.COLLECT, m, design, Set.of(), 0, Math.max(1, count), null, 0, 0, 0, 0, pickup, take, null); }
        public static Objective craft(Material m, String design, int count) { return new Objective(Kind.CRAFT, m, design, Set.of(), 0, Math.max(1, count), null, 0, 0, 0, 0, false, false, null); }
        public static Objective visit(String world, double x, double y, double z, double radius) { return new Objective(Kind.VISIT, null, null, Set.of(), 0, 1, world, x, y, z, Math.max(1, radius), false, false, null); }
        public static Objective breaks(Material m, int count) { return new Objective(Kind.BREAK, m, null, Set.of(), 0, Math.max(1, count), null, 0, 0, 0, 0, false, false, null); }
        public static Objective talk(String menu) { return new Objective(Kind.TALK, null, null, Set.of(), 0, 1, null, 0, 0, 0, 0, false, false, menu); }
        public static Objective survive(int seconds) { return new Objective(Kind.SURVIVE, null, null, Set.of(), 0, Math.max(1, seconds), null, 0, 0, 0, 0, false, false, null); }
    }

    public record Step(String id, String text, List<Objective> objectives) {}

    public record Branch(String id, ItemStack icon, List<Step> steps) {}

    protected final Gameplay g;
    private final String id;
    private final Start start;
    private final Repeat repeat;
    private final OnDeath onDeath;
    private final boolean abandon;
    private final boolean actionbar;
    private final String permission;
    private final List<String> requires;
    private String title = "";
    private String description = "";
    private String prompt = "Choose your path";
    private ItemStack icon;
    private long cooldownSeconds;
    private long timeLimitSeconds;
    final List<Step> steps = new ArrayList<>();
    final List<Branch> branches = new ArrayList<>();

    protected QuestDef(Gameplay g, String id, Start start, Repeat repeat, OnDeath onDeath, boolean abandon, boolean actionbar, String permission, List<String> requires) {
        this.g = g;
        this.id = id;
        this.start = start;
        this.repeat = repeat;
        this.onDeath = onDeath;
        this.abandon = abandon;
        this.actionbar = actionbar;
        this.permission = permission;
        this.requires = requires;
    }

    public final String id() { return id; }
    public final Start start() { return start; }
    public final Repeat repeat() { return repeat; }
    public final OnDeath onDeath() { return onDeath; }
    public final boolean abandon() { return abandon; }
    public final boolean actionbar() { return actionbar; }
    public final String permission() { return permission; }
    public final List<String> requires() { return requires; }
    public final String title() { return title; }
    public final String description() { return description; }
    public final String prompt() { return prompt; }
    public final ItemStack icon() { return icon == null ? g.icon(Material.BOOK, title, null, List.of(), 1, false, null, null) : icon; }
    public final long cooldownSeconds() { return cooldownSeconds; }
    public final long timeLimitSeconds() { return timeLimitSeconds; }
    public final List<Step> steps() { return steps; }
    public final List<Branch> branches() { return branches; }
    public final boolean hasBranches() { return !branches.isEmpty(); }
    public final Step first() { return steps.get(0); }

    public final Branch branch(String branchId) {
        for (Branch b : branches) if (b.id().equals(branchId)) return b;
        return null;
    }

    /** The steps a player walks: the main steps, then the chosen branch's. */
    public final List<Step> path(String branchId) {
        List<Step> out = new ArrayList<>(steps);
        Branch b = branchId == null || branchId.isEmpty() ? null : branch(branchId);
        if (b != null) out.addAll(b.steps());
        return out;
    }

    public final Step step(String branchId, String stepId) {
        for (Step s : path(branchId)) if (s.id().equals(stepId)) return s;
        return null;
    }

    /** The step after stepId on the path, or null at the end of the path. */
    public final Step nextAfter(String branchId, String stepId) {
        List<Step> p = path(branchId);
        for (int i = 0; i < p.size() - 1; i++) if (p.get(i).id().equals(stepId)) return p.get(i + 1);
        return null;
    }

    public abstract void load(DesignConfig c);

    /** Generated: the quest's rewards (and the chosen branch's). Called AFTER the completion is stored. */
    protected abstract void rewards(Player p, RewardDistributor r, String branch);

    public void describe(List<String> out) {}

    protected final void reset() { steps.clear(); branches.clear(); }

    protected final void info(String title, String description, ItemStack icon, long cooldownSeconds, long timeLimitSeconds, String prompt) {
        this.title = title;
        this.description = description == null ? "" : description;
        this.icon = icon;
        this.cooldownSeconds = Math.max(0, cooldownSeconds);
        this.timeLimitSeconds = Math.max(0, timeLimitSeconds);
        if (prompt != null && !prompt.isEmpty()) this.prompt = prompt;
    }

    protected final void step(String stepId, String text, Objective... os) { steps.add(new Step(stepId, text, List.of(os))); }

    protected final void branch(String branchId, ItemStack branchIcon, Step... list) { branches.add(new Branch(branchId, branchIcon, List.of(list))); }

    protected static Step s(String stepId, String text, Objective... os) { return new Step(stepId, text, List.of(os)); }

    protected final ItemStack icon(Material m, String name, TextColor color, List<String> lore, int amount, boolean glint, String modelNs, String modelKey) { return g.icon(m, name, color, lore, amount, glint, modelNs, modelKey); }
    protected final ItemStack designIcon(String item, String name, TextColor color, List<String> lore, int amount, boolean glint) { return g.designIcon(item, name, color, lore, amount, glint); }
}
