import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;

/**
 * Component gameplay-quest-store v1 (QuestStore): per-player quest progress in the player's PersistentDataContainer
 * under <ns>:quests (saved with the player file, no database). Versioned text encoding, bounded (MAX_CHARS) and
 * migration-safe against the CURRENT quest definitions:
 *   q1|<quest>,<state A|C|D>,<step id>,<branch id>,<c0>.<c1>.<c2>,<started s>,<completions>,<last completed s>|...
 * (entries sorted by quest id). On load: an unknown format is copied to <ns>:quests_backup and reset; entries of quests
 * that no longer exist are dropped; a step or branch that no longer exists restarts that quest (completions are kept);
 * counts are clamped to the current targets. The TS twin (simulate.ts encodeProgress / decodeProgress) is identical.
 */
public final class QuestStore {
    public static final String VERSION = "q1";
    public static final int MAX_CHARS = 2048;
    public static final int MAX_COUNT = 1000000;
    public static final long MAX_TIME = 4102444800L;

    public static final class Entry {
        public final String quest;
        public char state = 'A';
        public String step = "";
        public String branch = "";
        public final int[] counts = new int[3];
        public long started;
        public int completions;
        public long last;

        public Entry(String quest) { this.quest = quest; }

        public void zero() { Arrays.fill(counts, 0); }
    }

    private final NamespacedKey key;
    private final NamespacedKey backup;

    QuestStore(String namespace) {
        this.key = new NamespacedKey(namespace, "quests");
        this.backup = new NamespacedKey(namespace, "quests_backup");
    }

    public static String encode(Map<String, Entry> m) {
        StringBuilder b = new StringBuilder(VERSION);
        List<String> ids = new ArrayList<>(m.keySet());
        Collections.sort(ids);
        for (String id : ids) {
            Entry e = m.get(id);
            b.append('|').append(e.quest).append(',').append(e.state).append(',').append(e.step).append(',').append(e.branch).append(',')
                .append(e.counts[0]).append('.').append(e.counts[1]).append('.').append(e.counts[2]).append(',')
                .append(e.started).append(',').append(e.completions).append(',').append(e.last);
        }
        return b.toString();
    }

    private static int num(String s, int min, int max) {
        try { return Math.max(min, Math.min(max, Integer.parseInt(s))); } catch (NumberFormatException e) { return min; }
    }

    private static long time(String s) {
        try { return Math.max(0L, Math.min(MAX_TIME, Long.parseLong(s))); } catch (NumberFormatException e) { return 0L; }
    }

    private static String cut(String s) { return s.length() > 32 ? s.substring(0, 32) : s; }

    /** Decode + migrate (never throws; notes say what changed). An unknown format gives an empty map and a note. */
    public static Map<String, Entry> decode(String raw, Map<String, QuestDef> defs, List<String> notes) {
        Map<String, Entry> out = new TreeMap<>();
        if (raw == null || raw.isEmpty() || raw.equals(VERSION)) return out;
        if (!raw.startsWith(VERSION + "|") || raw.length() > MAX_CHARS * 2) { notes.add("unknown or oversized quest progress format, reset (backup kept)"); return out; }
        String[] parts = raw.split("\\|", -1);
        for (int i = 1; i < parts.length && out.size() < 64; i++) {
            String[] f = parts[i].split(",", -1);
            if (f.length != 8) { notes.add("dropped a malformed progress entry"); continue; }
            QuestDef q = defs.get(f[0]);
            if (q == null) { notes.add("dropped the progress of quest " + cut(f[0]) + " (no longer in this mod)"); continue; }
            char st = f[1].length() == 1 ? f[1].charAt(0) : '?';
            if ("ACD".indexOf(st) < 0) { notes.add("dropped the progress of quest " + q.id() + " (unknown state)"); continue; }
            Entry e = new Entry(q.id());
            e.state = st;
            e.step = f[2];
            e.branch = f[3];
            String[] c = f[4].split("\\.", -1);
            for (int j = 0; j < 3; j++) e.counts[j] = j < c.length ? num(c[j], 0, MAX_COUNT) : 0;
            e.started = time(f[5]);
            e.completions = num(f[6], 0, MAX_COUNT);
            e.last = time(f[7]);
            if (!e.branch.isEmpty() && q.branch(e.branch) == null) { notes.add(q.id() + ": branch " + cut(e.branch) + " no longer exists"); e.branch = ""; }
            if (e.state == 'A') {
                QuestDef.Step s = q.step(e.branch, e.step);
                if (s == null) { notes.add(q.id() + ": step " + cut(e.step) + " changed, the quest restarts"); e.step = q.first().id(); e.branch = ""; e.zero(); s = q.first(); }
                for (int j = 0; j < 3; j++) e.counts[j] = j < s.objectives().size() ? Math.min(e.counts[j], s.objectives().get(j).count()) : 0;
            } else if (e.state == 'C') {
                if (!q.hasBranches()) { notes.add(q.id() + ": the branches were removed, the quest restarts"); e.state = 'A'; e.step = q.first().id(); }
                else e.step = "";
                e.branch = "";
                e.zero();
            } else { e.step = ""; e.branch = ""; e.zero(); }
            out.put(q.id(), e);
        }
        return out;
    }

    public Map<String, Entry> load(Player p, Map<String, QuestDef> defs, List<String> notes) {
        PersistentDataContainer pdc = p.getPersistentDataContainer();
        String raw = pdc.get(key, PersistentDataType.STRING);
        if (raw != null && !raw.isEmpty() && !raw.equals(VERSION) && (!raw.startsWith(VERSION + "|") || raw.length() > MAX_CHARS * 2)) {
            pdc.set(backup, PersistentDataType.STRING, raw.length() > MAX_CHARS ? raw.substring(0, MAX_CHARS) : raw);
            pdc.remove(key);
        }
        return decode(raw, defs, notes);
    }

    /** Store (false = it would exceed MAX_CHARS: nothing is written). */
    public boolean save(Player p, Map<String, Entry> m) {
        String s = encode(m);
        if (s.length() > MAX_CHARS) return false;
        if (m.isEmpty()) p.getPersistentDataContainer().remove(key);
        else p.getPersistentDataContainer().set(key, PersistentDataType.STRING, s);
        return true;
    }

    public void reset(Player p) { p.getPersistentDataContainer().remove(key); }
}
