import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

/**
 * Component gameplay-rewards v1 (RewardDistributor): quest rewards and menu gives. Items go into the inventory (what does
 * not fit drops at the player's feet: a reward is never lost); XP points / levels; a potion effect; an advancement of
 * THIS project's data pack (all remaining criteria awarded; a missing advancement is logged once and grants nothing);
 * an item ability of this mod; a message. Never a command, never another player.
 */
public final class RewardDistributor {
    private final Gameplay g;
    private final Set<String> missing = new HashSet<>();

    RewardDistributor(Gameplay g) { this.g = g; }

    public void give(Player p, ItemStack stack, int count) {
        if (stack == null || count <= 0) return;
        int max = Math.max(1, stack.getMaxStackSize());
        int left = Math.min(count, 2304);
        while (left > 0) {
            ItemStack s = stack.clone();
            int n = Math.min(left, max);
            s.setAmount(n);
            left -= n;
            for (ItemStack rest : p.getInventory().addItem(s).values()) p.getWorld().dropItemNaturally(p.getLocation(), rest);
        }
    }

    public void design(Player p, String item, int count) { DesignItem i = g.designer().item(item); if (i != null) give(p, i.create(), count); }
    public void points(Player p, int n) { if (n > 0) p.giveExp(n); }
    public void levels(Player p, int n) { if (n > 0) p.giveExpLevels(n); }
    public void potion(Player p, PotionEffectType t, int ticks, int amplifier) { if (t != null) p.addPotionEffect(new PotionEffect(t, ticks, amplifier)); }
    public void ability(Player p, String item, String ability) { g.runAbility(p, item, ability); }
    public void message(Player p, String text, TextColor color) { p.sendMessage(Component.text(text.replace("{player}", p.getName()), color)); }

    public void advancement(Player p, String key) {
        Advancement a = Bukkit.getAdvancement(new NamespacedKey(g.designer().namespace(), key));
        if (a == null) {
            if (missing.add(key)) g.designer().plugin().getLogger().warning("quest reward: advancement " + g.designer().namespace() + ":" + key + " is not loaded (is the mod's data pack installed?)");
            return;
        }
        AdvancementProgress pr = p.getAdvancementProgress(a);
        for (String c : new ArrayList<>(pr.getRemainingCriteria())) pr.awardCriteria(c);
    }
}
