// Cyrus R3 gameplay designers, part 2: the verified Java components for MENUS and QUESTS. Fixed code (reviewed once,
// compiled with javac against the real Paper classpaths of 1.21.11 / JDK 21 and 26.2 / JDK 25, strict-scanned, booted in
// Test Flight); generated menu / quest classes only call them. `__PKG__` is replaced by the mod's package. They live in
// the same `<pkg>.designer` package as the item components (they use the Designer hub: identity, tasks, config, items,
// abilities) and add NO per-version code: the item library's Compat is the only per-version file. No reflection, no
// threads, no network, no command dispatch, no files outside the plugin folder.
/* eslint-disable no-useless-escape */

export const PAGINATION_JAVA = String.raw`package __PKG__.designer;

/** Component gameplay-pagination v1: page math of paginated menu lists (pure). Pages are 0-based, always clamped, at most MAX_PAGES. */
public final class Pagination {
    public static final int MAX_PAGES = 10;

    private Pagination() {}

    public static int pages(int entries, int pageSize) {
        if (pageSize <= 0) return 1;
        int p = (Math.max(0, entries) + pageSize - 1) / pageSize;
        return Math.max(1, Math.min(MAX_PAGES, p));
    }

    public static int clamp(int page, int entries, int pageSize) { return Math.max(0, Math.min(pages(entries, pageSize) - 1, page)); }

    public static int first(int page, int pageSize) { return Math.max(0, page) * Math.max(0, pageSize); }

    /** Entries shown on this (clamped) page; entries past MAX_PAGES are never shown. */
    public static int count(int page, int entries, int pageSize) {
        if (pageSize <= 0) return 0;
        int f = first(clamp(page, entries, pageSize), pageSize);
        int shown = Math.min(Math.max(0, entries), pages(entries, pageSize) * pageSize);
        return Math.max(0, Math.min(pageSize, shown - f));
    }

    public static boolean hasNext(int page, int entries, int pageSize) { return clamp(page, entries, pageSize) < pages(entries, pageSize) - 1; }

    public static boolean hasPrev(int page, int entries, int pageSize) { return clamp(page, entries, pageSize) > 0; }
}
`;

export const COST_JAVA = String.raw`package __PKG__.designer;

import java.util.List;
import java.util.Locale;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.PlayerInventory;

/**
 * Component gameplay-cost v1: costs of menu clicks. Items (a vanilla material WITHOUT a design identity, or one of this
 * mod's design items BY identity; menu icons never count), XP levels, or money through Vault (only when the Vault
 * plugin and an economy are on the server; otherwise the click is refused with a clear message). The protocol is fixed
 * and dupe-proof: everything runs on the main thread inside one click handler, in this order: room for the given stacks
 * -> can pay -> TAKE (re-checked, all-or-nothing) -> give. A failed take gives nothing.
 */
public final class CostCharger {
    public enum Kind { FREE, ITEM, XP_LEVELS, ECONOMY }

    /** kind + vanilla material or design item key + count (items / levels) or amount (money). */
    public record Cost(Kind kind, Material material, String design, int count, double amount) {
        public static final Cost NONE = new Cost(Kind.FREE, null, null, 0, 0);
        public static Cost items(Material m, int count) { return new Cost(Kind.ITEM, m, null, Math.max(1, count), 0); }
        public static Cost design(String key, int count) { return new Cost(Kind.ITEM, null, key, Math.max(1, count), 0); }
        public static Cost levels(int n) { return new Cost(Kind.XP_LEVELS, null, null, Math.max(1, n), 0); }
        public static Cost money(double a) { return new Cost(Kind.ECONOMY, null, null, 0, Math.max(0.01, a)); }
        public boolean free() { return kind == Kind.FREE; }
    }

    /** Money hook: set by the main class only when the mod has money costs AND the Vault plugin is installed. */
    public interface Money {
        boolean ready();
        boolean has(Player p, double amount);
        boolean withdraw(Player p, double amount);
        String format(double amount);
    }

    private final Gameplay g;
    private Money money;

    CostCharger(Gameplay g) { this.g = g; }

    void money(Money m) { this.money = m; }

    public boolean moneyReady() { return money != null && money.ready(); }

    public String describe(Cost c) {
        switch (c.kind()) {
            case ITEM: return c.count() + " x " + (c.design() != null ? c.design().replace('_', ' ') : c.material().getKey().getKey().replace('_', ' '));
            case XP_LEVELS: return c.count() + " level" + (c.count() == 1 ? "" : "s");
            case ECONOMY: return moneyReady() ? money.format(c.amount()) : String.format(Locale.ROOT, "%.2f money", c.amount());
            default: return "free";
        }
    }

    private boolean matches(ItemStack s, Cost c) {
        if (s == null || s.getType().isAir() || g.menus().isIcon(s)) return false;
        String id = g.designer().identity().idOf(s);
        if (c.design() != null) return c.design().equals(id);
        return id == null && s.getType() == c.material();
    }

    /** How many matching items the player's storage (36 slots, no armor / off hand) holds. */
    public int count(Player p, Cost c) {
        if (c.kind() != Kind.ITEM) return 0;
        int n = 0;
        for (ItemStack s : p.getInventory().getStorageContents()) if (matches(s, c)) n += s.getAmount();
        return n;
    }

    /** null = the player can pay; else the reason shown to the player. */
    public String refusal(Player p, Cost c) {
        switch (c.kind()) {
            case ITEM: return count(p, c) >= c.count() ? null : "You need " + describe(c) + ".";
            case XP_LEVELS: return p.getLevel() >= c.count() ? null : "You need " + describe(c) + ".";
            case ECONOMY:
                if (!moneyReady()) return "This server has no economy (Vault) set up, so this can't be bought with money.";
                return money.has(p, c.amount()) ? null : "You need " + describe(c) + ".";
            default: return null;
        }
    }

    /** Take the cost (re-checked first). All or nothing: returns false and takes NOTHING when the player cannot pay. */
    public boolean take(Player p, Cost c) {
        if (refusal(p, c) != null) return false;
        switch (c.kind()) {
            case ITEM: {
                PlayerInventory inv = p.getInventory();
                ItemStack[] st = inv.getStorageContents();
                int left = c.count();
                for (int i = 0; i < st.length && left > 0; i++) {
                    ItemStack s = st[i];
                    if (!matches(s, c)) continue;
                    int use = Math.min(left, s.getAmount());
                    left -= use;
                    if (use == s.getAmount()) st[i] = null;
                    else { ItemStack r = s.clone(); r.setAmount(s.getAmount() - use); st[i] = r; }
                }
                if (left > 0) return false;
                inv.setStorageContents(st);
                return true;
            }
            case XP_LEVELS: p.setLevel(Math.max(0, p.getLevel() - c.count())); return true;
            case ECONOMY: return money != null && money.withdraw(p, c.amount());
            default: return true;
        }
    }

    /** Can the player's storage take ALL these stacks without dropping anything (simulated on a copy)? */
    public static boolean fits(Player p, List<ItemStack> stacks) {
        if (stacks == null || stacks.isEmpty()) return true;
        ItemStack[] st = p.getInventory().getStorageContents();
        ItemStack[] sim = new ItemStack[st.length];
        for (int i = 0; i < st.length; i++) sim[i] = st[i] == null || st[i].getType().isAir() ? null : st[i].clone();
        for (ItemStack want : stacks) {
            if (want == null) continue;
            int left = want.getAmount();
            int max = Math.max(1, want.getMaxStackSize());
            for (int i = 0; i < sim.length && left > 0; i++) {
                if (sim[i] != null && sim[i].isSimilar(want) && sim[i].getAmount() < max) {
                    int add = Math.min(left, max - sim[i].getAmount());
                    sim[i].setAmount(sim[i].getAmount() + add);
                    left -= add;
                }
            }
            for (int i = 0; i < sim.length && left > 0; i++) {
                if (sim[i] == null) { int add = Math.min(left, max); ItemStack n = want.clone(); n.setAmount(add); sim[i] = n; left -= add; }
            }
            if (left > 0) return false;
        }
        return true;
    }
}
`;

export const MENUDEF_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.format.TextColor;
import org.bukkit.Material;
import org.bukkit.inventory.ItemStack;

/**
 * Component gameplay-menu-def v1: the base of every generated menu. A generated menu only declares its layout in load()
 * (after reading its parameters from config.yml): fixed buttons, a paginated list (fixed entries or a config list),
 * dialogue speaker + lines + choices. Every clickable carries its icon, cost, permission, the stacks it gives (checked
 * for room BEFORE the cost is taken) and a Click with straight-line calls on MenuContext. No code runs at render time.
 */
public abstract class MenuDef {
    public enum Style { CHEST, DIALOGUE }

    /** What a click does: generated straight-line calls on MenuContext. */
    public interface Click { void run(MenuContext ctx); }

    /** One clickable (slot -1 = a list entry / dialogue choice placed by the layout). */
    public static final class Button {
        final int slot;
        final ItemStack icon;
        final CostCharger.Cost cost;
        final String permission;
        final boolean hide;
        final List<ItemStack> gives;
        final Click click;

        Button(int slot, ItemStack icon, CostCharger.Cost cost, String permission, boolean hide, List<ItemStack> gives, Click click) {
            this.slot = slot;
            this.icon = icon;
            this.cost = cost == null ? CostCharger.Cost.NONE : cost;
            this.permission = permission;
            this.hide = hide;
            this.gives = gives == null ? List.of() : gives;
            this.click = click;
        }

        public CostCharger.Cost cost() { return cost; }
        public String permission() { return permission; }
        public ItemStack icon() { return icon; }
    }

    protected final Gameplay g;
    private final String id;
    private final Style style;
    private final int rows;
    private final String permission;
    private final boolean command;
    private final String opener;
    private final boolean npc;
    final List<Button> buttons = new ArrayList<>();
    final List<Button> entries = new ArrayList<>();
    final List<String> lines = new ArrayList<>();
    int[] listSlots = new int[0];
    Button prev;
    Button next;
    Material filler;
    String speaker = "";
    TextColor speakerColor;
    ItemStack speakerIcon;
    String configList;

    protected MenuDef(Gameplay g, String id, Style style, int rows, String permission, boolean command, String opener, boolean npc) {
        this.g = g;
        this.id = id;
        this.style = style;
        this.rows = Math.max(1, Math.min(6, rows));
        this.permission = permission;
        this.command = command;
        this.opener = opener;
        this.npc = npc;
    }

    public final String id() { return id; }
    public final Style style() { return style; }
    public final int rows() { return style == Style.DIALOGUE ? 3 : rows; }
    public final String permission() { return permission; }
    public final boolean command() { return command; }
    public final String opener() { return opener; }
    public final boolean npc() { return npc; }
    public final List<Button> buttons() { return buttons; }
    public final List<Button> entries() { return entries; }
    public final int pageSize() { return listSlots.length; }
    public final String configList() { return configList; }

    public abstract void load(DesignConfig c);
    public abstract String title();
    public void describe(List<String> out) {}

    protected final void reset() {
        buttons.clear();
        entries.clear();
        lines.clear();
        listSlots = new int[0];
        prev = null;
        next = null;
        filler = null;
        configList = null;
    }

    protected final void filler(Material m) { filler = m; }

    protected final void button(int slot, ItemStack icon, CostCharger.Cost cost, String perm, boolean hide, List<ItemStack> gives, Click click) {
        if (icon != null && slot >= 0 && slot < rows() * 9) buttons.add(new Button(slot, icon, cost, perm, hide, gives, click));
    }

    protected final void entry(ItemStack icon, CostCharger.Cost cost, String perm, boolean hide, List<ItemStack> gives, Click click) {
        if (icon != null) entries.add(new Button(-1, icon, cost, perm, hide, gives, click));
    }

    protected final void list(int[] slots, int prevSlot, ItemStack prevIcon, int nextSlot, ItemStack nextIcon) {
        listSlots = slots.clone();
        prev = new Button(prevSlot, prevIcon, CostCharger.Cost.NONE, null, false, List.of(), MenuContext::prevPage);
        next = new Button(nextSlot, nextIcon, CostCharger.Cost.NONE, null, false, List.of(), MenuContext::nextPage);
    }

    /** A list read from config.yml lists.<menu id> (owner-editable, never reset by an update; checked + clamped on load). */
    protected final void configList(CostCharger.Kind currency, Material currencyMaterial, String currencyItem) {
        configList = "lists." + id;
        g.menus().loadConfigList(this, configList, currency, currencyMaterial, currencyItem);
    }

    protected final void dialogue(String speakerName, TextColor color, ItemStack icon, List<String> text) {
        speaker = speakerName;
        speakerColor = color;
        speakerIcon = icon;
        lines.clear();
        for (String s : text) if (s != null && !s.isEmpty()) lines.add(s);
    }

    protected final ItemStack icon(Material m, String name, TextColor color, List<String> lore, int amount, boolean glint, String modelNs, String modelKey) { return g.icon(m, name, color, lore, amount, glint, modelNs, modelKey); }
    protected final ItemStack designIcon(String item, String name, TextColor color, List<String> lore, int amount, boolean glint) { return g.designIcon(item, name, color, lore, amount, glint); }
    protected final ItemStack stack(Material m, int count) { ItemStack s = new ItemStack(m); s.setAmount(Math.max(1, count)); return s; }
    protected final ItemStack designStack(String item, int count) { DesignItem i = g.designer().item(item); if (i == null) return null; ItemStack s = i.create(); s.setAmount(Math.max(1, count)); return s; }
    protected static List<ItemStack> gives(ItemStack... stacks) { List<ItemStack> out = new ArrayList<>(); for (ItemStack s : stacks) if (s != null) out.add(s); return out; }
}
`;

export const MENUCTX_JAVA = String.raw`package __PKG__.designer;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextColor;
import org.bukkit.SoundCategory;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

/**
 * Component gameplay-menu-context v1: everything a menu click may do, on the clicking player only. Navigation (open,
 * back, pages, close, quest log) is deferred one tick (never inside the click event); quest actions go through Quests
 * (which checks every rule again). No command dispatch, no other player.
 */
public final class MenuContext {
