    private final Player p;
    private final MenuManager.Holder h;

    MenuContext(Gameplay g, Player p, MenuManager.Holder h) { this.g = g; this.p = p; this.h = h; }

    public Player player() { return p; }

    private String fill(String s) { return s.replace("{player}", p.getName()); }

    public void give(ItemStack stack, int count) { g.rewards().give(p, stack, count); }
    public void giveDesign(String item, int count) { g.rewards().design(p, item, count); }
    public void message(String text, TextColor color) { p.sendMessage(Component.text(fill(text), color)); }
    public void actionbar(String text, TextColor color) { p.sendActionBar(Component.text(fill(text), color)); }

    public void sound(String key, float volume, float pitch) {
        if (key != null && !key.isEmpty()) p.playSound(p.getLocation(), key, SoundCategory.PLAYERS, volume, pitch);
    }

    public void potion(PotionEffectType type, int ticks, int amplifier) { if (type != null) p.addPotionEffect(new PotionEffect(type, ticks, amplifier)); }

    public void heal(double amount) {
        if (amount <= 0 || p.isDead()) return;
        AttributeInstance max = p.getAttribute(Compat.MAX_HEALTH);
        p.setHealth(Math.min(max == null ? 20.0 : max.getValue(), p.getHealth() + amount));
    }

    public void ability(String item, String ability) { g.runAbility(p, item, ability); }
    public void open(String menu) { g.menus().later(p, () -> g.menus().open(p, menu, 0, true)); }
    public void close() { g.menus().later(p, p::closeInventory); }
    public void back() { g.menus().later(p, () -> g.menus().back(p)); }
    public void nextPage() { final int page = h.page() + 1; final String m = h.menu(); g.menus().later(p, () -> g.menus().open(p, m, page, false)); }
    public void prevPage() { final int page = h.page() - 1; final String m = h.menu(); g.menus().later(p, () -> g.menus().open(p, m, page, false)); }
    public void startQuest(String quest) { g.quests().start(p, quest, false); }
    public void abandonQuest(String quest) { g.quests().abandon(p, quest); }
    public void chooseBranch(String quest, String branch) { if (g.quests().choose(p, quest, branch)) close(); }
    public void questLog() { g.menus().later(p, () -> g.menus().open(p, MenuManager.LOG, 0, true)); }
}
