public final class MenuManager implements Listener {
    public static final int MAX_BACK = 8;
    public static final int MAX_CONFIG_ENTRIES = 270;
    public static final String LOG = "#log";
    public static final String BRANCH = "#branch:";
    private static final Pattern BANNED = Pattern.compile("(air|command_block.*|chain_command_block|repeating_command_block|structure_block|structure_void|jigsaw|barrier|light|debug_stick|knowledge_book|.*_spawn_egg|ender_pearl|ender_eye|chorus_fruit|milk_bucket|written_book|bundle|.*_bundle|test_block|test_instance_block)");

    /** The holder of a menu inventory: which menu, for whom, which page, which slots hold which button. */
    public static final class Holder implements InventoryHolder {
        private final String menu;
        private final UUID viewer;
        private int page;
        final Map<Integer, MenuDef.Button> slots = new HashMap<>();
        Inventory inv;

        Holder(String menu, UUID viewer, int page) { this.menu = menu; this.viewer = viewer; this.page = page; }

        @Override
        public Inventory getInventory() { return inv; }

        public String menu() { return menu; }
        public int page() { return page; }
        void page(int p) { page = p; }
        public UUID viewer() { return viewer; }
    }

    private static final class Session {
        final ArrayDeque<String> back = new ArrayDeque<>();
        String current;
        long lastClick = -1000L;
        long lastOpen = -1000L;
