    private final Gameplay g;
    private final Map<String, MenuDef> menus = new LinkedHashMap<>();
    private final Map<UUID, Session> sessions = new HashMap<>();
    private final NamespacedKey iconKey;
    private long clickCooldown = 4L;

    MenuManager(Gameplay g) {
