import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;

/**
 * Component gameplay-quest-store v1 (QuestStore): per-player quest progress in the player's PersistentDataContainer
 * under <ns>:quests (saved with the player file, no database). Versioned text encoding, bounded (MAX_CHARS) and
 * migration-safe against the CURRENT quest definitions:
 *   q1|<quest>,<state A|C|D>,<step id>,<branch id>,<c0>.<c1>.<c2>,<started s>,<completions>,<last completed s>|...
 * (entries sorted by quest id). On load: an unknown format is copied to <ns>:quests_backup and reset; entries of quests
 * that no longer exist are dropped; a step or branch that no longer exists restarts that quest (completions are kept);
 * counts are clamped to the current targets. The TS twin (simulate.ts encodeProgress / decodeProgress) is identical.
 */
public final class QuestStore {
    public static final String VERSION = "q1";
    public static final int MAX_CHARS = 2048;
    public static final int MAX_COUNT = 1000000;
    public static final long MAX_TIME = 4102444800L;

    public static final class Entry {
        public final String quest;
        public char state = 'A';
        public String step = "";
        public String branch = "";
        public final int[] counts = new int[3];
        public long started;
        public int completions;
        public long last;

        public Entry(String quest) { this.quest = quest; }

        public void zero() { Arrays.fill(counts, 0); }
    }

    private final NamespacedKey key;
    private final NamespacedKey backup;

    QuestStore(String namespace) {
        this.key = new NamespacedKey(namespace, "quests");
        this.backup = new NamespacedKey(namespace, "quests_backup");
    }

    public static String encode(Map<String, Entry> m) {
        StringBuilder b = new StringBuilder(VERSION);
        List<String> ids = new ArrayList<>(m.keySet());
        Collections.sort(ids);
        for (String id : ids) {
            Entry e = m.get(id);
            b.append('|').append(e.quest).append(',').append(e.state).append(',').append(e.step).append(',').append(e.branch).append(',')
                .append(e.counts[0]).append('.').append(e.counts[1]).append('.').append(e.counts[2]).append(',')
                .append(e.started).append(',').append(e.completions).append(',').append(e.last);
        }
        return b.toString();
    }

    private static int num(String s, int min, int max) {
        try { return Math.max(min, Math.min(max, Integer.parseInt(s))); } catch (NumberFormatException e) { return min; }
    }

    private static long time(String s) {
        try { return Math.max(0L, Math.min(MAX_TIME, Long.parseLong(s))); } catch (NumberFormatException e) { return 0L; }
    }

    private static String cut(String s) { return s.length() > 32 ? s.substring(0, 32) : s; }

    /** Decode + migrate (never throws; notes say what changed). An unknown format gives an empty map and a note. */
    public static Map<String, Entry> decode(String raw, Map<String, QuestDef> defs, List<String> notes) {
        Map<String, Entry> out = new TreeMap<>();
        if (raw == null || raw.isEmpty() || raw.equals(VERSION)) return out;
        if (!raw.startsWith(VERSION + "|") || raw.length() > MAX_CHARS * 2) { notes.add("unknown or oversized quest progress format, reset (backup kept)"); return out; }
        String[] parts = raw.split("\\|", -1);
        for (int i = 1; i < parts.length && out.size() < 64; i++) {
            String[] f = parts[i].split(",", -1);
            if (f.length != 8) { notes.add("dropped a malformed progress entry"); continue; }
            QuestDef q = defs.get(f[0]);
            if (q == null) { notes.add("dropped the progress of quest " + cut(f[0]) + " (no longer in this mod)"); continue; }
            char st = f[1].length() == 1 ? f[1].charAt(0) : '?';
            if ("ACD".indexOf(st) < 0) { notes.add("dropped the progress of quest " + q.id() + " (unknown state)"); continue; }
            Entry e = new Entry(q.id());
            e.state = st;
            e.step = f[2];
            e.branch = f[3];
            String[] c = f[4].split("\\.", -1);
            for (int j = 0; j < 3; j++) e.counts[j] = j < c.length ? num(c[j], 0, MAX_COUNT) : 0;
            e.started = time(f[5]);
            e.completions = num(f[6], 0, MAX_COUNT);
            e.last = time(f[7]);
            if (!e.branch.isEmpty() && q.branch(e.branch) == null) { notes.add(q.id() + ": branch " + cut(e.branch) + " no longer exists"); e.branch = ""; }
            if (e.state == 'A') {
                QuestDef.Step s = q.step(e.branch, e.step);
                if (s == null) { notes.add(q.id() + ": step " + cut(e.step) + " changed, the quest restarts"); e.step = q.first().id(); e.branch = ""; e.zero(); s = q.first(); }
                for (int j = 0; j < 3; j++) e.counts[j] = j < s.objectives().size() ? Math.min(e.counts[j], s.objectives().get(j).count()) : 0;
            } else if (e.state == 'C') {
                if (!q.hasBranches()) { notes.add(q.id() + ": the branches were removed, the quest restarts"); e.state = 'A'; e.step = q.first().id(); }
                else e.step = "";
                e.branch = "";
                e.zero();
            } else { e.step = ""; e.branch = ""; e.zero(); }
            out.put(q.id(), e);
        }
        return out;
    }

    public Map<String, Entry> load(Player p, Map<String, QuestDef> defs, List<String> notes) {
        PersistentDataContainer pdc = p.getPersistentDataContainer();
        String raw = pdc.get(key, PersistentDataType.STRING);
        if (raw != null && !raw.isEmpty() && !raw.equals(VERSION) && (!raw.startsWith(VERSION + "|") || raw.length() > MAX_CHARS * 2)) {
            pdc.set(backup, PersistentDataType.STRING, raw.length() > MAX_CHARS ? raw.substring(0, MAX_CHARS) : raw);
            pdc.remove(key);
        }
        return decode(raw, defs, notes);
    }

    /** Store (false = it would exceed MAX_CHARS: nothing is written). */
    public boolean save(Player p, Map<String, Entry> m) {
        String s = encode(m);
        if (s.length() > MAX_CHARS) return false;
        if (m.isEmpty()) p.getPersistentDataContainer().remove(key);
        else p.getPersistentDataContainer().set(key, PersistentDataType.STRING, s);
        return true;
    }

    public void reset(Player p) { p.getPersistentDataContainer().remove(key); }
}
`;

export const QUESTS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

/**
 * Component gameplay-quests v1: the quest engine. Rules (the TS simulator implements exactly these): a quest starts when
 * its permission, prerequisites (completed at least once), repeat rule (once / cooldown since the last completion) and
 * the active-quest cap (general.max_active_quests, 1-5) allow it; steps run in order, a step completes when all its
 * objectives reach their targets (collect objectives with take remove the items first, all or nothing); after the main
 * steps a quest with branches waits for a choice; completion is STORED before any reward is given (a reward can never
 * be claimed twice); death follows the quest's rule (keep: survive counts restart, reset_step, fail); a time limit fails
 * the quest; abandoning keeps the completion history. Progress lives in QuestStore (cached per online player).
 */
public final class Quests {
    public interface Match { int amount(QuestDef.Objective o); }

    private final Gameplay g;
    private final QuestStore store;
    private final Map<String, QuestDef> defs = new LinkedHashMap<>();
    private final Map<UUID, Map<String, QuestStore.Entry>> cache = new HashMap<>();
    private final EnumMap<QuestDef.Kind, Integer> index = new EnumMap<>(QuestDef.Kind.class);
    private int maxActive = 3;

    Quests(Gameplay g) {
        this.g = g;
        this.store = new QuestStore(g.designer().namespace());
    }

    void register(List<QuestDef> list) {
        List<QuestDef> sorted = new ArrayList<>(list);
        sorted.sort((a, b) -> a.id().compareTo(b.id()));
        for (QuestDef q : sorted) defs.put(q.id(), q);
    }

    void load(DesignConfig c) {
        maxActive = c.integer("general.max_active_quests", 1, 5);
        for (QuestDef q : defs.values()) q.load(c);
        index.clear();
        for (QuestDef q : defs.values()) {
            List<QuestDef.Step> all = new ArrayList<>(q.steps());
            for (QuestDef.Branch b : q.branches()) all.addAll(b.steps());
            for (QuestDef.Step s : all) for (QuestDef.Objective o : s.objectives()) index.merge(o.kind(), 1, Integer::sum);
        }
        // definitions changed: re-check every cached player against them (migration-safe)
        for (UUID id : new ArrayList<>(cache.keySet())) {
            Player p = g.designer().plugin().getServer().getPlayer(id);
            cache.remove(id);
            if (p != null) of(p);
        }
    }

    public Map<String, QuestDef> defs() { return defs; }
    public QuestDef def(String id) { return id == null ? null : defs.get(id); }
    public boolean uses(QuestDef.Kind k) { return index.containsKey(k); }
    public Map<QuestDef.Kind, Integer> index() { return index; }
    public int maxActive() { return maxActive; }
    public int cached() { return cache.size(); }
    public long now() { return System.currentTimeMillis() / 1000L; }

    Map<String, QuestStore.Entry> of(Player p) {
        Map<String, QuestStore.Entry> m = cache.get(p.getUniqueId());
        if (m != null) return m;
        List<String> notes = new ArrayList<>();
        m = store.load(p, defs, notes);
        cache.put(p.getUniqueId(), m);
        for (String n : notes) g.designer().plugin().getLogger().info("quest progress of " + p.getName() + ": " + n);
        if (!notes.isEmpty()) store.save(p, m);
        return m;
    }

    boolean save(Player p) { return store.save(p, of(p)); }
    void forget(UUID id) { cache.remove(id); }
    void saveAll() { for (UUID id : cache.keySet()) { Player p = g.designer().plugin().getServer().getPlayer(id); if (p != null) store.save(p, cache.get(id)); } }
    void clear() { cache.clear(); }
    void reset(Player p) { cache.remove(p.getUniqueId()); store.reset(p); }

    public int active(Player p) {
        int n = 0;
        for (QuestStore.Entry e : of(p).values()) if (e.state == 'A' || e.state == 'C') n++;
        return n;
    }

    private static void say(Player p, String text, NamedTextColor color) { p.sendMessage(Component.text(text, color)); }

    static String duration(long s) {
        if (s >= 86400) return (s / 86400) + "d " + ((s % 86400) / 3600) + "h";
        if (s >= 3600) return (s / 3600) + "h " + ((s % 3600) / 60) + "m";
        if (s >= 60) return (s / 60) + "m " + (s % 60) + "s";
        return s + "s";
    }

    /** null = the player may start it now; else why not. */
    public String startRefusal(Player p, QuestDef q, boolean viaCommand) {
        if (q == null) return "There is no such quest.";
        if (viaCommand && q.start() == QuestDef.Start.MENU) return "This quest is started from a menu.";
        if (q.permission() != null && !p.hasPermission(g.designer().namespace() + "." + q.permission())) return "You don't have permission to start this quest.";
        Map<String, QuestStore.Entry> m = of(p);
        for (String r : q.requires()) { QuestStore.Entry x = m.get(r); if (x == null || x.completions == 0) return "Finish " + (def(r) == null ? r : def(r).title()) + " first."; }
        QuestStore.Entry e = m.get(q.id());
        if (e != null && (e.state == 'A' || e.state == 'C')) return "You are already doing this quest.";
        if (e != null && e.completions > 0) {
            if (q.repeat() == QuestDef.Repeat.ONCE) return "You already completed this quest.";
            long left = e.last + q.cooldownSeconds() - now();
            if (left > 0) return "You can do this quest again in " + duration(left) + ".";
        }
        if (active(p) >= maxActive) return "You already have " + maxActive + " active quest" + (maxActive == 1 ? "" : "s") + ". Abandon one first.";
        return null;
    }

    public boolean start(Player p, String id, boolean viaCommand) {
        QuestDef q = def(id);
        String why = startRefusal(p, q, viaCommand);
        if (why != null) { say(p, why, NamedTextColor.RED); return false; }
        Map<String, QuestStore.Entry> m = of(p);
        QuestStore.Entry old = m.get(id);
        QuestStore.Entry e = new QuestStore.Entry(id);
        if (old != null) { e.completions = old.completions; e.last = old.last; }
        e.state = 'A';
        e.step = q.first().id();
        e.started = now();
        m.put(id, e);
        if (!save(p)) { if (old == null) m.remove(id); else m.put(id, old); say(p, "Your quest log is full.", NamedTextColor.RED); return false; }
        say(p, "Quest started: " + q.title() + ". " + q.first().text(), NamedTextColor.GOLD);
        evaluate(p, q, e);
        return true;
    }

    public boolean abandon(Player p, String id) {
        QuestDef q = def(id);
        QuestStore.Entry e = q == null ? null : of(p).get(id);
        if (e == null || (e.state != 'A' && e.state != 'C')) { say(p, "You are not doing that quest.", NamedTextColor.RED); return false; }
        if (!q.abandon()) { say(p, "This quest cannot be abandoned.", NamedTextColor.RED); return false; }
        drop(p, e);
        say(p, "Quest abandoned: " + q.title() + ".", NamedTextColor.YELLOW);
        return true;
    }

    private void drop(Player p, QuestStore.Entry e) {
        if (e.completions > 0) { e.state = 'D'; e.step = ""; e.branch = ""; e.zero(); }
        else of(p).remove(e.quest);
        save(p);
    }

    public boolean choose(Player p, String id, String branch) {
        QuestDef q = def(id);
        QuestStore.Entry e = q == null ? null : of(p).get(id);
        QuestDef.Branch b = q == null ? null : q.branch(branch);
        if (e == null || e.state != 'C' || b == null) { say(p, "There is nothing to choose for that quest right now.", NamedTextColor.RED); return false; }
        e.state = 'A';
        e.branch = branch;
        e.step = b.steps().get(0).id();
        e.zero();
        save(p);
        say(p, q.title() + ": " + b.steps().get(0).text(), NamedTextColor.GOLD);
        evaluate(p, q, e);
        return true;
    }

    // ------------------------------------------------------------------------------------------- progress
    /** Add to every matching objective of every active quest's current step. */
    void add(Player p, QuestDef.Kind kind, Match match) {
        if (!uses(kind)) return;
        Map<String, QuestStore.Entry> m = of(p);
        for (QuestStore.Entry e : new ArrayList<>(m.values())) {
            if (e.state != 'A') continue;
            QuestDef q = def(e.quest);
            QuestDef.Step s = q == null ? null : q.step(e.branch, e.step);
            if (s == null) continue;
            boolean changed = false;
            for (int j = 0; j < s.objectives().size(); j++) {
                QuestDef.Objective o = s.objectives().get(j);
                if (o.kind() != kind || e.counts[j] >= o.count()) continue;
                int inc = match.amount(o);
                if (inc <= 0) continue;
                e.counts[j] = (int) Math.min(o.count(), (long) e.counts[j] + inc);
                changed = true;
                if (q.actionbar()) p.sendActionBar(Component.text(q.title() + ": " + describe(o, e.counts[j]), NamedTextColor.AQUA));
            }
            if (changed) { save(p); evaluate(p, q, e); }
        }
    }

    void talked(Player p, String menu) { add(p, QuestDef.Kind.TALK, o -> menu.equals(o.menu()) ? 1 : 0); }

    /** Refresh the "state" objectives (inventory collect, visit) and complete the step when every objective is met. */
    void evaluate(Player p, QuestDef q, QuestStore.Entry e) {
        for (int guard = 0; guard < 16 && e.state == 'A'; guard++) {
            QuestDef.Step s = q.step(e.branch, e.step);
            if (s == null) return;
            boolean done = true;
            for (int j = 0; j < s.objectives().size(); j++) {
                QuestDef.Objective o = s.objectives().get(j);
                if (o.kind() == QuestDef.Kind.COLLECT && !o.pickup()) e.counts[j] = Math.min(o.count(), g.costs().count(p, costOf(o)));
                if (o.kind() == QuestDef.Kind.VISIT && e.counts[j] < 1 && near(p, o)) e.counts[j] = 1;
                if (e.counts[j] < o.count()) done = false;
            }
            if (!done) return;
            for (QuestDef.Objective o : s.objectives()) if (o.kind() == QuestDef.Kind.COLLECT && o.take() && g.costs().count(p, costOf(o)) < o.count()) return;
            for (QuestDef.Objective o : s.objectives()) if (o.kind() == QuestDef.Kind.COLLECT && o.take()) g.costs().take(p, costOf(o));
            QuestDef.Step next = q.nextAfter(e.branch, e.step);
            if (next != null) {
                e.step = next.id();
                e.zero();
                save(p);
                say(p, q.title() + ": " + next.text(), NamedTextColor.GOLD);
                continue;
            }
            if (q.hasBranches() && e.branch.isEmpty()) {
                e.state = 'C';
                e.step = "";
                e.zero();
                save(p);
                say(p, q.title() + ": " + q.prompt() + " (/" + g.label() + " quests choose " + q.id() + ")", NamedTextColor.GOLD);
                final String id = q.id();
                g.menus().later(p, () -> g.menus().open(p, MenuManager.BRANCH + id, 0, false));
                return;
            }
            complete(p, q, e);
            return;
        }
    }

    private void complete(Player p, QuestDef q, QuestStore.Entry e) {
        String branch = e.branch;
        e.state = 'D';
        e.step = "";
        e.branch = "";
        e.zero();
        e.completions = Math.min(QuestStore.MAX_COUNT, e.completions + 1);
        e.last = now();
        save(p); // stored FIRST: the rewards below can never be claimed twice
        say(p, "Quest complete: " + q.title() + "!", NamedTextColor.GREEN);
        q.rewards(p, g.rewards(), branch);
    }

    private void fail(Player p, QuestDef q, QuestStore.Entry e, String why) {
        drop(p, e);
        say(p, "Quest failed: " + q.title() + " (" + why + ").", NamedTextColor.RED);
    }

    void died(Player p) {
        for (QuestStore.Entry e : new ArrayList<>(of(p).values())) {
            if (e.state != 'A') continue;
            QuestDef q = def(e.quest);
            if (q == null) continue;
            if (q.onDeath() == QuestDef.OnDeath.FAIL) { fail(p, q, e, "you died"); continue; }
            QuestDef.Step s = q.step(e.branch, e.step);
            if (s == null) continue;
            for (int j = 0; j < s.objectives().size(); j++) if (q.onDeath() == QuestDef.OnDeath.RESET_STEP || s.objectives().get(j).kind() == QuestDef.Kind.SURVIVE) e.counts[j] = 0;
            save(p);
        }
    }

    /** Once per second per online player with progress: survive seconds, visit / inventory checks, time limits. */
    void tick(Player p) {
        Map<String, QuestStore.Entry> m = cache.get(p.getUniqueId());
        if (m == null || p.isDead()) return;
        long now = now();
        for (QuestStore.Entry e : new ArrayList<>(m.values())) {
            if (e.state != 'A') continue;
            QuestDef q = def(e.quest);
            if (q == null) continue;
            if (q.timeLimitSeconds() > 0 && now - e.started > q.timeLimitSeconds()) { fail(p, q, e, "out of time"); continue; }
            QuestDef.Step s = q.step(e.branch, e.step);
            if (s == null) continue;
            boolean changed = false;
            for (int j = 0; j < s.objectives().size(); j++) {
                QuestDef.Objective o = s.objectives().get(j);
                if (o.kind() == QuestDef.Kind.SURVIVE && e.counts[j] < o.count()) { e.counts[j]++; changed = true; }
            }
            if (changed) save(p);
            evaluate(p, q, e);
        }
    }

    boolean near(Player p, QuestDef.Objective o) {
        Location l = p.getLocation();
        if (l.getWorld() == null || !l.getWorld().getName().equals(o.world())) return false;
        double dx = l.getX() - o.x(), dy = l.getY() - o.y(), dz = l.getZ() - o.z();
        return dx * dx + dy * dy + dz * dz <= o.radius() * o.radius();
    }

    static CostCharger.Cost costOf(QuestDef.Objective o) { return o.design() != null ? CostCharger.Cost.design(o.design(), o.count()) : CostCharger.Cost.items(o.material(), o.count()); }

    boolean matches(QuestDef.Objective o, ItemStack s) {
        if (s == null || s.getType().isAir()) return false;
        String id = g.designer().identity().idOf(s);
        return o.design() != null ? o.design().equals(id) : id == null && s.getType() == o.material();
    }

    String describe(QuestDef.Objective o, int have) {
        String what = o.design() != null ? o.design().replace('_', ' ') : o.material() != null ? o.material().getKey().getKey().replace('_', ' ') : "";
        switch (o.kind()) {
            case KILL: return "kill " + (o.entities().isEmpty() ? "mobs" : String.join("/", new TreeMap<String, String>(Map.of()).keySet().isEmpty() ? o.entities() : o.entities()).replace('_', ' ')) + " " + have + "/" + o.count();
            case COLLECT: return (o.pickup() ? "pick up " : "have ") + what + " " + have + "/" + o.count();
            case CRAFT: return "craft " + what + " " + have + "/" + o.count();
            case BREAK: return "break " + what + " " + have + "/" + o.count();
            case VISIT: return "go to " + (int) o.x() + " " + (int) o.y() + " " + (int) o.z() + (have >= 1 ? " (done)" : "");
            case TALK: { MenuDef m = g.menus().menu(o.menu()); return "talk: " + (m == null ? o.menu() : m.title()) + (have >= 1 ? " (done)" : ""); }
            case SURVIVE: return "survive " + have + "/" + o.count() + " s";
            default: return "";
        }
    }

    /** One line for the quest log / list. */
    public String state(Player p, QuestDef q) {
        QuestStore.Entry e = of(p).get(q.id());
        if (e != null && e.state == 'A') {
            QuestDef.Step s = q.step(e.branch, e.step);
            if (s == null) return "Active";
            List<String> parts = new ArrayList<>();
            for (int j = 0; j < s.objectives().size(); j++) parts.add(describe(s.objectives().get(j), e.counts[j]));
            return "Active: " + s.text() + " (" + String.join(", ", parts) + ")";
        }
        if (e != null && e.state == 'C') return "Choose your path: /" + g.label() + " quests choose " + q.id();
        String why = startRefusal(p, q, false);
        if (e != null && e.completions > 0 && why != null && why.startsWith("You can do")) return "Completed " + e.completions + "x, " + why.substring(4, why.length() - 1).toLowerCase(java.util.Locale.ROOT);
        if (e != null && e.completions > 0 && q.repeat() == QuestDef.Repeat.ONCE) return "Completed";
        return why == null ? "Available" : "Locked: " + why;
    }

    public void info(Player p, String id) {
        QuestDef q = def(id);
        if (q == null) { say(p, "There is no quest " + id + ".", NamedTextColor.RED); return; }
        say(p, q.title() + (q.description().isEmpty() ? "" : ": " + q.description()), NamedTextColor.GOLD);
        say(p, state(p, q), NamedTextColor.AQUA);
    }
}
`;

export const TRACKER_JAVA = String.raw`package __PKG__.designer;

import java.util.Iterator;
import java.util.LinkedHashSet;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.block.Block;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityPickupItemEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.inventory.CraftItemEvent;
import org.bukkit.event.inventory.InventoryCloseEvent;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.ItemStack;

/**
 * Component gameplay-objectives v1 (ObjectiveTracker): ONE listener for every quest of the mod, one handler per event
 * kind (never one listener per quest): kills, pickups, crafts, block place/break, deaths, join/quit, inventory close;
 * plus one shared once-a-second timer (survive, visit, inventory collect, time limits). Observation only: MONITOR,
 * ignoreCancelled, nothing is changed or cancelled. A kind no quest uses returns at once. Blocks placed by players are
 * remembered (4096, oldest forgotten; not across restarts) so placing and breaking again does not count.
 */
public final class ObjectiveTracker implements Listener {
    public static final int HANDLERS = 9;
    public static final int PLACED_MEMORY = 4096;
    private final Gameplay g;
    private final LinkedHashSet<String> placed = new LinkedHashSet<>();

    ObjectiveTracker(Gameplay g) { this.g = g; }

    private static String pos(Block b) { return b.getWorld().getName() + ":" + b.getX() + ":" + b.getY() + ":" + b.getZ(); }

    private static boolean kills(LivingEntity e, QuestDef.Objective o) {
        if (o.kinds() != 0 && Checks.kinds(e, o.kinds())) return true;
        return !o.entities().isEmpty() && o.entities().contains(e.getType().getKey().getKey());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onKill(EntityDeathEvent e) {
        LivingEntity dead = e.getEntity();
        Player k = dead.getKiller();
        if (k == null || k == dead || !g.quests().uses(QuestDef.Kind.KILL)) return;
        g.quests().add(k, QuestDef.Kind.KILL, o -> kills(dead, o) ? 1 : 0);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPickup(EntityPickupItemEvent e) {
        if (!(e.getEntity() instanceof Player p) || !g.quests().uses(QuestDef.Kind.COLLECT)) return;
        ItemStack s = e.getItem().getItemStack();
        final int n = s.getAmount();
        g.quests().add(p, QuestDef.Kind.COLLECT, o -> o.pickup() && g.quests().matches(o, s) ? n : 0);
        g.menus().later(p, () -> recheck(p));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onCraft(CraftItemEvent e) {
        if (!(e.getWhoClicked() instanceof Player p) || !g.quests().uses(QuestDef.Kind.CRAFT)) return;
        ItemStack r = e.getRecipe().getResult();
        int times = 1;
        if (e.isShiftClick()) {
            times = Integer.MAX_VALUE;
            for (ItemStack m : e.getInventory().getMatrix()) if (m != null && !m.getType().isAir()) times = Math.min(times, m.getAmount());
            if (times == Integer.MAX_VALUE) times = 1;
        }
        final int n = Math.max(1, times) * Math.max(1, r.getAmount());
        g.quests().add(p, QuestDef.Kind.CRAFT, o -> g.quests().matches(o, r) ? n : 0);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent e) {
        if (!g.quests().uses(QuestDef.Kind.BREAK)) return;
        placed.add(pos(e.getBlockPlaced()));
        if (placed.size() > PLACED_MEMORY) { Iterator<String> it = placed.iterator(); it.next(); it.remove(); }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        if (!g.quests().uses(QuestDef.Kind.BREAK)) return;
        if (placed.remove(pos(e.getBlock()))) return;
        final Material type = e.getBlock().getType();
        g.quests().add(e.getPlayer(), QuestDef.Kind.BREAK, o -> o.material() == type ? 1 : 0);
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onDeath(PlayerDeathEvent e) { g.quests().died(e.getEntity()); }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onJoin(PlayerJoinEvent e) { g.quests().of(e.getPlayer()); }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onQuit(PlayerQuitEvent e) { g.quests().save(e.getPlayer()); g.quests().forget(e.getPlayer().getUniqueId()); }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onClose(InventoryCloseEvent e) { if (e.getPlayer() instanceof Player p && g.quests().uses(QuestDef.Kind.COLLECT)) g.menus().later(p, () -> recheck(p)); }

    private void recheck(Player p) {
        for (QuestStore.Entry en : new java.util.ArrayList<>(g.quests().of(p).values())) {
            QuestDef q = g.quests().def(en.quest);
            if (q != null && en.state == 'A') g.quests().evaluate(p, q, en);
        }
    }

    /** The shared timer (every 20 ticks). */
    void tick() { for (Player p : Bukkit.getOnlinePlayers()) g.quests().tick(p); }

    public int placedRemembered() { return placed.size(); }
}
`;

export const REWARDS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextColor;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.advancement.Advancement;
import org.bukkit.advancement.AdvancementProgress;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

/**
 * Component gameplay-rewards v1 (RewardDistributor): quest rewards and menu gives. Items go into the inventory (what does
 * not fit drops at the player's feet: a reward is never lost); XP points / levels; a potion effect; an advancement of
 * THIS project's data pack (all remaining criteria awarded; a missing advancement is logged once and grants nothing);
 * an item ability of this mod; a message. Never a command, never another player.
 */
public final class RewardDistributor {
    private final Gameplay g;
    private final Set<String> missing = new HashSet<>();

    RewardDistributor(Gameplay g) { this.g = g; }

    public void give(Player p, ItemStack stack, int count) {
        if (stack == null || count <= 0) return;
        int max = Math.max(1, stack.getMaxStackSize());
        int left = Math.min(count, 2304);
        while (left > 0) {
            ItemStack s = stack.clone();
            int n = Math.min(left, max);
            s.setAmount(n);
            left -= n;
            for (ItemStack rest : p.getInventory().addItem(s).values()) p.getWorld().dropItemNaturally(p.getLocation(), rest);
        }
    }

    public void design(Player p, String item, int count) { DesignItem i = g.designer().item(item); if (i != null) give(p, i.create(), count); }
    public void points(Player p, int n) { if (n > 0) p.giveExp(n); }
    public void levels(Player p, int n) { if (n > 0) p.giveExpLevels(n); }
    public void potion(Player p, PotionEffectType t, int ticks, int amplifier) { if (t != null) p.addPotionEffect(new PotionEffect(t, ticks, amplifier)); }
    public void ability(Player p, String item, String ability) { g.runAbility(p, item, ability); }
    public void message(Player p, String text, TextColor color) { p.sendMessage(Component.text(text.replace("{player}", p.getName()), color)); }

    public void advancement(Player p, String key) {
        Advancement a = Bukkit.getAdvancement(new NamespacedKey(g.designer().namespace(), key));
        if (a == null) {
            if (missing.add(key)) g.designer().plugin().getLogger().warning("quest reward: advancement " + g.designer().namespace() + ":" + key + " is not loaded (is the mod's data pack installed?)");
            return;
        }
        AdvancementProgress pr = p.getAdvancementProgress(a);
        for (String c : new ArrayList<>(pr.getRemainingCriteria())) pr.awardCriteria(c);
    }
}
