export const GAMEPLAY_JAVA = String.raw`package __PKG__.designer;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.command.PluginCommand;
import org.bukkit.configuration.Configuration;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Component gameplay-runtime v1 (the menus + quests hub, next to the item Designer): owns the menu manager, the quest
 * engine, costs, rewards and the objective tracker; loads every menu / quest parameter through its own clamping
 * DesignConfig; on a config_version bump also resets every value under menus.* and quests.* to the jar's new default
 * (the item Designer resets items.*; general.* and the owner's lists.* are never touched); replaces the mod command
 * with GameplayCommand (items' give/list stay with DesignCommand). Everything is dropped on disable.
 */
public final class Gameplay {
    private final Designer d;
    private final JavaPlugin plugin;
    private final DesignConfig config;
    private final CostCharger costs;
    private final MenuManager menus;
    private final Quests quests;
    private final RewardDistributor rewards;
    private final ObjectiveTracker tracker;
    private final List<String> notes = new ArrayList<>();
    private final int startVersion;
    private String label = "";

    public Gameplay(Designer d) {
        this.d = d;
        this.plugin = d.plugin();
        this.config = new DesignConfig(plugin);
        this.costs = new CostCharger(this);
        this.menus = new MenuManager(this);
        this.quests = new Quests(this);
        this.rewards = new RewardDistributor(this);
        this.tracker = new ObjectiveTracker(this);
        this.startVersion = fileVersion();
    }

    public void enable(PluginCommand command, List<MenuDef> menuList, List<QuestDef> questList) {
        menus.register(menuList);
        quests.register(questList);
        if (command != null) label = command.getName();
        List<String> out = new ArrayList<>();
        load(startVersion, out);
        plugin.getServer().getPluginManager().registerEvents(menus, plugin);
        plugin.getServer().getPluginManager().registerEvents(tracker, plugin);
        if (command != null) {
            GameplayCommand c = new GameplayCommand(this, command.getName());
            command.setExecutor(c);
            command.setTabCompleter(c);
        }
        for (Player p : plugin.getServer().getOnlinePlayers()) quests.of(p);
    }

    public void money(CostCharger.Money m) { costs.money(m); }

    /** /<mod> reload: items (Designer, with its migration) then menus + quests. */
    public List<String> reload() {
        int before = fileVersion();
        List<String> out = new ArrayList<>(d.reload());
        load(before, out);
        return out;
    }

    private void load(int before, List<String> out) {
        FileConfiguration cfg = plugin.getConfig();
        Configuration defaults = cfg.getDefaults();
        int jar = defaults == null ? 1 : defaults.getInt("config_version", 1);
        if (before >= 0 && before < jar && defaults != null) {
            int n = 0;
            for (String key : defaults.getKeys(true)) {
                if (!(key.startsWith("menus.") || key.startsWith("quests.")) || defaults.isConfigurationSection(key)) continue;
                cfg.set(key, defaults.get(key));
                n++;
            }
            plugin.saveConfig();
            String m = "config.yml: " + n + " menu and quest values updated to version " + jar;
            out.add(m);
            plugin.getLogger().info(m);
        }
        config.load();
        notes.clear();
        menus.load(config);
        quests.load(config);
        for (String s : config.notes()) { out.add(s); plugin.getLogger().warning("config: " + s); }
        for (String s : notes) { out.add(s); plugin.getLogger().warning("config: " + s); }
        d.tasks().timer(20L, tracker::tick);
    }

    /** config_version of the file on disk (-1: no file yet, 0: missing or not a number). */
    private int fileVersion() {
        File f = new File(plugin.getDataFolder(), "config.yml");
        if (!f.isFile()) return -1;
        Object raw = YamlConfiguration.loadConfiguration(f).get("config_version");
        return raw instanceof Number n ? n.intValue() : 0;
    }

    public void disable() {
        menus.closeAll();
        quests.saveAll();
        quests.clear();
    }

    void note(String s) { if (notes.size() < 64) notes.add(s); }

    public void runAbility(Player p, String item, String ability) {
        Ability a = d.ability(item, ability);
        if (a != null) a.fire(Activation.of(a, p, null, null, 0));
    }

    /** A display icon: never a design identity, always the <ns>:menu_icon flag. */
    public ItemStack icon(Material m, String name, TextColor color, List<String> lore, int amount, boolean glint, String modelNs, String modelKey) {
        ItemStack s = new ItemStack(m == null || m.isAir() ? Material.PAPER : m);
        s.setAmount(Math.max(1, Math.min(s.getMaxStackSize(), amount)));
        return dress(s, name, color, lore, glint, modelNs, modelKey);
    }

    public ItemStack designIcon(String item, String name, TextColor color, List<String> lore, int amount, boolean glint) {
        DesignItem i = d.item(item);
        if (i == null) return icon(Material.PAPER, name, color, lore, amount, glint, null, null);
        ItemStack s = i.create();
        s.setAmount(Math.max(1, Math.min(s.getMaxStackSize(), amount)));
        ItemMeta meta = s.getItemMeta();
        if (meta != null) { meta.getPersistentDataContainer().remove(d.identity().key()); s.setItemMeta(meta); }
        return dress(s, name, color, lore, glint, null, null);
    }

    private ItemStack dress(ItemStack s, String name, TextColor color, List<String> lore, boolean glint, String modelNs, String modelKey) {
        ItemMeta meta = s.getItemMeta();
        if (meta == null) return s;
        if (name != null && !name.isEmpty()) meta.itemName(Component.text(name, color == null ? NamedTextColor.WHITE : color));
        if (lore != null && !lore.isEmpty()) {
            List<Component> l = new ArrayList<>();
            for (String line : lore) if (line != null && !line.isEmpty()) l.add(Component.text(line, NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false));
            meta.lore(l);
        }
        if (glint) meta.setEnchantmentGlintOverride(true);
        if (modelNs != null && modelKey != null && Compat.ITEM_MODELS) Compat.itemModel(meta, modelNs, modelKey);
        meta.getPersistentDataContainer().set(menus.iconKey(), PersistentDataType.BYTE, (byte) 1);
        s.setItemMeta(meta);
        return s;
    }

    public Designer designer() { return d; }
    public JavaPlugin plugin() { return plugin; }
    public CostCharger costs() { return costs; }
    public MenuManager menus() { return menus; }
    public Quests quests() { return quests; }
    public RewardDistributor rewards() { return rewards; }
    public ObjectiveTracker tracker() { return tracker; }
    public String label() { return label; }
    NamespacedKey iconKey() { return menus.iconKey(); }
}
`;

export const GPCOMMAND_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
