// Cyrus R3 gameplay designers, part 2: metadata of the MENU / QUEST components (purpose, supported families, limits, how
// they are tested) + the library hash. The Java is in ./java.ts. A component is "verified" exactly like the item
// components (../components/index.ts): javac against the real Paper classpaths of 1.21.11 (JDK 21) and 26.2 (JDK 25)
// with zero warnings, the strict safety scan on its bytecode + source, and a Test Flight boot with no ERROR line
// (test/cyrus-gameplay-real.ts). Other registry versions use the same sources (no per-version code here; the item
// library's Compat is the only per-version file): compiled per the API sheets, NOT by javac (`javacVerified: false`).
import { createHash } from "node:crypto";
import { COMPONENTS as ITEM_COMPONENTS, COMPONENT_LIBRARY_VERSION, compatSource, type ComponentMeta } from "../components";
import { GAMEPLAY_LIMITS } from "./spec";
import * as J from "./java";

export const GAMEPLAY_LIBRARY_VERSION = "cyrus-gameplay-components-1";

const ALL: ("1.21" | "26")[] = ["1.21", "26"];
const UNIT = "test/cyrus-gameplay.test.ts (pure: present in every menu/quest compile, strict-scan text rules, precheck, golden hashes, TS simulator twin)";
const REAL = "test/cyrus-gameplay-real.ts (javac 1.21.11/JDK 21 + 26.2/JDK 25 with 0 warnings, strict scan, Test Flight boot + RCON)";

export const GAMEPLAY_COMPONENTS: ComponentMeta[] = [
  { id: "gameplay-runtime", file: "designer/Gameplay.java", purpose: "the menus + quests hub next to the item Designer: config (clamping, menus.*/quests.* migration), icons, cleanup", families: ALL, limits: ["menus.* and quests.* reset on a config_version bump (backup by the item config loader)", "general.* and lists.* never reset"], tests: [UNIT, REAL, "Test Flight: reload clamps, old config_version migrated"], source: J.GAMEPLAY_JAVA },
  { id: "gameplay-menu-def", file: "designer/MenuDef.java", purpose: "base of every generated menu: buttons, paginated list, dialogue layout data", families: ALL, limits: [`${GAMEPLAY_LIMITS.maxButtons} buttons`, `${GAMEPLAY_LIMITS.maxListSlots} list slots`, `${GAMEPLAY_LIMITS.maxClickActions} actions per click`], tests: [UNIT, REAL], source: J.MENUDEF_JAVA },
  { id: "gameplay-menu-context", file: "designer/MenuContext.java", purpose: "what a click may do (clicking player only; navigation deferred one tick)", families: ALL, limits: ["no command dispatch", "no other player"], tests: [UNIT, REAL], source: J.MENUCTX_JAVA },
  { id: "gameplay-menus", file: "designer/MenuManager.java", purpose: "MenuManager: holder-based inventories, click/drag cancel hardening, dupe-proof click order, openers (command/item/NPC), config lists, cleanup", families: ALL, limits: ["every click/drag in a menu cancelled at LOWEST and HIGHEST", "only plain left/right clicks act", "general.menu_click_cooldown_ticks 2-40", `back stack ${GAMEPLAY_LIMITS.maxBack}`, `config lists ${GAMEPLAY_LIMITS.maxConfigEntries} entries`, "icons flagged and swept on close/drop"], tests: [UNIT, REAL, "simulator click-order and anti-dupe tests", "Test Flight: /<mod> menu list / costs / console usage"], source: J.MENUS_JAVA },
  { id: "gameplay-pagination", file: "designer/Pagination.java", purpose: "page math (clamped, at most 10 pages)", families: ALL, limits: [`${GAMEPLAY_LIMITS.maxPages} pages`], tests: [UNIT, REAL, "simulator pagination tests"], source: J.PAGINATION_JAVA },
  { id: "gameplay-cost", file: "designer/CostCharger.java", purpose: "CostCharger: item (identity-aware) / XP level / Vault money costs; room -> pay check -> take (all or nothing) -> give", families: ALL, limits: ["items 1-2304", "levels 1-1000", "money 0.01-1000000 (Vault only)", "menu icons never count as payment"], tests: [UNIT, REAL, "simulator cost tests", "Test Flight: money cost refused without Vault"], source: J.COST_JAVA },
  { id: "gameplay-dialogue", file: "designer/DialogueMenu.java", purpose: "DialogueMenu: 3-row dialogue layout (speaker, lines, 1-5 choices), branch choice menu, quest log", families: ALL, limits: [`${GAMEPLAY_LIMITS.maxChoices} choices`, `${GAMEPLAY_LIMITS.maxDialogueLines} lines`, "inventory based (no Dialog API)"], tests: [UNIT, REAL], source: J.DIALOGUE_JAVA },
  { id: "gameplay-quest-def", file: "designer/QuestDef.java", purpose: "base of every generated quest: steps, objectives (closed set), branches", families: ALL, limits: [`${GAMEPLAY_LIMITS.maxSteps} steps`, `${GAMEPLAY_LIMITS.maxObjectives} objectives per step`, `${GAMEPLAY_LIMITS.maxBranches} branches of ${GAMEPLAY_LIMITS.maxBranchSteps} steps`], tests: [UNIT, REAL], source: J.QUESTDEF_JAVA },
