// Cyrus R3 gameplay designers, part 2: the MOD COMPILER for menus and quests. `compileMod(inputs, ctx)` takes every
// design file of a mod (items, menus, quests). A mod with only item designs is compiled by the unchanged item compiler
// (../compile.ts compileDesigns: byte-identical output, same golden hashes). A mod with menus or quests gets the item
// library + the gameplay library (./components) + generated straight-line classes (items/, abilities/, menus/, quests/),
// a main class that wires both hubs, plugin.yml and config.yml. Every number and text of a menu or quest (prices,
// counts, cooldowns, titles, texts, coordinates) is a config.yml PARAMETER under menus.<id>. / quests.<id>., so a value
// edit changes config.yml (+ README) only, never a Java file (./params.ts proves it). Deterministic: same designs +
// context = same bytes (golden hashes in test/fixtures/cyrus-gameplay/golden.json).
import { vanillaIds } from "../../datapack/versions";
import { COMPAT_META, COMPONENTS, compatSource, renderComponent } from "../components";
import {
  COMPILER_VERSION, DEFAULTS, JAVAC_VERIFIED_VERSIONS, MATERIAL, abilityClass, addParam, bare, camel, colorExpr, compileDesigns, designParams, designerValuesHash, fmtNum,
  itemClass, jstr, loadLine, nextConfigVersion, randomSeedFor, sha256, sq, yamlTree, JTYPE,
  type CompileContext, type CompileOk, type CompiledFile, type Param, type ParamKind, type ParamSink,
} from "../compile";
import type { DesignFeatures, DzIssue, ItemDesign } from "../spec";
import { GAMEPLAY_COMPONENTS, GAMEPLAY_LIBRARY_VERSION, VAULT_COMPONENT, VAULT_DEP, gameplayLibraryHash } from "./components";
import {
  GAMEPLAY_CAPS, REPEAT_DEFAULTS, designKind, menuClickables, questSteps, repeatCooldown, validateGameplay,
  type Cost, type Icon, type MenuAction, type MenuDesign, type Objective, type QuestDesign, type Reward, type GpCapName, type GpIssue,
} from "./spec";

export const GAMEPLAY_COMPILER_VERSION = "cyrus-gameplay-compile-1";
export const GENERAL_DEFAULTS = { menuClickCooldownTicks: 4, maxActiveQuests: 3 } as const;

export type ModCompileOk = CompileOk & {
  menus: MenuDesign[];
  quests: QuestDesign[];
  /** Compile-only dependencies from the import allowlist the javac classpath needs (vault-api for money costs). */
  deps: string[];
  counts: { items: number; menus: number; quests: number };
  /** false for an item-only mod (compiled by the item compiler). */
  gameplay: boolean;
};
export type ModCompileResult = ModCompileOk | { ok: false; errors: GpIssue[]; warnings: GpIssue[] };

const cap = (c: GpCapName): [number, number] => [GAMEPLAY_CAPS[c][0], GAMEPLAY_CAPS[c][1]];

// -------------------------------------------------------------------------------------------------- parameters
function sinkFor(base: string, id: string): ParamSink { return { params: [], base, item: id }; }
const own = (s: ParamSink, owner: "menu" | "quest") => s.params.map((p) => ({ ...p, owner }));

function iconParams(s: ParamSink, rel: string, ic: Icon, what: string) {
  if (ic.name) addParam(s, `${rel}.name`, "text", [0, 60], ic.name.text, `${what} name`, "text");
  (ic.lore ?? []).forEach((l, j) => addParam(s, `${rel}.lore${j}`, "text", [0, 60], l.text, `${what} lore line ${j + 1}`, "text"));
  if (ic.amount !== undefined) addParam(s, `${rel}.amount`, "int", cap("iconAmount"), ic.amount, `${what} stack size shown`, "count");
}
function costParams(s: ParamSink, rel: string, c: Cost | undefined, what: string) {
  if (!c) return;
  if (c.type === "item") addParam(s, `${rel}.cost.count`, "int", cap("itemCost"), c.count, `${what} price (${c.item.replace(/^minecraft:/, "")})`, "price");
  if (c.type === "xp_levels") addParam(s, `${rel}.cost.levels`, "int", cap("xpLevelCost"), c.levels, `${what} price (XP levels)`, "price");
  if (c.type === "economy") addParam(s, `${rel}.cost.amount`, "num", cap("economyCost"), c.amount, `${what} price (money, Vault)`, "price");
}
function actionParams(s: ParamSink, rel: string, list: MenuAction[] | undefined, what: string) {
  (list ?? []).forEach((a, k) => {
    const r = `${rel}.a${k}`;
    switch (a.type) {
      case "give_item": addParam(s, `${r}.count`, "int", cap("giveCount"), a.count ?? DEFAULTS.giveCount, `${what} gives ${a.item.replace(/^minecraft:/, "")} (count)`, "count"); break;
      case "send_message": case "actionbar": addParam(s, `${r}.text`, "text", [0, 120], a.text, `${what} ${a.type === "actionbar" ? "actionbar" : "message"} text`, "text"); break;
      case "play_sound": addParam(s, `${r}.sound`, "sound", [0, 100], a.sound, `${what} sound key`, "sound"); addParam(s, `${r}.volume`, "num", cap("volume"), a.volume ?? DEFAULTS.volume, `${what} sound volume`, "other"); addParam(s, `${r}.pitch`, "num", cap("pitch"), a.pitch ?? DEFAULTS.pitch, `${what} sound pitch`, "other"); break;
      case "potion_effect": addParam(s, `${r}.duration_ticks`, "ticks", cap("potionTicks"), a.durationTicks, `${what} ${a.effect} duration (ticks)`, "duration"); addParam(s, `${r}.amplifier`, "int", cap("amplifier"), a.amplifier ?? DEFAULTS.amplifier, `${what} ${a.effect} level - 1`, "level"); break;
      case "heal": addParam(s, `${r}.amount`, "num", cap("heal"), a.amount, `${what} heal (health points)`, "heal"); break;
      default: break;
    }
  });
}
/** Node id of each clickable: buttons by slot (b<slot>), fixed list entries e<i>, dialogue choices c<i>. */
export function clickNode(path: string, slot?: number): string {
  if (slot !== undefined) return `b${slot}`;
  const m = /\[(\d+)\]$/.exec(path);
  return path.startsWith("choices") ? `c${m![1]}` : `e${m![1]}`;
}

export function menuParams(m: MenuDesign): Param[] {
  const s = sinkFor(`menus.${m.id}.`, m.id);
  addParam(s, "title", "text", [0, 32], m.title, "menu title", "text");
  if (m.style === "dialogue") {
    addParam(s, "speaker", "text", [0, 60], m.speaker.text, "speaker name", "text");
    m.lines.forEach((l, i) => addParam(s, `line${i}`, "text", [0, 80], l, `dialogue line ${i + 1}`, "text"));
    if (m.speakerIcon) iconParams(s, "speaker_icon", m.speakerIcon, "speaker icon");
  }
  for (const { path, c, slot } of menuClickables(m)) {
    const node = clickNode(path, slot);
    const what = slot !== undefined ? `slot ${slot}` : path.startsWith("choices") ? `choice ${node.slice(1)}` : `entry ${node.slice(1)}`;
    iconParams(s, node, c.icon, what);
    costParams(s, node, c.cost, what);
    actionParams(s, node, c.actions, what);
  }
  if (m.style === "chest" && m.list) { iconParams(s, "prev", m.list.prev.icon, "previous page button"); iconParams(s, "next", m.list.next.icon, "next page button"); }
  return own(s, "menu");
}

function objectiveParams(s: ParamSink, rel: string, o: Objective, what: string) {
  switch (o.type) {
    case "kill_entity": addParam(s, `${rel}.count`, "int", cap("killCount"), o.count, `${what}: kills needed`, "count"); break;
    case "collect_item": addParam(s, `${rel}.count`, "int", cap("collectCount"), o.count, `${what}: ${o.item.replace(/^minecraft:/, "")} needed`, "count"); break;
    case "craft_item": addParam(s, `${rel}.count`, "int", cap("craftCount"), o.count, `${what}: crafts needed`, "count"); break;
    case "break_block": addParam(s, `${rel}.count`, "int", cap("breakCount"), o.count, `${what}: blocks needed`, "count"); break;
    case "survive": addParam(s, `${rel}.seconds`, "int", cap("surviveSeconds"), o.seconds, `${what}: seconds to survive`, "duration"); break;
    case "visit_location":
      addParam(s, `${rel}.world`, "text", [0, 64], o.world, `${what}: world`, "text");
      addParam(s, `${rel}.x`, "num", cap("coord"), o.x, `${what}: x`, "other"); addParam(s, `${rel}.y`, "num", cap("coordY"), o.y, `${what}: y`, "other"); addParam(s, `${rel}.z`, "num", cap("coord"), o.z, `${what}: z`, "other");
      addParam(s, `${rel}.radius`, "num", cap("visitRadius"), o.radius, `${what}: radius (blocks)`, "range"); break;
    default: break;
  }
}
function rewardParams(s: ParamSink, rel: string, list: Reward[] | undefined, what: string) {
  (list ?? []).forEach((r, i) => {
    const p = `${rel}.r${i}`;
    switch (r.type) {
      case "give_item": addParam(s, `${p}.count`, "int", cap("giveCount"), r.count ?? DEFAULTS.giveCount, `${what} reward ${r.item.replace(/^minecraft:/, "")} (count)`, "count"); break;
      case "xp": if (r.points !== undefined) addParam(s, `${p}.points`, "int", cap("xpPoints"), r.points, `${what} reward XP points`, "count"); else addParam(s, `${p}.levels`, "int", cap("xpLevels"), r.levels!, `${what} reward XP levels`, "count"); break;
      case "potion_effect": addParam(s, `${p}.duration_ticks`, "ticks", cap("potionTicks"), r.durationTicks, `${what} reward ${r.effect} duration (ticks)`, "duration"); addParam(s, `${p}.amplifier`, "int", cap("amplifier"), r.amplifier ?? DEFAULTS.amplifier, `${what} reward ${r.effect} level - 1`, "level"); break;
      case "send_message": addParam(s, `${p}.text`, "text", [0, 120], r.text, `${what} reward message`, "text"); break;
      default: break;
    }
  });
}

export function questParams(q: QuestDesign): Param[] {
  const s = sinkFor(`quests.${q.id}.`, q.id);
  addParam(s, "title", "text", [0, 40], q.title, "quest title", "text");
  if (q.description) addParam(s, "description", "text", [0, 120], q.description, "quest description", "text");
  if (q.icon) iconParams(s, "icon", q.icon, "quest icon");
  if ((q.repeat?.mode ?? "once") !== "once") addParam(s, "repeat.cooldown_seconds", "int", cap("repeatCooldownSeconds"), repeatCooldown(q), `${q.repeat!.mode} cooldown (seconds)`, "cooldown");
  if (q.failure?.timeLimitSeconds !== undefined) addParam(s, "failure.time_limit_seconds", "int", cap("timeLimitSeconds"), q.failure.timeLimitSeconds, "time limit (seconds)", "duration");
  if (q.branches?.prompt) addParam(s, "branches.prompt", "text", [0, 60], q.branches.prompt, "branch choice prompt", "text");
  for (const { step } of questSteps(q)) {
    addParam(s, `steps.${step.id}.text`, "text", [0, 80], step.text, `step ${step.id} text`, "text");
    step.objectives.forEach((o, j) => objectiveParams(s, `steps.${step.id}.o${j}`, o, `step ${step.id}`));
  }
  for (const b of q.branches?.options ?? []) {
    addParam(s, `branches.${b.id}.label`, "text", [0, 60], b.label.text, `branch ${b.id} label`, "text");
    rewardParams(s, `branches.${b.id}.rewards`, b.rewards, `branch ${b.id}`);
  }
  rewardParams(s, "rewards", q.rewards, "quest");
  return own(s, "quest");
}

/** Every parameter of a mod, in config order: items, then menus, then quests (each sorted by id). */
export function modParams(items: ItemDesign[], menus: MenuDesign[], quests: QuestDesign[]): Param[] {
  const byId = <T extends { id: string }>(x: T[]) => [...x].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return [...designParams(items), ...byId(menus).flatMap(menuParams), ...byId(quests).flatMap(questParams)];
}

// ---------------------------------------------------------------------------------------------------- Java codegen
type Gen = { params: Map<string, Param>; statics: string[]; ns: string; models: string[] | undefined };
const P = (g: Gen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };
const has = (g: Gen, rel: string) => g.params.has(rel);
const nameColor = (c?: string) => (c ? colorExpr(c) : "null");

function iconExpr(g: Gen, rel: string, ic: Icon, fallbackName?: string): string {
  const name = has(g, `${rel}.name`) ? P(g, `${rel}.name`) : fallbackName ?? "null";
  const lore = (ic.lore ?? []).map((_, j) => P(g, `${rel}.lore${j}`));
  const loreExpr = lore.length ? `List.of(${lore.join(", ")})` : "List.of()";
  const amount = has(g, `${rel}.amount`) ? P(g, `${rel}.amount`) : "1";
  if (ic.item) return `designIcon(${jstr(ic.item)}, ${name}, ${nameColor(ic.name?.color)}, ${loreExpr}, ${amount}, ${!!ic.glint})`;
  const modelOk = !!ic.model && (!g.models || g.models.includes(ic.model));
  const [mns, mkey] = modelOk ? ic.model!.split(":") : [null, null];
  return `icon(${MATERIAL(ic.material!)}, ${name}, ${nameColor(ic.name?.color)}, ${loreExpr}, ${amount}, ${!!ic.glint}, ${mns ? jstr(mns) : "null"}, ${mkey ? jstr(mkey) : "null"})`;
}
function costExpr(g: Gen, rel: string, c: Cost | undefined): string {
  if (!c) return "CostCharger.Cost.NONE";
  if (c.type === "item") return c.item.startsWith("minecraft:") ? `CostCharger.Cost.items(${MATERIAL(c.item)}, ${P(g, `${rel}.cost.count`)})` : `CostCharger.Cost.design(${jstr(c.item)}, ${P(g, `${rel}.cost.count`)})`;
  if (c.type === "xp_levels") return `CostCharger.Cost.levels(${P(g, `${rel}.cost.levels`)})`;
  return `CostCharger.Cost.money(${P(g, `${rel}.cost.amount`)})`;
}
function givesExpr(g: Gen, rel: string, list: MenuAction[] | undefined): string {
  const s = (list ?? []).map((a, k) => (a.type !== "give_item" ? null : a.item.startsWith("minecraft:") ? `stack(${MATERIAL(a.item)}, ${P(g, `${rel}.a${k}.count`)})` : `designStack(${jstr(a.item)}, ${P(g, `${rel}.a${k}.count`)})`)).filter(Boolean);
  return `gives(${s.join(", ")})`;
}
function clickBody(g: Gen, rel: string, list: MenuAction[] | undefined): string[] {
  const out: string[] = [];
  (list ?? []).forEach((a, k) => {
    const r = `${rel}.a${k}`;
    switch (a.type) {
      case "open_menu": out.push(`ctx.open(${jstr(a.menu)});`); break;
      case "close": out.push("ctx.close();"); break;
      case "back": out.push("ctx.back();"); break;
      case "next_page": out.push("ctx.nextPage();"); break;
      case "prev_page": out.push("ctx.prevPage();"); break;
      case "give_item": out.push(a.item.startsWith("minecraft:") ? `ctx.give(stack(${MATERIAL(a.item)}, 1), ${P(g, `${r}.count`)});` : `ctx.giveDesign(${jstr(a.item)}, ${P(g, `${r}.count`)});`); break;
      case "send_message": out.push(`ctx.message(${P(g, `${r}.text`)}, ${a.color ? colorExpr(a.color) : "NamedTextColor.WHITE"});`); break;
      case "actionbar": out.push(`ctx.actionbar(${P(g, `${r}.text`)}, ${a.color ? colorExpr(a.color) : "NamedTextColor.WHITE"});`); break;
      case "play_sound": out.push(`ctx.sound(${P(g, `${r}.sound`)}, (float) ${P(g, `${r}.volume`)}, (float) ${P(g, `${r}.pitch`)});`); break;
      case "potion_effect": out.push(`ctx.potion(PotionEffectType.${a.effect.toUpperCase()}, (int) ${P(g, `${r}.duration_ticks`)}, ${P(g, `${r}.amplifier`)});`); break;
      case "heal": out.push(`ctx.heal(${P(g, `${r}.amount`)});`); break;
      case "run_ability": out.push(`ctx.ability(${jstr(a.item)}, ${jstr(a.ability)});`); break;
      case "start_quest": out.push(`ctx.startQuest(${jstr(a.quest)});`); break;
      case "abandon_quest": out.push(`ctx.abandonQuest(${jstr(a.quest)});`); break;
      case "choose_branch": out.push(`ctx.chooseBranch(${jstr(a.quest)}, ${jstr(a.branch)});`); break;
      case "open_quest_log": out.push("ctx.questLog();"); break;
    }
  });
  return out;
}
function lambda(body: string[], ind: string): string {
  if (!body.length) return "ctx -> {}";
  return `ctx -> {\n${body.map((l) => `${ind}    ${l}`).join("\n")}\n${ind}}`;
}

function classHeader(pkg: string, sub: string, extra: string[]): string[] {
  return [
    `package ${pkg}.${sub};`, ``,
    `import java.util.List;`, `import java.util.Set;`,
    `import net.kyori.adventure.text.format.NamedTextColor;`, `import net.kyori.adventure.text.format.TextColor;`,
    `import org.bukkit.Material;`, `import org.bukkit.entity.Player;`, `import org.bukkit.inventory.ItemStack;`, `import org.bukkit.potion.PotionEffectType;`,
    ...extra.map((e) => `import ${pkg}.designer.${e};`), ``,
  ];
}

function menuClass(pkg: string, m: MenuDesign, cls: string, ns: string, models: string[] | undefined): { source: string; params: Param[] } {
  const params = menuParams(m);
  const base = `menus.${m.id}.`;
  const g: Gen = { params: new Map(params.map((p) => [p.path.slice(base.length), p])), statics: [], ns, models };
  const body: string[] = ["reset();"];
  if (m.style === "chest") {
    if (m.filler) body.push(`filler(${MATERIAL(m.filler)});`);
    for (const { path, c, slot } of menuClickables(m)) {
      const node = clickNode(path, slot);
      const head = slot !== undefined ? `button(${slot}, ` : "entry(";
      body.push(`${head}${iconExpr(g, node, c.icon)}, ${costExpr(g, node, c.cost)}, ${c.permission ? jstr(c.permission) : "null"}, ${!!c.hideWithoutPermission}, ${givesExpr(g, node, c.actions)}, ${lambda(clickBody(g, node, c.actions), "        ")});`);
    }
    if (m.list) {
      body.push(`list(new int[] {${m.list.slots.join(", ")}}, ${m.list.prev.slot}, ${iconExpr(g, "prev", m.list.prev.icon, jstr("Previous page"))}, ${m.list.next.slot}, ${iconExpr(g, "next", m.list.next.icon, jstr("Next page"))});`);
      const src = m.list.source;
      if (src.type === "config") {
        const cur = src.currency;
        const kind = cur.type === "item" ? "ITEM" : cur.type === "xp_levels" ? "XP_LEVELS" : cur.type === "economy" ? "ECONOMY" : "FREE";
        const mat = cur.type === "item" && cur.item.startsWith("minecraft:") ? MATERIAL(cur.item) : "null";
        const des = cur.type === "item" && !cur.item.startsWith("minecraft:") ? jstr(cur.item) : "null";
        body.push(`configList(CostCharger.Kind.${kind}, ${mat}, ${des});`);
      }
    }
  } else {
    const icon = m.speakerIcon ? iconExpr(g, "speaker_icon", m.speakerIcon, P(g, "speaker")) : "null";
    body.push(`dialogue(${P(g, "speaker")}, ${nameColor(m.speaker.color)}, ${icon}, List.of(${m.lines.map((_, i) => P(g, `line${i}`)).join(", ")}));`);
    for (const { path, c } of menuClickables(m)) {
      const node = clickNode(path);
      body.push(`entry(${iconExpr(g, node, c.icon)}, ${costExpr(g, node, c.cost)}, ${c.permission ? jstr(c.permission) : "null"}, ${!!c.hideWithoutPermission}, ${givesExpr(g, node, c.actions)}, ${lambda(clickBody(g, node, c.actions), "        ")});`);
    }
  }
  const load = params.map((p) => loadLine(p, p.path.slice(base.length)));
  const ow = m.openWith ?? {};
  const src = [
    ...classHeader(pkg, "menus", ["CostCharger", "DesignConfig", "Gameplay", "MenuDef"]),
    `/** Menu "${m.title.replace(/\*\//g, "")}" (${ns}:${m.id}, ${m.style}${m.style === "chest" ? `, ${m.rows} rows` : ""}). Generated by Cyrus from assets/designs/${m.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends MenuDef {`,
    `    private static final String B = ${jstr(base)};`,
    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
    ``,
    `    public ${cls}(Gameplay g) {`,
    `        super(g, ${jstr(m.id)}, Style.${m.style === "chest" ? "CHEST" : "DIALOGUE"}, ${m.style === "chest" ? m.rows : 3}, ${m.permission ? jstr(m.permission) : "null"}, ${ow.command !== false}, ${ow.item ? jstr(ow.item) : "null"}, ${!!ow.npc});`,
    `    }`,
    ``,
    `    @Override`,
    `    public String title() { return p_title; }`,
    ``,
    `    @Override`,
    `    public void load(DesignConfig c) {`,
    ...load.map((l) => `        ${l}`),
    ...body.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public void describe(List<String> out) {`,
    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
    `    }`,
    `}`,
    ``,
  ];
  return { source: src.join("\n").replace(/\n(\s*)(List|Set|NamedTextColor|TextColor|Material|Player|ItemStack|PotionEffectType)\b/g, "\n$1$2"), params };
}

const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
function objectiveExpr(g: Gen, rel: string, o: Objective): string {
  const mat = (ref: string) => (ref.startsWith("minecraft:") ? `${MATERIAL(ref)}, null` : `null, ${jstr(ref)}`);
  switch (o.type) {
    case "kill_entity": {
      const set = o.entity ? `T_${rel.replace(/\./g, "_")}` : "Set.of()";
      if (o.entity) g.statics.push(`private static final Set<String> ${set} = Set.of(${jstr(bare(o.entity))});`);
      return `QuestDef.Objective.kill(${set}, ${(o.kinds ?? []).reduce((m, k) => m | KIND_BITS[k], 0)}, ${P(g, `${rel}.count`)})`;
    }
    case "collect_item": return `QuestDef.Objective.collect(${mat(o.item)}, ${P(g, `${rel}.count`)}, ${o.mode === "pickup"}, ${!!o.take})`;
    case "craft_item": return `QuestDef.Objective.craft(${mat(o.item)}, ${P(g, `${rel}.count`)})`;
    case "visit_location": return `QuestDef.Objective.visit(${P(g, `${rel}.world`)}, ${P(g, `${rel}.x`)}, ${P(g, `${rel}.y`)}, ${P(g, `${rel}.z`)}, ${P(g, `${rel}.radius`)})`;
    case "break_block": return `QuestDef.Objective.breaks(${MATERIAL(o.block)}, ${P(g, `${rel}.count`)})`;
    case "talk": return `QuestDef.Objective.talk(${jstr(o.menu)})`;
    case "survive": return `QuestDef.Objective.survive(${P(g, `${rel}.seconds`)})`;
  }
}
function rewardLines(g: Gen, rel: string, list: Reward[] | undefined): string[] {
  return (list ?? []).map((r, i) => {
    const p = `${rel}.r${i}`;
    switch (r.type) {
      case "give_item": return r.item.startsWith("minecraft:") ? `r.give(p, new ItemStack(${MATERIAL(r.item)}), ${P(g, `${p}.count`)});` : `r.design(p, ${jstr(r.item)}, ${P(g, `${p}.count`)});`;
      case "xp": return r.points !== undefined ? `r.points(p, ${P(g, `${p}.points`)});` : `r.levels(p, ${P(g, `${p}.levels`)});`;
      case "potion_effect": return `r.potion(p, PotionEffectType.${r.effect.toUpperCase()}, (int) ${P(g, `${p}.duration_ticks`)}, ${P(g, `${p}.amplifier`)});`;
      case "advancement": return `r.advancement(p, ${jstr(r.advancement.split(":").slice(1).join(":"))});`;
      case "run_ability": return `r.ability(p, ${jstr(r.item)}, ${jstr(r.ability)});`;
      case "send_message": return `r.message(p, ${P(g, `${p}.text`)}, ${r.color ? colorExpr(r.color) : "NamedTextColor.GREEN"});`;
    }
  });
}

function questClass(pkg: string, q: QuestDesign, cls: string, ns: string, models: string[] | undefined): { source: string; params: Param[] } {
  const params = questParams(q);
  const base = `quests.${q.id}.`;
  const g: Gen = { params: new Map(params.map((p) => [p.path.slice(base.length), p])), statics: [], ns, models };
  const mode = q.repeat?.mode ?? "once";
  const icon = q.icon ? iconExpr(g, "icon", q.icon, P(g, "title")) : "null";
  const body: string[] = [
    "reset();",
    `info(${P(g, "title")}, ${has(g, "description") ? P(g, "description") : '""'}, ${icon}, ${has(g, "repeat.cooldown_seconds") ? P(g, "repeat.cooldown_seconds") : "0"}, ${has(g, "failure.time_limit_seconds") ? P(g, "failure.time_limit_seconds") : "0"}, ${has(g, "branches.prompt") ? P(g, "branches.prompt") : "null"});`,
  ];
  const stepArgs = (st: QuestDesign["steps"][number]) => `${jstr(st.id)}, ${P(g, `steps.${st.id}.text`)}, ${st.objectives.map((o, j) => objectiveExpr(g, `steps.${st.id}.o${j}`, o)).join(", ")}`;
  for (const st of q.steps) body.push(`step(${stepArgs(st)});`);
  for (const b of q.branches?.options ?? []) {
    const ic = b.icon ? iconExpr(g, `branches.${b.id}.icon`, b.icon, P(g, `branches.${b.id}.label`)) : `icon(Material.PAPER, ${P(g, `branches.${b.id}.label`)}, ${nameColor(b.label.color)}, List.of(), 1, false, null, null)`;
    body.push(`branch(${jstr(b.id)}, ${ic}, ${b.steps.map((st) => `s(${stepArgs(st)})`).join(", ")});`);
  }
  const rewards = [...rewardLines(g, "rewards", q.rewards)];
  for (const b of q.branches?.options ?? []) {
    const lines = rewardLines(g, `branches.${b.id}.rewards`, b.rewards);
    if (lines.length) rewards.push(`if (${jstr(b.id)}.equals(branch)) {`, ...lines.map((l) => `    ${l}`), `}`);
  }
  const load = params.map((p) => loadLine(p, p.path.slice(base.length)));
  const start = (q.start ?? "command") === "menu" ? "MENU" : "COMMAND";
  const death = (q.failure?.onDeath ?? "keep").toUpperCase();
  const src = [
    ...classHeader(pkg, "quests", ["DesignConfig", "Gameplay", "QuestDef", "RewardDistributor"]),
    `/** Quest "${q.title.replace(/\*\//g, "")}" (${ns}:${q.id}). Generated by Cyrus from assets/designs/${q.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends QuestDef {`,
    `    private static final String B = ${jstr(base)};`,
    ...[...new Set(g.statics)].map((s) => `    ${s}`),
    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
    ``,
    `    public ${cls}(Gameplay g) {`,
    `        super(g, ${jstr(q.id)}, Start.${start}, Repeat.${mode.toUpperCase()}, OnDeath.${death}, ${q.failure?.abandon !== false}, ${q.progressBar !== false}, ${q.permission ? jstr(q.permission) : "null"}, List.of(${(q.requires ?? []).map(jstr).join(", ")}));`,
    `    }`,
    ``,
    `    @Override`,
    `    public void load(DesignConfig c) {`,
    ...load.map((l) => `        ${l}`),
    ...body.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    protected void rewards(Player p, RewardDistributor r, String branch) {`,
    ...rewards.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public void describe(List<String> out) {`,
    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
    `    }`,
    `}`,
    ``,
  ];
  return { source: src.join("\n"), params };
}

function mainClassGp(pkg: string, main: string, ns: string, command: string, items: string[], menus: string[], quests: string[], ids: { items: string[]; menus: string[]; quests: string[] }, hooks: boolean, money: boolean): string {
  return [
    `package ${pkg};`, ``,
    `import java.util.List;`,
    `import org.bukkit.plugin.java.JavaPlugin;`,
    `import ${pkg}.designer.Designer;`,
    `import ${pkg}.designer.Gameplay;`,
    ...(money ? [`import ${pkg}.designer.VaultMoney;`] : []),
    ...(items.length ? [`import ${pkg}.items.*;`] : []),
    ...(menus.length ? [`import ${pkg}.menus.*;`] : []),
    ...(quests.length ? [`import ${pkg}.quests.*;`] : []),
    ``,
    `/** Main class. Generated by Cyrus from the designs (do not edit; custom code goes in the custom package). */`,
    `public class ${main} extends JavaPlugin {`,
    `    private Designer designer;`,
    `    private Gameplay gameplay;`,
    ``,
    `    @Override`,
    `    public void onEnable() {`,
    `        designer = new Designer(this, ${jstr(ns)});`,
    `        gameplay = new Gameplay(designer);`,
    `        designer.enable(null, List.of(${items.map((c) => `new ${c}(designer)`).join(", ")}));`,
    `        gameplay.enable(getCommand(${jstr(command)}), List.of(${menus.map((c) => `new ${c}(gameplay)`).join(", ")}), List.of(${quests.map((c) => `new ${c}(gameplay)`).join(", ")}));`,
    ...(money ? [`        if (getServer().getPluginManager().getPlugin("Vault") != null) gameplay.money(new VaultMoney());`] : []),
    ...(hooks ? [`        ${pkg}.custom.CustomHooks.enable(this);`] : []),
    `        getLogger().info(${jstr(`Designer ready: items ${ids.items.join(", ") || "-"}; menus ${ids.menus.join(", ") || "-"}; quests ${ids.quests.join(", ") || "-"}`)});`,
    `    }`,
    ``,
    `    @Override`,
    `    public void onDisable() {`,
    ...(hooks ? [`        ${pkg}.custom.CustomHooks.disable();`] : []),
    `        if (gameplay != null) gameplay.disable();`,
    `        if (designer != null) designer.disable();`,
    `        gameplay = null;`,
    `        designer = null;`,
    `    }`,
    `}`,
    ``,
  ].join("\n");
}

// --------------------------------------------------------------------------------------------- resources + README
function listYaml(menus: MenuDesign[]): string[] {
  const lists = menus.filter((m): m is Extract<MenuDesign, { style: "chest" }> => m.style === "chest" && m.list?.source.type === "config");
  if (!lists.length) return [];
  const out = [`# Config lists (shop lines) belong to you: edit, add or remove lines and run reload. They are never reset by an update.`, `# Each line: material (a vanilla item id), amount (1-64), price (in the list's currency), name (optional).`, `lists:`];
  for (const m of lists) {
    const src = m.list!.source as Extract<NonNullable<typeof m.list>["source"], { type: "config" }>;
    const cur = src.currency.type === "item" ? src.currency.item : src.currency.type;
    out.push(`  # ${m.id}: currency ${cur}`);
    if (!src.entries.length) { out.push(`  ${m.id}: []`); continue; }
    out.push(`  ${m.id}:`);
    for (const e of src.entries) {
      out.push(`  - material: ${JSON.stringify(e.material)}`, `    amount: ${e.amount}`, `    price: ${Number.isInteger(e.price) ? e.price : e.price}`);
      if (e.name) out.push(`    name: ${JSON.stringify(e.name)}`);
    }
  }
  return out;
}

function configYmlGp(name: string, command: string, params: Param[], version: number, valuesHash: string, seed: number, menus: MenuDesign[]): string {
  return [
    `# ${name} configuration (generated by Cyrus from the designs).`,
    `# Values under "items", "menus" and "quests" are the designs' parameters: change them here and run /${command} reload.`,
    `# Every value is checked when it is loaded: numbers are clamped to the range in their comment.`,
    `# When the mod is updated with new designer values, config_version goes up and those values are re-applied`,
    `# (your previous file is kept as config.yml.bak-v<N>). The "general" and "lists" sections are never overwritten.`,
    `# designer-values: ${valuesHash}`,
    `config_version: ${version}`,
    `general:`,
    `  # Seed of the random_chance conditions (java.util.Random)`,
    `  random_seed: ${seed}`,
    `  # Ticks between two menu clicks of one player (2 to 40)`,
    `  menu_click_cooldown_ticks: ${GENERAL_DEFAULTS.menuClickCooldownTicks}`,
    `  # Quests one player can have active at once (1 to 5)`,
    `  max_active_quests: ${GENERAL_DEFAULTS.maxActiveQuests}`,
    ...yamlTree(params),
    ...listYaml(menus),
    ``,
  ].join("\n");
}

function pluginYmlGp(name: string, main: string, version: string, mc: string, description: string, command: string, ns: string, perms: { node: string; description: string; default: string }[], money: boolean): string {
  const uniq = perms.filter((p, i, a) => a.findIndex((x) => x.node === p.node) === i).sort((a, b) => (a.node < b.node ? -1 : 1));
  const own: [string, string, string][] = [
    ["command", `Use /${command} list, params, menu list/costs and quests list/check`, "op"],
    ["give", `Give ${name} items with /${command} give`, "op"],
    ["menu", `Open ${name} menus with /${command} menu <id>`, "true"],
    ["menu.others", `Open ${name} menus for other players`, "op"],
    ["quests", `Do ${name} quests (/${command} quests)`, "true"],
    ["quests.admin", `Reset other players' ${name} quest progress`, "op"],
    ["reload", `Reload ${name}'s config.yml`, "op"],
  ];
  return [
    `name: ${name}`,
    `version: ${sq(version)}`,
    `main: ${main}`,
    `api-version: ${sq(mc)}`,
    `description: ${sq(description)}`,
    `author: Nxeon Mod Builder`,
    ...(money ? [`softdepend: [Vault]`] : []),
    `commands:`,
    `  ${command}:`,
    `    description: ${sq(`${name}: menus, quests and items`)}`,
    `    usage: ${sq(`/${command} <menu|quests|give|list|params|reload>`)}`,
    `permissions:`,
    ...own.flatMap(([n, d, def]) => [`  ${ns}.${n}:`, `    description: ${sq(d)}`, `    default: ${def}`]),
    ...uniq.flatMap((p) => [`  ${ns}.${p.node}:`, `    description: ${sq(p.description)}`, `    default: ${p.default}`]),
    ``,
  ].join("\n");
}

const secs = (t: number) => (t >= 86400 ? `${+(t / 86400).toFixed(2)} days` : t >= 3600 ? `${+(t / 3600).toFixed(2)} hours` : `${t} seconds`);
const costText = (c?: Cost) => (!c ? "" : c.type === "item" ? ` for ${c.count} x ${bare(c.item).replace(/_/g, " ")}` : c.type === "xp_levels" ? ` for ${c.levels} XP levels` : ` for ${c.amount} money (needs Vault)`);
const OBJ_WORDS = (o: Objective): string => {
  switch (o.type) {
    case "kill_entity": return `kill ${o.count} ${o.entity ? bare(o.entity).replace(/_/g, " ") : (o.kinds ?? []).join("/")}`;
    case "collect_item": return `${o.mode === "pickup" ? "pick up" : "have"} ${o.count} ${bare(o.item).replace(/_/g, " ")}${o.take ? " (handed in)" : ""}`;
    case "craft_item": return `craft ${o.count} ${bare(o.item).replace(/_/g, " ")}`;
    case "visit_location": return `go to ${o.x} ${o.y} ${o.z} in ${o.world}`;
    case "break_block": return `break ${o.count} ${bare(o.block).replace(/_/g, " ")}`;
    case "talk": return `talk (${o.menu})`;
    case "survive": return `survive ${o.seconds} s`;
  }
};

function readmeGp(base: string, name: string, command: string, ns: string, menus: MenuDesign[], quests: QuestDesign[], notes: string[]): string {
  const lines = [base.replace(/\n## Settings \(config\.yml\)[\s\S]*$/, "").replace(/^# .*\n\nCustom items made with the Cyrus Item Designer.*\n/, `# ${name}\n\nItems, menus and quests made with the Cyrus designers.\n`).trimEnd(), ``];
  if (menus.length) lines.push(`## Menus`, ``);
  for (const m of menus) {
    const ow = m.openWith ?? {};
    const how = [ow.command !== false ? `\`/${command} menu ${m.id}\`` : "", ow.item ? `right-click with ${ow.item.replace(/_/g, " ")}` : "", ow.npc ? `right-click an entity tagged \`${ns}.npc.${m.id}\`` : ""].filter(Boolean).join(", ") || "from another menu";
    lines.push(`- **${m.title}** (${m.style}${m.style === "chest" ? `, ${m.rows} rows` : ""}): open with ${how}.${m.permission ? ` Needs ${ns}.${m.permission}.` : ""}`);
    for (const { c } of menuClickables(m)) if (c.cost) lines.push(`  - ${c.icon.name?.text ?? (c.icon.material ? bare(c.icon.material).replace(/_/g, " ") : c.icon.item)}${costText(c.cost)}${c.permission ? ` (${ns}.${c.permission})` : ""}`);
    if (m.style === "chest" && m.list?.source.type === "config") lines.push(`  - Shop lines from config.yml \`lists.${m.id}\` (${m.list.source.entries.length} by default, ${m.list.slots.length} per page).`);
  }
  if (quests.length) lines.push(``, `## Quests`, ``);
  for (const q of quests) {
    const mode = q.repeat?.mode ?? "once";
    lines.push(`- **${q.title}**${q.description ? `: ${q.description}` : ""} ${(q.start ?? "command") === "menu" ? "Started from a menu." : `Start with \`/${command} quests start ${q.id}\`.`}${q.requires?.length ? ` Needs ${q.requires.join(", ")} first.` : ""}${mode !== "once" ? ` Repeats ${mode === "repeatable" ? "" : `${mode} `}(cooldown ${secs(repeatCooldown(q))}).` : ""}`);
    q.steps.forEach((s, i) => lines.push(`  ${i + 1}. ${s.text} (${s.objectives.map(OBJ_WORDS).join(", ")})`));
    for (const b of q.branches?.options ?? []) lines.push(`  - Path "${b.label.text}": ${b.steps.map((s) => `${s.text} (${s.objectives.map(OBJ_WORDS).join(", ")})`).join("; ")}`);
  }
  lines.push(``, base.slice(base.indexOf("## Settings (config.yml)")).replace(/\n## Commands and permissions[\s\S]*$/, "").trimEnd());
  lines.push(``, `## Commands and permissions`, ``,
    `- \`/${command} menu <id> [player]\` (${ns}.menu: everyone; other players ${ns}.menu.others), \`/${command} menu list\`, \`/${command} menu costs <id>\` (${ns}.command)`,
    `- \`/${command} quests\`, \`quests log\`, \`quests start|abandon|info|choose <id>\` (${ns}.quests: everyone); \`quests list\`, \`quests check\` (${ns}.command); \`quests reset <player>\` (${ns}.quests.admin)`,
    `- \`/${command} give <item> [player] [count]\` (${ns}.give), \`/${command} list\`, \`/${command} params [id]\` (${ns}.command), \`/${command} reload\` (${ns}.reload); all operators by default`);
  if (notes.length) lines.push(``, `## Good to know`, ``, ...notes.map((n) => `- ${n}`));
  lines.push(``);
  return lines.join("\n");
}

// ------------------------------------------------------------------------------------------------------------ main
/** Compile a whole mod (any mix of item, menu and quest design files). Item-only mods: the item compiler, unchanged. */
export function compileMod(inputs: unknown[], ctx: CompileContext & { assets?: CompileContext["assets"] & { advancements?: string[] } }): ModCompileResult {
  const kinds = inputs.map(designKind);
  if (kinds.every((k) => k === "item")) {
    const r = compileDesigns(inputs, ctx);
    if (!r.ok) return { ok: false, errors: r.errors, warnings: r.warnings };
    return { ...r, menus: [], quests: [], deps: [], counts: { items: r.designs.length, menus: 0, quests: 0 }, gameplay: false };
  }
  const warnings: GpIssue[] = [];
  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
  const v = validateGameplay(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
  for (const f of v.files) for (const w of f.warnings) warnings.push({ ...w, path: `${f.id}: ${w.path}` });
  if (!v.ok) return { ok: false, errors: [...v.errors.map((e) => ({ ...e, path: e.file ? `${e.file}: ${e.path}` : e.path }))], warnings };
  const fe = v.features as DesignFeatures;
  const items = [...v.items].sort((a, b) => (a.id < b.id ? -1 : 1));
  const { menus, quests } = v;
  const lower = ctx.pluginName.toLowerCase().replace(/_/g, "");
  const pkg = `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
  const main = camel(ctx.pluginName.replace(/^[a-z]/, (c) => c.toUpperCase())) || "DesignerMod";
  const mainCls = /^[A-Z]/.test(main) ? main : `M${main}`;
  const command = ctx.pluginName.toLowerCase().slice(0, 32);
  if (vanillaIds("command", ctx.version).has(command)) return { ok: false, errors: [{ path: "pluginName", code: "command_clash", message: `/${command} is a vanilla command in Minecraft ${ctx.version}; pick another plugin name` }], warnings };
  const money = menus.some((m) => menuClickables(m).some(({ c }) => c.cost?.type === "economy") || (m.style === "chest" && m.list?.source.type === "config" && m.list.source.currency.type === "economy"));
  const files: CompiledFile[] = [];
  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
  const add = (path: string, content: string, role: CompiledFile["role"]) => files.push({ path, content, sha256: sha256(content), role });
  for (const c of [...COMPONENTS, ...GAMEPLAY_COMPONENTS, ...(money ? [VAULT_COMPONENT] : [])]) add(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
  add(`${dir}/${COMPAT_META.file}`, renderComponent(compatSource(fe), pkg), "compat");
  const classes = new Map<string, string>();
  const claim = (cls: string, what: string): DzIssue | null => { if (classes.has(cls)) return { path: what, code: "class_clash", message: `${classes.get(cls)} and ${what} map to the same Java class ${cls}; rename one` }; classes.set(cls, what); return null; };
  const itemClasses: string[] = [], menuClasses: string[] = [], questClasses: string[] = [];
  const modelsApplied: string[] = [];
  for (const d of items) {
    const icls = `${camel(d.id)}Item`;
    const e1 = claim(`items.${icls}`, d.id); if (e1) return { ok: false, errors: [e1], warnings };
    const abCls: string[] = [];
    for (const ab of d.abilities) {
      const acls = `${camel(d.id)}${camel(ab.id)}`;
      const e2 = claim(`abilities.${acls}`, `${d.id}.${ab.id}`); if (e2) return { ok: false, errors: [e2], warnings };
      add(`${dir}/abilities/${acls}.java`, abilityClass(pkg, d, ab, acls, ctx.namespace).source, "generated");
      abCls.push(acls);
    }
    const modelOk = !!d.assets?.model && (!ctx.assets?.models || ctx.assets.models.includes(d.assets.model));
    if (modelOk) modelsApplied.push(d.assets!.model!);
    add(`${dir}/items/${icls}.java`, itemClass(pkg, d, icls, abCls, ctx.namespace, fe, modelOk).source, "generated");
    itemClasses.push(icls);
  }
  for (const m of menus) {
    const cls = `${camel(m.id)}Menu`;
    const e = claim(`menus.${cls}`, m.id); if (e) return { ok: false, errors: [e], warnings };
    add(`${dir}/menus/${cls}.java`, menuClass(pkg, m, cls, ctx.namespace, ctx.assets?.models).source, "generated");
    menuClasses.push(cls);
  }
  for (const q of quests) {
    const cls = `${camel(q.id)}Quest`;
    const e = claim(`quests.${cls}`, q.id); if (e) return { ok: false, errors: [e], warnings };
    add(`${dir}/quests/${cls}.java`, questClass(pkg, q, cls, ctx.namespace, ctx.assets?.models).source, "generated");
    questClasses.push(cls);
  }
  const ids = { items: items.map((d) => d.id), menus: menus.map((m) => m.id), quests: quests.map((q) => q.id) };
  add(`${dir}/${mainCls}.java`, mainClassGp(pkg, mainCls, ctx.namespace, command, itemClasses, menuClasses, questClasses, ids, !!ctx.customHooks, money), "generated");
  const ordered = modParams(items, menus, quests);
  const valuesHash = designerValuesHash(ordered);
  const configVersion = ctx.configVersion !== undefined ? Math.max(1, Math.min(1_000_000, Math.round(ctx.configVersion))) : nextConfigVersion(ctx.previousConfig, valuesHash);
  add(`src/main/resources/config.yml`, configYmlGp(ctx.pluginName, command, ordered, configVersion, valuesHash, randomSeedFor(ctx.namespace), menus), "resource");
  const perms = [...items.flatMap((d) => d.permissions ?? []), ...menus.flatMap((m) => m.permissions ?? []), ...quests.flatMap((q) => q.permissions ?? [])];
  const desc = (ctx.description ?? [items.length ? `Items: ${items.map((d) => d.name.text).join(", ")}` : "", menus.length ? `Menus: ${menus.map((m) => m.title).join(", ")}` : "", quests.length ? `Quests: ${quests.map((q) => q.title).join(", ")}` : ""].filter(Boolean).join(". ")).slice(0, 200);
  add(`src/main/resources/plugin.yml`, pluginYmlGp(ctx.pluginName, `${pkg}.${mainCls}`, ctx.pluginVersion ?? "1.0.0", ctx.version, desc, command, ctx.namespace, perms, money), "resource");
  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  // README: the item part from the item compiler's README text when there are items, then menus, quests, settings
  const notes: string[] = [];
  for (const d of items) if (d.assets?.model && fe.itemModel && !modelsApplied.includes(d.assets.model)) notes.push(`${d.name.text} keeps the ${bare(d.base).replace(/_/g, " ")} look: this mod has no custom model "${d.assets.model}".`);
  if (!fe.itemModel && (items.some((d) => d.assets?.model) || menus.some((m) => menuClickables(m).some(({ c }) => c.icon.model)))) notes.push(`Custom item models need Minecraft 1.21.4 or newer: on ${fe.version} items and icons keep their base look.`);
  if (money) notes.push("Money prices need the Vault plugin and an economy plugin on the server; without them those buttons say so and take nothing.");
  if (menus.some((m) => m.openWith?.npc)) notes.push(`NPC menus open when a player right-clicks an entity tagged ${ctx.namespace}.npc.<menu id> (an operator adds the tag with /tag <entity> add ${ctx.namespace}.npc.<menu id>).`);
  if (quests.length) notes.push("Quest progress is stored on each player (no database) and survives restarts; when a quest's steps change in an update, players on a changed step restart that quest.");
  if (quests.some((q) => (q.repeat?.mode ?? "once") === "daily" || q.repeat?.mode === "weekly")) notes.push("Daily and weekly quests use a rolling cooldown from the last completion (24 h / 7 days), not a calendar reset.");
  if (menus.length) notes.push("Menu clicks are server-side only: shift-clicks, number keys, drags and drops in a menu do nothing; prices are taken before anything is given.");
  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
  const itemBase = (() => {
    if (!items.length) return `# ${ctx.pluginName}\n\n\n## Settings (config.yml)\n\nChange any of these in plugins/${ctx.pluginName}/config.yml and run \`/${command} reload\` (values are clamped to the range shown):\n\n${ordered.map((p) => `- \`${p.path}\` = ${p.kind === "text" || p.kind === "sound" ? `"${p.value}"` : fmtNum(Number(p.value), p.kind)}: ${p.label}${p.kind === "text" || p.kind === "sound" ? "" : ` (${fmtNum(p.min, p.kind)}-${fmtNum(p.max, p.kind)})`}`).join("\n")}\n\n## Commands and permissions\n`;
    const r = compileDesigns(items, { ...ctx, configVersion: 1 });
    if (!r.ok) return "";
    const settings = ordered.map((p) => `- \`${p.path}\` = ${p.kind === "text" || p.kind === "sound" ? `"${p.value}"` : fmtNum(Number(p.value), p.kind)}: ${p.label}${p.kind === "text" || p.kind === "sound" ? "" : ` (${fmtNum(p.min, p.kind)}-${fmtNum(p.max, p.kind)})`}`).join("\n");
    return r.readme.replace(/## Settings \(config\.yml\)\n\n[^\n]*\n\n[\s\S]*?\n\n## Commands and permissions/, `## Settings (config.yml)\n\nChange any of these in plugins/${ctx.pluginName}/config.yml and run \`/${command} reload\` (values are clamped to the range shown):\n\n${settings}\n\n## Commands and permissions`);
  })();
  const rd = readmeGp(itemBase, ctx.pluginName, command, ctx.namespace, menus, quests, notes);
  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(rd)}`);
  return {
    ok: true, files, readme: rd, readmeSha256: sha256(rd), hash, params: ordered, warnings, notes, pkg, modelsApplied, mainClass: `${pkg}.${mainCls}`, command, configVersion, designerValuesHash: valuesHash,
    features: fe, javacVerified: (JAVAC_VERIFIED_VERSIONS as readonly string[]).includes(ctx.version), compiler: `${COMPILER_VERSION}+${GAMEPLAY_COMPILER_VERSION}`, library: GAMEPLAY_LIBRARY_VERSION, libraryHash: gameplayLibraryHash(),
    designs: items, menus, quests, deps: money ? [VAULT_DEP] : [], counts: { items: items.length, menus: menus.length, quests: quests.length }, gameplay: true,
  };
}

