import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { compileMod } from "../../lib/cyrus/designer/gameplay/compile";
import { designFeatures } from "../../lib/cyrus/designer/spec";
import { VERSIONS } from "../../lib/cyrus/versions/registry";

const FX = path.join(__dirname, "../../test/fixtures/cyrus-gameplay");
export const GAMEPLAY_FIXTURES = ["guild_badge", "guild_charm", "shop", "elder", "trial_one", "trial_two", "trial_three", "daily_bread"];
