export const GP_NS = "nx_r11guild";
export const GP_PLUGIN = "GuildQuests";

if (require.main === module) {
  void readdirSync;
  const out: Record<string, unknown> = {};
  for (const v of VERSIONS.map((x) => x.id).filter((x) => designFeatures(x).ok)) {
    const r = compileMod(loadGameplayFixtures(), { version: v, namespace: GP_NS, pluginName: GP_PLUGIN });
