// Cyrus R3 gameplay designers, part 2: the TS REFERENCE SIMULATOR of the menu and quest components (MenuManager,
// Pagination, CostCharger, Quests, QuestStore, ObjectiveTracker semantics). It implements the same rules in the same order
// as the Java: every click in a menu is cancelled; only plain left/right clicks act, rate-limited; permission -> room ->
// can pay -> take (all or nothing) -> actions; quests: start rules, steps, take-on-complete, branches, completion stored
// before rewards, repeat cooldowns, death rules, time limits; the progress codec (QuestStore q1) is byte-identical
// (encodeProgress / decodeProgress; checked against the real JVM by `/<mod> quests check` on node-2).
// NOT simulated: real inventories' exact max stack sizes (a small table), the client, physics, other plugins.
import type { ItemDesign } from "../spec";
import { GAMEPLAY_LIMITS, REPEAT_DEFAULTS, menuClickables, objectiveTarget, questSteps, repeatCooldown, type Cost, type MenuAction, type MenuDesign, type Objective, type QuestDesign, type Reward } from "./spec";

// ------------------------------------------------------------------------------------------------------- pagination
export const Pagination = {
  MAX_PAGES: GAMEPLAY_LIMITS.maxPages,
  pages(entries: number, size: number) { if (size <= 0) return 1; return Math.max(1, Math.min(this.MAX_PAGES, Math.floor((Math.max(0, entries) + size - 1) / size))); },
  clamp(page: number, entries: number, size: number) { return Math.max(0, Math.min(this.pages(entries, size) - 1, page)); },
  first(page: number, size: number) { return Math.max(0, page) * Math.max(0, size); },
  count(page: number, entries: number, size: number) { if (size <= 0) return 0; const f = this.first(this.clamp(page, entries, size), size); const shown = Math.min(Math.max(0, entries), this.pages(entries, size) * size); return Math.max(0, Math.min(size, shown - f)); },
  hasNext(page: number, entries: number, size: number) { return this.clamp(page, entries, size) < this.pages(entries, size) - 1; },
  hasPrev(page: number, entries: number, size: number) { return this.clamp(page, entries, size) > 0; },
};

// --------------------------------------------------------------------------------------------------------- codec
export type ProgressEntry = { quest: string; state: "A" | "C" | "D"; step: string; branch: string; counts: [number, number, number]; started: number; completions: number; last: number };
export const PROGRESS_VERSION = "q1";
const MAX_COUNT = 1_000_000;
const MAX_TIME = 4102444800;

export function encodeProgress(m: Map<string, ProgressEntry>): string {
  let b = PROGRESS_VERSION;
  for (const id of [...m.keys()].sort((a, c) => (a < c ? -1 : a > c ? 1 : 0))) {
    const e = m.get(id)!;
    b += `|${e.quest},${e.state},${e.step},${e.branch},${e.counts[0]}.${e.counts[1]}.${e.counts[2]},${e.started},${e.completions},${e.last}`;
  }
  return b;
}
const javaInt = (s: string, min: number, max: number) => (/^[+-]?\d+$/.test(s) && Math.abs(Number(s)) <= 2147483647 ? Math.max(min, Math.min(max, Number(s))) : min);
const javaLong = (s: string) => (/^[+-]?\d+$/.test(s) && s.replace(/^[+-]/, "").length <= 18 ? Math.max(0, Math.min(MAX_TIME, Number(s))) : 0);
const cut = (s: string) => (s.length > 32 ? s.slice(0, 32) : s);
const pathOf = (q: QuestDesign, branch: string) => [...q.steps, ...(q.branches?.options.find((b) => b.id === branch)?.steps ?? [])];
const stepOf = (q: QuestDesign, branch: string, id: string) => pathOf(q, branch).find((s) => s.id === id) ?? null;

/** The Java QuestStore.decode, line for line (notes are counted by tests). */
export function decodeProgress(raw: string | null | undefined, defs: Map<string, QuestDesign>, notes: string[]): Map<string, ProgressEntry> {
  const out = new Map<string, ProgressEntry>();
  if (!raw || raw === PROGRESS_VERSION) return out;
  if (!raw.startsWith(`${PROGRESS_VERSION}|`) || raw.length > GAMEPLAY_LIMITS.maxProgressChars * 2) { notes.push("unknown or oversized quest progress format, reset (backup kept)"); return out; }
  const parts = raw.split("|");
  for (let i = 1; i < parts.length && out.size < 64; i++) {
    const f = parts[i].split(",");
    if (f.length !== 8) { notes.push("dropped a malformed progress entry"); continue; }
    const q = defs.get(f[0]);
    if (!q) { notes.push(`dropped the progress of quest ${cut(f[0])} (no longer in this mod)`); continue; }
    const st = f[1].length === 1 ? f[1] : "?";
    if (!"ACD".includes(st)) { notes.push(`dropped the progress of quest ${q.id} (unknown state)`); continue; }
    const c = f[4].split(".");
    const e: ProgressEntry = { quest: q.id, state: st as ProgressEntry["state"], step: f[2], branch: f[3], counts: [0, 1, 2].map((j) => (j < c.length ? javaInt(c[j], 0, MAX_COUNT) : 0)) as [number, number, number], started: javaLong(f[5]), completions: javaInt(f[6], 0, MAX_COUNT), last: javaLong(f[7]) };
    if (e.branch && !q.branches?.options.some((b) => b.id === e.branch)) { notes.push(`${q.id}: branch ${cut(e.branch)} no longer exists`); e.branch = ""; }
    if (e.state === "A") {
      let s = stepOf(q, e.branch, e.step);
      if (!s) { notes.push(`${q.id}: step ${cut(e.step)} changed, the quest restarts`); e.step = q.steps[0].id; e.branch = ""; e.counts = [0, 0, 0]; s = q.steps[0]; }
      e.counts = [0, 1, 2].map((j) => (j < s!.objectives.length ? Math.min(e.counts[j], objectiveTarget(s!.objectives[j])) : 0)) as [number, number, number];
    } else if (e.state === "C") {
      if (!q.branches) { notes.push(`${q.id}: the branches were removed, the quest restarts`); e.state = "A"; e.step = q.steps[0].id; } else e.step = "";
      e.branch = ""; e.counts = [0, 0, 0];
    } else { e.step = ""; e.branch = ""; e.counts = [0, 0, 0]; }
    out.set(q.id, e);
  }
  return out;
}

/** The deterministic sample `/<mod> quests check` prints on the server (same entries, same encoding). */
export function progressSample(quests: QuestDesign[]): string {
  const m = new Map<string, ProgressEntry>();
  for (const q of quests) {
    const first = q.steps[0];
    m.set(q.id, { quest: q.id, state: "A", step: first.id, branch: "", counts: [0, 1, 2].map((j) => (j < first.objectives.length ? Math.min(j + 1, objectiveTarget(first.objectives[j])) : 0)) as [number, number, number], started: 1700000000, completions: 2, last: 1700000100 });
  }
  return encodeProgress(m);
}

// --------------------------------------------------------------------------------------------------- the world
export type SimPlayer = {
  name: string;
  /** Storage (36 slots): stacks of an item key (minecraft:x or a design item key). */
  slots: ({ item: string; count: number } | null)[];
  levels: number;
  money: number;
  perms: Set<string>;
  online: boolean;
  alive: boolean;
  world: string;
  pos: [number, number, number];
};
export type SimEvent = { t: number; player: string; kind: string; detail?: string };
export type ClickType = "left" | "right" | "shift_left" | "shift_right" | "number_key" | "double_click" | "drop" | "control_drop" | "middle" | "swap_offhand" | "creative";
export type ClickResult = { cancelled: true; ran: boolean; reason: string };

const maxStack = (item: string) => (/(sword|pickaxe|_axe|shovel|hoe|helmet|chestplate|leggings|boots|^minecraft:bow|shield|saddle|potion|elytra|trident|crossbow|compass)$/.test(item) ? 1 : /(ender_pearl|snowball|egg|_sign|banner|honey_bottle|bucket)$/.test(item) ? 16 : 64);

type Clickable = { slot: number; label: string; actions: MenuAction[]; cost?: Cost; permission?: string; hide?: boolean; nav?: "prev" | "next" };
type Open = { menu: string; page: number; slots: Map<number, Clickable> };

export type GameplaySimOptions = {
  namespace: string;
  /** config.yml overrides (exact parameter paths, e.g. menus.shop.b47.cost.count), already clamped by the caller or the loader. */
  config?: Record<string, number | string>;
  clickCooldownTicks?: number;
  maxActive?: number;
  /** Vault + an economy are on the server. */
  vault?: boolean;
  /** Wall clock (seconds) at tick 0. */
  clock?: number;
};

export class GameplaySimulator {
  tick = 0;
  clock: number;
  readonly log: SimEvent[] = [];
  readonly players = new Map<string, SimPlayer>();
  private readonly menus: Map<string, MenuDesign>;
  private readonly quests: Map<string, QuestDesign>;
  private readonly progress = new Map<string, Map<string, ProgressEntry>>();
  private readonly open = new Map<string, Open>();
  private readonly back = new Map<string, string[]>();
  private readonly lastClick = new Map<string, number>();
  private readonly placed = new Set<string>();
  constructor(readonly items: ItemDesign[], menus: MenuDesign[], quests: QuestDesign[], readonly opts: GameplaySimOptions) {
    this.menus = new Map(menus.map((m) => [m.id, m]));
    this.quests = new Map([...quests].sort((a, b) => (a.id < b.id ? -1 : 1)).map((q) => [q.id, q]));
    this.clock = opts.clock ?? 1_800_000_000;
  }
  private ev(player: string, kind: string, detail?: string) { this.log.push({ t: this.tick, player, kind, ...(detail !== undefined ? { detail } : {}) }); }
  private cfg<T extends number | string>(path: string, dflt: T): T { const v = this.opts.config?.[path]; return (v === undefined ? dflt : v) as T; }
  get clickCooldown() { return Math.max(2, Math.min(40, this.opts.clickCooldownTicks ?? 4)); }
  get maxActive() { return Math.max(1, Math.min(5, this.opts.maxActive ?? 3)); }

  join(name: string, init: Partial<SimPlayer> = {}): SimPlayer {
    const p: SimPlayer = { name, slots: Array(36).fill(null), levels: 0, money: 0, perms: new Set(), online: true, alive: true, world: "world", pos: [0, 64, 0], ...init };
    this.players.set(name, p);
    return p;
  }
  quit(name: string) { const p = this.players.get(name)!; p.online = false; this.open.delete(name); this.back.delete(name); }
  advance(ticks: number) { for (let i = 0; i < ticks; i++) { this.tick++; if (this.tick % 20 === 0) { this.clock++; for (const p of this.players.values()) if (p.online) this.questTick(p.name); } } }

  // ------------------------------------------------------------------------------------------ inventory
  count(name: string, item: string): number { return this.players.get(name)!.slots.reduce((n, s) => n + (s && s.item === item ? s.count : 0), 0); }
  /** Add as much as fits; returns what did not fit (the Java drops it at the feet). */
  give(name: string, item: string, count: number): number {
    const p = this.players.get(name)!;
    let left = count;
    const max = maxStack(item);
    for (const s of p.slots) if (s && s.item === item && s.count < max && left > 0) { const a = Math.min(left, max - s.count); s.count += a; left -= a; }
    for (let i = 0; i < p.slots.length && left > 0; i++) if (!p.slots[i]) { const a = Math.min(left, max); p.slots[i] = { item, count: a }; left -= a; }
    if (left > 0) this.ev(name, "dropped_at_feet", `${left} x ${item}`);
    return left;
  }
  fits(name: string, stacks: { item: string; count: number }[]): boolean {
    const sim = this.players.get(name)!.slots.map((s) => (s ? { ...s } : null));
    for (const w of stacks) {
      let left = w.count; const max = maxStack(w.item);
      for (const s of sim) if (s && s.item === w.item && s.count < max && left > 0) { const a = Math.min(left, max - s.count); s.count += a; left -= a; }
      for (let i = 0; i < sim.length && left > 0; i++) if (!sim[i]) { const a = Math.min(left, max); sim[i] = { item: w.item, count: a }; left -= a; }
      if (left > 0) return false;
    }
    return true;
  }
  private takeItems(name: string, item: string, count: number): boolean {
    if (this.count(name, item) < count) return false;
    const p = this.players.get(name)!;
    let left = count;
    for (let i = 0; i < p.slots.length && left > 0; i++) { const s = p.slots[i]; if (!s || s.item !== item) continue; const use = Math.min(left, s.count); left -= use; s.count -= use; if (!s.count) p.slots[i] = null; }
    return true;
  }
  /** CostCharger.refusal: null = can pay. */
  refusal(name: string, c: Cost | undefined): string | null {
    const p = this.players.get(name)!;
    if (!c) return null;
    if (c.type === "item") return this.count(name, c.item) >= c.count ? null : "cannot_pay";
    if (c.type === "xp_levels") return p.levels >= c.levels ? null : "cannot_pay";
    if (!this.opts.vault) return "no_economy";
    return p.money >= c.amount ? null : "cannot_pay";
  }
  private take(name: string, c: Cost | undefined): boolean {
    if (this.refusal(name, c) !== null) return false;
    const p = this.players.get(name)!;
    if (!c) return true;
    if (c.type === "item") return this.takeItems(name, c.item, c.count);
    if (c.type === "xp_levels") { p.levels = Math.max(0, p.levels - c.levels); return true; }
    p.money -= c.amount; return true;
  }

  // ----------------------------------------------------------------------------------------------- menus
