  private allowed(name: string, c: { permission?: string }) { return !c.permission || this.players.get(name)!.perms.has(`${this.opts.namespace}.${c.permission}`); }

  /** MenuManager.open: what each slot holds (null = refused). */
  openMenu(name: string, id: string, page = 0, push = true): Open | null {
    const p = this.players.get(name)!;
    if (!p.online || !p.alive) return null;
    const m = this.menus.get(id);
    if (!m) { this.ev(name, "no_menu", id); return null; }
    if (m.permission && !p.perms.has(`${this.opts.namespace}.${m.permission}`)) { this.ev(name, "no_permission_menu", id); return null; }
    const cur = this.open.get(name);
    if (push && cur && cur.menu !== id) { const st = this.back.get(name) ?? []; st.unshift(cur.menu); while (st.length > GAMEPLAY_LIMITS.maxBack) st.pop(); this.back.set(name, st); }
    const o: Open = { menu: id, page, slots: new Map() };
