// Cyrus R3 gameplay designers, part 2: the TS REFERENCE SIMULATOR of the menu and quest components (MenuManager,
// Pagination, CostCharger, Quests, QuestStore, ObjectiveTracker semantics). It implements the same rules in the same order
// as the Java: every click in a menu is cancelled; only plain left/right clicks act, rate-limited; permission -> room ->
// can pay -> take (all or nothing) -> actions; quests: start rules, steps, take-on-complete, branches, completion stored
// before rewards, repeat cooldowns, death rules, time limits; the progress codec (QuestStore q1) is byte-identical
// (encodeProgress / decodeProgress; checked against the real JVM by `/<mod> quests check` on node-2).
// NOT simulated: real inventories' exact max stack sizes (a small table), the client, physics, other plugins.
import type { ItemDesign } from "../spec";
import { GAMEPLAY_LIMITS, REPEAT_DEFAULTS, menuClickables, objectiveTarget, questSteps, repeatCooldown, type Cost, type MenuAction, type MenuDesign, type Objective, type QuestDesign, type Reward } from "./spec";

// ------------------------------------------------------------------------------------------------------- pagination
export const Pagination = {
  MAX_PAGES: GAMEPLAY_LIMITS.maxPages,
  pages(entries: number, size: number) { if (size <= 0) return 1; return Math.max(1, Math.min(this.MAX_PAGES, Math.floor((Math.max(0, entries) + size - 1) / size))); },
  clamp(page: number, entries: number, size: number) { return Math.max(0, Math.min(this.pages(entries, size) - 1, page)); },
  first(page: number, size: number) { return Math.max(0, page) * Math.max(0, size); },
  count(page: number, entries: number, size: number) { if (size <= 0) return 0; const f = this.first(this.clamp(page, entries, size), size); const shown = Math.min(Math.max(0, entries), this.pages(entries, size) * size); return Math.max(0, Math.min(size, shown - f)); },
  hasNext(page: number, entries: number, size: number) { return this.clamp(page, entries, size) < this.pages(entries, size) - 1; },
  hasPrev(page: number, entries: number, size: number) { return this.clamp(page, entries, size) > 0; },
