// --------------------------------------------------------------------------------------------------------- codec
export type ProgressEntry = { quest: string; state: "A" | "C" | "D"; step: string; branch: string; counts: [number, number, number]; started: number; completions: number; last: number };
export const PROGRESS_VERSION = "q1";
const MAX_COUNT = 1_000_000;
const MAX_TIME = 4102444800;

export function encodeProgress(m: Map<string, ProgressEntry>): string {
  let b = PROGRESS_VERSION;
  for (const id of [...m.keys()].sort((a, c) => (a < c ? -1 : a > c ? 1 : 0))) {
    const e = m.get(id)!;
    b += `|${e.quest},${e.state},${e.step},${e.branch},${e.counts[0]}.${e.counts[1]}.${e.counts[2]},${e.started},${e.completions},${e.last}`;
  }
  return b;
}
const javaInt = (s: string, min: number, max: number) => (/^[+-]?\d+$/.test(s) && Math.abs(Number(s)) <= 2147483647 ? Math.max(min, Math.min(max, Number(s))) : min);
const javaLong = (s: string) => (/^[+-]?\d+$/.test(s) && s.replace(/^[+-]/, "").length <= 18 ? Math.max(0, Math.min(MAX_TIME, Number(s))) : 0);
const cut = (s: string) => (s.length > 32 ? s.slice(0, 32) : s);
const pathOf = (q: QuestDesign, branch: string) => [...q.steps, ...(q.branches?.options.find((b) => b.id === branch)?.steps ?? [])];
const stepOf = (q: QuestDesign, branch: string, id: string) => pathOf(q, branch).find((s) => s.id === id) ?? null;

/** The Java QuestStore.decode, line for line (notes are counted by tests). */
export function decodeProgress(raw: string | null | undefined, defs: Map<string, QuestDesign>, notes: string[]): Map<string, ProgressEntry> {
  const out = new Map<string, ProgressEntry>();
  if (!raw || raw === PROGRESS_VERSION) return out;
  if (!raw.startsWith(`${PROGRESS_VERSION}|`) || raw.length > GAMEPLAY_LIMITS.maxProgressChars * 2) { notes.push("unknown or oversized quest progress format, reset (backup kept)"); return out; }
  const parts = raw.split("|");
  for (let i = 1; i < parts.length && out.size < 64; i++) {
    const f = parts[i].split(",");
    if (f.length !== 8) { notes.push("dropped a malformed progress entry"); continue; }
    const q = defs.get(f[0]);
    if (!q) { notes.push(`dropped the progress of quest ${cut(f[0])} (no longer in this mod)`); continue; }
    const st = f[1].length === 1 ? f[1] : "?";
    if (!"ACD".includes(st)) { notes.push(`dropped the progress of quest ${q.id} (unknown state)`); continue; }
    const c = f[4].split(".");
    const e: ProgressEntry = { quest: q.id, state: st as ProgressEntry["state"], step: f[2], branch: f[3], counts: [0, 1, 2].map((j) => (j < c.length ? javaInt(c[j], 0, MAX_COUNT) : 0)) as [number, number, number], started: javaLong(f[5]), completions: javaInt(f[6], 0, MAX_COUNT), last: javaLong(f[7]) };
    if (e.branch && !q.branches?.options.some((b) => b.id === e.branch)) { notes.push(`${q.id}: branch ${cut(e.branch)} no longer exists`); e.branch = ""; }
    if (e.state === "A") {
      let s = stepOf(q, e.branch, e.step);
      if (!s) { notes.push(`${q.id}: step ${cut(e.step)} changed, the quest restarts`); e.step = q.steps[0].id; e.branch = ""; e.counts = [0, 0, 0]; s = q.steps[0]; }
      e.counts = [0, 1, 2].map((j) => (j < s!.objectives.length ? Math.min(e.counts[j], objectiveTarget(s!.objectives[j])) : 0)) as [number, number, number];
    } else if (e.state === "C") {
      if (!q.branches) { notes.push(`${q.id}: the branches were removed, the quest restarts`); e.state = "A"; e.step = q.steps[0].id; } else e.step = "";
      e.branch = ""; e.counts = [0, 0, 0];
    } else { e.step = ""; e.branch = ""; e.counts = [0, 0, 0]; }
    out.set(q.id, e);
  }
  return out;
}

/** The deterministic sample `/<mod> quests check` prints on the server (same entries, same encoding). */
export function progressSample(quests: QuestDesign[]): string {
  const m = new Map<string, ProgressEntry>();
  for (const q of quests) {
    const first = q.steps[0];
    m.set(q.id, { quest: q.id, state: "A", step: first.id, branch: "", counts: [0, 1, 2].map((j) => (j < first.objectives.length ? Math.min(j + 1, objectiveTarget(first.objectives[j])) : 0)) as [number, number, number], started: 1700000000, completions: 2, last: 1700000100 });
  }
  return encodeProgress(m);
}

// --------------------------------------------------------------------------------------------------- the world
export type SimPlayer = {
  name: string;
  /** Storage (36 slots): stacks of an item key (minecraft:x or a design item key). */
  slots: ({ item: string; count: number } | null)[];
  levels: number;
  money: number;
  perms: Set<string>;
  online: boolean;
  alive: boolean;
  world: string;
  pos: [number, number, number];
};
export type SimEvent = { t: number; player: string; kind: string; detail?: string };
export type ClickType = "left" | "right" | "shift_left" | "shift_right" | "number_key" | "double_click" | "drop" | "control_drop" | "middle" | "swap_offhand" | "creative";
export type ClickResult = { cancelled: true; ran: boolean; reason: string };

const maxStack = (item: string) => (/(sword|pickaxe|_axe|shovel|hoe|helmet|chestplate|leggings|boots|^minecraft:bow|shield|saddle|potion|elytra|trident|crossbow|compass)$/.test(item) ? 1 : /(ender_pearl|snowball|egg|_sign|banner|honey_bottle|bucket)$/.test(item) ? 16 : 64);

type Clickable = { slot: number; label: string; actions: MenuAction[]; cost?: Cost; permission?: string; hide?: boolean; nav?: "prev" | "next" };
type Open = { menu: string; page: number; slots: Map<number, Clickable> };

export type GameplaySimOptions = {
  namespace: string;
  /** config.yml overrides (exact parameter paths, e.g. menus.shop.b47.cost.count), already clamped by the caller or the loader. */
  config?: Record<string, number | string>;
  clickCooldownTicks?: number;
  maxActive?: number;
  /** Vault + an economy are on the server. */
  vault?: boolean;
  /** Wall clock (seconds) at tick 0. */
  clock?: number;
};

export class GameplaySimulator {
  tick = 0;
  clock: number;
  readonly log: SimEvent[] = [];
  readonly players = new Map<string, SimPlayer>();
  private readonly menus: Map<string, MenuDesign>;
  private readonly quests: Map<string, QuestDesign>;
  private readonly progress = new Map<string, Map<string, ProgressEntry>>();
  private readonly open = new Map<string, Open>();
  private readonly back = new Map<string, string[]>();
  private readonly lastClick = new Map<string, number>();
  private readonly placed = new Set<string>();
  constructor(readonly items: ItemDesign[], menus: MenuDesign[], quests: QuestDesign[], readonly opts: GameplaySimOptions) {
    this.menus = new Map(menus.map((m) => [m.id, m]));
    this.quests = new Map([...quests].sort((a, b) => (a.id < b.id ? -1 : 1)).map((q) => [q.id, q]));
    this.clock = opts.clock ?? 1_800_000_000;
  }
  private ev(player: string, kind: string, detail?: string) { this.log.push({ t: this.tick, player, kind, ...(detail !== undefined ? { detail } : {}) }); }
  private cfg<T extends number | string>(path: string, dflt: T): T { const v = this.opts.config?.[path]; return (v === undefined ? dflt : v) as T; }
  get clickCooldown() { return Math.max(2, Math.min(40, this.opts.clickCooldownTicks ?? 4)); }
  get maxActive() { return Math.max(1, Math.min(5, this.opts.maxActive ?? 3)); }

  join(name: string, init: Partial<SimPlayer> = {}): SimPlayer {
    const p: SimPlayer = { name, slots: Array(36).fill(null), levels: 0, money: 0, perms: new Set(), online: true, alive: true, world: "world", pos: [0, 64, 0], ...init };
    this.players.set(name, p);
    return p;
  }
  quit(name: string) { const p = this.players.get(name)!; p.online = false; this.open.delete(name); this.back.delete(name); }
  advance(ticks: number) { for (let i = 0; i < ticks; i++) { this.tick++; if (this.tick % 20 === 0) { this.clock++; for (const p of this.players.values()) if (p.online) this.questTick(p.name); } } }

  // ------------------------------------------------------------------------------------------ inventory
  count(name: string, item: string): number { return this.players.get(name)!.slots.reduce((n, s) => n + (s && s.item === item ? s.count : 0), 0); }
  /** Add as much as fits; returns what did not fit (the Java drops it at the feet). */
  give(name: string, item: string, count: number): number {
    const p = this.players.get(name)!;
    let left = count;
    const max = maxStack(item);
    for (const s of p.slots) if (s && s.item === item && s.count < max && left > 0) { const a = Math.min(left, max - s.count); s.count += a; left -= a; }
    for (let i = 0; i < p.slots.length && left > 0; i++) if (!p.slots[i]) { const a = Math.min(left, max); p.slots[i] = { item, count: a }; left -= a; }
    if (left > 0) this.ev(name, "dropped_at_feet", `${left} x ${item}`);
    return left;
  }
  fits(name: string, stacks: { item: string; count: number }[]): boolean {
    const sim = this.players.get(name)!.slots.map((s) => (s ? { ...s } : null));
    for (const w of stacks) {
      let left = w.count; const max = maxStack(w.item);
      for (const s of sim) if (s && s.item === w.item && s.count < max && left > 0) { const a = Math.min(left, max - s.count); s.count += a; left -= a; }
      for (let i = 0; i < sim.length && left > 0; i++) if (!sim[i]) { const a = Math.min(left, max); sim[i] = { item: w.item, count: a }; left -= a; }
      if (left > 0) return false;
    }
    return true;
  }
  private takeItems(name: string, item: string, count: number): boolean {
    if (this.count(name, item) < count) return false;
    const p = this.players.get(name)!;
    let left = count;
    for (let i = 0; i < p.slots.length && left > 0; i++) { const s = p.slots[i]; if (!s || s.item !== item) continue; const use = Math.min(left, s.count); left -= use; s.count -= use; if (!s.count) p.slots[i] = null; }
    return true;
  }
  /** CostCharger.refusal: null = can pay. */
  refusal(name: string, c: Cost | undefined): string | null {
    const p = this.players.get(name)!;
    if (!c) return null;
    if (c.type === "item") return this.count(name, c.item) >= c.count ? null : "cannot_pay";
    if (c.type === "xp_levels") return p.levels >= c.levels ? null : "cannot_pay";
    if (!this.opts.vault) return "no_economy";
    return p.money >= c.amount ? null : "cannot_pay";
  }
  private take(name: string, c: Cost | undefined): boolean {
    if (this.refusal(name, c) !== null) return false;
    const p = this.players.get(name)!;
    if (!c) return true;
    if (c.type === "item") return this.takeItems(name, c.item, c.count);
    if (c.type === "xp_levels") { p.levels = Math.max(0, p.levels - c.levels); return true; }
    p.money -= c.amount; return true;
  }

  // ----------------------------------------------------------------------------------------------- menus
  private clickables(m: MenuDesign): Clickable[] {
    const base = `menus.${m.id}.`;
    const withCfg = (node: string, c: { icon: { name?: { text: string } }; actions?: MenuAction[]; cost?: Cost; permission?: string; hideWithoutPermission?: boolean }, slot: number): Clickable => {
      const cost = c.cost ? (c.cost.type === "item" ? { ...c.cost, count: this.cfg(`${base}${node}.cost.count`, c.cost.count) } : c.cost.type === "xp_levels" ? { ...c.cost, levels: this.cfg(`${base}${node}.cost.levels`, c.cost.levels) } : { ...c.cost, amount: this.cfg(`${base}${node}.cost.amount`, c.cost.amount) }) : undefined;
      const actions = (c.actions ?? []).map((a, k) => (a.type === "give_item" ? { ...a, count: this.cfg(`${base}${node}.a${k}.count`, a.count ?? 1) } : a));
      return { slot, label: c.icon.name?.text ?? node, actions, cost, permission: c.permission, hide: c.hideWithoutPermission };
    };
    const out: Clickable[] = [];
    for (const { path, c, slot } of menuClickables(m)) {
      const node = slot !== undefined ? `b${slot}` : path.startsWith("choices") ? `c${/\[(\d+)\]$/.exec(path)![1]}` : `e${/\[(\d+)\]$/.exec(path)![1]}`;
      out.push(withCfg(node, c, slot ?? -1));
    }
    if (m.style === "chest" && m.list?.source.type === "config") {
      const cur = m.list.source.currency;
      for (const e of m.list.source.entries) {
        const cost: Cost | undefined = cur.type === "item" ? { type: "item", item: cur.item, count: Math.round(e.price) } : cur.type === "xp_levels" ? { type: "xp_levels", levels: Math.round(e.price) } : cur.type === "economy" ? { type: "economy", amount: e.price } : undefined;
        out.push({ slot: -1, label: e.name ?? e.material, actions: [{ type: "give_item", item: e.material, count: e.amount }], cost });
      }
    }
    return out;
  }
  private allowed(name: string, c: { permission?: string }) { return !c.permission || this.players.get(name)!.perms.has(`${this.opts.namespace}.${c.permission}`); }

  /** MenuManager.open: what each slot holds (null = refused). */
  openMenu(name: string, id: string, page = 0, push = true): Open | null {
    const p = this.players.get(name)!;
    if (!p.online || !p.alive) return null;
    const m = this.menus.get(id);
    if (!m) { this.ev(name, "no_menu", id); return null; }
    if (m.permission && !p.perms.has(`${this.opts.namespace}.${m.permission}`)) { this.ev(name, "no_permission_menu", id); return null; }
    const cur = this.open.get(name);
    if (push && cur && cur.menu !== id) { const st = this.back.get(name) ?? []; st.unshift(cur.menu); while (st.length > GAMEPLAY_LIMITS.maxBack) st.pop(); this.back.set(name, st); }
    const o: Open = { menu: id, page, slots: new Map() };
    const all = this.clickables(m);
    if (m.style === "dialogue") {
      const vis = all.filter((c) => !c.hide || this.allowed(name, c));
      const pos = [[], [22], [20, 24], [20, 22, 24], [19, 21, 23, 25], [18, 20, 22, 24, 26]][Math.min(5, vis.length)];
      pos.forEach((s, i) => o.slots.set(s, vis[i]));
    } else {
      for (const c of all.filter((x) => x.slot >= 0)) if (this.allowed(name, c) || !c.hide) o.slots.set(c.slot, c);
      if (m.list) {
        const vis = all.filter((x) => x.slot < 0).filter((c) => !c.hide || this.allowed(name, c));
        const size = m.list.slots.length;
        o.page = Pagination.clamp(page, vis.length, size);
        const first = Pagination.first(o.page, size), n = Pagination.count(o.page, vis.length, size);
        for (let i = 0; i < n; i++) o.slots.set(m.list.slots[i], vis[first + i]);
        if (Pagination.hasPrev(o.page, vis.length, size)) o.slots.set(m.list.prev.slot, { slot: m.list.prev.slot, label: "prev", actions: [{ type: "prev_page" }], nav: "prev" });
        if (Pagination.hasNext(o.page, vis.length, size)) o.slots.set(m.list.next.slot, { slot: m.list.next.slot, label: "next", actions: [{ type: "next_page" }], nav: "next" });
      }
    }
    this.open.set(name, o);
    this.ev(name, "open", `${id}#${o.page}`);
    if (m.style === "dialogue") this.addProgress(name, "talk", (ob) => (ob.type === "talk" && ob.menu === id ? 1 : 0));
    return o;
  }
  current(name: string) { return this.open.get(name) ?? null; }
  closeMenu(name: string) { this.open.delete(name); this.ev(name, "close"); }

  /** MenuManager.onClick: EVERY click is cancelled; only plain left/right on a menu slot acts. */
  click(name: string, slot: number, type: ClickType = "left"): ClickResult {
    const o = this.open.get(name);
    if (!o) return { cancelled: true, ran: false, reason: "no_menu" };
    const m = this.menus.get(o.menu)!;
    const size = m.style === "chest" ? m.rows * 9 : 27;
    if (type !== "left" && type !== "right") return { cancelled: true, ran: false, reason: "click_type" };
    if (slot < 0 || slot >= size) return { cancelled: true, ran: false, reason: "outside" };
    const c = o.slots.get(slot);
    if (!c) return { cancelled: true, ran: false, reason: "empty" };
    const last = this.lastClick.get(name) ?? -1000;
    if (this.tick - last < this.clickCooldown) return { cancelled: true, ran: false, reason: "rate_limited" };
    this.lastClick.set(name, this.tick);
    if (!this.allowed(name, c)) return { cancelled: true, ran: false, reason: "no_permission" };
    const gives = c.actions.filter((a): a is Extract<MenuAction, { type: "give_item" }> => a.type === "give_item").map((a) => ({ item: a.item, count: a.count ?? 1 }));
    if (!this.fits(name, gives)) return { cancelled: true, ran: false, reason: "no_space" };
    const why = this.refusal(name, c.cost);
    if (why) return { cancelled: true, ran: false, reason: why };
    if (!this.take(name, c.cost)) return { cancelled: true, ran: false, reason: "cannot_pay" };
    if (c.cost) this.ev(name, "paid", JSON.stringify(c.cost));
    for (const a of c.actions) this.menuAction(name, o, a);
    return { cancelled: true, ran: true, reason: "ok" };
  }
  /** A drag over menu slots: always cancelled, nothing happens. */
  drag(name: string): ClickResult { return { cancelled: true, ran: false, reason: this.open.has(name) ? "drag" : "no_menu" }; }

  private menuAction(name: string, o: Open, a: MenuAction) {
    switch (a.type) {
      case "give_item": this.give(name, a.item, a.count ?? 1); this.ev(name, "give", `${a.count ?? 1} x ${a.item}`); break;
      case "open_menu": this.openMenu(name, a.menu, 0, true); break;
      case "close": this.closeMenu(name); break;
      case "back": { const st = this.back.get(name) ?? []; const prev = st.shift(); if (prev) this.openMenu(name, prev, 0, false); else this.closeMenu(name); break; }
      case "next_page": this.openMenu(name, o.menu, o.page + 1, false); break;
      case "prev_page": this.openMenu(name, o.menu, o.page - 1, false); break;
      case "start_quest": this.startQuest(name, a.quest, false); break;
      case "abandon_quest": this.abandonQuest(name, a.quest); break;
      case "choose_branch": if (this.chooseBranch(name, a.quest, a.branch)) this.closeMenu(name); break;
      default: this.ev(name, a.type, "text" in a ? a.text : "sound" in a ? a.sound : "effect" in a ? a.effect : "item" in a ? `${a.item}` : undefined);
    }
  }

  // ---------------------------------------------------------------------------------------------- quests
  entries(name: string): Map<string, ProgressEntry> { let m = this.progress.get(name); if (!m) { m = new Map(); this.progress.set(name, m); } return m; }
  encoded(name: string) { return encodeProgress(this.entries(name)); }
  private target(q: QuestDesign, stepId: string, j: number, o: Objective): number {
    const base = `quests.${q.id}.steps.${stepId}.o${j}`;
    return o.type === "visit_location" || o.type === "talk" ? 1 : o.type === "survive" ? this.cfg(`${base}.seconds`, o.seconds) : this.cfg(`${base}.count`, o.count);
  }
  private cooldown(q: QuestDesign) { return (q.repeat?.mode ?? "once") === "once" ? 0 : this.cfg(`quests.${q.id}.repeat.cooldown_seconds`, repeatCooldown(q)); }
  active(name: string) { return [...this.entries(name).values()].filter((e) => e.state === "A" || e.state === "C").length; }

  startRefusal(name: string, id: string, viaCommand: boolean): string | null {
    const q = this.quests.get(id);
    const p = this.players.get(name)!;
    if (!q) return "no_quest";
    if (viaCommand && q.start === "menu") return "menu_only";
    if (q.permission && !p.perms.has(`${this.opts.namespace}.${q.permission}`)) return "no_permission";
    const m = this.entries(name);
    for (const r of q.requires ?? []) { const x = m.get(r); if (!x || x.completions === 0) return `needs:${r}`; }
    const e = m.get(id);
    if (e && (e.state === "A" || e.state === "C")) return "already_active";
    if (e && e.completions > 0) {
      if ((q.repeat?.mode ?? "once") === "once") return "already_completed";
      const left = e.last + this.cooldown(q) - this.clock;
      if (left > 0) return `cooldown:${left}`;
    }
    if (this.active(name) >= this.maxActive) return "too_many_active";
    return null;
  }
  startQuest(name: string, id: string, viaCommand: boolean): boolean {
    const why = this.startRefusal(name, id, viaCommand);
    if (why) { this.ev(name, "quest_refused", `${id}:${why}`); return false; }
    const q = this.quests.get(id)!;
    const m = this.entries(name);
    const old = m.get(id);
    const e: ProgressEntry = { quest: id, state: "A", step: q.steps[0].id, branch: "", counts: [0, 0, 0], started: this.clock, completions: old?.completions ?? 0, last: old?.last ?? 0 };
    m.set(id, e);
    if (encodeProgress(m).length > GAMEPLAY_LIMITS.maxProgressChars) { if (old) m.set(id, old); else m.delete(id); this.ev(name, "quest_log_full", id); return false; }
    this.ev(name, "quest_started", id);
    this.evaluate(name, q, e);
    return true;
  }
  abandonQuest(name: string, id: string): boolean {
    const q = this.quests.get(id);
    const e = this.entries(name).get(id);
    if (!q || !e || (e.state !== "A" && e.state !== "C")) { this.ev(name, "not_active", id); return false; }
    if (q.failure?.abandon === false) { this.ev(name, "cannot_abandon", id); return false; }
    this.drop(name, e);
    this.ev(name, "quest_abandoned", id);
    return true;
  }
  private drop(name: string, e: ProgressEntry) { if (e.completions > 0) { e.state = "D"; e.step = ""; e.branch = ""; e.counts = [0, 0, 0]; } else this.entries(name).delete(e.quest); }
  chooseBranch(name: string, id: string, branch: string): boolean {
    const q = this.quests.get(id);
    const e = this.entries(name).get(id);
    const b = q?.branches?.options.find((x) => x.id === branch);
    if (!q || !e || e.state !== "C" || !b) { this.ev(name, "nothing_to_choose", `${id}:${branch}`); return false; }
    e.state = "A"; e.branch = branch; e.step = b.steps[0].id; e.counts = [0, 0, 0];
    this.ev(name, "branch_chosen", `${id}:${branch}`);
    this.evaluate(name, q, e);
    return true;
  }

  /** Quests.add: every matching objective of every active quest's current step. */
  addProgress(name: string, kind: Objective["type"], match: (o: Objective) => number) {
    for (const e of [...this.entries(name).values()]) {
      if (e.state !== "A") continue;
      const q = this.quests.get(e.quest)!;
      const s = stepOf(q, e.branch, e.step);
      if (!s) continue;
      let changed = false;
      s.objectives.forEach((o, j) => {
        const t = this.target(q, s.id, j, o);
        if (o.type !== kind || e.counts[j] >= t) return;
        const inc = match(o);
        if (inc <= 0) return;
        e.counts[j] = Math.min(t, e.counts[j] + inc);
        changed = true;
      });
      if (changed) { this.ev(name, "progress", `${e.quest}:${e.step}:${e.counts.join(".")}`); this.evaluate(name, q, e); }
    }
  }
  kill(name: string, entity: string, kinds: string[] = []) { this.addProgress(name, "kill_entity", (o) => (o.type === "kill_entity" && ((o.entity && o.entity === entity) || (o.kinds ?? []).some((k) => k === "living" || kinds.includes(k))) ? 1 : 0)); }
  pickup(name: string, item: string, count: number) { this.give(name, item, count); this.addProgress(name, "collect_item", (o) => (o.type === "collect_item" && o.mode === "pickup" && o.item === item ? count : 0)); this.recheck(name); }
  craft(name: string, item: string, count: number) { this.give(name, item, count); this.addProgress(name, "craft_item", (o) => (o.type === "craft_item" && o.item === item ? count : 0)); }
  place(block: string, at: string) { this.placed.add(`${block}@${at}`); }
  breakBlock(name: string, block: string, at = `${Math.random()}`) { if (this.placed.delete(`${block}@${at}`)) { this.ev(name, "placed_block_ignored", block); return; } this.addProgress(name, "break_block", (o) => (o.type === "break_block" && o.block === block ? 1 : 0)); }
  moveTo(name: string, world: string, pos: [number, number, number]) { const p = this.players.get(name)!; p.world = world; p.pos = pos; }
  die(name: string) {
    const p = this.players.get(name)!;
    this.open.delete(name);
    for (const e of [...this.entries(name).values()]) {
      if (e.state !== "A") continue;
      const q = this.quests.get(e.quest)!;
      const rule = q.failure?.onDeath ?? "keep";
      if (rule === "fail") { this.drop(name, e); this.ev(name, "quest_failed", `${q.id}:died`); continue; }
      const s = stepOf(q, e.branch, e.step);
      if (!s) continue;
      s.objectives.forEach((o, j) => { if (rule === "reset_step" || o.type === "survive") e.counts[j] = 0; });
    }
    p.alive = true;
  }
  recheck(name: string) { for (const e of [...this.entries(name).values()]) if (e.state === "A") this.evaluate(name, this.quests.get(e.quest)!, e); }

  private near(name: string, q: QuestDesign, stepId: string, j: number, o: Extract<Objective, { type: "visit_location" }>) {
    const p = this.players.get(name)!;
    const b = `quests.${q.id}.steps.${stepId}.o${j}`;
    const [x, y, z, r] = [this.cfg(`${b}.x`, o.x), this.cfg(`${b}.y`, o.y), this.cfg(`${b}.z`, o.z), this.cfg(`${b}.radius`, o.radius)];
    if (p.world !== this.cfg(`${b}.world`, o.world)) return false;
    return (p.pos[0] - x) ** 2 + (p.pos[1] - y) ** 2 + (p.pos[2] - z) ** 2 <= r * r;
  }
  /** Quests.evaluate. */
  private evaluate(name: string, q: QuestDesign, e: ProgressEntry) {
    for (let guard = 0; guard < 16 && e.state === "A"; guard++) {
      const s = stepOf(q, e.branch, e.step);
      if (!s) return;
      let done = true;
      s.objectives.forEach((o, j) => {
        const t = this.target(q, s.id, j, o);
        if (o.type === "collect_item" && o.mode === "inventory") e.counts[j] = Math.min(t, this.count(name, o.item));
        if (o.type === "visit_location" && e.counts[j] < 1 && this.near(name, q, s.id, j, o)) e.counts[j] = 1;
        if (e.counts[j] < t) done = false;
      });
      if (!done) return;
      const takes = s.objectives.map((o, j) => ({ o, t: this.target(q, s.id, j, o) })).filter((x) => x.o.type === "collect_item" && x.o.take);
      if (takes.some((x) => this.count(name, (x.o as { item: string }).item) < x.t)) return;
      for (const x of takes) { this.takeItems(name, (x.o as { item: string }).item, x.t); this.ev(name, "handed_in", `${x.t} x ${(x.o as { item: string }).item}`); }
      const path = pathOf(q, e.branch);
      const i = path.findIndex((x) => x.id === e.step);
      if (i >= 0 && i < path.length - 1) { e.step = path[i + 1].id; e.counts = [0, 0, 0]; this.ev(name, "step", `${q.id}:${e.step}`); continue; }
      if (q.branches && !e.branch) { e.state = "C"; e.step = ""; e.counts = [0, 0, 0]; this.ev(name, "choose", q.id); return; }
      this.complete(name, q, e);
      return;
    }
  }
  private complete(name: string, q: QuestDesign, e: ProgressEntry) {
    const branch = e.branch;
    e.state = "D"; e.step = ""; e.branch = ""; e.counts = [0, 0, 0];
    e.completions = Math.min(MAX_COUNT, e.completions + 1);
    e.last = this.clock;
    // stored FIRST (the Java saves here), then the rewards
    this.ev(name, "quest_complete", `${q.id}:${encodeProgress(this.entries(name))}`);
    this.rewards(name, q.rewards, `quests.${q.id}.rewards`);
    const b = q.branches?.options.find((x) => x.id === branch);
    if (b) this.rewards(name, b.rewards, `quests.${q.id}.branches.${b.id}.rewards`);
  }
  private rewards(name: string, list: Reward[] | undefined, base: string) {
    const p = this.players.get(name)!;
    (list ?? []).forEach((r, i) => {
      const at = `${base}.r${i}`;
      if (r.type === "give_item") { const n = this.cfg(`${at}.count`, r.count ?? 1); this.give(name, r.item, n); this.ev(name, "reward", `${n} x ${r.item}`); }
      else if (r.type === "xp") { if (r.levels !== undefined) p.levels += this.cfg(`${at}.levels`, r.levels); this.ev(name, "reward", r.points !== undefined ? `${this.cfg(`${at}.points`, r.points)} xp` : `${this.cfg(`${at}.levels`, r.levels!)} levels`); }
      else this.ev(name, "reward", r.type);
    });
  }
  /** ObjectiveTracker timer (once a second): time limits, survive, visit / inventory checks. */
  private questTick(name: string) {
    const p = this.players.get(name)!;
    if (!p.alive) return;
    for (const e of [...this.entries(name).values()]) {
      if (e.state !== "A") continue;
      const q = this.quests.get(e.quest)!;
      const limit = q.failure?.timeLimitSeconds !== undefined ? this.cfg(`quests.${q.id}.failure.time_limit_seconds`, q.failure.timeLimitSeconds) : 0;
      if (limit > 0 && this.clock - e.started > limit) { this.drop(name, e); this.ev(name, "quest_failed", `${q.id}:time`); continue; }
      const s = stepOf(q, e.branch, e.step);
      if (!s) continue;
      s.objectives.forEach((o, j) => { if (o.type === "survive" && e.counts[j] < this.target(q, s.id, j, o)) e.counts[j]++; });
      this.evaluate(name, q, e);
    }
  }
  /** Simulate a relog: the progress goes through the codec (what the PDC stores) against possibly NEW definitions. */
  relog(name: string, newDefs?: QuestDesign[]): string[] {
    const notes: string[] = [];
    const raw = this.encoded(name);
    const defs = newDefs ? new Map(newDefs.map((q) => [q.id, q])) : this.quests;
    if (newDefs) { this.quests.clear(); for (const q of [...newDefs].sort((a, b) => (a.id < b.id ? -1 : 1))) this.quests.set(q.id, q); }
    this.progress.set(name, decodeProgress(raw, defs, notes));
    return notes;
  }
}

