    L.jar = { sha256: b.jarSha256, bytes: b.jarBytes, reproducible: b.reproducible };
    L.scan = scan(b, lane);
    console.log(`${lane.version}: javac ok (${b.sources} sources, ${b.javacWarnings} warnings), jar reproducible=${b.reproducible}, scan blocks=${(L.scan as { blocks: number }).blocks} warnings=${(L.scan as { warnings: number }).warnings}`);
    if (b.javacWarnings) console.log(b.javacOut);
