    L.flight = { status: f.report.status, overall: f.summary.overall, success: f.summary.success, line: describeSummary(f.summary), bootMs: f.report.bootMs, peakRssMb: f.report.peakRssKb ? Math.round(f.report.peakRssKb / 1024) : null, paper: f.report.engine?.paper ?? null, jdkVersion: f.report.engine?.jdk.version ?? null, checks: f.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 20) })), disk: harvest(f.report.runId ?? null) };
    console.log(`flight ${lane.version}: ${describeSummary(f.summary)}`);
    for (const x of f.report.checks) if (x.status !== "pass") console.log(`  ${x.id}: ${x.status}\n    ${x.evidence.slice(0, 20).join("\n    ")}`);

    // parameter edit: price, kill count, daily cooldown -> only config.yml changes; the edited jar migrates an existing config
    const edits = [{ path: "menus.shop.b47.cost.count", value: 7 }, { path: "quests.trial_one.steps.s1.o0.count", value: 8 }, { path: "quests.daily_bread.repeat.cooldown_seconds", value: 43200 }];
    const e = recompileModWithEdits(c, edits, { version: lane.version, namespace: NS, pluginName: PLUGIN });
    if (!e.ok) { L.edit = { ok: false, errors: e.errors }; continue; }
