    const entryHashes = (z: ReturnType<typeof indexZip>) => (z.ok ? Object.fromEntries(z.zip.entries.map((x) => { const r = readEntry(z.zip, x); return [x.name, r.ok ? sha(r.data) : "?"]; })) : {});
