      + `  - material: "minecraft:command_block"\n    amount: 1\n    price: 1\n  - material: "minecraft:emerald_block"\n    amount: 1\n    price: 99999\n  - material: "minecraft:emerald"\n    amount: 1\n    price: 1\n`;
    const oldCfg = cfg.replace("config_version: 1", "config_version: 0").replace(/(\n    b47:\n(?:.*\n)*?        count: )5\n/, "$19\n");
