// Cyrus R3 gameplay designers, part 2: EDIT WITHOUT REGENERATING for menus and quests. Every number and text of a menu
// or quest is a config.yml parameter (./compile.ts menuParams / questParams), so a value edit (a price, a kill count, a
// cooldown, a title, a coordinate) changes the design, and the recompile changes config.yml (values + designer-values
// hash + config_version) and the README, never a Java file. Item parameters go through the item edit path (../params.ts).
// Pure: no I/O, no model call.
import { applyParameterEdits, diffCompiled, type AppliedEdit, type CompiledDiff, type ParamEdit } from "../params";
import type { CompileContext } from "../compile";
import type { ItemDesign } from "../spec";
import { compileMod, modParams, type ModCompileOk } from "./compile";
import { MenuDesignSchema, QuestDesignSchema, type MenuDesign, type QuestDesign } from "./spec";

export type GameplayMod = { items: ItemDesign[]; menus: MenuDesign[]; quests: QuestDesign[] };
export type GameplayEditResult = { ok: true; mod: GameplayMod; applied: AppliedEdit[] } | { ok: false; errors: string[] };

const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());
type Obj = Record<string, unknown>;

function iconSet(icon: Obj | undefined, field: string, value: number | string): string | null {
  if (!icon) return "no icon";
  if (field === "name") { (icon.name as Obj).text = value; return null; }
  if (field === "amount") { icon.amount = value; return null; }
