const NONE: AssetRequestResult = { plan: null, service: null, meta: null };

export async function resolveBuildAssets(input: AssetRequestInput, deps: AssetRequestDeps): Promise<AssetRequestResult> {
  const requested = requestedAssetKinds({ explicit: input.explicit, text: input.text, existing: input.existing });
  // Cyrus R2: the data pack route (capability router rules, not plan-gated). Off -> decides nothing (byte-identical).
  const dpOn = (deps.dataPackStudioOn ?? (() => dataPackStudioOn()))();
  const dp = decideDataPackRoute({ text: input.text, explicit: input.explicit, existing: input.existingDatapack, existingWorldgen: input.existingWorldgen, mcVersion: input.mcVersion, on: dpOn, worldgen: dpOn && (deps.worldgenOn ?? (() => worldgenOn()))() });
  const dpMeta = dp.route || dp.notices.length ? { datapack: { route: dp.route, matched: dp.matched, limits: dp.limits, ...(dp.worldgen ? { worldgen: true as const } : {}) } } : {};
  // Cyrus R3: the gameplay designer route (item with abilities; not plan-gated). Off -> decides nothing (byte-identical).
  const dz = decideDesignerRoute({ text: input.text, explicit: input.explicit, existing: input.existingDesign, mcVersion: input.mcVersion, on: (deps.designerOn ?? (() => designerOn()))() });
  const dzMeta = dz.route || dz.notices.length ? { designer: { route: dz.route, matched: dz.matched, limits: dz.limits } } : {};
  if (!requested.length && !dp.route && !dp.notices.length && !dz.route && !dz.notices.length) return NONE;
  let plan: BuildAssetPlan | null = null;
  let meta: CyrusAssetMeta;
  if (requested.length) {
    let tier: unknown = null;
    try { tier = await deps.tierOf(input.userId); } catch { tier = null; } // unknown token state: fail closed
    plan = planBuildAssets({ plan: tier, requested, mcVersion: input.mcVersion, change: input.change, existing: input.existing, creaturesOn: (deps.creaturesEnabled ?? (() => process.env.CYRUS_CREATURES === "1"))() });
    meta = { requested, allowed: BUILD_ASSET_KINDS.filter((k) => plan!.allowed[k]), notices: [...plan.notices, ...dp.notices, ...dz.notices], ...dpMeta, ...dzMeta };
  } else meta = { requested: [], allowed: [], notices: [...dp.notices, ...dz.notices], ...dpMeta, ...dzMeta };
  if ((!plan || !anyAllowed(plan.allowed)) && !dp.route && !dz.route) return { plan, service: null, meta };
  let project: ProjectRef | null = null;
  try {
    project = (await deps.projectForRootBuild(input.rootBuildId)) ?? (await deps.createProject({ userId: input.userId, game: "minecraft", rootBuildId: input.rootBuildId, title: input.title ?? null }));
  } catch {
    // A racing create (root_taken) means it exists now; anything else: no namespace, so no assets (fail closed).
    project = await deps.projectForRootBuild(input.rootBuildId).catch(() => null);
  }
  if (!project) {
    const msg = dz.route && !(plan && anyAllowed(plan.allowed)) && !dp.route
      ? "Cyrus couldn't set up this mod's project right now, so it writes the plugin as plain code instead of an item design. Try again later."
      : dp.route && !(plan && anyAllowed(plan.allowed))
      ? "Cyrus couldn't set up this mod's project right now, so it builds the plugin without the data pack. Try again later."
      : "Cyrus couldn't set up this mod's asset project right now, so it builds the plugin without custom assets. Try again later.";
    return { plan: plan ? { ...plan, allowed: { texture: false, sound: false, creature: false } } : null, service: null, meta: { ...meta, allowed: [], notices: [...meta.notices, msg], ...(dp.route ? { datapack: { route: false, matched: dp.matched, limits: dp.limits } } : {}), ...(dz.route ? { designer: { route: false, matched: dz.matched, limits: dz.limits } } : {}) } };
  }
  const texture = !!plan?.allowed.texture, sound = !!plan?.allowed.sound;
  return {
    plan,
    // `library` only rides along with sound and `datapack` only when routed, so texture-only requests stay byte-identical
    service: { texture, sound, namespace: project.namespace, ...(sound ? { library: (deps.soundLibraryCleared ?? (() => process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1"))() } : {}), ...(plan?.allowed.creature ? { creature: true as const } : {}), ...(dp.route ? { datapack: true as const } : {}), ...(dz.route ? { design: true as const } : {}), ...(dp.route && dp.worldgen ? { worldgen: true as const } : {}) },
    meta: { ...meta, projectId: project.id, namespace: project.namespace },
  };
}

