- conditions (all must pass; "negate"?: true on any): cooldown_ready {"ability"?}, has_permission {"node"} (declare it in permissions; full node <namespace>.<node>), target_is {"kinds"?:["player","hostile","animal","living"],"types"?:["minecraft:zombie",...]}, world_in {"worlds":[names]}, health_below / health_above {"subject":"self|target","fraction":0-1}, item_identity {"slot":"main_hand|off_han
