    assert.equal(decideDesignerRoute({ ...base, text: "broadcast a message every hour" }).route, false);
    assert.equal(decideDesignerRoute({ ...base, text: "a sword with a cooldown" }).gameplay, undefined, "item builds are unchanged");
    assert.deepEqual(decideDesignerRoute({ ...base, text: "make it cheaper", existingGameplay: true }).gameplay, { menus: true, quests: true });
    assert.ok(hasGameplayDesigns({ assets: { designs: [{ kind: "quest" }] } }) && !hasGameplayDesigns({ assets: { designs: [{}] } }));
  });
  it("resolveBuildAssets: a menu/quest request gets design + gameplay; not plan-gated; byte-identical when off", async () => {
    let tierCalls = 0;
    const deps = { tierOf: async () => { tierCalls++; return "free"; }, projectForRootBuild: async () => ({ id: "cp1", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }) };
    const text = "a guild shop GUI with pages and a daily quest";
    assert.deepEqual(await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => false }), { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: NS, design: true, gameplay: true });
    assert.deepEqual(on.meta!.designer!.gameplay, { menus: true, quests: true });
    assert.equal(tierCalls, 0);
    const TX = require(path.join(ROOT, "services/modbuilder/textures.js"));
    const ok = () => true;
    assert.equal(TX.parseAssetsRequest({ namespace: NS, design: true, gameplay: true }, "1.21.11", new Set(), ok, ok).gameplay, true);
    assert.match(TX.parseAssetsRequest({ namespace: NS, gameplay: true }, "1.21.11", new Set(), ok, ok).error, /needs assets\.design/);
    assert.match(TX.parseAssetsRequest({ namespace: NS, design: true, gameplay: "yes" }, "1.21.11", new Set(), ok, ok).error, /true or false/);
  });
  it("service workspace: kind-aware checks, per-kind caps, drops, compile with the Vault dep", () => {
    const DZS = require(path.join(ROOT, "services/modbuilder/designs.js"));
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-gp-ws-"));
    fs.mkdirSync(path.join(ws, "assets/designs"), { recursive: true });
    for (const d of ALL()) fs.writeFileSync(path.join(ws, `assets/designs/${d.id}.json`), JSON.stringify(d));
    fs.writeFileSync(path.join(ws, "assets/designs/loop_quest.json"), JSON.stringify(quest("loop_quest", { requires: ["loop_quest"] })));
    const r = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    assert.deepEqual(r.results.filter((x: { ok: boolean }) => !x.ok).map((x: { name: string }) => x.name), ["loop_quest"]);
    assert.deepEqual(r.results.filter((x: { ok: boolean }) => x.ok).map((x: { kind: string }) => x.kind).sort(), ["item", "item", "menu", "menu", "quest", "quest", "quest", "quest"]);
    fs.rmSync(path.join(ws, "assets/designs/loop_quest.json"));
    const ok = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    const c = DZS.compileWorkspaceDesigns(ws, { pluginName: GP_PLUGIN, mcVersion: "1.21.11", assets: { namespace: NS } }, ok.results.map((x: { spec: unknown }) => x.spec));
    assert.ok(c.ok); assert.deepEqual(c.summary.deps, ["vault-api"]); assert.deepEqual(c.summary.counts, { items: 2, menus: 2, quests: 4 });
    assert.equal(c.summary.hash, compileOk(ALL()).hash, "service == TypeScript");
  });
  it("portal sync: re-validates every kind, re-compiles (serviceAgreed), drops a tampered quest, mime per kind", () => {
    const svc = compileOk(ALL());
    const list = ALL().map((d: { id: string }) => ({ name: d.id, path: `assets/designs/${d.id}.json`, sha256: "x", spec: d }));
    const r = checkReturnedDesigns(list, { namespace: NS, mcVersion: "1.21.11", pluginName: GP_PLUGIN, compile: { hash: svc.hash, configVersion: 1 } });
    assert.equal(r.serviceAgreed, true);
    assert.deepEqual(r.ok.map((x) => x.kind).sort(), ["item", "item", "menu", "menu", "quest", "quest", "quest", "quest"]);
    const bad = clone(byId("daily_bread")); bad.rewards[0].count = 9999;
    const t = checkReturnedDesigns(list.map((x) => (x.name === "daily_bread" ? { ...x, spec: bad } : x)), { namespace: NS, mcVersion: "1.21.11", pluginName: GP_PLUGIN, compile: { hash: svc.hash } });
    assert.deepEqual(t.dropped.map((d) => d.name), ["daily_bread"]); assert.equal(t.serviceAgreed, false);
    assert.match(t.notices[0], /^Quest design "daily_bread" was left out/);
    assert.deepEqual(DESIGN_KIND_MIME, { item: "application/vnd.nxeon.item-design+json", menu: "application/vnd.nxeon.menu-design+json", quest: "application/vnd.nxeon.quest-design+json" });
  });
  it("mod page lines: 'Includes N menus and M quests'", () => {
    const row = { version: "1.21.11", specSha256: "x", compileHash: "y", serviceAgreed: true, configVersion: 1, settings: 3, abilities: 0 };
    const a = { status: "none" as const, namespace: NS, projectId: "p", revisionId: "r", textures: [], dropped: [{ name: "q", reason: "x", kind: "design" as const }], pack: null, loader: null, notices: [],
      designs: [{ ...row, name: "shop", kind: "menu" as const }, { ...row, name: "elder", kind: "menu" as const }, { ...row, name: "daily", kind: "quest" as const }, { ...row, name: "badge", abilities: 1 }] };
    const lines = assetLines(a);
    assert.ok(lines.some((l) => /^Includes 2 menus and 1 quest;/.test(l)), JSON.stringify(lines));
    assert.ok(lines.includes("1 requested design was left out after failing Nxeon's design checks."));
    assert.ok(!lines.some((l) => /texture/.test(l)), "a dropped design is not a texture");
  });
});

toolu_01CUyRfdh3wPs1WWHaaW9L7r.content:
// Cyrus R3 gameplay designers, part 2 (pure): the MENU and QUEST designers. The IR (kind discriminator on the existing
// design files, ItemDesign unchanged byte for byte), every cap, the adversarial corpus (dupe / arbitrage loops, reward
// farms, circular prerequisites, unreachable menus / quests / dialogues, oversize progress, over-budget menus), the
// component library (present, documented, version-independent, strict-scan + precheck clean), the compiler (golden
// hashes per version, order independence, config.yml / plugin.yml), edit-without-regenerating, the TS simulator (click
// hardening and the dupe-proof order, pagination, costs, quest rules, the progress codec), TS == generated service JS,
// the prompt part, routing, the build request, the service workspace checks and the portal sync + mod page lines.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { GAMEPLAY_CAPS, GAMEPLAY_LIMITS, designKind, gameplayJsonSchema, progressEntryChars, validateGameplay, type GpCapName, type MenuDesign, type QuestDesign } from "../lib/cyrus/designer/gameplay/spec";
import { GENERAL_DEFAULTS, compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { GAMEPLAY_COMPONENTS, VAULT_COMPONENT, gameplayLibraryHash } from "../lib/cyrus/designer/gameplay/components";
import { applyGameplayEdits, recompileModWithEdits } from "../lib/cyrus/designer/gameplay/params";
import { GameplaySimulator, Pagination, decodeProgress, encodeProgress, progressSample } from "../lib/cyrus/designer/gameplay/simulate";
import { compileDesigns } from "../lib/cyrus/designer/compile";
import { COMPONENTS } from "../lib/cyrus/designer/components";
import { designFeatures, validateDesign, type ItemDesign } from "../lib/cyrus/designer/spec";
import { decideDesignerRoute, hasGameplayDesigns, matchGameplayWords } from "../lib/cyrus/designer/route";
import { checkReturnedDesigns, DESIGN_KIND_MIME } from "../lib/cyrus/designer/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { assetLines } from "../lib/cyrus-mods/doc";
import { VERSIONS } from "../lib/cyrus/versions/registry";
import { GP_NS as NS, GP_PLUGIN, loadGameplayFixtures } from "../scripts/cyrus/gameplay-golden";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-gameplay");
const ALL = () => loadGameplayFixtures();
const byId = (id: string) => ALL().find((d: { id: string }) => d.id === id);
const clone = <T,>(x: T): T => structuredClone(x);
const SUPPORTED = VERSIONS.map((v) => v.id).filter((v) => designFeatures(v).ok);
const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: GP_PLUGIN });
const compileOk = (d: unknown[], c = ctx()): ModCompileOk => { const r = compileMod(d, c); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const codes = (inputs: unknown[], extra: Record<string, unknown> = {}) => validateGameplay(inputs, { version: "1.21.11", namespace: NS, ...extra }).errors.map((e) => e.code);
const items = () => ALL().filter((d: { kind?: string }) => !d.kind || d.kind === "item") as ItemDesign[];
const menus = () => ALL().filter((d: { kind?: string }) => d.kind === "menu") as MenuDesign[];
const quests = () => ALL().filter((d: { kind?: string }) => d.kind === "quest") as QuestDesign[];

const btn = (slot: number, extra: Record<string, unknown> = {}) => ({ slot, icon: { material: "minecraft:emerald", name: { text: `b${slot}` } }, ...extra });
const chest = (id: string, extra: Record<string, unknown> = {}) => ({ schemaVersion: 1, kind: "menu", style: "chest", id, title: id, rows: 3, buttons: [btn(0)], ...extra });
const quest = (id: string, extra: Record<string, unknown> = {}) => ({ schemaVersion: 1, kind: "quest", id, title: id, steps: [{ id: "s1", text: "Kill", objectives: [{ type: "kill_entity", entity: "minecraft:zombie", count: 1 }] }], ...extra });

describe("gameplay IR: the showcase mod", () => {
  it("is valid on every supported version; 26.3 fails closed; the kind discriminator", () => {
    for (const v of SUPPORTED) { const r = validateGameplay(ALL(), { version: v, namespace: NS }); assert.ok(r.ok, `${v}: ${JSON.stringify(r.errors)}`); assert.deepEqual([r.items.length, r.menus.length, r.quests.length], [2, 2, 4]); }
    assert.equal(validateGameplay(ALL(), { version: "26.3", namespace: NS }).ok, false);
    assert.equal(designKind({ id: "x" }), "item"); assert.equal(designKind({ kind: "item" }), "item"); assert.equal(designKind({ kind: "menu" }), "menu"); assert.equal(designKind({ kind: "quest" }), "quest");
    assert.equal(designKind({ kind: "script" }), null); assert.equal(designKind([]), null);
    assert.ok(codes([{ ...chest("m"), kind: "script" }]).includes("unknown_kind"));
  });
  it("ItemDesign stays valid byte for byte: item-only mods compile exactly as before (R3 golden hashes)", () => {
    const fx = ["void_reaper", "storm_staff", "vigor_tonic"].map((n) => JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-designer", `${n}.json`), "utf8")));
    const golden = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-designer/golden.json"), "utf8"));
    for (const v of SUPPORTED) {
      const a = compileMod(fx, { version: v, namespace: "nx_r7design", pluginName: "VoidArsenal" });
      assert.ok(a.ok && !a.gameplay && a.hash === golden[v].hash, v);
    }
    // an explicit kind "item" is accepted (only the spec hash differs, not the compiled plugin)
    const k = compileDesigns(fx.map((d) => ({ ...d, kind: "item" })), { version: "1.21.11", namespace: "nx_r7design", pluginName: "VoidArsenal" });
    assert.ok(k.ok && k.hash === golden["1.21.11"].hash);
    assert.ok(validateDesign({ ...fx[0], kind: "menu" }, { version: "1.21.11", namespace: "nx_r7design" }).ok === false, "an item file cannot claim another kind");
  });
  it("the JSON Schema file is current and carries the caps", () => {
    const file = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/gameplay.v1.schema.json"), "utf8"));
    assert.deepEqual(file, gameplayJsonSchema());
    assert.match(JSON.stringify(file), /"maximum":2304/); assert.match(JSON.stringify(file), /"maximum":2592000/);
  });
});

describe("gameplay IR: every cap (min/max accepted, just outside refused)", () => {
  const dlg = { schemaVersion: 1, kind: "menu", style: "dialogue", id: "talker", title: "T", speaker: { text: "S" }, lines: ["Hi"], choices: [{ icon: { material: "minecraft:paper" } }] };
  const m = (b: Record<string, unknown>, extra: Record<string, unknown> = {}) => [chest("m", { buttons: [btn(0, b)], ...extra })];
  const q = (extra: Record<string, unknown>) => [quest("q", extra)];
  const obj = (o: Record<string, unknown>) => q({ steps: [{ id: "s1", text: "x", objectives: [o] }] });
  const T: [GpCapName, (v: number) => unknown[], boolean][] = [
    ["rows", (v) => [chest("m", { rows: v })], true],
    ["slot", (v) => [chest("m", { rows: 6, buttons: [btn(v)] })], true],
    ["iconAmount", (v) => m({ icon: { material: "minecraft:paper", amount: v } }), true],
    ["itemCost", (v) => m({ cost: { type: "item", item: "minecraft:emerald", count: v }, actions: [{ type: "give_item", item: "minecraft:bread" }] }), true],
    ["xpLevelCost", (v) => m({ cost: { type: "xp_levels", levels: v }, actions: [{ type: "give_item", item: "minecraft:bread" }] }), true],
    ["economyCost", (v) => m({ cost: { type: "economy", amount: v }, actions: [{ type: "give_item", item: "minecraft:bread" }] }), false],
    ["giveCount", (v) => m({ actions: [{ type: "give_item", item: "minecraft:bread", count: v }] }), true],
    ["heal", (v) => m({ actions: [{ type: "heal", amount: v }] }), false],
    ["potionTicks", (v) => m({ actions: [{ type: "potion_effect", effect: "speed", durationTicks: v }] }), true],
    ["amplifier", (v) => m({ actions: [{ type: "potion_effect", effect: "speed", durationTicks: 20, amplifier: v }] }), true],
    ["volume", (v) => m({ actions: [{ type: "play_sound", sound: "minecraft:ui.button.click", volume: v }] }), false],
    ["pitch", (v) => m({ actions: [{ type: "play_sound", sound: "minecraft:ui.button.click", pitch: v }] }), false],
    ["killCount", (v) => obj({ type: "kill_entity", entity: "minecraft:zombie", count: v }), true],
    ["collectCount", (v) => obj({ type: "collect_item", item: "minecraft:bone", count: v, mode: "inventory" }), true],
    ["craftCount", (v) => obj({ type: "craft_item", item: "minecraft:bread", count: v }), true],
    ["breakCount", (v) => obj({ type: "break_block", block: "minecraft:stone", count: v }), true],
    ["surviveSeconds", (v) => obj({ type: "survive", seconds: v }), true],
    ["visitRadius", (v) => obj({ type: "visit_location", world: "world", x: 0, y: 64, z: 0, radius: v }), false],
    ["coord", (v) => obj({ type: "visit_location", world: "world", x: v, y: 64, z: 0, radius: 3 }), false],
    ["coordY", (v) => obj({ type: "visit_location", world: "world", x: 0, y: v, z: 0, radius: 3 }), false],
    ["repeatCooldownSeconds", (v) => q({ repeat: { mode: "repeatable", cooldownSeconds: v } }), true],
    ["timeLimitSeconds", (v) => q({ failure: { timeLimitSeconds: v } }), true],
    ["xpPoints", (v) => q({ rewards: [{ type: "xp", points: v }] }), true],
    ["xpLevels", (v) => q({ rewards: [{ type: "xp", levels: v }] }), true],
    ["configAmount", (v) => [chest("m", { buttons: [], list: { slots: [0, 1], prev: { slot: 18, icon: { material: "minecraft:arrow" } }, next: { slot: 26, icon: { material: "minecraft:arrow" } }, source: { type: "config", currency: { type: "item", item: "minecraft:emerald" }, entries: [{ material: "minecraft:bread", amount: v, price: 1 }] } } })], true],
  ];
  it(`covers every IR cap (${Object.keys(GAMEPLAY_CAPS).length - 1} + the runtime click cooldown)`, () => {
    assert.deepEqual([...T.map((t) => t[0]), "clickCooldownTicks"].sort(), Object.keys(GAMEPLAY_CAPS).sort());
    const [lo, hi] = GAMEPLAY_CAPS.clickCooldownTicks;
    assert.ok(GENERAL_DEFAULTS.menuClickCooldownTicks >= lo && GENERAL_DEFAULTS.menuClickCooldownTicks <= hi);
    assert.ok(GENERAL_DEFAULTS.maxActiveQuests >= GAMEPLAY_LIMITS.activeQuests[0] && GENERAL_DEFAULTS.maxActiveQuests <= GAMEPLAY_LIMITS.activeQuests[1]);
  });
  for (const [cap, mk, int] of T) {
    it(cap, () => {
      const [lo, hi] = GAMEPLAY_CAPS[cap];
      const d = int ? 1 : 0.01;
      const v = (x: number) => validateGameplay([...mk(x), dlg], { version: "1.21.11", namespace: NS });
      assert.ok(v(lo).ok, `${cap} min ${lo}: ${JSON.stringify(v(lo).errors)}`);
      assert.ok(v(hi).ok, `${cap} max ${hi}: ${JSON.stringify(v(hi).errors)}`);
      assert.equal(v(lo - d).ok, false, `${cap} below min accepted`);
      assert.equal(v(hi + d).ok, false, `${cap} above max accepted`);
    });
  }
});

describe("gameplay IR: adversarial corpus", () => {
  const emerald = (n: number) => ({ type: "item", item: "minecraft:emerald", count: n });
  it("refuses code and commands in any form (closed action/objective/reward sets, unknown keys)", () => {
    for (const bad of [
      [chest("m", { buttons: [btn(0, { actions: [{ type: "run_command", command: "op @a" }] })] })],
      [chest("m", { java: "Runtime.getRuntime()" })],
      [quest("q", { rewards: [{ type: "command", command: "give @a diamond 64" }] })],
      [quest("q", { steps: [{ id: "s1", text: "x", objectives: [{ type: "script", code: "x" }] }] })],
      [chest("m", { list: { slots: [1], prev: { slot: 9, icon: { material: "minecraft:arrow" } }, next: { slot: 10, icon: { material: "minecraft:arrow" } }, source: { type: "sql", query: "select" } } })],
    ]) assert.ok(codes(bad).includes("schema"), JSON.stringify(bad).slice(0, 80));
  });
  it("dupe attempts at the IR level: a click that gives more of its own cost, an arbitrage loop across menus, a config list selling its currency", () => {
    assert.ok(codes([chest("m", { buttons: [btn(0, { cost: emerald(1), actions: [{ type: "give_item", item: "minecraft:emerald", count: 2 }] })] })]).includes("cost_loop"));
    const loop = [
      chest("a", { buttons: [btn(0, { cost: emerald(1), actions: [{ type: "give_item", item: "minecraft:diamond", count: 2 }] })] }),
      chest("b", { buttons: [btn(0, { cost: { type: "item", item: "minecraft:diamond", count: 1 }, actions: [{ type: "give_item", item: "minecraft:emerald", count: 1 }] })] }),
    ];
    const v = validateGameplay(loop, { version: "1.21.11", namespace: NS });
    assert.ok(v.errors.some((e) => e.code === "arbitrage_loop" && /x 2/.test(e.message)), JSON.stringify(v.errors));
    // the same pair at a fair rate is fine
    const fair = clone(loop); (fair[1].buttons as { cost: { count: number } }[])[0].cost.count = 2;
    assert.ok(validateGameplay(fair, { version: "1.21.11", namespace: NS }).ok);
    const list = { slots: [1], prev: { slot: 9, icon: { material: "minecraft:arrow" } }, next: { slot: 10, icon: { material: "minecraft:arrow" } }, source: { type: "config", currency: { type: "item", item: "minecraft:emerald" }, entries: [{ material: "minecraft:emerald", amount: 2, price: 1 }] } };
    assert.ok(codes([chest("m", { list })]).includes("cost_loop"));
    // a config list feeding an arbitrage loop with a fixed button
    const list2 = { ...list, source: { ...list.source, entries: [{ material: "minecraft:gold_ingot", amount: 4, price: 1 }] } };
    assert.ok(codes([chest("m", { list: list2, buttons: [btn(0, { cost: { type: "item", item: "minecraft:gold_ingot", count: 2 }, actions: [{ type: "give_item", item: "minecraft:emerald" }] })] })]).includes("arbitrage_loop"));
    assert.ok(codes([chest("m", { buttons: [btn(0, { cost: emerald(3) })] })]).includes("cost_without_action"));
    assert.ok(codes([chest("m", { buttons: [btn(0, { actions: Array(5).fill({ type: "give_item", item: "minecraft:bread" }) })] })]).includes("too_many_gives"));
  });
  it("reward farms: an instant repeatable quest with items, collect-kept-and-get-back", () => {
    const dlg = { schemaVersion: 1, kind: "menu", style: "dialogue", id: "d", title: "D", speaker: { text: "S" }, lines: ["x"], choices: [{ icon: { material: "minecraft:paper" } }] };
    const instant = quest("farm", { repeat: { mode: "repeatable", cooldownSeconds: 5 }, steps: [{ id: "s1", text: "talk", objectives: [{ type: "talk", menu: "d" }] }], rewards: [{ type: "give_item", item: "minecraft:diamond", count: 4 }] });
    assert.ok(codes([dlg, instant]).includes("reward_farm"));
    assert.ok(validateGameplay([dlg, { ...instant, repeat: { mode: "repeatable", cooldownSeconds: 600 } }], { version: "1.21.11", namespace: NS }).ok, "a real cooldown makes it fine");
    const kept = quest("kept", { repeat: { mode: "repeatable" }, steps: [{ id: "s1", text: "have", objectives: [{ type: "collect_item", item: "minecraft:diamond", count: 1, mode: "inventory" }] }], rewards: [{ type: "give_item", item: "minecraft:diamond", count: 2 }] });
    assert.ok(codes([kept]).includes("reward_farm"));
    const hand = quest("hand", { repeat: { mode: "repeatable" }, steps: [{ id: "s1", text: "give", objectives: [{ type: "collect_item", item: "minecraft:emerald", count: 1, mode: "inventory", take: true }] }], rewards: [{ type: "give_item", item: "minecraft:emerald", count: 3 }] });
    assert.ok(codes([hand]).includes("arbitrage_loop"), "a fast repeat hand-in that pays more of the same is an exchange loop");
  });
  it("circular prerequisites, unreachable quests / menus / dialogues", () => {
    const c = codes([quest("a", { requires: ["c"] }), quest("b", { requires: ["a"] }), quest("c", { requires: ["b"] }), quest("ok")]);
    assert.equal(c.filter((x) => x === "circular_prerequisites").length, 3);
    assert.ok(codes([quest("self", { requires: ["self"] })]).includes("circular_prerequisites"));
    assert.ok(codes([quest("q", { start: "menu" })]).includes("unreachable_quest"));
    assert.ok(codes([quest("a", { start: "menu" }), quest("b", { requires: ["a"] })]).filter((x) => x === "unreachable_quest").length === 2);
    assert.ok(codes([chest("hidden", { openWith: { command: false } })]).includes("unreachable_menu"));
    assert.ok(validateGameplay([chest("root"), chest("hidden", { openWith: { command: false } }), chest("root2", { buttons: [btn(0, { actions: [{ type: "open_menu", menu: "hidden" }] })] })], { version: "1.21.11", namespace: NS }).ok, "reachable through open_menu");
    const dlg = { schemaVersion: 1, kind: "menu", style: "dialogue", id: "d", title: "D", speaker: { text: "S" }, lines: ["x"], choices: [{ icon: { material: "minecraft:paper" } }], openWith: { command: false } };
    const c2 = codes([dlg, quest("q", { steps: [{ id: "s1", text: "talk", objectives: [{ type: "talk", menu: "d" }] }] })]);
    assert.ok(c2.includes("unreachable_dialogue") && c2.includes("unreachable_menu"));
    assert.ok(codes([chest("c"), quest("q", { steps: [{ id: "s1", text: "talk", objectives: [{ type: "talk", menu: "c" }] }] })]).includes("not_dialogue"));
  });
  it("oversize progress, too many menus / quests, over-budget menus", () => {
