describe("gameplay component library + compiler", () => {
  const out = compileOk(ALL());
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-gameplay-"));
  for (const f of out.files) { fs.mkdirSync(path.dirname(path.join(tmp, f.path)), { recursive: true }); fs.writeFileSync(path.join(tmp, f.path), f.content); }
  const java = out.files.filter((f) => f.path.endsWith(".java"));
  it("every component (item + gameplay + Vault when money is used) is in the tree, documented", () => {
    for (const c of [...COMPONENTS, ...GAMEPLAY_COMPONENTS, VAULT_COMPONENT]) {
      assert.ok(out.files.some((f) => f.path.endsWith(`/guildquests/${c.file}`)), c.id);
      assert.deepEqual(c.families, ["1.21", "26"]);
      assert.ok(c.tests.length >= 2 && c.purpose.length > 10 && c.limits.length >= 1 || c.id === "designer-trigger" || c.id === "designer-item", c.id);
    }
    assert.deepEqual(out.deps, ["vault-api"]);
    assert.match(out.files.find((f) => f.path.endsWith("plugin.yml"))!.content, /softdepend: \[Vault\]/);
    const noMoney = compileOk(ALL().map((d: { id: string }) => (d.id === "shop" ? { ...d, buttons: (d as unknown as { buttons: { slot: number }[] }).buttons.filter((b) => b.slot !== 51) } : d)));
    assert.ok(!noMoney.files.some((f) => f.path.endsWith("VaultMoney.java")) && !noMoney.deps.length && !/softdepend/.test(noMoney.files.find((f) => f.path.endsWith("plugin.yml"))!.content));
    assert.equal(gameplayLibraryHash(), gameplayLibraryHash());
    assert.deepEqual(out.counts, { items: 2, menus: 2, quests: 4 });
  });
  it("is deterministic and matches the golden hashes on every version (order independent)", () => {
    const golden = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8"));
    assert.deepEqual(Object.keys(golden), SUPPORTED);
    for (const v of SUPPORTED) {
      const a = compileOk(ALL(), ctx(v)), b = compileOk(ALL().reverse(), ctx(v));
      assert.equal(a.hash, b.hash, `${v}: order-independent`);
      assert.equal(a.hash, golden[v].hash, `${v}: golden hash (regenerate with scripts/cyrus/gameplay-golden.ts and review)`);
    }
  });
  it("only Compat varies per version; the gameplay components are version-independent", () => {
    const by = Object.fromEntries(SUPPORTED.map((v) => [v, compileOk(ALL(), ctx(v))]));
    for (const c of [...GAMEPLAY_COMPONENTS, VAULT_COMPONENT]) assert.equal(new Set(SUPPORTED.map((v) => by[v].files.find((f) => f.path.endsWith(c.file))!.sha256)).size, 1, c.id);
    for (const v of SUPPORTED) for (const f of by[v].files.filter((x) => /\/(menus|quests)\//.test(x.path))) assert.equal(f.sha256, by["1.21.11"].files.find((x) => x.path === f.path)!.sha256, `${v} ${f.path}`);
    assert.equal(by["1.21.11"].javacVerified, true); assert.equal(by["1.21.4"].javacVerified, false);
  });
  it("generated code: no reflection, threads, network, commands; strict source rules + precheck clean on every version", () => {
    const banned = /\b(Runtime|ProcessBuilder|java\.lang\.reflect|Class\.forName|getDeclared|MethodHandles|dispatchCommand|performCommand|new Thread|Executors|java\.net|HttpClient|System\.exit|setOp|getenv|ClassLoader|ObjectInputStream|Unsafe|ScriptEngine|runTaskAsynchronously|getRegionScheduler|getAsyncScheduler)\b/;
    for (const f of java) assert.doesNotMatch(f.content, banned, f.path);
    const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
    assert.deepEqual(S.scanSource(java.map((f) => ({ abs: path.join(tmp, f.path), rel: f.path }))), [], "strict source rules");
    const pre = require(path.join(ROOT, "services/modbuilder/precheck.js"));
    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      const d = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-gameplay-pre-"));
      const files = r.files.filter((f) => f.path.endsWith(".java")).map((f) => { const abs = path.join(d, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); return { abs, rel: f.path }; });
      assert.deepEqual(pre.precheck(files, v), [], v);
    }
  });
  it("hardening is in the component code: every click/drag cancelled twice, holder-based, plain clicks only, cleanup", () => {
    const mm = out.files.find((f) => f.path.endsWith("MenuManager.java"))!.content;
    assert.equal((mm.match(/e\.setCancelled\(true\)/g) ?? []).length >= 4, true);
    assert.match(mm, /EventPriority\.LOWEST\)\s+public void onClickEarly/); assert.match(mm, /EventPriority\.HIGHEST\)\s+public void onClick\(/);
    assert.match(mm, /onDragEarly/); assert.match(mm, /ClickType\.LEFT && e\.getClick\(\) != ClickType\.RIGHT/);
    assert.match(mm, /instanceof Holder/); assert.doesNotMatch(mm, /getTitle\(/, "never by title");
    assert.match(mm, /onQuit/); assert.match(mm, /closeAll/); assert.match(mm, /sweep/);
    const press = /private void press[\s\S]*?\n    }\n/.exec(mm)![0];
    const order = ["allowed(p, b)", "CostCharger.fits", "refusal(p, b.cost)", "take(p, b.cost)", "b.click.run"].map((s) => press.indexOf(s));
    assert.deepEqual([...order].sort((a, b) => a - b), order, "permission -> room -> can pay -> take -> actions");
    const qs = out.files.find((f) => f.path.endsWith("Quests.java"))!.content;
    const complete = /private void complete[\s\S]*?\n    }\n/.exec(qs)![0];
    assert.ok(complete.indexOf("save(p)") < complete.indexOf("q.rewards("), "completion stored before rewards");
    const tr = out.files.find((f) => f.path.endsWith("ObjectiveTracker.java"))!.content;
    assert.equal((tr.match(/@EventHandler/g) ?? []).length, 9, "one handler per event kind");
  });
  it("config.yml (general, items, menus, quests, owner lists) and plugin.yml (no command permission gate, gameplay nodes)", () => {
    const cfg = out.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, /^config_version: 1$/m); assert.match(cfg, /menu_click_cooldown_ticks: 4/); assert.match(cfg, /max_active_quests: 3/);
    for (const p of out.params) assert.ok(cfg.includes(p.path.split(".").pop()! + ":"), p.path);
    assert.match(cfg, /^lists:\n  # shop: currency minecraft:emerald\n  shop:\n  - material: "minecraft:bread"/m);
    assert.equal((cfg.match(/- material:/g) ?? []).length, 30);
    const py = out.files.find((f) => f.path.endsWith("plugin.yml"))!.content;
    assert.doesNotMatch(py, /^    permission:/m, "players must reach /<mod> menu and quests");
    for (const n of ["command", "give", "menu", "menu.others", "quests", "quests.admin", "reload", "vip"]) assert.match(py, new RegExp(`  ${NS}\\.${n.replace(".", "\\.")}:`));
    assert.match(py, new RegExp(`${NS}\\.menu:\\n    description: [^\\n]*\\n    default: true`));
    assert.match(out.readme, /## Menus/); assert.match(out.readme, /## Quests/); assert.match(out.readme, /Path "Explorer"/);
  });
});

describe("edit without regenerating: menus and quests", () => {
  const prev = compileOk(ALL());
  it("price / count / cooldown / text / coordinate edits change ONLY config.yml (+ README); config_version goes up", () => {
    for (const v of ["1.21.11", "26.2"]) {
      const base = compileOk(ALL(), ctx(v));
      const r = recompileModWithEdits(base, [
        { path: "menus.shop.b47.cost.count", value: 7 }, { path: "menus.shop.b51.cost.amount", value: 30.5 }, { path: "quests.trial_one.steps.s1.o0.count", value: 8 },
        { path: "quests.daily_bread.repeat.cooldown_seconds", value: 43200 }, { path: "quests.trial_two.steps.x1.o0.x", value: -500 }, { path: "menus.elder.line1", value: "Skeletons now, too." },
        { path: "items.guild_charm.abilities.bless.cooldown_ticks", value: 1200 },
      ], ctx(v));
      assert.ok(r.ok, JSON.stringify(!r.ok && r.errors));
      if (!r.ok) return;
      assert.deepEqual(r.diff.changed.map((c) => c.path), ["src/main/resources/config.yml"], v);
      assert.deepEqual(r.diff.javaChanged, []);
      assert.equal(r.diff.readmeChanged, true);
      assert.equal(r.result.configVersion, 2);
      assert.equal(r.applied.length, 7);
      const cfg = r.result.files.find((f) => f.path.endsWith("config.yml"))!.content;
      assert.match(cfg, /cooldown_seconds: 43200/); assert.match(cfg, /x: -500\.0/);
    }
    const same = recompileModWithEdits(prev, [], ctx());
    assert.ok(same.ok && same.result.configVersion === 1 && same.diff.changed.length === 0, "no edit keeps config_version");
  });
  it("a structural change (another action on a button) changes exactly that menu's Java file (+ config)", () => {
    const d = ALL();
    const shop = d.find((x: { id: string }) => x.id === "shop") as { buttons: { slot: number; actions?: unknown[] }[] };
    shop.buttons.find((b) => b.slot === 46)!.actions!.push({ type: "play_sound", sound: "minecraft:block.note_block.bell" });
    const r = compileOk(d);
    const changed = r.files.filter((f) => prev.files.find((p) => p.path === f.path)?.sha256 !== f.sha256).map((f) => f.path.split("/").pop());
    assert.deepEqual(changed, ["ShopMenu.java", "config.yml"]);
  });
  it("refuses out-of-range values, wrong types and non-parameters", () => {
    const mod = { items: prev.designs, menus: prev.menus, quests: prev.quests };
    for (const [p, v] of [["menus.shop.b47.cost.count", 99999], ["quests.trial_one.steps.s1.o0.count", 0], ["menus.shop.title", 5], ["menus.shop.rows", 3], ["quests.trial_one.start", "command"], ["menus.shop.b47.cost.item", "minecraft:diamond"]] as [string, number | string][])
      assert.equal(applyGameplayEdits(mod, [{ path: p, value: v }]).ok, false, p);
  });
});

describe("TS reference simulator: menus", () => {
  const sim = () => { const s = new GameplaySimulator(items(), menus(), quests(), { namespace: NS }); s.join("ann"); s.advance(10); return s; };
  it("pagination math (clamped, at most 10 pages)", () => {
    assert.deepEqual([Pagination.pages(30, 28), Pagination.count(0, 30, 28), Pagination.count(1, 30, 28), Pagination.clamp(9, 30, 28), Pagination.hasNext(0, 30, 28), Pagination.hasPrev(0, 30, 28)], [2, 28, 2, 1, true, false]);
    assert.equal(Pagination.pages(1000, 5), 10); assert.equal(Pagination.count(9, 1000, 5), 5); assert.equal(Pagination.pages(0, 5), 1);
  });
  it("the shop: page 1 has 28 lines + next, page 2 has 2 + prev; nav buttons only where they make sense", () => {
    const s = sim();
    const o = s.openMenu("ann", "shop")!;
    assert.equal([10, 11, 12, 13, 14, 15, 16, 19, 20, 21, 22, 23, 24, 25, 28, 29, 30, 31, 32, 33, 34, 37, 38, 39, 40, 41, 42, 43].every((x) => o.slots.has(x)), true);
    assert.ok(o.slots.has(50) && !o.slots.has(48));
    s.advance(10); s.click("ann", 50); const p2 = s.current("ann")!;
    assert.equal(p2.page, 1); assert.ok(p2.slots.has(48) && !p2.slots.has(50) && p2.slots.has(10) && p2.slots.has(11) && !p2.slots.has(12));
  });
  it("hardening: every click type except plain left/right is cancelled with no effect; drags too; rate limit", () => {
    const s = sim();
    s.give("ann", "minecraft:emerald", 10);
    s.openMenu("ann", "shop");
    for (const t of ["shift_left", "shift_right", "number_key", "double_click", "drop", "control_drop", "middle", "swap_offhand", "creative"] as const) {
      const r = s.click("ann", 10, t);
      assert.deepEqual([r.cancelled, r.ran, r.reason], [true, false, "click_type"], t);
    }
    assert.deepEqual(s.drag("ann"), { cancelled: true, ran: false, reason: "drag" });
    assert.equal(s.count("ann", "minecraft:emerald"), 10, "nothing was spent");
    assert.equal(s.click("ann", 10).ran, true);
    assert.equal(s.click("ann", 10).reason, "rate_limited", "a second click in the same tick");
    s.advance(4); assert.equal(s.click("ann", 10).ran, true);
    assert.equal(s.count("ann", "minecraft:emerald"), 8); assert.equal(s.count("ann", "minecraft:bread"), 16);
    assert.equal(s.click("ann", 60).reason, "outside");
  });
  it("dupe-proof order: permission, room, can pay, take, give (a refused click takes nothing and gives nothing)", () => {
    const s = sim();
    s.openMenu("ann", "shop");
    s.give("ann", "minecraft:emerald", 10);
    assert.equal(s.click("ann", 47).reason, "no_permission");
    s.players.get("ann")!.perms.add(`${NS}.vip`);
    s.advance(5);
    // full inventory: no room for the golden apple -> nothing taken
    for (let i = 0; i < 35; i++) s.give("ann", "minecraft:cobblestone", 64);
    assert.equal(s.click("ann", 47).reason, "no_space");
    assert.equal(s.count("ann", "minecraft:emerald"), 10);
    const st = s.players.get("ann")!.slots;
    for (let i = 0; i < st.length; i++) if (st[i]?.item === "minecraft:cobblestone") st[i] = null;
    s.advance(5);
    assert.equal(s.click("ann", 47).ran, true);
    assert.deepEqual([s.count("ann", "minecraft:emerald"), s.count("ann", "minecraft:golden_apple")], [5, 1]);
    s.advance(5); s.click("ann", 47); s.advance(5);
    assert.equal(s.click("ann", 47).reason, "cannot_pay");
    assert.deepEqual([s.count("ann", "minecraft:emerald"), s.count("ann", "minecraft:golden_apple")], [0, 2]);
    const paid = s.log.filter((e) => e.kind === "paid").length, gave = s.log.filter((e) => e.kind === "give").length;
    assert.equal(paid, gave, "every give was paid first");
  });
  it("XP and money costs: money refused without Vault, paid with it; clamped config values change prices", () => {
    const s = sim();
    s.openMenu("ann", "shop");
    assert.equal(s.click("ann", 51).reason, "no_economy");
    const v = new GameplaySimulator(items(), menus(), quests(), { namespace: NS, vault: true, config: { "menus.shop.b46.cost.levels": 2 } });
    v.join("bob", { money: 30, levels: 3 }); v.advance(10); v.openMenu("bob", "shop");
    assert.equal(v.click("bob", 51).ran, true); assert.equal(v.players.get("bob")!.money, 5);
    v.advance(5); assert.equal(v.click("bob", 46).ran, true);
    assert.deepEqual([v.players.get("bob")!.levels, v.count("bob", "minecraft:diamond")], [1, 1]);
  });
});

describe("TS reference simulator: quests", () => {
  const sim = (opts = {}) => { const s = new GameplaySimulator(items(), menus(), quests(), { namespace: NS, ...opts }); s.join("ann"); return s; };
  it("the chain: dialogue start -> kills -> bones handed in -> rewards after the completion is stored", () => {
    const s = sim();
    assert.equal(s.startRefusal("ann", "trial_one", true), "menu_only");
    assert.equal(s.startRefusal("ann", "trial_two", true), "needs:trial_one");
    s.openMenu("ann", "elder"); s.advance(5); s.click("ann", 20);
    assert.equal(s.entries("ann").get("trial_one")!.state, "A");
    for (let i = 0; i < 4; i++) s.kill("ann", "minecraft:zombie");
    s.kill("ann", "minecraft:skeleton");
    assert.deepEqual(s.entries("ann").get("trial_one")!.counts, [4, 0, 0]);
    s.kill("ann", "minecraft:zombie");
    assert.equal(s.entries("ann").get("trial_one")!.step, "s2");
    s.pickup("ann", "minecraft:bone", 2);
    assert.equal(s.entries("ann").get("trial_one")!.state, "A");
    s.pickup("ann", "minecraft:bone", 2);
    const e = s.entries("ann").get("trial_one")!;
    assert.deepEqual([e.state, e.completions], ["D", 1]);
    assert.equal(s.count("ann", "minecraft:bone"), 1, "3 handed in, 1 kept");
    const kinds = s.log.map((x) => x.kind);
    assert.ok(kinds.lastIndexOf("quest_complete") < kinds.indexOf("reward"), "stored before rewards");
    assert.equal(s.count("ann", "minecraft:bread"), 6);
    assert.equal(s.startRefusal("ann", "trial_one", false), "already_completed");
  });
  it("branching: break logs -> choose explorer -> visit; the other branch's objective does not count; player-placed blocks do not count", () => {
    const s = sim();
    s.entries("ann").set("trial_one", { quest: "trial_one", state: "D", step: "", branch: "", counts: [0, 0, 0], started: 0, completions: 1, last: 1 });
    assert.ok(s.startQuest("ann", "trial_two", true));
    s.place("minecraft:oak_log", "1,64,1");
    s.breakBlock("ann", "minecraft:oak_log", "1,64,1");
    assert.equal(s.entries("ann").get("trial_two")!.counts[0], 0);
    for (let i = 0; i < 10; i++) s.breakBlock("ann", "minecraft:oak_log");
    assert.equal(s.entries("ann").get("trial_two")!.state, "C");
    assert.equal(s.chooseBranch("ann", "trial_two", "nope"), false);
    s.kill("ann", "minecraft:skeleton");
    assert.ok(s.chooseBranch("ann", "trial_two", "explorer"));
    s.kill("ann", "minecraft:skeleton"); s.kill("ann", "minecraft:skeleton"); s.kill("ann", "minecraft:skeleton");
    assert.equal(s.entries("ann").get("trial_two")!.state, "A");
    s.moveTo("ann", "world", [118, 70, -79]); s.advance(20);
    assert.equal(s.entries("ann").get("trial_two")!.state, "D");
    assert.deepEqual([s.count("ann", "minecraft:compass"), s.count("ann", "minecraft:iron_sword"), s.players.get("ann")!.levels], [1, 0, 2]);
  });
  it("talk + survive with reset_step on death; dialogue opened by NPC/command counts as talking", () => {
    const s = sim();
    for (const id of ["trial_one", "trial_two"]) s.entries("ann").set(id, { quest: id, state: "D", step: "", branch: "", counts: [0, 0, 0], started: 0, completions: 1, last: 1 });
    assert.ok(s.startQuest("ann", "trial_three", true));
    s.openMenu("ann", "elder");
    assert.equal(s.entries("ann").get("trial_three")!.step, "r2");
    s.advance(20 * 100); s.die("ann");
    assert.equal(s.entries("ann").get("trial_three")!.counts[0], 0, "reset_step on death");
    s.advance(20 * 120);
    assert.equal(s.entries("ann").get("trial_three")!.state, "D");
    assert.equal(s.count("ann", "guild_badge"), 1);
  });
  it("daily repeat cooldown (rolling 24 h), the active-quest cap and abandon keeping the history", () => {
    const s = sim({ maxActive: 1 });
    assert.ok(s.startQuest("ann", "daily_bread", true));
    assert.equal(s.startRefusal("ann", "trial_two", true), "needs:trial_one");
    s.craft("ann", "minecraft:bread", 4);
    assert.equal(s.entries("ann").get("daily_bread")!.completions, 1);
    assert.match(s.startRefusal("ann", "daily_bread", true)!, /^cooldown:86400$/);
    s.advance(20 * 3600);
    assert.match(s.startRefusal("ann", "daily_bread", true)!, /^cooldown:82800$/);
    s.clock += 86400;
    assert.ok(s.startQuest("ann", "daily_bread", true));
    s.entries("ann").set("trial_one", { quest: "trial_one", state: "D", step: "", branch: "", counts: [0, 0, 0], started: 0, completions: 1, last: 1 });
    assert.equal(s.startRefusal("ann", "trial_two", true), "too_many_active");
    assert.ok(s.abandonQuest("ann", "daily_bread"));
    const e = s.entries("ann").get("daily_bread")!;
    assert.deepEqual([e.state, e.completions], ["D", 1]);
    assert.ok(s.startQuest("ann", "trial_two", true));
    const cfg = new GameplaySimulator(items(), menus(), quests(), { namespace: NS, config: { "quests.daily_bread.repeat.cooldown_seconds": 60 } });
    cfg.join("x"); cfg.startQuest("x", "daily_bread", true); cfg.craft("x", "minecraft:bread", 4); cfg.clock += 61;
    assert.equal(cfg.startRefusal("x", "daily_bread", true), null, "the edited cooldown is used");
  });
  it("progress codec: roundtrip, the server sample, migration (removed quest, changed step, clamp, unknown format)", () => {
    const defs = new Map(quests().map((q) => [q.id, q]));
    const sample = progressSample(quests());
    assert.equal(sample, "q1|daily_bread,A,b1,,1.0.0,1700000000,2,1700000100|trial_one,A,s1,,1.0.0,1700000000,2,1700000100|trial_three,A,r1,,1.0.0,1700000000,2,1700000100|trial_two,A,c1,,1.0.0,1700000000,2,1700000100");
    const notes: string[] = [];
    assert.equal(encodeProgress(decodeProgress(sample, defs, notes)), sample); assert.deepEqual(notes, []);
    const n2: string[] = [];
    const m2 = decodeProgress("q1|trial_one,A,no_such_step,,5.5.5,1,0,0|zz_removed,A,s1,,1.0.0,1,0,0", defs, n2);
    assert.deepEqual([m2.size, m2.get("trial_one")!.step, m2.get("trial_one")!.counts[0], n2.length], [1, "s1", 0, 2]);
    const n3: string[] = [];
    assert.equal(decodeProgress("v9|whatever", defs, n3).size, 0); assert.equal(n3.length, 1);
    assert.equal(decodeProgress("q1|trial_one,A,s1,,999999.999999.999999,1,0,0", defs, [])!.get("trial_one")!.counts[0], 5);
    assert.equal(decodeProgress("q1|trial_one,Z,s1,,1.0.0,1,0,0|trial_two,C,,,0.0.0,1,0,0|bad", defs, []).size, 1);
    // a relog against changed definitions: the quest's step was renamed -> it restarts, completions kept
    const s = new GameplaySimulator(items(), menus(), quests(), { namespace: NS });
    s.join("ann");
    s.entries("ann").set("trial_one", { quest: "trial_one", state: "D", step: "", branch: "", counts: [0, 0, 0], started: 0, completions: 1, last: 1 });
    s.startQuest("ann", "trial_two", true); s.breakBlock("ann", "minecraft:oak_log");
    const changed = quests().map((q) => (q.id === "trial_two" ? { ...q, steps: [{ ...q.steps[0], id: "logs" }] } : q));
    const relog = s.relog("ann", changed);
    assert.deepEqual([relog.length, s.entries("ann").get("trial_two")!.step, s.entries("ann").get("trial_two")!.counts[0], s.entries("ann").get("trial_one")!.completions], [1, "logs", 0, 1]);
    for (const q of quests()) assert.ok(progressEntryChars(q) > q.id.length + 30);
  });
});

describe("service copy, prompt, routing, request, sync, mod page", () => {
  const DZ = require(path.join(ROOT, "services/modbuilder/designer-spec.js"));
  it("TS == generated JS: validation codes and compile hashes on the showcase and the corpus", () => {
    const corpus: unknown[][] = [ALL(), [chest("m", { buttons: [btn(0, { cost: { type: "item", item: "minecraft:emerald", count: 1 }, actions: [{ type: "give_item", item: "minecraft:emerald", count: 2 }] })] })], [quest("a", { requires: ["b"] }), quest("b", { requires: ["a"] })], [quest("q", { start: "menu" })], [chest("m", { buttons: [btn(99)] })]];
    for (const v of ["1.21.1", "1.21.11", "26.2"]) {
      for (const c of corpus) assert.deepEqual(DZ.validateGameplay(c, { version: v, namespace: NS }).errors.map((e: { code: string }) => e.code), validateGameplay(c, { version: v, namespace: NS }).errors.map((e) => e.code));
      assert.equal(DZ.compileMod(ALL(), ctx(v)).hash, compileOk(ALL(), ctx(v)).hash, v);
    }
  });
  it("prompt: the MENUS AND QUESTS part only with design + gameplay; the example validates", () => {
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    const d = P.systemPrompt("1.21.11", { design: true });
    assert.doesNotMatch(d, /MENUS AND QUESTS/);
    assert.equal(P.systemPrompt("1.21.11", { gameplay: true }), P.systemPrompt("1.21.11", {}), "gameplay alone adds nothing");
    const g = P.systemPrompt("1.21.11", { design: true, gameplay: true });
    assert.ok(g.startsWith(d) && /MENUS AND QUESTS \(this build uses them\)/.test(g));
    assert.deepEqual(P.GAMEPLAY_MAX, { menus: GAMEPLAY_LIMITS.maxMenus, quests: GAMEPLAY_LIMITS.maxQuests });
    const ex = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/designer-gameplay-example.json"), "utf8"));
    const r = validateGameplay(Object.values(ex), { version: "1.21.11", namespace: "nx_abcd1234" });
    assert.ok(r.ok, JSON.stringify(r.errors));
    assert.match(P.assetsBlock({ texture: false, sound: false, design: true, gameplay: true, namespace: NS }), /npc\.<menu id>/);
    const docker = fs.readFileSync(path.join(ROOT, "services/modbuilder/Dockerfile"), "utf8");
    assert.match(docker, /designer-gameplay-example\.json/);
  });
  it("routing: menu / quest words, honest exclusions, flag off, existing menus/quests keep the part", () => {
    const base = { mcVersion: "1.21.11", on: true };
    assert.deepEqual(matchGameplayWords("a shop menu with pages"), { menus: true, quests: false, matched: ["menu:shop"] });
    assert.deepEqual(matchGameplayWords("a quest chain with a daily quest"), { menus: false, quests: true, matched: ["quest:quest chain"] });
    assert.equal(matchGameplayWords("an auction house menu").menus, false);
    assert.equal(matchGameplayWords("player shops with chest shops").menus, false);
    const r = decideDesignerRoute({ ...base, text: "an NPC dialogue that gives quests and a shop GUI" });
    assert.equal(r.route, true); assert.deepEqual(r.gameplay, { menus: true, quests: true });
    assert.ok(r.limits.some((l) => /No player-to-player trading/.test(l)) && r.limits.some((l) => /progress is stored on each player/.test(l)));
    assert.deepEqual(decideDesignerRoute({ ...base, text: "a quest log", on: false }), { route: false, matched: [], notices: [], limits: [] });
    assert.equal(decideDesignerRoute({ ...base, text: "broadcast a message every hour" }).route, false);
    assert.equal(decideDesignerRoute({ ...base, text: "a sword with a cooldown" }).gameplay, undefined, "item builds are unchanged");
    assert.deepEqual(decideDesignerRoute({ ...base, text: "make it cheaper", existingGameplay: true }).gameplay, { menus: true, quests: true });
    assert.ok(hasGameplayDesigns({ assets: { designs: [{ kind: "quest" }] } }) && !hasGameplayDesigns({ assets: { designs: [{}] } }));
  });
  it("resolveBuildAssets: a menu/quest request gets design + gameplay; not plan-gated; byte-identical when off", async () => {
    let tierCalls = 0;
    const deps = { tierOf: async () => { tierCalls++; return "free"; }, projectForRootBuild: async () => ({ id: "cp1", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }) };
    const text = "a guild shop GUI with pages and a daily quest";
    assert.deepEqual(await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => false }), { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: NS, design: true, gameplay: true });
    assert.deepEqual(on.meta!.designer!.gameplay, { menus: true, quests: true });
    assert.equal(tierCalls, 0);
    const TX = require(path.join(ROOT, "services/modbuilder/textures.js"));
    const ok = () => true;
    assert.equal(TX.parseAssetsRequest({ namespace: NS, design: true, gameplay: true }, "1.21.11", new Set(), ok, ok).gameplay, true);
    assert.match(TX.parseAssetsRequest({ namespace: NS, gameplay: true }, "1.21.11", new Set(), ok, ok).error, /needs assets\.design/);
    assert.match(TX.parseAssetsRequest({ namespace: NS, design: true, gameplay: "yes" }, "1.21.11", new Set(), ok, ok).error, /true or false/);
  });
  it("service workspace: kind-aware checks, per-kind caps, drops, compile with the Vault dep", () => {
    const DZS = require(path.join(ROOT, "services/modbuilder/designs.js"));
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-gp-ws-"));
    fs.mkdirSync(path.join(ws, "assets/designs"), { recursive: true });
    for (const d of ALL()) fs.writeFileSync(path.join(ws, `assets/designs/${d.id}.json`), JSON.stringify(d));
    fs.writeFileSync(path.join(ws, "assets/designs/loop_quest.json"), JSON.stringify(quest("loop_quest", { requires: ["loop_quest"] })));
    const r = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    assert.deepEqual(r.results.filter((x: { ok: boolean }) => !x.ok).map((x: { name: string }) => x.name), ["loop_quest"]);
    assert.deepEqual(r.results.filter((x: { ok: boolean }) => x.ok).map((x: { kind: string }) => x.kind).sort(), ["item", "item", "menu", "menu", "quest", "quest", "quest", "quest"]);
    fs.rmSync(path.join(ws, "assets/designs/loop_quest.json"));
    const ok = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    const c = DZS.compileWorkspaceDesigns(ws, { pluginName: GP_PLUGIN, mcVersion: "1.21.11", assets: { namespace: NS } }, ok.results.map((x: { spec: unknown }) => x.spec));
    assert.ok(c.ok); assert.deepEqual(c.summary.deps, ["vault-api"]); assert.deepEqual(c.summary.counts, { items: 2, menus: 2, quests: 4 });
    assert.equal(c.summary.hash, compileOk(ALL()).hash, "service == TypeScript");
  });
  it("portal sync: re-validates every kind, re-compiles (serviceAgreed), drops a tampered quest, mime per kind", () => {
    const svc = compileOk(ALL());
    const list = ALL().map((d: { id: string }) => ({ name: d.id, path: `assets/designs/${d.id}.json`, sha256: "x", spec: d }));
    const r = checkReturnedDesigns(list, { namespace: NS, mcVersion: "1.21.11", pluginName: GP_PLUGIN, compile: { hash: svc.hash, configVersion: 1 } });
    assert.equal(r.serviceAgreed, true);
    assert.deepEqual(r.ok.map((x) => x.kind).sort(), ["item", "item", "menu", "menu", "quest", "quest", "quest", "quest"]);
    const bad = clone(byId("daily_bread")); bad.rewards[0].count = 9999;
    const t = checkReturnedDesigns(list.map((x) => (x.name === "daily_bread" ? { ...x, spec: bad } : x)), { namespace: NS, mcVersion: "1.21.11", pluginName: GP_PLUGIN, compile: { hash: svc.hash } });
    assert.deepEqual(t.dropped.map((d) => d.name), ["daily_bread"]); assert.equal(t.serviceAgreed, false);
    assert.match(t.notices[0], /^Quest design "daily_bread" was left out/);
    assert.deepEqual(DESIGN_KIND_MIME, { item: "application/vnd.nxeon.item-design+json", menu: "application/vnd.nxeon.menu-design+json", quest: "application/vnd.nxeon.quest-design+json" });
  });
  it("mod page lines: 'Includes N menus and M quests'", () => {
    const row = { version: "1.21.11", specSha256: "x", compileHash: "y", serviceAgreed: true, configVersion: 1, settings: 3, abilities: 0 };
    const a = { status: "none" as const, namespace: NS, projectId: "p", revisionId: "r", textures: [], dropped: [{ name: "q", reason: "x", kind: "design" as const }], pack: null, loader: null, notices: [],
      designs: [{ ...row, name: "shop", kind: "menu" as const }, { ...row, name: "elder", kind: "menu" as const }, { ...row, name: "daily", kind: "quest" as const }, { ...row, name: "badge", abilities: 1 }] };
    const lines = assetLines(a);
    assert.ok(lines.some((l) => /^Includes 2 menus and 1 quest;/.test(l)), JSON.stringify(lines));
    assert.ok(lines.includes("1 requested design was left out after failing Nxeon's design checks."));
    assert.ok(!lines.some((l) => /texture/.test(l)), "a dropped design is not a texture");
  });
});

