} else if (/item designs need fixing/.test(prompt)) {
  const cur = fs.readFileSync(path.join(ws, "assets/designs/storm_staff.json"), "utf8");
  w("assets/designs/storm_staff.json", cur.includes('"amount": 99') ? cur.replace('"amount": 99', '"amount": 6') : cur);
} else if (/custom asset specs need fixing/.test(prompt)) {
  if (fs.existsSync(path.join(ws, DPF))) { const cur = fs.readFileSync(path.join(ws, DPF), "utf8"); w(DPF, cur.includes("rubyy") ? cur : GOODDP); }
  if (fs.existsSync(path.join(ws, SND))) { const cur = fs.readFileSync(path.join(ws, SND), "utf8"); w(SND, cur.includes('"length":7.5') ? cur : GOODSND); }
  // The asset repair: a spec with an unknown colour gets fixed; the deliberately ugly one stays ugly (to test the downgrade).
  if (fs.existsSync(path.join(ws, SPEC))) { const cur = fs.readFileSync(path.join(ws, SPEC), "utf8"); w(SPEC, cur.includes("#777777") ? UGLY : GOOD); }
} else if (/Build this Paper/.test(prompt)) {
  w("src/main/resources/plugin.yml", "name: Hello\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.hello.Hello\\napi-version: '1.21'\\ndescription: hi\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/hello/Hello.java", "package dev.nxeon.plugins.hello;\\n\\nimport org.bukkit.configuration.FileConfiguration;\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic final class Hello extends JavaPlugin {\\n  NamespacedKey key;\\n  @Override public void onEnable() { FileConfiguration c = getConfig(); }\\n}\\n");
  w("modbuilder.json", JSON.stringify({ name: "Hello", version: "1.0.0", tagline: "Says hi", summary: "Says hi.", howToUse: ["Install it"] }));
} else if (/change request/.test(prompt)) {
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", FAKE_JAVAP]]) {
      fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    }
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/configuration/file/FileConfiguration.class\norg/bukkit/plugin/java/JavaPlugin.class\norg/bukkit/NamespacedKey.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), path.join(dir, "ruby_sword.json"));
    fs.copyFileSync(path.join(SVC, "sound-example.json"), path.join(dir, "sound-example.json"));
    fs.copyFileSync(path.join(SVC, "datapack-example.json"), path.join(dir, "datapack-example.json"));
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), path.join(dir, "storm_staff.json"));
    fs.copyFileSync(path.join(SVC, "worldgen-example.json"), path.join(dir, "worldgen-example.json"));
    const nodePath = path.join(dir, "node_modules");
