    assert.equal(call.datapack, false); assert.equal(call.textures, false);
    assert.equal(call.nsInPrompt, DZNS);
    assert.equal(r.dedupeKey, null, "designer builds are never deduped");
    const paths = r.files.map((f: { path: string }) => f.path);
    assert.ok(paths.includes("src/main/java/dev/nxeon/plugins/stormmod/designer/Designer.java"));
    assert.ok(paths.includes("src/main/java/dev/nxeon/plugins/stormmod/abilities/StormStaffBolt.java"));
    assert.ok(paths.includes("src/main/java/dev/nxeon/plugins/stormmod/custom/CustomHooks.java"), "custom code kept");
    assert.ok(!paths.includes("src/main/java/dev/nxeon/plugins/stormmod/Wrong.java"), "model-written Java outside custom/ replaced");
    assert.equal(r.pluginName, "StormMod");
    assert.equal(r.assetResult.designs.length, 1);
    assert.equal(r.assetResult.designs[0].name, "storm_staff");
    assert.equal(r.assetResult.designPromptVersion, "mb-design-2026-10-10.1");
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { compileDesigns } = require(path.join(ROOT, "lib/cyrus/designer/compile")) as typeof import("../lib/cyrus/designer/compile");
    const ts = compileDesigns([JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), "utf8"))], { version: "1.21.11", namespace: DZNS, pluginName: "StormMod", customHooks: true, assets: { models: [] } });
    assert.ok(ts.ok);
    if (ts.ok) assert.equal(r.assetResult.designCompile.hash, ts.hash, "service bundle == TypeScript compiler");
    assert.equal(r.assetResult.designCompile.configVersion, 1);
    assert.ok(r.config.some((c: { key: string }) => c.key === "items.storm_staff.abilities.bolt.cooldown_ticks"), "settings listed from the design");
    assert.ok(r.events.some((e: { message: string }) => /Compiled 1 item design into the plugin/.test(e.message)));
  });

  it("an out-of-cap value goes back as a design repair, then ships", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-dz-bad-02", prompt: "Storm staff DESIGNBUILD BADDESIGN", mcVersion: "1.21.11", assets: { design: true, namespace: DZNS } });
    const r = await waitDone("pipe-dz-bad-02");
    assert.equal(r.status, "succeeded", JSON.stringify(ev(r)));
    assert.deepEqual(log().slice(before).map((c: { kind: string }) => c.kind), ["generate", "repair"], "one model repair (the fake labels prompts by their text)");
    assert.deepEqual(r.repairPlan.map((p: { kind: string }) => p.kind), ["design"]);
    assert.ok(r.events.some((e: { message: string; detail?: string }) => /amount/.test(e.detail || "") && /40/.test(e.detail || "")), "repair feedback names the field and its cap");
    assert.equal(r.assetResult.designs.length, 1);
  });

  it("a design that keeps failing is dropped; with no design left the build fails clearly (never a half mod)", async () => {
    await api("POST", "/builds", { id: "pipe-dz-dead-03", prompt: "Storm staff DESIGNBUILD DEADDESIGN", mcVersion: "1.21.11", assets: { design: true, namespace: DZNS } });
    const r = await waitDone("pipe-dz-dead-03");
    assert.equal(r.status, "failed");
    assert.match(r.error, /None of the item designs passed/);
    assert.match(r.errorDetail, /is a block/);
  });

  it("designer not routed: no section, the design file is removed; malformed flag 400", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-dz-no-04", prompt: "Storm staff DESIGNBUILD no route", mcVersion: "1.21.11" });
